def get_model_by_name(name):
    # print("###Log, name", name, model_dict)
    if name in model_dict:
        return model_dict[name]['model'], model_dict[name]['tokenizer']
    else:
        if 'Qwen' in name:
            model, tokenizer = load_qwen_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer
        elif 'llama' in name.lower() and 'vision' in name.lower():
            model, processor = load_vision_llama_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = processor
            return model, processor
        elif 'llama' in name:
            '''
            3B 9T
            8B 15T
            70B 15T
            '''
            model, tokenizer = load_llama_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer
        elif 'gemma' in name:
            '''
            google/gemma-2-2b-it, 2T corpus
            google/gemma-2-9b-it, 8T corpus
            google/gemma-2-27b-it, 13T corpus
            '''
            if "gemma-3" in name:
                model, tokenizer = load_gemma3_model(name)
            else:
                model, tokenizer = load_gemma_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer
        elif 'Phi' in name:
            '''
            microsoft/Phi-3-mini-4k-instruct 3.8B, 3.3T
            microsoft/Phi-3-small-8k-instruct 7B, 4.8T 
            microsoft/Phi-3-medium-4k-instruct 14B, 4.8T
            '''
            model, tokenizer = load_phi_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer
        elif 'pythia' in name:
            '''
            EleutherAI/pythia-14m, 0.2T
            EleutherAI/pythia-70m
            EleutherAI/pythia-160m
            EleutherAI/pythia-410m
            EleutherAI/pythia-1b
            EleutherAI/pythia-1.4b
            EleutherAI/pythia-2.8b
            EleutherAI/pythia-6.9b
            EleutherAI/pythia-12b
            不是instruct
            '''
            model, tokenizer = load_pythia_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer
        elif 'mamba' in name:
            '''
            也没有apply template方法，舍弃
            "state-spaces/mamba-2.8b-hf"
            '''
            model, tokenizer = load_mamba_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer
        elif 'starcoder' in name:
            '''
            bigcode/starcoder2-3b
            bigcode/starcoder2-7b
            bigcode/starcoder2-15b
            不是instruct，没有apply template,舍弃
            '''
            model, tokenizer = load_starcoder_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer
        elif 'OpenCoder' in name:
            '''
            infly/OpenCoder-1.5B-Instruct
            infly/OpenCoder-8B-Instruct
            '''
            model, tokenizer = load_opencoder_model(name)
            model_dict[name] = {}
            model_dict[name]['model'] = model
            model_dict[name]['tokenizer'] = tokenizer
            return model, tokenizer

        else:
            pass


def custom_generator(model, messages, image=None, max_tokens=1024, temperature=0.7, repeating=1, **kwargs):
    if 'gemma' in model:
        if messages[0]['role'] == 'system':
            messages = messages[1:]
    model, tokenizer = get_model_by_name(model)
    text = tokenizer.apply_chat_template(
        messages,
        tokenize=False,
        add_generation_prompt=True
    )
    model_inputs = tokenizer([text], return_tensors="pt", padding=True, padding_side='left',
                             truncation=True).to(model.device)

    if repeating > 1:
        bs = 1
        responses_list = [[] for _ in range(bs)]  # no [[]]* bs, the inner [] is shared
        # 修改为每一个batch最大10，否则容易OOM
        for _r in range(0, repeating, 10):
            if repeating - _r  > 10:
                _repeating = 10
            else:
                _repeating = repeating - _r

            with torch.no_grad():
                generated_ids = model.generate(
                    **model_inputs,
                    temperature=temperature,  # default temperature is 0.7
                    max_new_tokens=max_tokens,
                    pad_token_id=tokenizer.eos_token_id,
                    num_return_sequences=_repeating,
                    do_sample=True
                )
            for i in range(0, len(generated_ids), _repeating):
                # Extract sequences corresponding to each input prompt
                chunk = generated_ids[i:i + _repeating]
                input_ids = model_inputs.input_ids[i // _repeating]
                for ids in chunk:
                    response = tokenizer.decode(ids[len(input_ids):], skip_special_tokens=True)
                    responses_list[i // _repeating].append(response)

        responses = responses_list[0]
    else:
        with torch.no_grad():
            generated_ids = model.generate(
                **model_inputs,
                temperature=temperature,  # default temperature is 0.7
                max_new_tokens=max_tokens,
                pad_token_id=tokenizer.eos_token_id,
                do_sample=True
            )
        generated_ids = [
            output_ids[len(input_ids):] for input_ids, output_ids in zip(model_inputs.input_ids, generated_ids)
        ]
        # Decode all responses in the batch
        response = tokenizer.batch_decode(generated_ids, skip_special_tokens=True)[0]
        responses = [response]

    # print('Log, responses:', responses)

    return responses


def custom_vision_generator(model, messages, image, max_tokens=1024, temperature=0.7, repeating=1, **kwargs):
    if 'gemma' in model:
        if messages[0]['role'] == 'system':
            messages = messages[1:]
    model, processor = get_model_by_name(model)
    text = processor.apply_chat_template(
        messages,
        tokenize=False,
        add_generation_prompt=True
    )
    # print('########## Log, ')
    # print(image)
    # print(text)
    model_inputs = processor(images=[image], text=[text], return_tensors="pt", padding=True, padding_side='left',
                             truncation=True).to(model.device)

    if repeating > 1:
        bs = 1
        responses_list = [[] for _ in range(bs)]  # no [[]]* bs, the inner [] is shared
        # 修改为每一个batch最大10，否则容易OOM
        for _r in range(0, repeating, 10):
            if repeating - _r  > 10:
                _repeating = 10
            else:
                _repeating = repeating - _r

            with torch.no_grad():
                generated_ids = model.generate(
                    **model_inputs,
                    temperature=temperature,  # default temperature is 0.7
                    max_new_tokens=max_tokens,
                    pad_token_id=processor.tokenizer.eos_token_id,
                    num_return_sequences=_repeating,
                    do_sample=True
                )
            for i in range(0, len(generated_ids), _repeating):
                # Extract sequences corresponding to each input prompt
                chunk = generated_ids[i:i + _repeating]
                input_ids = model_inputs.input_ids[i // _repeating]
                for ids in chunk:
                    response = processor.decode(ids[len(input_ids):], skip_special_tokens=True)
                    responses_list[i // _repeating].append(response)

        responses = responses_list[0]
    else:
        with torch.no_grad():
            generated_ids = model.generate(
                **model_inputs,
                temperature=temperature,  # default temperature is 0.7
                max_new_tokens=max_tokens,
                pad_token_id=processor.tokenizer.eos_token_id,
                do_sample=True
            )
        generated_ids = [
            output_ids[len(input_ids):] for input_ids, output_ids in zip(model_inputs.input_ids, generated_ids)
        ]
        # Decode all responses in the batch
        response = processor.batch_decode(generated_ids, skip_special_tokens=True)[0]
        responses = [response]

    # print('Log, responses:', responses)
    # 多个返回值，采样
    return responses


def compute_combination_by_budget(total_budget):
    # total_budget = 3
    retrieve_model_list = [72, 32, 7]
    generate_model_list = [70, 8, 3]
    t = {}
    for r in retrieve_model_list:
        for g in generate_model_list:
            unit1 = 4 * (72 // r) - 3
            unit2 = 4 * (70 // g) - 3
            top_times = total_budget * unit1
            for i in range(1, top_times + 1):
                remaining1 = (total_budget * unit1 - i) // unit1
                top_times2 = remaining1 * unit2
                if top_times2 > 0:
                    t[(r, i, g)] = top_times2
                    print(f'retrieve {r}B', i, f'times. gen model {g}B', top_times2, 'times.')
    print()
    for k, v in t.items():
        print(f'retrieve {k[0]}B', k[1], f'times. gen model {k[2]}B', v, 'times.')

from typing import List, Optional, Tuple, Union

from tqdm import tqdm
from vllm import LLM, SamplingParams

from lmms_eval.api.instance import Instance
from lmms_eval.api.model import lmms
from lmms_eval.api.registry import register_model


@register_model("whisper_vllm")
class WhisperVllm(lmms):
    """
    Whisper Audio Model VLLM
    """

    def __init__(
        self,
        pretrained: str = "Qwen/Qwen2.5-VL-3B-Instruct",
        tensor_parallel_size: int = 1,
        gpu_memory_utilization: float = 0.8,
        batch_size: Optional[Union[int, str]] = 1,
        **model_kwargs,
    ) -> None:
        super().__init__()
        self._batch_size = int(batch_size)

        self._model = LLM(
            model=pretrained,
            tensor_parallel_size=tensor_parallel_size,
            gpu_memory_utilization=gpu_memory_utilization,
            **model_kwargs,
        )

    @property
    def config(self):
        # return the associated transformers.AutoConfig for the given pretrained model.
        raise NotImplementedError()

    @property
    def tokenizer(self):
        return self._model.get_tokenizer()

    @property
    def model(self):
        return self._model

    @property
    def eot_token_id(self):
        return self.tokenizer.eos_token_id

    @property
    def max_length(self):
        return self._max_length

    @property
    def batch_size(self):
        return self._batch_size

    @property
    def device(self):
        return self._device

    @property
    def rank(self):
        return self._rank

    @property
    def world_size(self):
        return self._world_size

    def loglikelihood(self, requests: List[Instance]) -> List[Tuple[float, bool]]:
        raise NotImplementedError("Loglikelihood is not implemented for Whisper")

    def flatten(self, input):
        new_list = []
        for i in input:
            for j in i:
                new_list.append(j)
        return new_list

    def generate_until(self, requests: List[Instance]) -> List[str]:
        res = []
        pbar = tqdm(total=len(requests), disable=(self.rank != 0), desc="Model Responding")

        batched_requests = [requests[i : i + self.batch_size] for i in range(0, len(requests), self.batch_size)]
        for batch_requests in batched_requests:
            batched_prompts = []
            for idx in range(len(batch_requests)):
                contexts, gen_kwargs, doc_to_visual, doc_id, task, split = batch_requests[idx].arguments

                # generation parameters
                sampling_params = SamplingParams(
                    temperature=gen_kwargs.get("temperature", 0),
                    top_p=gen_kwargs.get("top_p", 0),
                    max_tokens=gen_kwargs.get("max_new_tokens", 256),
                )

                # prepare multimodal inputs
                audio = doc_to_visual(self.task_dict[task][split][doc_id])
                assert len(audio) == 1
                audio = audio[0]
                prompt = {
                    "prompt": "<|startoftranscript|>",
                    "multi_modal_data": {
                        "audio": (audio["array"], audio["sampling_rate"]),
                    },
                }
                batched_prompts.append(prompt)

            outputs = self.model.generate(batched_prompts, sampling_params, use_tqdm=False)
            transcriptions = [output.outputs[0].text for output in outputs]
            answers = [self.model.get_tokenizer().normalize(transcription) for transcription in transcriptions]  # whisper post processing

            assert len(answers) == len(batch_requests)
            res.extend(answers)
            pbar.update(len(batch_requests))

        pbar.close()
        return res

    def generate_until_multi_round(self, requests) -> List[str]:
        raise NotImplementedError("TODO: Implement multi-round generation")

import torch
from vllm import LLM, SamplingParams
from transformers import GenerationConfig
from typing import List, Union
from .modeling_utils import BeaconModelOutput

HF_KEY_TO_VLLM_KEY = {
    "top_k": "top_k", 
    "top_p": "top_p", 
    "temperature": "temperature",
    "max_new_tokens": "max_tokens",
    "eos_token_id": "stop_token_ids",
}


class HFStyleVllmModel:
    def __init__(
        self,
        generation_config={},
        **kwargs,
    ):
        self.model = LLM(**kwargs)
        self.generation_config = GenerationConfig(**self.model.llm_engine.generation_config_fields)

    @property
    def device(self):
        return self.model.llm_engine.device_config.device

    def parse_generation_config(self, generation_config:Union[dict,GenerationConfig]):
        """Rename hf generation config to vllm generation config."""
        vllm_config = {}

        if isinstance(generation_config, GenerationConfig):
            generation_config = generation_config.to_dict()

        for k, v in generation_config.items():
            if k in HF_KEY_TO_VLLM_KEY:
                k = HF_KEY_TO_VLLM_KEY[k]
                if k == "stop_token_ids" and isinstance(v, int):
                    v = [v]
                vllm_config[k] = v

        if generation_config.get("do_sample", None) == False:
            vllm_config["temperature"] = 0
        return vllm_config

    def generate(
        self, 
        prompts:Union[List[str],str]=None,
        input_ids:torch.Tensor=None, 
        attention_mask:torch.Tensor=None, 
        use_tqdm:bool=False,
        **kwargs
    ):
        # override the default sampling params
        sampling_params_dict = self.parse_generation_config(self.generation_config)
        sampling_params_dict.update(self.parse_generation_config(kwargs))
        sampling_params = SamplingParams(**sampling_params_dict) 

        if input_ids is not None:
            if isinstance(input_ids, torch.Tensor):
                input_ids = input_ids.tolist()
            outputs = self.model.generate(
                prompt_token_ids=input_ids,
                sampling_params=sampling_params,
                use_tqdm=use_tqdm,
            )
        else:
            outputs = self.model.generate(
                prompts=prompts,
                sampling_params=sampling_params,
                use_tqdm=use_tqdm,
            )
        outputs = [output.outputs[0].text for output in outputs]
        return outputs

    def __call__(self, input_ids, attention_mask, labels, **kwargs):
        if isinstance(input_ids, torch.Tensor):
            device = input_ids.device
            input_ids = input_ids.tolist()
            labels = labels.tolist()

        sampling_params = SamplingParams(prompt_logprobs=True, max_tokens=1, temperature=0)
        outputs = self.model.generate(prompt_token_ids=input_ids, sampling_params=sampling_params)

        batch_losses = []
        valid_token_nums = []

        for i, output in enumerate(outputs):
            log_probs = output.prompt_logprobs
            batch_loss = 0
            valid_token_num = 0
            for j, log_prob in enumerate(log_probs):
                if j == 0:
                    assert log_prob is None
                    continue
                # NOTE: we do not need to rotate here because
                label = labels[i][j]
                if label == -100:
                    continue
                assert label in log_prob
                batch_loss -= log_prob[label].logprob
                valid_token_num += 1
            batch_losses.append(batch_loss / valid_token_num)
            valid_token_nums.append(valid_token_num)

        return BeaconModelOutput(
            batch_loss=batch_losses,
            valid_token_num=valid_token_nums
        )

