@register_local_score_func()
def precise_match(query, img_path, gt_resp, pred_resp, **kwargs):
    scores = []
    for one_gt_resp, one_pred_resp in zip(gt_resp, pred_resp):
        if one_gt_resp == one_pred_resp:
            scores.append('score: 1.0')
        else:
            scores.append('score: 0.0')
    return scores


@register_local_score_func()
def single_choice(query, img_path, gt_resp, pred_resp, **kwargs):
    scores = []
    for one_gt_resp, one_pred_resp in zip(gt_resp, pred_resp):
        one_gt_resp = one_gt_resp.strip().upper()

        patterns = [
            # 匹配 "Answer: A", "The answer is A", "The correct option is: A" 等格式
            # re.IGNORECASE 忽略大小写
            r'(?:(?:the|my|the correct)\s+)?(?:answer|choice|option)\s*(?:is)?\s*[:：]?\s*([A-Z])',

            # 匹配被括号包围的答案, e.g., "(A)"
            r'\(([A-Z])\)',

            # 匹配以句号或右括号结尾的答案, e.g., "A." or "A)"
            # \b 是单词边界，确保不会匹配到单词中间的字母，例如从 "U.S.A." 中错误提取 "A"
            r'\b([A-Z])[\.\)]',

            # 匹配字符串开头的大写字母, e.g., "A. The cat is on the mat"
            r'^([A-Z])\b',

            # 作为最后的手段，匹配文本中第一个独立的单个大写字母
            r'\b([A-Z])\b'
        ]

        extracted_ans = None
        for pattern in patterns:
            match = re.search(pattern, one_pred_resp, re.IGNORECASE)
            if match:
                extracted_ans = match.group(1).upper()
                break

        # 比较提取出的答案和标准答案
        if extracted_ans and extracted_ans == one_gt_resp:
            scores.append(1)
        else:
            scores.append(0)

    return scores


@register_local_score_func()
def one_box_iou05(query, img_path, gt_resp, pred_resp, **kwargs):
    pred_bboxes = np.array([extract_one_bbox_from_str(resp) for resp in pred_resp])
    gt_bboxes = np.array(gt_resp)
    ious = cal_paired_ious(pred_bboxes, gt_bboxes)
    scores = ious > 0.5
    return scores.astype(np.float32).tolist()


def cal_score(result_data, cache, score_func):
    gt_resp = result_data['labels']
    pred_resp = result_data['response']
    query = result_data['messages'][0]['content']
    img_path = result_data['images'][0]['path']
    score_str = score_func(query, img_path, gt_resp, pred_resp)
    score = extract_score_from_str(score_str)
    cache.append({'query': query, 'gt': gt_resp, 'pred': pred_resp, 'score': score, 'score_str': score_str,'images': [img_path]})
    return score

def load_jsonl(file_path):
    with open(file_path, 'r') as f:
        return [json.loads(line) for line in f]

def save_jsonl(data, file_path):
    with open(file_path, 'w') as f:
        for line in data:
            f.write(json.dumps(line) + '\n')

def append_jsonl(one_data, file_path):
    with open(file_path, 'a') as f:
        f.write(json.dumps(one_data) + '\n')



def make_batch_inference_input(batch_data, tmp_in_path, model_name):
    tmp_in_lines = []
    # for result in tqdm(results, desc='Making batch inference input', total=len(results)):
    for r_id, result in enumerate(batch_data):
        user_query = result.pop('user_query')
        gt_resp = result.pop('gt_resp')
        pred_resp = result.pop('pred_resp')
        request_line = {
            "custom_id": f"request-{r_id}",
            "method": "POST",
            "url": "/v1/chat/completions",
            "body": {
                "model": model_name.replace('_', '-'),
                "messages": [
                    {"role": "system", "content": SYS_PROMPT},
                    {"role": "user", "content": PROMPT.format(user_query, gt_resp, pred_resp)},
                ]
            }
        }
        tmp_in_lines.append(request_line)
    save_jsonl(tmp_in_lines, tmp_in_path)
    print(f'Batch inference input saved to {tmp_in_path}')


def convert_batch_inference_output_to_score(results, tmp_out_path):
    tmp_out_lines = load_jsonl(tmp_out_path)

    if len(results) != len(tmp_out_lines):
        raise ValueError(f"Length of input lines and output lines are not equal: {len(results)} vs {len(tmp_out_lines)}")
    score_dict = {}
    for line in tqdm(tmp_out_lines, desc='Converting batch inference output to score', total=len(tmp_out_lines)):
        rid = line['custom_id']
        result_idx = int(rid.split('-')[-1])
        status = line['response']['status_code']
        if status == 200:
            score_str = line['response']['body']['choices'][0]['message']['content']
            score = extract_score_from_str(score_str)
        else:
            # warning
            warnings.warn(f"Request {rid} failed with status code {status}")
            score_str = ''
            score = 0.0
        score_dict[result_idx] = score
    score_dict = {k: score_dict[k] for k in sorted(score_dict.keys())}
    scores = list(score_dict.values())
    return scores


def upload_file(client, file_path):
    print(f"Uploading the JSONL file containing request information...")
    file_object = client.files.create(file=Path(file_path), purpose="batch")
    print(f"File uploaded successfully. Obtained file ID: {file_object.id}\n")
    return file_object.id

def create_batch_job(client, input_file_id):
    print(f"Creating a Batch job based on the file ID...")
    batch = client.batches.create(input_file_id=input_file_id, endpoint="/v1/chat/completions", completion_window="24h")
    print(f"Batch job created successfully. Obtained Batch job ID: {batch.id}\n")
    return batch.id

def check_job_status(client, batch_id):
    batch = client.batches.retrieve(batch_id=batch_id)
    return batch.status

def get_output_id(client, batch_id):
    print(f"Retrieving the output file ID of successfully executed requests in the Batch job...")
    batch = client.batches.retrieve(batch_id=batch_id)
    print(f"Output file ID: {batch.output_file_id}\n")
    return batch.output_file_id

def get_error_id(client, batch_id):
    print(f"Retrieving the output file ID of requests with errors in the Batch job...")
    batch = client.batches.retrieve(batch_id=batch_id)
    print(f"Error file ID: {batch.error_file_id}\n")
    return batch.error_file_id

def download_results(client, output_file_id, output_file_path):
    print(f"Printing and downloading the successful request results of the Batch job...")
    content = client.files.content(output_file_id)
    print(f"Printing the first 1000 characters of the successful request results: {content.text[:1000]}...\n")
    content.write_to_file(output_file_path)
    print(f"The complete output results have been saved to the local output file: {output_file_path}\n")

def download_errors(client, error_file_id, error_file_path):
    print(f"Printing and downloading the failed request information of the Batch job...")
    content = client.files.content(error_file_id)
    print(f"Printing the first 1000 characters of the failed request information: {content.text[:1000]}...\n")
    content.write_to_file(error_file_path)
    print(f"The complete failed request information has been saved to the local error file: {error_file_path}\n")


def collect_as_batched_obj(batch_objs):
    return batch_objs


def calculate_avg_score(batch_data, args):
    scores = []
    for one_data in batch_data:
        scores.append(one_data['score'])
    return sum(scores) / len(scores)

def update_scores(batch_data, scores, args):
    assert len(batch_data) == len(scores)
    for one_data, score in zip(batch_data, scores):
        one_data['score'] = score  


def process_batch_data_by_local(batch_data, args):
    gt_resp = [one_data.pop('gt_resp') for one_data in batch_data]
    pred_resp = [one_data.pop('pred_resp') for one_data in batch_data]
    user_query = [one_data.pop('user_query') for one_data in batch_data]
    score_strs = LOCAL_SCORE_FUNCS[args.score_func](user_query, None, gt_resp, pred_resp, **vars(args))
    scores = [extract_score_from_str(score_str) for score_str in score_strs]
    return scores

def process_one_data_by_api(one_data, args):
    gt_resp = one_data.pop('gt_resp')
    pred_resp = one_data.pop('pred_resp')
    user_query = one_data.pop('user_query')
    score_str = SCORE_FUNCS[args.score_func](user_query, None, gt_resp, pred_resp)
    score = extract_score_from_str(score_str)
    return score

def process_batch_data_by_api(batch_data, bid, args):
    score_func_name = args.score_func
    # assert score_func_name in ['qwen_max', 'qwen_plus', 'qwen_turbo'], f"Batch inference is not supported for {score_func_name}"
    tmp_in_path = os.path.join(os.path.dirname(args.tmp_score_path), os.path.basename(args.tmp_score_path).replace('.jsonl', f'_batch-{bid}_in.jsonl'))
    tmp_out_path = os.path.join(os.path.dirname(args.tmp_score_path), os.path.basename(args.tmp_score_path).replace('.jsonl', f'_batch-{bid}_out.jsonl'))
    error_path = os.path.join(os.path.dirname(args.tmp_score_path), os.path.basename(args.tmp_score_path).replace('.jsonl', f'_batch-{bid}_error.jsonl'))

    # if os.path.exists(tmp_in_path) and args.batch_id is None:
    #     raise ValueError(f"Batch inference input file {tmp_in_path} already exists")
    if not os.path.exists(tmp_out_path):
        client = OpenAI(
            api_key=os.getenv("DASHSCOPE_API_KEY"),
            base_url="https://dashscope.aliyuncs.com/compatible-mode/v1"  # 百炼服务的base_url
        )
        if args.batch_id is not None:
            batch_id = args.batch_id
        else:
            make_batch_inference_input(batch_data, tmp_in_path, score_func_name)
            input_file_id = upload_file(client, tmp_in_path)
            batch_id = create_batch_job(client, input_file_id)
        status = ""
        check_times = 0
        with tqdm(
            desc=f"[0s] 等待任务完成...",
            bar_format="{desc}",
        ) as pbar:
            while True:
                status = check_job_status(client, batch_id)
                elapsed_time = check_times * args.interval
                pbar.set_description(f"[{elapsed_time}s] 等待任务完成... 当前状态: {status}")
                if status in ["completed", "failed", "expired", "cancelled"]:
                    break
                check_times += 1
                time.sleep(args.interval)

        if status == "failed":
            batch = client.batches.retrieve(batch_id)
            print(f"Batch failed: {batch.errors}\n")
            print(f"Refer to: https://help.aliyun.com/zh/model-studio/developer-reference/error-code")
        output_file_id = get_output_id(client, batch_id)
        if output_file_id:
            download_results(client, output_file_id, tmp_out_path)
        error_file_id = get_error_id(client, batch_id)
        if error_file_id:
            download_errors(client, error_file_id, error_path)
            print(f"Refer to: https://help.aliyun.com/zh/model-studio/developer-reference/error-code")
            raise ValueError(f"Batch job failed, error file saved to {error_path}")

    print(f"Batch inference finished.")
    scores = convert_batch_inference_output_to_score(batch_data, tmp_out_path)
    if os.path.exists(tmp_in_path):
        os.remove(tmp_in_path)
    return scores


def process_batch_data(batch_data, bid, args):
    if args.score_func in SCORE_FUNCS:
        if len(batch_data) == 1:
            scores = [process_one_data_by_api(batch_data[0], args)]
        else:
            scores = process_batch_data_by_api(batch_data, bid, args)
    else:
        scores = process_batch_data_by_local(batch_data, args)
    update_scores(batch_data, scores, args)
    return batch_data

def post_process_batch_data(batch_data, args):
    # remove intermediate data
    keys = ['user_query', 'gt_resp', 'pred_resp']
    for one_data in batch_data:
        for key in keys:
            if key in one_data:
                one_data.pop(key)




def gather_batched_obj(batch_src_data, mask):
    return [batch_src_data[i] for i in range(len(batch_src_data)) if mask[i]]


def scatter_batched_obj(batch_dst_data, batch_src_data, mask):
    j = 0
    for i in range(len(batch_dst_data)):
        if mask[i]:
            batch_dst_data[i] = batch_src_data[j]
            j += 1
    assert j == len(batch_src_data)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--result-jsonl', type=str, required=True, nargs='+', help='Result JSONL file paths')
    parser.add_argument('--score-func', type=str, default='vllm_qwen_2_5_32b_int8', choices=list(SCORE_FUNCS.keys()) + list(LOCAL_SCORE_FUNCS.keys()))
    parser.add_argument('--interval', type=int, default=10, help='Interval for checking batch job status, in seconds')
    parser.add_argument('--batch-id', type=str, default=None, help='Batch ID for checking batch job status')
    parser.add_argument('--batch-size', type=int, default=1)
    parser.add_argument('--mapper', type=str, default='cot_bench', choices=SCORE_MAPPERS.keys())
    parser.add_argument('--split', type=str, default='train', choices=['train', 'val', 'test'])
    parser.add_argument('--max-num-seqs', type=int, default=256, help='Max number of sequences for VLLM')
    parser.add_argument('--max-model-len', type=int, default=4096, help='Max model length for VLLM')
    parser.add_argument('--tensor-parallel-size', type=int, default=1, help='Tensor parallel size for VLLM')
    parser.add_argument('--pipeline-parallel-size', type=int, default=1, help='Pipeline parallel size for VLLM')
    parser.add_argument('--gpu-memory-utilization', type=float, default=0.9, help='GPU memory utilization for VLLM')
    parser.add_argument('--seed', type=int, default=42, help='Random seed for reproducibility')
    args = parser.parse_args()

    set_seed(args.seed)

    if args.tensor_parallel_size > 1 or args.pipeline_parallel_size > 1:
        os.environ['VLLM_WORKER_MULTIPROC_METHOD'] = 'spawn'

    for result_jsonl in args.result_jsonl:
        try:
            print(f"\nProcessing file: {result_jsonl}")

            len_dataset = len(load_dataset("json", data_files=result_jsonl, split=args.split))
            dataset = load_dataset("json", data_files=result_jsonl, split=args.split, streaming=True)

            if "vstar" in result_jsonl:
                mapper_name = 'vstar_bench'
            else:
                mapper_name = args.mapper

            dataset = dataset.map(lambda x: SCORE_MAPPERS[mapper_name](x, args))

            tmp_score_path = os.path.join(os.path.dirname(result_jsonl), os.path.basename(result_jsonl).replace('.jsonl', f'_{args.score_func}-tmp.jsonl'))
            if check_exists_score_file(tmp_score_path):
                continue
            beg_line = resume_from_path(tmp_score_path)
            beg_batch = beg_line // args.batch_size
            dataloader = DataLoader(dataset, batch_size=args.batch_size, collate_fn=collect_as_batched_obj)
            args.tmp_score_path = tmp_score_path
            print(f"Output to {tmp_score_path}, start from line {beg_line} in batch {beg_batch}")

            if beg_line == 0:
                avg_score = 0.0
                total_num = 0
            else:
                old_datas = load_jsonl(tmp_score_path)
                avg_score = calculate_avg_score(old_datas, args)
                total_num = len(old_datas)
                del old_datas

            with open(tmp_score_path, 'a') as out_fp:
                for bid, batch_data in tqdm(enumerate(dataloader), total=len_dataset//args.batch_size):
                    if bid < beg_batch:
                        continue
                    if bid == beg_batch:
                        skip = beg_line % args.batch_size
                        if skip > 0:
                            print(f"Skip {skip} lines in batch {bid}")
                            batch_data = batch_data[skip:]
                    batch_data = process_batch_data(batch_data, bid, args)
                    post_process_batch_data(batch_data, args)            
                    total_num += len(batch_data)
                    avg_score += (calculate_avg_score(batch_data, args) - avg_score) * len(batch_data) / total_num
                    for one_output in batch_data:
                        out_fp.write(json.dumps(one_output) + '\n')
                    out_fp.flush()

            score_path = tmp_score_path.replace('-tmp', f'-{avg_score:.4f}')
            os.rename(tmp_score_path, score_path)
            print(f"Output to {score_path} done!, final avg score: {avg_score}, total num: {total_num}")

        except Exception as e:
            print(f"Error processing file {result_jsonl}: {str(e)}")
            print("Skipping to next file...")
            continue


if __name__ == "__main__":
    main()

from flask import Flask, request, jsonify
from vllm import LLM, SamplingParams

app = Flask(__name__)
sampling_params = SamplingParams(temperature=0.8, top_p=0.95)
llm = LLM(model="meta-llama/Llama-2-7b-chat-hf", enforce_eager=True)

@app.route('/generate', methods=['POST'])
def generate():
    data = request.get_json()
    prompts = data.get('prompts', [])

    outputs = llm.generate(prompts, sampling_params)

    # Prepare the outputs.
    results = []

    for output in outputs:
        prompt = output.prompt
        generated_text = output.outputs[0].text
        results.append({
            'prompt': prompt,
            'generated_text': generated_text
        })

    return jsonify(results)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

import os
import json
import random
import re
import argparse
import numpy as np
from typing import List, Dict, Set, Tuple
from langchain_openai import AzureOpenAIEmbeddings
from langchain.embeddings import HuggingFaceEmbeddings, CacheBackedEmbeddings
from langchain.storage import LocalFileStore, RedisStore
from langchain_community.vectorstores import FAISS
from vllm import LLM, SamplingParams
from transformers import AutoTokenizer
from src.sparql_utils import get_1hop_relations_with_odbc, get_another_entity, get_label
from src.utils import save_to_json

def load_special_tokens(tokenizer: AutoTokenizer) -> Tuple[Dict, Dict, Dict]:
    """Load special tokens and convert to token IDs."""
    token_sets = [
        ['[Unrelevant]', '[Partially Relevant]', '[Fully Relevant]'],
        ['[Fully Reasonable]', '[Partially Reasonable]', '[Unreasonable]'],
        ['[Utility:5]', '[Utility:4]', '[Utility:3]', '[Utility:2]', '[Utility:1]']
    ]
    return tuple({token: tokenizer.convert_tokens_to_ids(token) for token in tokens} 
                 for tokens in token_sets)

def random_sample(items: List, k: int = 3) -> List:
    """Sample k items randomly from a list."""
    return random.sample(items, min(k, len(items)))

def calculate_metrics(predictions: Set, answers: List) -> Tuple[float, float, float, float]:
    """Calculate precision, recall, F1 score, and hits."""
    correct = sum(1 for entity in predictions if entity in answers)
    total = len(predictions)
    ans_len = len(answers)

    if ans_len == 0:
        return (1.0, 1.0, 1.0, 1.0) if total == 0 else (0.0, 1.0, 0.0, 1.0)

    hits = 1 if correct > 0 else 0
    if total == 0:
        return 1.0, 0.0, 0.0, hits

    precision = correct / total
    recall = correct / ans_len
    f1 = 2.0 / (1.0 / precision + 1.0 / recall) if precision and recall else 0.0
    return precision, recall, f1, hits

def initialize_embeddings(cached: bool, model_name: str, redis_url: str = None) -> CacheBackedEmbeddings:
    """Initialize embeddings with optional caching."""
    embeddings = HuggingFaceEmbeddings(model_name=model_name, encode_kwargs={'normalize_embeddings': False})
    if cached and redis_url:
        store = RedisStore(redis_url=redis_url)
        embeddings = CacheBackedEmbeddings.from_bytes_store(embeddings, store, namespace="bge-large")
    return embeddings

def get_retriever(topic_entities: List[str], use_1hop: bool, cached_embedder: CacheBackedEmbeddings, 
                 all_db: FAISS) -> FAISS:
    """Initialize retriever based on 1-hop relations or full database."""
    if use_1hop:
        relations = set()
        for entity in topic_entities:
            try:
                relations.update(get_1hop_relations_with_odbc(entity))
            except:
                continue
        return FAISS.from_texts(list(relations), cached_embedder).as_retriever(search_kwargs={"k": 5})
    return all_db.as_retriever(search_kwargs={"k": 5})

def process_retrieved_paragraphs(prompt: str, retriever: FAISS, context: str, 
                               llama: str) -> Set[str]:
    """Retrieve and process paragraphs from the prompt."""
    paragraphs = set()
    try:
        query = (prompt.split('\n\n')[1].split('<|eot_id|>')[0] if llama == 'llama3' 
                else prompt.split('[INST]')[1].split('[/INST]')[0].strip()) + ' ' + context
        paragraphs.update(page.page_content.strip() for page in retriever.invoke(query))
    except:
        pass
    return paragraphs

def run_relation_generation_batch(model: LLM, prompt: str, llama: str, context: str, 
                                topic_entities: List[str], hypo: bool, income: str, 
                                cached_embedder: CacheBackedEmbeddings, all_db: FAISS, 
                                sampling_params: SamplingParams, rel_tokens: Dict) -> Tuple[List, List, List]:
    """Generate relation predictions in batch."""
    retriever = get_retriever(topic_entities, use_1hop=True, cached_embedder=cached_embedder, all_db=all_db)
    paragraphs = process_retrieved_paragraphs(prompt, retriever, context, llama)

    if hypo:
        hypo_rel = model.generate(prompt + "[Retrieve Relation]", sampling_params)[0].outputs[0].text
        matches = dict(re.findall(r'(\w+\.\w+\.\w+)\[(.*?)\]', hypo_rel.split('[Retrieve Entity]')[0]))
        paragraphs.update(page.page_content.strip() for page in retriever.invoke(
            ' '.join(k for k, v in matches.items() if v in ['Fully Relevant', 'Partially Relevant'])))

    paragraphs.discard(income)
    aug_prompts = ["<paragraph>{}</paragraph>".format(';'.join(p)) 
                   for p in [list(paragraphs)[i:i+5] for i in range(0, len(paragraphs), 5)]]

    final_preds, scores, contexts = [], [], []
    for pred in model.generate([prompt + "[Retrieve Relation]" + aug for aug in aug_prompts], sampling_params):
        pred_text = pred.outputs[0].text
        pred_text = pred_text.split('[Retrieve Entity]')[0] + '[Retrieve Entity]' if '[Retrieve Entity]' in pred_text else pred_text
        score_dict = process_relation_prediction(pred, rel_tokens)
        final_preds.append("[Retrieve Relation]" + aug_prompts[len(final_preds)] + pred_text)
        scores.append(pred.outputs[0].cumulative_logprob / max(len(pred.outputs[0].token_ids), 1))
        contexts.append(score_dict)

    return final_preds, scores, contexts

def process_relation_prediction(pred, rel_tokens: Dict) -> Dict:
    """Process a single relation prediction."""
    score_dict = {}
    pred_text = pred.outputs[0].text
    pred_log_probs = pred.outputs[0].logprobs
    pred_token_ids = pred.outputs[0].token_ids

    matches = re.findall(r'(\w+\.\w+\.\w+)\[(.*?)\]', pred_text.split('[Retrieve Entity]')[0])
    relevance_indices = [i for i, tok in enumerate(pred_token_ids) if tok in rel_tokens.values()]

    for i, idx in enumerate(relevance_indices[:len(matches)]):
        rel_scores = {token: np.exp(pred_log_probs[idx][token_id].logprob 
                      if token_id in pred_log_probs[idx] else -100) 
                      for token, token_id in rel_tokens.items()}
        score_sum = sum(rel_scores.values())
        score_dict[matches[i][0]] = {
            "relevance": matches[i][1],
            "score": (rel_scores['[Fully Relevant]'] + 0.5 * rel_scores['[Partially Relevant]']) / score_sum
        }
    return score_dict

def run_entity_generation_batch(model: LLM, prompt: str, topic_entities: List[str], context: Dict, 
                              sampling_params: SamplingParams, utility_tokens: Dict, 
                              rel_tokens: Dict, reason_tokens: Dict, tokenizer: AutoTokenizer) -> Tuple[List, List, List, List, Dict, List]:
    """Generate entity predictions in batch."""
    entity_prompts, income_rel, overall_scores, name_to_id = [], [], {}, {}
    effective_count = 0

    for entity in topic_entities:
        for key, relevance in context.items():
            if relevance['relevance'] not in ['Fully Relevant', 'Partially Relevant']:
                continue
            try:
                related_entities = get_another_entity(entity, key, return_label=True)
            except:
                continue

            if related_entities:
                income_rel.append(key)
                name_to_id[effective_count] = related_entities
                overall_scores[effective_count] = {'r_relevance': relevance['score']}
                entities = [f'({get_label(entity)}, {key}, {rel_entity})' 
                           for rel_entity in related_entities.keys()][:5]
                overall_scores[effective_count]['path'] = entities
                entity_prompts.append(f"<paragraph>{';'.join(entities)}</paragraph>")
                effective_count += 1

    predictions = model.generate([f"{prompt}[Retrieve Entity]{ep}" for ep in entity_prompts], sampling_params)
    final_preds, final_entities, final_contexts, scores = [], [], [], []

    for idx, pred in enumerate(predictions):
        pred_output = pred.outputs[0]
        processed_pred, rel_score, reason_score, utility_score, return_entities, matches, rationality, utility = process_prediction(
            idx, pred_output.text, pred_output.logprobs, pred_output.token_ids, 
            r'(.+?)\[(.*?)\]', name_to_id, utility_tokens, rel_tokens, reason_tokens, tokenizer
        )

        overall_scores[idx].update({
            "r_match": {income_rel[idx]: context[income_rel[idx]]},
            "e_match": matches,
            "reason_score": reason_score,
            "rationality": rationality,
            "utility": utility,
            "utility_score": utility_score,
            "seq_score": pred_output.cumulative_logprob / max(len(pred_output.token_ids), 1),
            "final_score": rel_score * overall_scores[idx]['r_relevance'] * reason_score
        })

        final_preds.append(f"[Retrieve Entity]{entity_prompts[idx]}{processed_pred}")
        final_entities.append(list(return_entities.values()))
        final_contexts.append(' '.join(return_entities.keys()))
        scores.append(overall_scores[idx]['final_score'])

    return final_preds, scores, final_entities, final_contexts, overall_scores, income_rel

def process_prediction(idx: int, pred_text: str, pred_log_probs: List, pred_token_ids: List, 
                      pattern: str, name_to_id: Dict, utility_tokens: Dict, 
                      rel_tokens: Dict, reason_tokens: Dict, tokenizer: AutoTokenizer) -> Tuple:
    """Process a single entity prediction."""
    rel_score, reason_score, utility_score = 0, 0, 0
    rationality, utility = '', ''
    return_entities = {}

    relevance_indices = [i for i, tok in enumerate(pred_token_ids) if tok in rel_tokens.values()]
    reason_indices = [i for i, tok in enumerate(pred_token_ids) if tok in reason_tokens.values()]
    utility_indices = [i for i, tok in enumerate(pred_token_ids) if tok in utility_tokens.values()]

    if '[Retrieve Relation]' in pred_text:
        processed_pred = pred_text.split('[Retrieve Relation]')[0].strip() + '[Retrieve Relation]'
        matches = dict(re.findall(pattern, processed_pred))
        for key, relevance in matches.items():
            if relevance.strip() in ['Fully Relevant', 'Partially Relevant']:
                if key in name_to_id[idx]:
                    return_entities[key] = name_to_id[idx][key]
                elif key.strip() == 'Unknown Entity':
                    for random_key in random_sample(list(name_to_id[idx].keys())):
                        return_entities[random_key] = name_to_id[idx][random_key]
    elif '[No Retrieval]' in pred_text:
        processed_pred = pred_text
        matches = dict(re.findall(pattern, pred_text.split('[No Retrieval]')[0]))
        if utility_indices:
            uti_scores = {token: np.exp(pred_log_probs[utility_indices[0]][token_id].logprob 
                         if token_id in pred_log_probs[utility_indices[0]] else -100) 
                         for token, token_id in utility_tokens.items()}
            ut_sum = sum(uti_scores.values())
            if len(uti_scores) == 5:
                utility_score = sum(i * (uti_scores[f"[Utility:{i}]"] / ut_sum) 
                                  for i in range(1, 6)) / 5
            utility = tokenizer.convert_ids_to_tokens(pred_token_ids[utility_indices[0]])
    else:
        matches = {}
        processed_pred = '[No Retrieval]Answer: None'

    if relevance_indices:
        rel_scores = {token: np.exp(pred_log_probs[idx][token_id].logprob 
                     if token_id in pred_log_probs[idx] else -100) 
                     for token, token_id in rel_tokens.items()}
        rl_sum = sum(rel_scores.values())
        rel_score = max((rel_scores['[Fully Relevant]'] + 0.5 * rel_scores['[Partially Relevant]']) / rl_sum, rel_score)

    if reason_indices:
        reason_scores = {token: np.exp(pred_log_probs[reason_indices[0]][token_id].logprob 
                        if token_id in pred_log_probs[reason_indices[0]] else -100) 
                        for token, token_id in reason_tokens.items()}
        rs_sum = sum(reason_scores.values())
        reason_score = (reason_scores['[Fully Reasonable]'] + 0.5 * reason_scores['[Partially Reasonable]']) / rs_sum
        rationality = tokenizer.convert_ids_to_tokens(pred_token_ids[reason_indices[0]])

    return processed_pred, rel_score, reason_score, utility_score, return_entities, matches, rationality, utility

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--model_name', type=str, default='/media/disk2/llama_factory/generation_0202_uti_no_mask/')
    parser.add_argument('--world_size', type=int, default=1)
    parser.add_argument('--cached_embedding', action='store_false', default=True)
    parser.add_argument('--input_file', type=str, default='./data/merged/WebQSP_test.json')
    parser.add_argument('--output_file', type=str, default='./output/inference/webqsp_code_0111_res.json')
    parser.add_argument('--max_new_tokens', type=int, default=100)
    parser.add_argument('--save_output', action='store_true')
    args = parser.parse_args()

    # Initialize model and resources
    tokenizer = AutoTokenizer.from_pretrained(args.model_name)
    rel_tokens, reason_tokens, utility_tokens = load_special_tokens(tokenizer)
    model = LLM(model=args.model_name, trust_remote_code=True, tensor_parallel_size=args.world_size)
    embeddings = initialize_embeddings(args.cached_embedding, "BAAI/bge-large-en-v1.5", "redis://localhost:6379")

    with open('./data/clean_relations', 'r') as f:
        all_db = FAISS.from_texts([line.strip() for line in f], embeddings)

    sampling_params = SamplingParams(temperature=0.0, top_p=1.0, max_tokens=args.max_new_tokens, 
                                  logprobs=5, skip_special_tokens=False, include_stop_str_in_output=True)
    PROMPT_DICT = {
        "llama3": '<|begin_of_text|><|start_header_id|>user<|end_header_id>\n\n{input}<|eot_id|><|start_header_id|>assistant<|end_header_id>',
        "llama2": "<s>[INST] {input} [/INST]"
    }

    with open(args.input_file, 'r', encoding='utf-8') as f:
        test_data = json.load(f)

    precisions, recalls, f1s, hits, logging_res = [], [], [], [], []

    for index in range(min(10, len(test_data))):
        print(f'Processing {index}')
        data_input = test_data[index]['question']
        prompt = PROMPT_DICT['llama3'].format(input=data_input)
        topic_entities = list(test_data[index]['gold_entity_map'].keys())
        prediction_tree = {
            0: {
                "prompt": prompt, "pred": "[Retrieve Relation]", "processed_pred": "",
                "score": None, "topic_entity": topic_entities, "parent": None,
                "context": "", "income": "", "depth": 0
            }
        }
        levels = {0: [0]}
        curr_depth = 1
        node_id = 0
        max_depth = 5

        while curr_depth < max_depth:
            levels[curr_depth] = []
            for node in levels.get(curr_depth-1, []):
                node_data = prediction_tree[node]
                if "<|eot_id|>" in node_data["pred"] or 'No Retrieval' in node_data["pred"]:
                    continue

                cur_prompt = node_data["prompt"] + node_data["processed_pred"]
                score = node_data["score"] or 0

                if "Retrieve Entity" in node_data["pred"].split('[')[-1]:
                    preds, scores, next_entities, contexts, overall_scores, income_rel = run_entity_generation_batch(
                        model, cur_prompt, node_data["topic_entity"], node_data["context"],
                        sampling_params, utility_tokens, rel_tokens, reason_tokens, tokenizer
                    )
                    for i, (pred, p_score, next_topic, context, rel) in enumerate(zip(preds, scores, next_entities, contexts, income_rel)):
                        node_id += 1
                        node_score = (p_score + score) / (curr_depth // 2 + 1)
                        next_entity = next_topic if next_topic else node_data["topic_entity"]
                        prediction_tree[node_id] = {
                            "prompt": cur_prompt, "pred": pred, "context": context,
                            "score": node_score, "parent": node, "topic_entity": next_entity,
                            "income": rel, "verbose": {
                                "path": overall_scores[i]['path'], "e_match": overall_scores[i]['e_match'],
                                "r_match": overall_scores[i]['r_match'], "reason_score": overall_scores[i]['reason_score'],
                                "rationality": overall_scores[i]['rationality'], "utility": overall_scores[i]['utility'],
                                "utility_score": overall_scores[i]['utility_score'], "seq_score": overall_scores[i]['seq_score']
                            }, "depth": curr_depth
                        }
                        prediction_tree[node_id]["processed_pred"] = pred.split("[Retrieve Relation]")[0] if "[Retrieve Relation]" in pred else pred
                        levels[curr_depth].append(node_id)

                if "Retrieve Relation" in node_data["pred"].split('[')[-1]:
                    preds, scores, contexts = run_relation_generation_batch(
                        model, cur_prompt, 'llama3', node_data["context"], node_data["topic_entity"],
                        hypo=False, income=node_data["income"], cached_embedder=embeddings, 
                        all_db=all_db, sampling_params=sampling_params, rel_tokens=rel_tokens
                    )
                    for i, (pred, p_score, context) in enumerate(zip(preds, scores, contexts)):
                        node_id += 1
                        node_score = p_score + score if score is not None else p_score
                        prediction_tree[node_id] = {
                            "prompt": cur_prompt, "pred": pred, "score": node_score,
                            "parent": node, "topic_entity": node_data["topic_entity"],
                            "context": context, "income": node_data["income"], "depth": curr_depth
                        }
                        prediction_tree[node_id]["processed_pred"] = pred.split("[Retrieve Entity]")[0] if "[Retrieve Entity]" in pred else pred
                        levels[curr_depth].append(node_id)

            if not levels[curr_depth]:
                break
            levels[curr_depth] = [node for node, _ in sorted(
                [(n, prediction_tree[n]["score"]) for n in levels[curr_depth]],
                key=lambda x: x[1], reverse=True)][:3]
            curr_depth += 1

        labels = [get_label(ans) if ans.startswith('m.') else ans for ans in test_data[index]['answer']]
        end_nodes = [n for n, node in prediction_tree.items() if 'Answer' in node['processed_pred']]

        queues = []
        for n_ind in end_nodes:
            queue = []
            node = prediction_tree[n_ind]
            answer = node['processed_pred'].split('Answer:')[-1]
            score = node['score'] + (0.5 * (node['verbose']['utility_score'] + 1) + node['verbose']['seq_score']
                                   if 'verbose' in node else 0)
            while node:
                if 'verbose' in node:
                    queue.append(node['verbose'])
                node = prediction_tree[node['parent']] if node['parent'] is not None else None
            queues.append({'verbose': queue, "answer": answer, "score": score})

        answers = set()
        for q in sorted(queues, key=lambda x: x['score'], reverse=True)[:3]:
            candidates = q['answer'].strip().split(';')
            answers.update(re.findall(r'(.+?)\[(.*?)\]', c)[0][0] for c in candidates 
                          if re.findall(r'(.+?)\[(.*?)\]', c))

        precision, recall, f1, hit = calculate_metrics(answers, labels)
        if hit == 1:
            print(f'Correct {index}')
        precisions.append(precision)
        recalls.append(recall)
        f1s.append(f1)
        hits.append(hit)
        logging_res.append({"index": index, "tree": prediction_tree})

        if len(logging_res) == 20:
            save_to_json(logging_res, './output/inference/cwq_test_top3_0214_beam3_k5_detph9_wohyper2.json')
            logging_res = []

    print('============================ Output Result Analysis =============================')
    print(f'Test data length: {len(test_data)}')
    print(f'Average F1: {np.mean(f1s):.4f}')
    print(f'Average Hits: {np.mean(hits):.4f}')

if __name__ == "__main__":
    main()

import json
import os
from tqdm import tqdm
from transformers import AutoProcessor
from qwen_vl_utils import process_vision_info
from vllm import LLM, SamplingParams

def batch_generator(data, batch_size):
    for i in range(0, len(data), batch_size):
        yield data[i:i + batch_size]

def build_prompt(processor, item, key, image_path, batch_prompt, processed_batch):
    question = item[key]
    if image_path is None:
        messages = [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": question},
                ],
            }
        ]
        prompt = processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)

        prompt = {
            "prompt": prompt,
        }
    else:
        messages = [
            {
                "role": "user",
                "content": [
                    {
                        "type": "image",
                        "image": image_path,
                    },
                    {"type": "text", "text": question},
                ],
            }
        ]
        prompt = processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        image_inputs, _ = process_vision_info(messages)

        prompt = {
            "prompt": prompt,
            "multi_modal_data": {"image": image_inputs},
        }
        batch_prompt.append(prompt)
        processed_batch.append(item)
        return batch_prompt, processed_batch

def run_qwen_image_features(config, data):
    llm = LLM(
        model=config['model_path'],
        limit_mm_per_prompt={"image": 1},
        tensor_parallel_size=config['tensor_parallel_size'],
        gpu_memory_utilization=0.9,
        enforce_eager = True
    )
    sampling_params = SamplingParams(
        temperature= 0.0,
        max_tokens=1024,
        skip_special_tokens=True
    )
    processor = AutoProcessor.from_pretrained(config['model_path'])
    total_batches = (len(data) + config['batch_size'] - 1) // config['batch_size']

    batches = tqdm(
        batch_generator(data, config['batch_size']),
        total=total_batches,
        desc="Batch Processing",
        leave=True
    )
    results = []

    for batch in batches:
        batch_prompt = []
        processed_batch = []
        for item in batch:  
            if config['image_dir'] is not None:
                img_path = os.path.join(config['image_dir'], item[config['image_key']].lstrip('/'))
            else:
                img_path = item[config['image_key']]
            if not os.path.exists(img_path):
                continue
            batch_prompt, processed_batch = build_prompt(processor, item, config['query_key'], img_path, batch_prompt, processed_batch)
        outputs = llm.generate(
            prompts=batch_prompt,
            sampling_params=sampling_params,
        )

        for idx, (input_data, output) in enumerate(zip(processed_batch, outputs)):
            result_entry = input_data
            result_entry[config['output_key']] = output.outputs[0].text if output.outputs else ""
            results.append(result_entry)
    return results

import json
import os
import argparse
from tqdm import tqdm
from transformers import AutoProcessor
from qwen_vl_utils import process_vision_info
from vllm import LLM, SamplingParams
import yaml
import ray
import torch
import copy

def batch_generator(data, batch_size):
    for i in range(0, len(data), batch_size):
        yield data[i:i + batch_size]

def build_prompt(processor, item, key, image_path, batch_prompt, processed_batch):
    dialog_list = copy.deepcopy(item[key])
    messages = []
    if image_path is None:
        for text in dialog_list:
            text['content'] = [{"type": "text", "text": text['content']}]
            messages.append(text)
        prompt = processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        prompt = {
            "prompt": prompt,
        }
    else:
        for idx, text in enumerate(dialog_list):
            if idx == 0:
                text['content'] = [
                        {
                            "type": "image",
                            "image": image_path,
                        },
                        {"type": "text", "text": text['content']},
                    ]
            else:
                text['content'] = [
                        {"type": "text", "text": text['content']},
                    ]
            messages.append(text)
        raw_prompt = processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        image_inputs, _ = process_vision_info(messages)

        prompt = {
            "prompt": raw_prompt,
            "multi_modal_data": {"image": image_inputs},
        }
    processed_batch.append(item)
    batch_prompt.append(prompt)
    return batch_prompt, processed_batch

def run_qwen_chat(config, data):
    llm = LLM(
        model=config['model_path'],
        limit_mm_per_prompt={"image": 1},
        tensor_parallel_size=config['tensor_parallel_size'],
        gpu_memory_utilization=0.9,
        trust_remote_code=True
    )
    sampling_params = SamplingParams(
        temperature=0.0,
        max_tokens=1024,
        skip_special_tokens=True
    )
    processor = AutoProcessor.from_pretrained(config['model_path'])
    total_batches = (len(data) + config['batch_size'] - 1) // config['batch_size']

    batches = tqdm(
        batch_generator(data, config['batch_size']),
        total=total_batches,
        desc="Batch Processing",
        leave=True
    )
    results = []

    for batch in batches:
        batch_prompt = []
        processed_batch = []
        for item in batch:  
            if config['image_dir'] is not None:
                img_path = os.path.join(config['image_dir'], item[config['image_key']].lstrip('/'))
            else:
                img_path = item[config['image_key']]
            # if not os.path.exists(img_path):
            #     # raise FileNotFoundError(f"Missing Image: {img_path}")
            #     continue
            if config['query_key'] in item.keys():
                batch_prompt, processed_batch = build_prompt(processor, item, config['query_key'], img_path, batch_prompt, processed_batch)
        outputs  = llm.generate(
            prompts=batch_prompt,
            sampling_params=sampling_params,
        )
        for idx, (input_data, output) in enumerate(zip(processed_batch, outputs)):
            input_data[config['output_key']] = output.outputs[0].text if output.outputs else ""
            results.append(input_data)

    return results

import argparse
import os
import json
import torch
from tqdm import tqdm
import yaml
from vllm import LLM, SamplingParams
from PIL import Image
import ray
from transformers import AutoProcessor
import copy


def batch_generator(data, batch_size):
    for i in range(0, len(data), batch_size):
        yield data[i:i + batch_size]

def build_prompt(processor, item, key, image_path, batch_prompt, processed_batch):
    print(item['id'])
    dialog_list =copy.deepcopy(item[key])
    messages = []
    if image_path == None:
        for text in dialog_list:
            text['content'] = [{"type": "text", "text": text['content']}]
            messages.append(text)
        raw_prompt = processor.apply_chat_template(messages, add_generation_prompt=True)
        prompt = {
            "prompt": raw_prompt,
        }

    else:
        has_image = any('<image>' in item.get('content', '') for item in dialog_list)
        if has_image:
            return batch_prompt, processed_batch
        for idx, text in enumerate(dialog_list):
            if idx == 0:
                text['content'] = [
                        {
                            "type": "image",
                            "image": image_path,
                        },
                        {"type": "text", "text": text['content']},
                    ]
            else:
                text['content'] = [
                        {"type": "text", "text": text['content']},
                    ]
            messages.append(text)
        raw_prompt = processor.apply_chat_template(messages, add_generation_prompt=True, tokenize=False)
        raw_image = Image.open(image_path)
        img_rgb = raw_image.convert('RGB')
        prompt = {
            "prompt": raw_prompt,
            "multi_modal_data": {"image": img_rgb},
        }
    processed_batch.append(item)
    batch_prompt.append(prompt)
    return batch_prompt, processed_batch


def run_llava_chat(config, queries):
    llm = LLM(
        model=config['model_path'],
        limit_mm_per_prompt={"image": 1},
        tensor_parallel_size=config['tensor_parallel_size'],
        gpu_memory_utilization=0.9,
        trust_remote_code=True,
        max_model_len=4096, 
        max_num_seqs=20  
    )
    sampling_params = SamplingParams(
        temperature=0.0,
        max_tokens=1024,
        skip_special_tokens=True
    )
    processor = AutoProcessor.from_pretrained(config['model_path'],trust_remote_code=True)
    total_batches = (len(queries) + config['batch_size'] - 1) // config['batch_size']

    batches = tqdm(
        batch_generator(queries, config['batch_size']),
        total=total_batches,
        desc="Batch Processing",
        leave=True
    )
    results = []
    for batch in batches:
        batch_prompt = []
        processed_batch = []
        for item in batch:  
            if config['image_dir'] is not None:
                img_path = os.path.join(config['image_dir'], item[config['image_key']].lstrip('/'))
            else:
                img_path = item[config['image_key']]
            if config['query_key'] in item.keys():
                batch_prompt, processed_batch = build_prompt(processor, item, config['query_key'], img_path, batch_prompt, processed_batch)

        outputs = llm.generate(
            prompts=batch_prompt,
            sampling_params=sampling_params,
        )

        for idx, (input_data, output) in enumerate(zip(processed_batch, outputs)):
            input_data[config['output_key']] = output.outputs[0].text if output.outputs else ""
            results.append(input_data)

    return results

