def base_wo_retri(question):
    prompt=f'Answer this question :\n{question}\nGive me only the answer without including any other words.\n\nAnswer:'
    if args.dataset=="bioasq":
        prompt=f'ANSWER "yes" OR "no" ONLY (You have to choose the most likely option).\nAnswer:'
    answer=call_llm(prompt)
    return answer



class Search_Engine:
    def __init__(self, dataset,topk):
        self.dataset = dataset
        self.topk = topk

    @staticmethod
    def introduction():
        return """{"name":"Search_Engine", "description":"This is a knowledge base general search engine that can be used to query external knowledge, learn facts, etc.", "input":"The phrase or question to be searched."}"""

    @retry((Exception), delay=1, backoff=2, max_delay=10,jitter=(1, 10))  
    def call(self,query):
        query=str(query).strip('"')
        try:
            with DDGS(timeout=60, proxy=None, verify=False) as ddgs:
                result=[f"""title:{r["title"]}\ncontent:{r["body"]}""" for r in ddgs.text(query, region='wt-wt', safesearch='off',max_results=self.topk)]
        except DuckDuckGoSearchException as e:
            if "return None" in str(e):
                print(f"Caught specific DuckDuckGoSearchException: {e}")
                result = "No related information was found."
                return result
            else:
                raise e
        return "\n\n".join(result)

class Search_Prefer_Local:
    def __init__(self, dataset,topk):
        self.dataset = dataset
        self.topk = topk

    @staticmethod
    def introduction():
        return """{"name":"Search_Prefer_Local", "description":"This is a local knowledge base general search engine that can be used to query external knowledge, learn facts, etc.", "input":"The phrase or question to be searched."}"""

    def call(self,query):
        query=str(query).strip('"')
        refs = retrieve(self.dataset, query=query, topk=self.topk)
        return "\n\n".join(refs)



class Pref:
    def __init__(self, max_step=3, tools=[]):

        self.tools = tools
        self.max_step = max_step

    def call(self,question):

        return self.gen_answer(question)

    def gen_answer(self,question):

        prompt_template = Template(config["prompt"]["prefrag"])
        answer_try_search = False
        output_process, observations_logs, evaluation_process = [], [], []
        i = 0
        while i <= self.max_step:
            prompt = prompt_template.render(
                answer_format=answer_format, max_step=self.max_step,
                question=question, tools=self.tools, thought="\n".join(output_process)
            ).strip()
            output=call_llm(prompt,stop=["Observation:","Observation:\n"])
            answer = self.extract_final_answer(output)
            action, action_input = self.extract_action_info(output)

            if answer:
                self_evaluation_match=self.extract_self_evaluation(output)
                if self_evaluation_match and ('PARTIALLY CORRECT' in self_evaluation_match or 'INCORRECT' in self_evaluation_match):
                    if not answer_try_search:

                            evaluation_process.append(output)
                            i-=1 
                            search_info_local = Search_Prefer_Local(args.dataset,args.retrieve_top_k).call(question)
                            search_info = Search_Engine(args.dataset,args.retrieve_top_k).call(question)
                            search_info=search_info_local+search_info
                            observations_logs.append({"info":search_info,"type":"web"})
                            output_process.extend([output + "\nObservation:", search_info])
                            answer_try_search = True
                            continue
                output_process.append(output)
                return (answer.strip(),'\n'.join(output_process))
            if action and action_input:
                tool = next((t for t in self.tools if t.__name__.lower() in action.lower()), None)
                if tool:
                    observation = self.prefer_retrieval(question,action_input,observations_logs)
                    observations_logs.append({"info":observation})
                    if "Observation" not in output:
                        output+="Observation:"   
                    output_process.extend([output, observation])
            elif "Observation" not in output or "Action" not in output:
                break
            i += 1
        thoughts_str='\n'.join(output_process)
        prompt=thoughts_str+base_format.format(question=question)
        output=call_llm(prompt)
        answer=self.extract_final_answer("Final Answer:"+output)
        if not answer:
            answer=output.strip(":").strip()
        thoughts_str+=f"Final Answer:{answer}"
        return (answer,thoughts_str)

    def prefer_retrieval(self,question,new_q,obser_logs):
        if not obser_logs:
            observation=Search_Prefer_Local(args.dataset,args.retrieve_top_k).call(new_q)
            return observation
        observation=Search_Prefer_Local(args.dataset,args.retrieve_top_k).call(new_q)
        existed_info="\n".join([d["info"] for d in obser_logs])
        template = config["prompt"]["prefer_retrieval"]
        prompt = template.format(question=question, existed_info=existed_info, observation=observation).strip()

        response=call_llm(prompt)
        try:    
            if 'json' in response:
                response = response[response.index('{'):response.rindex('}')+1]

            result=json.loads(response)
            res=result["status"] 

            if res.lower()=="true":
                return observation
        except:
            match=re.search("True|true",response)
            if match:
                return observation
        observation=Search_Engine(args.dataset,args.retrieve_top_k).call(new_q)
        return observation

    @staticmethod
    def extract_self_evaluation(output):
        match = re.search(r"Self-Evaluation\s*:\s*(.+?)(?:\s|$)Explanation", output, re.IGNORECASE | re.MULTILINE | re.DOTALL)
        if match:
            return match.group(1).strip()

        return output

    @staticmethod
    def extract_final_answer(output):
        matches = re.findall(r"Final Answer\s*:\s*(.*?)(?:\n\s*Self-Evaluation|Explanation:|Observation:|Thought:|$)", output, re.IGNORECASE | re.DOTALL)

        if matches:
            return matches[-1].strip(":").strip()
        elif "Self-Evaluation:" in output:
            match = re.search(r"(.*?)(?:\n\s*Self-Evaluation|$)", output, re.IGNORECASE | re.DOTALL)
            if match:
                return match.group(1).strip(":").strip()
        return None

    @staticmethod
    def extract_action_info(output):
        action_match = re.search(r"Action\s*:\s*(.*)", output, re.IGNORECASE)
        action_input_match = re.search(r"Action Input\s*:\s*(\".*?\"|.*?)\s*(?=Observation:|Thought:|Final Answer:|Self-Evaluation:|$)", output, re.IGNORECASE | re.DOTALL)

        if action_match and action_input_match:
            action=action_match.group(1).strip()
            action_input=action_input_match.group(1).strip()
            if "none" not in [action.lower(),action_input.lower()]:
                return action, action_input
        return None, None


if __name__ == "__main__":
    args = parser.parse_args()
    seed_everything(44)

    answer_format=config["prompt"]["answer_format"]
    base_format=config["prompt"]["base_answer_format"]

    if args.dataset=="bioasq":
        answer_format=config["prompt"]["bio_answer_format"]
        base_format=config["prompt"]["bio_base_answer_format"]

    if args.retrieve_method=="emb":

        vector = faiss.read_index(f"../data/corpus/{args.dataset}/{args.dataset}.index")   
        emb_model = SentenceTransformer(
            config["model"]["bge-large-en-v1.5"], device=args.device
        )
        with open(f"../data/corpus/{args.dataset}/chunk.json", encoding="utf-8") as f:
            raw_data = json.load(f)

        def retrieve(_, query, topk):
            feature = emb_model.encode([query])
            _, match_id = vector.search(feature, topk)
            return [raw_data[i] for i in match_id[0]]


    if "gpt" in args.model or args.model in ["glm-4-plus"]:
        from utils import api_gen
        call_llm = call_api
    else:
        llm = LLM(model=config["model"][args.model], tensor_parallel_size=1, trust_remote_code=True, dtype='bfloat16', gpu_memory_utilization=args.gpu_memory_utilization)

        call_llm = call_vllm

    prefrag=Pref(tools=[Search_Engine],max_step=args.max_step)

    logger = logging.getLogger(__name__)
    logging.basicConfig(
        format="%(asctime)s - %(levelname)s - %(name)s -   %(message)s",
        datefmt="%m/%d/%Y %H:%M:%S",
        level=logging.INFO,
    )
    save_log_to_file(
        logger,
        log_file=f"{args.dataset}_{args.method}_{args.model}",
        log_folder="../log",
    )
    logger.info(f"{'*' * 30} CONFIGURATION {'*' * 30}")
    for key, val in sorted(vars(args).items()):
        keystr = "{}".format(key) + (" " * (30 - len(key)))
        logger.info("%s -->   %s", keystr, val)

    formatted_time = time.strftime("%Y%m%d-%H%M%S")

    with open(f"../data/eval/{args.dataset}/test.json", encoding="utf-8") as f:
        qa_data = json.load(f)

    save_path = f"../output/{args.dataset}/{args.method}/{args.model}/{args.retrieve_method}"
    os.makedirs(save_path, exist_ok=True)

    all_result = []

    if args.resume_path:
        with open(args.resume_path, "r", encoding="utf-8") as fin:
            resume_data = [json.loads(i) for i in fin.readlines()]
            all_result = resume_data
            filepath = args.resume_path
    else:
        resume_data = []
        if args.method=="prefrag":
            filepath = (
                f"{save_path}/topk-{args.retrieve_top_k}_max_step-{args.max_step}_{formatted_time}.jsonl"
            )
        else:
            filepath = (
                f"{save_path}/topk-{args.retrieve_top_k}_{formatted_time}.jsonl"
            )
    logger.info(f"The predicted results will be saved in '{filepath}'.")
    last_id = len(resume_data)
    batch_size = args.MaxClients
    for bid in tqdm(range(last_id, len(qa_data), batch_size)):
        pool = ThreadPool(processes=args.MaxClients)
        current_batch = qa_data[bid : bid + batch_size]
        tasks = [
            (cb["question"],) for cb in current_batch
        ]
        if args.method=="prefrag":
            outputs = pool.starmap(prefrag.call, tasks)
        elif args.method=="base_local":
            outputs = pool.starmap(base_local, tasks)
        elif args.method=="base_web":
            outputs = pool.starmap(base_web, tasks)
        elif args.method=="base_local_web":
            outputs = pool.starmap(base_local_web, tasks)
        elif args.method=="base_wo_retri":
            outputs = pool.starmap(base_wo_retri, tasks)
        pool.close()
        pool.join()

        for id,output in enumerate(outputs):
            if output:
                if args.method=="prefrag":
                    result={"id": bid+id, "question": current_batch[id]["question"], "answer": current_batch[id]["answer"], "output": output[0],"thoughts": output[1]}
                else:
                    result={"id": bid+id, "question": current_batch[id]["question"], "answer": current_batch[id]["answer"], "output": output}
                all_result.append(result)
                with open(filepath, "a", buffering=1) as fout:
                    fout.write(json.dumps(result, ensure_ascii=False) + "\n")

    predictions = [data["output"] for data in all_result]
    answers = [data["answer"] for data in all_result]
    if args.dataset == "bioasq":
        eval_result = {"Acc": acc_score_yn(predictions, answers)}
    else:
        eval_result = {"Acc": acc_score(predictions, answers), "F1": F1_scorer(predictions, answers), "EM": compute_exact(predictions, answers)}
    if eval_result:
        with open(filepath, "a", buffering=1) as fout:
            fout.write(json.dumps(eval_result, ensure_ascii=False) + "\n")

    logger.info(f"eval result: {eval_result}")

import os
import torch
import openai
import asyncio
import itertools
from logging import getLogger
from abc import ABC, abstractmethod
from dataclasses import asdict

import backoff
import copy
from typing import List, Dict, Any, Tuple
from transformers import AutoModelForCausalLM, AutoTokenizer
from vllm import LLM, SamplingParams, RequestOutput
from openai import AzureOpenAI
from openai.types.completion_choice import CompletionChoice

try:
    import anthropic
    import anthropic.types.message as anthropic_message
except ImportError:
    pass

from .api import SampleParams
from .tokenizer_utils import TiktokenHuggingFaceTokenizer
from .config_store import model_configs, cs
from .registry_utils import Registry


LOGGER = getLogger(__name__)


def parse_api_output(response: openai.types.Completion) -> List[Dict[str, Any]]:
    parsed_responses = [
        {"text": response.message.content, "decode_id": response.index}
        for response in response.choices
    ]
    return parsed_responses


def parse_anthropic_output(
    responses,
) -> List[Dict[str, Any]]:
    parsed_responses = [
        {"text": response.content[0].text, "decode_id": rid}
        for response, rid in responses
    ]
    return parsed_responses


def parse_vllm_output(responses: List[RequestOutput]) -> List[Dict[str, Any]]:
    def extract_single(output: RequestOutput):
        res = [
            {
                "text": out.text,
                # "token": out.token_ids,
                "decode_id": out.index,
                "len": len(out.token_ids),
            }
            for out in output.outputs
        ]
        return res

    parsed_response = [
        extract_single(response) for response in responses if response is not None
    ]

    return parsed_response


class LanguageModel(ABC):
    API_URL = None
    api_key = None
    model = None
    sample_params = None
    tokenizer = None

    @abstractmethod
    def generate(self):
        pass

    @abstractmethod
    def batch_generate(self):
        pass


class VLLMLanguageModel(LanguageModel):
    # This is a synchronize VLLM engine that runs on locally.
    def __init__(self, model, sample_params, tokenizer=None):
        self.model_name = model
        self.model = None  #! We delay the model initilziation
        self.sample_params = asdict(sample_params)
        if tokenizer is None:
            self.tokenizer = AutoTokenizer.from_pretrained(self.model_name)
        else:
            self.tokenizer = tokenizer

    def prepare_sampling_params(
        self,
        max_tokens: int = None,
        temperature: float = None,
        top_p: float = None,
        frequency_penalty: float = None,
        presence_penalty: float = None,
        stop: str = None,
        n: int = None,
    ) -> SamplingParams:
        final_sample_params = copy.deepcopy(self.sample_params)
        final_sample_params.update(
            {
                k: v
                for k, v in locals().items()
                if v is not None and k in self.sample_params
            }
        )

        def convert_naming(dicts: Dict[str, Any]) -> Dict[str, Any]:
            name_mapping = {}
            result = {}

            for k, v in dicts.items():
                if k in name_mapping:
                    result[name_mapping[k]] = v
                else:
                    result[k] = v
            return result

        final_sample_params = SamplingParams(**convert_naming(final_sample_params))
        return final_sample_params

    def generate(
        self,
        prompt: str,
        max_tokens: int = None,
        temperature: float = None,
        top_p: float = None,
        frequency_penalty: float = None,
        presence_penalty: float = None,
        stop: str = None,
        n: int = None,
    ):
        if self.model is None:
            ALL_GPU = os.environ.get("ALL_GPU", False)
            if ALL_GPU:
                gpus = torch.cuda.device_count()
            else:
                gpus = 1
            hostname = os.uname()[1]
            disable_custom_all_reduce = "bluevela" in hostname
            self.model = LLM(
                self.model_name,
                enable_prefix_caching=True,
                enable_chunked_prefill=True,
                swap_space=8,
                tensor_parallel_size=gpus,
                disable_custom_all_reduce=disable_custom_all_reduce,
            )

        sample_params = self.prepare_sampling_params(
            max_tokens,
            temperature,
            top_p,
            frequency_penalty,
            presence_penalty,
            stop,
            n,
        )
        outputs = self.model.generate(prompt, sample_params)
        outputs: List[RequestOutput]
        outputs = parse_vllm_output(outputs)
        return outputs

    def batch_generate(
        self,
        prompts: List[str],
        max_tokens: int = None,
        temperature: float = None,
        top_p: float = None,
        frequency_penalty: float = None,
        presence_penalty: float = None,
        stop: str = None,
        n: int = None,
    ):
        return self.generate(
            prompts,
            max_tokens,
            temperature,
            top_p,
            frequency_penalty,
            presence_penalty,
            stop,
            n,
        )


class APILanguageModel(LanguageModel):
    API_URL = "https://api.openai.com/v1/"

    def __init__(
        self,
        API_URL=None,
        api_key=None,
        model=None,
        sample_params=None,
        user_stop_token=None,
        tokenizer=None,
    ):
        self.API_URL = API_URL
        self.api_key = api_key
        self.model_name = model
        self.sample_params = asdict(sample_params) if sample_params is not None else {}
        self.tokenizer = tokenizer
        self.user_stop_token = user_stop_token

        self.client: openai.Client = openai.Client(
            api_key=self.api_key,
            base_url=self.API_URL,
        )

    def __repr__(self):
        return f"APILanguageModel({self.model_name}, port={self.API_URL})"

    @backoff.on_exception(backoff.expo, openai.OpenAIError, max_time=60, max_tries=3)
    def generate(
        self,
        prompt: str,
        max_tokens: int = None,
        temperature: float = None,
        top_p: float = None,
        frequency_penalty: float = None,
        presence_penalty: float = None,
        stop: str = None,
        n: int = None,
    ):
        final_sample_params = copy.deepcopy(self.sample_params)
        final_sample_params.update(
            {
                k: v
                for k, v in locals().items()
                if v is not None and k in self.sample_params
            }
        )

        try:
            response = self.client.completions.create(
                model=self.model_name,
                prompt=prompt,
                **final_sample_params,
            )
            return parse_api_output(response)
        except openai.OpenAIError as e:
            LOGGER.error(f"OpenAIError: {e}")
            raise
        except Exception as e:
            LOGGER.error(f"Unexpected error: {e}")
            raise

    def batch_generate(
        self,
        prompts: List[str],
        max_tokens: int = None,
        temperature: float = None,
        top_p: float = None,
        frequency_penalty: float = None,
        presence_penalty: float = None,
        stop: str = None,
        n: int = None,
        return_text: bool = True,
    ):
        if not isinstance(prompts[0], list):
            prompts = [prompts]
        results = [
            self.generate(
                prompt,
                max_tokens,
                temperature,
                top_p,
                frequency_penalty,
                presence_penalty,
                stop,
                n,
            )
            for prompt in prompts
        ]

        return results


class GPTLanguageModel(APILanguageModel):
    @backoff.on_exception(backoff.expo, openai.OpenAIError, max_time=10, max_tries=3)
    def generate(
        self,
        prompt: str,
        max_tokens: int = None,
        temperature: float = None,
        top_p: float = None,
        frequency_penalty: float = None,
        presence_penalty: float = None,
        stop: str = None,
        n: int = None,
    ):
        # This function calls the API for one input prompt
        final_sample_params = copy.deepcopy(self.sample_params)
        final_sample_params.update(
            {
                k: v
                for k, v in locals().items()
                if v is not None and k in self.sample_params
            }
        )

        try:
            response = self.client.chat.completions.create(
                model=self.model_name,
                messages=prompt,
                **final_sample_params,
            )
        except openai.OpenAIError as e:
            LOGGER.error(f"OpenAIError: {e}")
            raise
        except Exception as e:
            LOGGER.error(f"Unexpected error: {e}")
            raise

        outputs = parse_api_output(response)
        return outputs


class AzureLanguageModel(GPTLanguageModel):
    def __init__(
        self,
        API_URL=None,
        api_key=None,
        model=None,
        sample_params=None,
        user_stop_token=None,
        tokenizer=None,
    ):
        self.API_URL = API_URL
        self.api_key = api_key
        self.model_name = model
        self.sample_params = asdict(sample_params) if sample_params is not None else {}
        self.tokenizer = tokenizer
        self.user_stop_token = user_stop_token

        self.client: openai.Client = AzureOpenAI(
            api_key=self.api_key,
            azure_endpoint=self.API_URL,
            api_version="2024-08-01-preview",  # TODO (jiabao): we may put it in config
        )


def convert_param2hf(openai_param: Dict[str, Any]) -> Dict[str, Any]:
    mapping = {
        "max_tokens": "max_new_tokens",
        "top_p": "top_p",
        "stop": "stop_string",
        "n": "num_return_sequences",
    }
    return {mapping[k]: openai_param.get(k, None) for k in mapping.keys()}


class HFLanguageModel(LanguageModel):
    def __init__(self, model, sample_params, tokenizer=None):
        super().__init__()
        self.model_name = model
        self.model = AutoModelForCausalLM.from_pretrained(model).cuda().eval()
        self.sample_params = asdict(sample_params)

    def generate(
        self,
        prompt: str,
        max_tokens: int = None,
        temperature: float = None,
        top_p: float = None,
        frequency_penalty: float = None,
        presence_penalty: float = None,
        stop: str = None,
        n: int = None,
    ):
        final_sample_params = copy.deepcopy(self.sample_params)
        final_sample_params.update(
            {
                k: v
                for k, v in locals().items()
                if v is not None and k in self.sample_params
            }
        )
        final_sample_params = convert_param2hf(final_sample_params)

        try:
            input_ids = self.tokenizer(prompt, return_tensors="pt").input_ids.cuda()
            response = self.model.generate(
                input_ids=input_ids,
                **final_sample_params,
            )
            responses = [
                self.tokenizer.decode(response[i], skip_special_tokens=True).split(
                    prompt
                )[-1]
                for i in range(response.shape[0])
            ]
            # TODO: 01/15: should wrap it as a completionchoice object
            responses = [
                CompletionChoice(
                    finish_reason="stop",
                    index=i,
                    logprobs=None,
                    text=responses[i],
                )
                for i in range(response.shape[0])
            ]
        except openai.OpenAIError as e:
            LOGGER.error(f"OpenAIError: {e}")
            raise
        except Exception as e:
            LOGGER.error(f"Unexpected error: {e}")
            raise
        return responses


class AnthropicLanguageModel(APILanguageModel):
    def __init__(
        self,
        API_URL=None,
        api_key=None,
        model=None,
        sample_params=None,
        user_stop_token=None,
        tokenizer=None,
    ):
        self.API_URL = API_URL
        self.api_key = api_key
        self.model_name = model
        self.sample_params = asdict(sample_params) if sample_params is not None else {}
        self.tokenizer = tokenizer
        self.user_stop_token = user_stop_token
        self.client = anthropic.Anthropic(
            api_key=self.api_key,
        )

    def generate(
        self,
        prompt,
        max_tokens=None,
        temperature=None,
        top_p=None,
        frequency_penalty=None,
        presence_penalty=None,
        stop=None,
        n=None,
    ):
        final_sample_params = copy.deepcopy(self.sample_params)
        final_sample_params.update(
            {
                k: v
                for k, v in locals().items()
                if v is not None and k in self.sample_params
            }
        )
        final_sample_params = convert_param2hf(final_sample_params)

        assert final_sample_params.get("n", 1) == 1, "Anthropic only supports n=1"

        try:
            response = self.client.messages.create(
                model=self.model_name,
                messages=prompt,
                **final_sample_params,
            )
        except anthropic.APIError as e:
            LOGGER.error(f"AntrhopicError: {e}")
            raise
        except Exception as e:
            LOGGER.error(f"Unexpected error: {e}")
            raise

        outputs = parse_anthropic_output(response)
        return outputs


def build_language_model(
    # configs: RunConfig,
    model_name: str,
    raw_model_name: str,
    tokenizer=None,
    PORT: int = None,
    API_KEY: str = None,
    API_URL: str = None,
) -> LanguageModel:
    # This function creates a language model object based on the model name
    # xxx-vllm: the model is initialied as an APILanguageModel, but the API_URL is set to the local server
    # gpt-models: the model is initialized as an APIlanguageModel, but the API_URL is set to the OpenAI API
    # xxx-hf: the model is initailized as an HFLanguageModel
    if tokenizer is None:
        if "gpt" in raw_model_name:
            tokenizer = TiktokenHuggingFaceTokenizer("gpt-4o")
        elif "claude" in raw_model_name:
            # TODO (jiabao): need to implement
            tokenizer = TiktokenHuggingFaceTokenizer("gpt-4o")
        elif "@grok" in model_name:
            tokenizer = TiktokenHuggingFaceTokenizer("gpt-4")
        else:
            tokenizer = AutoTokenizer.from_pretrained(raw_model_name)
    if "@localvllm" in model_name:
        return VLLMLanguageModel(
            model=raw_model_name,
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )
    elif "@vllm" in model_name:
        return APILanguageModel(
            API_URL=f"http://localhost:{PORT}/v1/",
            api_key="empty",
            model=model_name.split("@vllm")[0],
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )
    elif "claude" in model_name:
        return AnthropicLanguageModel(
            API_URL="",
            api_key=API_KEY,
            model=model_name,
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )
    elif "@azure" in model_name:
        return AzureLanguageModel(
            API_URL=API_URL,
            api_key=API_KEY,
            model=model_name.split("@azure")[0],
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )
    elif "@grok" in model_name:
        return GPTLanguageModel(
            API_URL=API_URL,
            api_key=API_KEY,
            model=model_name.split("@grok")[0],
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )
    elif "deepseek" in model_name:
        return GPTLanguageModel(
            API_URL=API_URL,
            api_key=API_KEY,
            model=model_name,
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )
    elif "gpt" in model_name:
        return GPTLanguageModel(
            API_URL="https://api.openai.com/v1/",
            api_key=API_KEY,
            model=model_name,
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )
    elif "@hf" in model_name:
        return HFLanguageModel(
            model=model_name.split("@hf")[0],
            sample_params=SampleParams(
                max_tokens=100,
                temperature=1.0,
                top_p=1.0,
            ),
            tokenizer=tokenizer,
        )


ModelRegistry = Registry()
for model_name in model_configs:
    model_config = cs.repo[model_name + ".yaml"].node
    model = build_language_model(**model_config)
    ModelRegistry.register(model_name, model)

import json
import os
from abc import ABC, abstractmethod
from typing import List
from warnings import warn

import openai

try:
    import anthropic

    from bigcodebench.gen.util import anthropic_request
except ImportError:
    warn("Anthropic decoder will not work. Fix by `pip install anthropic`")

# mistral.ai
try:
    from mistralai.client import MistralClient
    from mistralai.models.chat_completion import ChatMessage
except ImportError:
    warn("MistralAI decoder will not work. Fix by `pip install mistralai`")
try:
    import google.generativeai as genai
except ImportError:
    warn("GoogleGenAI decoder will not work. Fix by `pip install google-generativeai`")

import torch
from transformers import AutoModelForCausalLM, AutoTokenizer

try:
    from vllm import LLM, SamplingParams
except ImportError:
    warn("VLLM decoder will not work. Fix by `pip install vllm`")

from gen.util import openai_request

EOS = [
    "<|endoftext|>",
    "<|endofmask|>",
    "</s>",
    "\nif __name__",
    "\ndef main(",
    "\nprint(",
]


def extra_eos_for_direct_completion(dataset) -> List[str]:
    if dataset.lower() == "bigcodebench":
        return ["\ndef ", "\nclass ", "\nimport ", "\nfrom ", "\nassert "]
    raise ValueError(f"Unknown dataset: {dataset}")


# some random words which serves as the splitter
_MAGIC_SPLITTER_ = "-[[]]-this-is-really-our-highest-priority-[[]]-"


def make_chat_prompt(prompt: str, tokenizer: AutoTokenizer) -> str:
    # directly return prompt if it does not have a tokenizer.chat_template
    if tokenizer.chat_template is None:
        return prompt

    prompt = f"""\
Please provide a self-contained Python script that solves the following problem in a markdown code block:
```
{prompt.strip()}
```
"""
    response = f"""\
Below is a Python script with a self-contained function that solves the problem and passes corresponding tests:
```python
{_MAGIC_SPLITTER_}
```
"""
    prompt = tokenizer.apply_chat_template(
        [
            {
                "role": "user",
                "content": prompt
            },
            {
                "role": "assistant",
                "content": response
            },
        ],
        tokenize=False,
    ).split(_MAGIC_SPLITTER_)[0]
    return prompt


class DecoderBase(ABC):

    def __init__(
        self,
        name: str,
        batch_size: int = 1,
        temperature: float = 0.8,
        max_new_tokens: int = 1280,
        dtype: str = "bfloat16",  # default
        trust_remote_code: bool = False,
        tokenizer_name: str = None,
        tokenizer_legacy: bool = False,
    ) -> None:
        print("Initializing a decoder model: {} ...".format(name))
        self.name = name
        self.batch_size = batch_size
        self.temperature = temperature
        self.eos = EOS
        self.skip_special_tokens = False
        self.max_new_tokens = max_new_tokens
        self.dtype = dtype
        self.trust_remote_code = trust_remote_code
        self.tokenizer_name = tokenizer_name
        self.tokenizer_legacy = tokenizer_legacy

    @abstractmethod
    def codegen(self, prompt: str, do_sample: bool = True, num_samples: int = 200) -> List[str]:
        pass

    @abstractmethod
    def is_direct_completion(self) -> bool:
        pass

    def __repr__(self) -> str:
        return self.name

    def __str__(self) -> str:
        return self.name


class VllmDecoder(DecoderBase):

    def __init__(self, name: str, dataset: str, tp: int, **kwargs) -> None:
        super().__init__(name, **kwargs)

        kwargs = {
            "tensor_parallel_size": int(os.getenv("VLLM_N_GPUS", tp)),
            "dtype": self.dtype,
            "trust_remote_code": True,
            "enforce_eager": True,
            "gpu_memory_utilization": 0.95,
            "worker_use_ray": True
        }
        if self.tokenizer_name is None:
            self.tokenizer_name = self.name

        self.tokenizer = AutoTokenizer.from_pretrained(self.tokenizer_name, **kwargs, legacy=self.tokenizer_legacy)
        if self.tokenizer.chat_template is None:
            self.eos += extra_eos_for_direct_completion(dataset)
        self.llm = LLM(model=name, max_model_len=2048, **kwargs)
        self.llm.set_tokenizer(tokenizer=self.tokenizer)

    def is_direct_completion(self) -> bool:
        return self.tokenizer.chat_template is None

    def codegen(self, prompts: List[str], do_sample: bool = True, num_samples: int = 200) -> List[str]:
        if do_sample:
            assert self.temperature > 0, "Temperature must be greater than 0!"

        vllm_outputs = self.llm.generate(
            prompts,
            SamplingParams(
                temperature=self.temperature,
                max_tokens=self.max_new_tokens,
                top_p=0.95 if do_sample else 1.0,
                stop=self.eos,
            ),
            use_tqdm=True,
        )

        gen_strs = [x.outputs[0].text.replace("\t", "    ") for x in vllm_outputs]
        return gen_strs


class GeneralVllmDecoder(VllmDecoder):

    def __init__(self, name: str, **kwargs) -> None:
        super().__init__(name, **kwargs)
        self.eos += ["\n```\n"]
        print(f"EOS strings: {self.eos}")

    def codegen(self, prompts: List[str], do_sample: bool = True, num_samples: int = 200) -> List[str]:
        chat_prompts = [make_chat_prompt(prompt, self.tokenizer) for prompt in prompts]
        return VllmDecoder.codegen(self, chat_prompts, do_sample, num_samples)


class HfTorchDecoder(DecoderBase):

    def __init__(self, name: str, dataset: str, **kwargs):
        super().__init__(name=name, **kwargs)
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

        kwargs = {}
        kwargs["device_map"] = "auto"
        kwargs["trust_remote_code"] = self.trust_remote_code
        # string to torch dtype
        kwargs["torch_dtype"] = getattr(torch, self.dtype)
        self.skip_special_tokens = True

        print(f"{kwargs = }", self.tokenizer_name)
        if self.tokenizer_name is None:
            self.tokenizer_name = self.name

        self.tokenizer = AutoTokenizer.from_pretrained(self.tokenizer_name, **kwargs, legacy=self.tokenizer_legacy)

        if self.tokenizer.chat_template is None:
            self.eos += extra_eos_for_direct_completion(dataset)

        self.model = AutoModelForCausalLM.from_pretrained(name, **kwargs)
        self.model = self.model.to(self.device)

    def is_direct_completion(self) -> bool:
        return self.tokenizer.chat_template is None

    @torch.inference_mode()
    def codegen(self, prompt: str, do_sample: bool = True, num_samples: int = 200) -> List[str]:
        if self.temperature == 0:
            assert not do_sample
            assert num_samples == 1

        input_tokens = self.tokenizer.encode(prompt, return_tensors="pt").to(self.device)
        kwargs = {}
        if do_sample:
            kwargs["top_p"] = 0.95
            kwargs["temperature"] = self.temperature

        outputs = self.model.generate(
            input_tokens,
            max_new_tokens=self.max_new_tokens,
            do_sample=do_sample,
            num_return_sequences=min(self.batch_size, num_samples),
            pad_token_id=self.tokenizer.eos_token_id,
            stop_strings=self.eos,
            tokenizer=self.tokenizer,
            **kwargs,
        )

        gen_strs = self.tokenizer.batch_decode(
            outputs[:, input_tokens.size(-1):],
            skip_special_tokens=self.skip_special_tokens,
        )
        outputs = []
        # removes eos tokens.
        for output in gen_strs:
            min_index = 10000
            for eos in self.eos:
                if eos in output:
                    min_index = min(min_index, output.index(eos))
            outputs.append(output[:min_index].replace("\t", "    "))
        return outputs


class GenenralHfTorchDecoder(HfTorchDecoder):

    def __init__(self, name: str, **kwargs):
        super().__init__(name=name, **kwargs)
        self.eos += ["\n```\n"]
        print(f"EOS strings: {self.eos}")
        self.tokenizer = AutoTokenizer.from_pretrained(self.tokenizer_name if self.tokenizer_name else self.name, **kwargs, legacy=self.tokenizer_legacy)

    def codegen(self, prompt: str, do_sample: bool = True, num_samples: int = 200) -> List[str]:
        prompt = make_chat_prompt(prompt, self.tokenizer)
        return HfTorchDecoder.codegen(self, prompt, do_sample, num_samples)


class OpenAIChatDecoder(DecoderBase):

    def __init__(self, name: str, base_url=None, **kwargs) -> None:
        super().__init__(name, **kwargs)
        self.client = openai.OpenAI(base_url=base_url)

    def codegen(self, prompt: str, do_sample: bool = True, num_samples: int = 200) -> List[str]:
        if do_sample:
            assert self.temperature > 0, "Temperature must be positive for sampling"
        batch_size = min(self.batch_size, num_samples)

        # construct prompt
        fmt = "json_object" if self.name == "gpt-4-1106-preview" else "text"
        if fmt == "json_object":
            message = r'Please complete the following code snippet by generating JSON like {"code": ""}'
        else:
            message = r"Please generate self-contained code to complete the following problem:"

        message += f"\n```python\n{prompt.strip()}\n```"

        ret = openai_request.make_auto_request(
            self.client,
            message=message,
            model=self.name,
            max_tokens=self.max_new_tokens,
            temperature=self.temperature,
            n=batch_size,
            response_format={"type": fmt},
        )

        outputs = []
        for item in ret.choices:
            content = item.message.content
            # if json serializable
            if fmt == "json_object":
                try:
                    json_data = json.loads(content)
                    if json_data.get("code", None) is not None:
                        outputs.append(prompt + "\n" + json_data["code"])
                        continue

                    print(f"'code' field not found in: {json_data}")
                except Exception as e:
                    print(e)
            outputs.append(content)

        return outputs

    def is_direct_completion(self) -> bool:
        return False


class MistralChatDecoder(DecoderBase):

    def __init__(self, name: str, **kwargs) -> None:
        super().__init__(name, **kwargs)
        self.client = MistralClient(api_key=os.getenv("MISTRAL_API_KEY"))

    def codegen(self, prompt: str, do_sample: bool = True, num_samples: int = 200) -> List[str]:
        kwargs = {}
        if do_sample:
            assert self.temperature > 0, "Temperature must be positive for sampling"
            kwargs["top_p"] = 0.95
            kwargs["temperature"] = self.temperature
        else:
            self.temperature = 0

        batch_size = min(self.batch_size, num_samples)

        outputs = []
        for _ in range(batch_size):
            ret = self.client.chat(
                model=self.name,
                messages=[ChatMessage(
                    role="user",
                    content="Please generate self-contained code to solve the following problem in a Python markdown block:" + f"\n```python\n{prompt.strip()}\n```",
                )],
                max_tokens=self.max_new_tokens,
                **kwargs,
            )

            outputs.append(ret.choices[0].message.content)

        return outputs

    def is_direct_completion(self) -> bool:
        return False


class AnthropicDecoder(DecoderBase, ABC):
    def __init__(self, name: str, **kwargs) -> None:
        super().__init__(name, **kwargs)
        self.client = anthropic.Anthropic(api_key=os.getenv("ANTHROPIC_KEY"))

    def is_direct_completion(self) -> bool:
        return False


class AnthropicMessageDecoder(AnthropicDecoder):

    def codegen(self, prompt: str, do_sample: bool = True, num_samples: int = 200) -> List[str]:
        kwargs = {}
        if do_sample:
            assert self.temperature > 0, "Temperature must be positive for sampling"
            kwargs["top_p"] = 0.95
            kwargs["temperature"] = self.temperature
        else:
            self.temperature = 0

        batch_size = min(self.batch_size, num_samples)
        if not do_sample:
            assert batch_size == 1, "Sampling only supports batch size of 1"

        outputs = []
        for _ in range(batch_size):
            message = anthropic_request.make_auto_request(
                client=self.client,
                model=self.name,
                messages=[{
                    "role": "user",
                    "content": "Please generate self-contained code to complete the following problem wrapped in a Python markdown block:" + f"\n```python\n{prompt.strip()}\n```\n",
                }],
                max_tokens=self.max_new_tokens,
                stop_sequences=["\n```\n", "\nif "],
                **kwargs,
            )
            outputs.append(message.content[0].text)

        return outputs


class GoogleGenAIDecoder(DecoderBase, ABC):

    def __init__(self, name: str, **kwargs) -> None:
        super().__init__(name, **kwargs)
        genai.configure(api_key=os.environ['GOOGLE_API_KEY'])

    def is_direct_completion(self) -> bool:
        return False


class GeminiDecoder(GoogleGenAIDecoder):

    def codegen(self, prompt: str, do_sample: bool = True, num_samples: int = 200) -> List[str]:
        kwargs = {}
        if do_sample:
            assert self.temperature > 0, "Temperature must be positive for sampling"
            kwargs["top_p"] = 0.95
            kwargs["temperature"] = self.temperature
        else:
            self.temperature = 0

        batch_size = min(self.batch_size, num_samples)
        if not do_sample:
            assert batch_size == 1, "Sampling only supports batch size of 1"

        genai_config = genai.GenerationConfig(
            max_output_tokens=self.max_new_tokens,
            **kwargs,
        )

        safety_settings = [
            {
                "category": "HARM_CATEGORY_DANGEROUS",
                "threshold": "BLOCK_NONE",
            },
            {
                "category": "HARM_CATEGORY_HARASSMENT",
                "threshold": "BLOCK_NONE",
            },
            {
                "category": "HARM_CATEGORY_HATE_SPEECH",
                "threshold": "BLOCK_NONE",
            },
            {
                "category": "HARM_CATEGORY_SEXUALLY_EXPLICIT",
                "threshold": "BLOCK_NONE",
            },
            {
                "category": "HARM_CATEGORY_DANGEROUS_CONTENT",
                "threshold": "BLOCK_NONE",
            },
        ]

        model = genai.GenerativeModel(model_name=self.name, generation_config=genai_config, safety_settings=safety_settings)

        outputs = []
        for _ in range(batch_size):
            while True:
                try:
                    response = model.generate_content("Please generate self-contained code to complete the following problem wrapped in a Python markdown block:" + f"\n```python\n{prompt.strip()}\n```", generation_config=genai_config)
                    output = response.candidates[0].content.parts[0].text
                    outputs.append(output)
                    break
                except Exception as e:
                    if "list index out of range" in str(e):
                        # append dummy response
                        outputs.append("NO_RESPONSE")
                        break
                    else:
                        print(e)
                        continue

        return outputs


def make_model(
    model: str,
    backend: str,
    dataset: str = "bigcodebench",
    batch_size: int = 1,
    temperature: float = 0.0,
    tp=1,
    base_url=None,
    trust_remote_code=False,
    tokenizer_name=None,
    tokenizer_legacy=True,
):
    if backend == "vllm":
        return GeneralVllmDecoder(
            name=model,
            batch_size=batch_size,
            temperature=temperature,
            dataset=dataset,
            tp=tp,
            trust_remote_code=trust_remote_code,
            tokenizer_name=tokenizer_name,
            tokenizer_legacy=tokenizer_legacy,
        )
    elif backend == "hf":
        return GenenralHfTorchDecoder(
            name=model,
            batch_size=batch_size,
            temperature=temperature,
            dataset=dataset,
            trust_remote_code=trust_remote_code,
            tokenizer_name=tokenizer_name,
            tokenizer_legacy=tokenizer_legacy,
        )
    elif backend == "openai":
        return OpenAIChatDecoder(
            name=model,
            batch_size=batch_size,
            temperature=temperature,
            base_url=base_url,
        )
    elif backend == "mistral":
        return MistralChatDecoder(
            name=model,
            batch_size=batch_size,
            temperature=temperature,
        )
    elif backend == "anthropic":
        return AnthropicMessageDecoder(
            name=model,
            batch_size=batch_size,
            temperature=temperature,
        )
    elif backend == "google":
        return GeminiDecoder(
            name=model,
            batch_size=batch_size,
            temperature=temperature,
        )

import re
import requests
from transformers import AutoTokenizer
from typing import List, Dict, Optional, final, Union
from vllm import LLM

def search(query: str):
    if query == '':
        return 'invalid query'

    url = f'your_search_api_url'
    data = {'query': query, 'top_n': 5}
    response = requests.post(url, json=data)
    retrieval_text = ''
    for line in response.json():
        retrieval_text += f"{line['contents']}\n\n"
    retrieval_text = retrieval_text.strip()
    return retrieval_text

def batch_search(query: Union[str, List[str]], top_n=5) -> List[str]:
    if len(query) == 0:
        return 'invalid query'

    url = f'your_search_api_url'
    if isinstance(query, str):
        query = [query]
    data = {'query': query, 'top_n': top_n}
    response = requests.post(url, json=data)

    result_list = []
    for item in response.json():
        curr_result = ''
        for line in item:
            curr_result += f"{line['contents']}\n\n"
        result_list.append(curr_result.strip())

    return result_list

def extract_search_content(text: str) -> str:
    try:
        start_tag = '<search>'
        end_tag = '</search>'
        assert text.strip().endswith(end_tag)
        end_pos = text.rindex(end_tag)
        start_pos = text.rindex(start_tag, 0, end_pos)
        return text[start_pos + len(start_tag):end_pos].strip()
    except ValueError:
        return ""

def validate_template_format(text: str) -> tuple[bool, str]:
    if text.count('<think>') != text.count('</think>'):
        return False, "<think> </think> unpair"

    if text.count('<think>') == 0 or text.count('</think>') == 0:
        return False, "less <think> or </think> label"

    if text.count('<answer>') != 1 or text.count('</answer>') != 1:
        return False, "the appearance time for <answer> or </answer> is not 1"        

    # 检查 search/result 标签的顺序
    current_pos = 0
    while True:
        search_pos = text.find('<search>', current_pos)
        if search_pos == -1:
            break

        result_pos = text.find('<result>', search_pos)
        search_end_pos = text.find('</search>', search_pos)
        result_end_pos = text.find('</result>', result_pos)

        if -1 in (result_pos, search_end_pos, result_end_pos):
            return False, "search/result is uncomplete"

        if not (search_pos < search_end_pos < result_pos < result_end_pos):
            return False, "search/result order error"

        current_pos = result_end_pos

    answer_start = text.find('<answer>')
    answer_end = text.find('</answer>')
    if answer_start > answer_end:
        return False, "<answer> must exist before </answer>"
    answer_content = text[answer_start:answer_end]
    if '\\boxed{' not in answer_content or '}' not in answer_content:
        return False, "answer needs \\boxed{}"

    return True, "correct format"

def extract_answer(text: str):
    text = text.strip()

    pattern = r"<answer>(.*?)</answer>"
    match = re.search(pattern, text, re.DOTALL)
    if not match:
        return None

    return match.group(1)

def remove_boxed(s):
    if "\\boxed " in s:
        left = "\\boxed "
        assert s[:len(left)] == left
        return s[len(left):]

    left = "\\boxed{"

    assert s[:len(left)] == left
    assert s[-1] == "}"

    return s[len(left):-1]

def extract_python_content(text: str) -> str:
    try:
        start_tag = '<python>'
        end_tag = '</python>'
        assert text.strip().endswith(end_tag)
        end_pos = text.rindex(end_tag)
        start_pos = text.rindex(start_tag, 0, end_pos)
        return text[start_pos + len(start_tag):end_pos].strip()
    except ValueError:
        return ""


def last_boxed_only_string(string):
    try:
        idx = string.rfind("\\boxed")
    except:
        import pdb; pdb.set_trace()
    if idx < 0:
        idx = string.rfind("\\fbox")
        if idx < 0:
            return None

    i = idx
    right_brace_idx = None
    num_left_braces_open = 0
    while i < len(string):
        if string[i] == "{":
            num_left_braces_open += 1
        if string[i] == "}":
            num_left_braces_open -= 1
            if num_left_braces_open == 0:
                right_brace_idx = i
                break
        i += 1

    if right_brace_idx is None:
        retval = string[idx:]
    else:
        retval = string[idx:right_brace_idx + 1]

    return retval


def extract_answer(solution_str) -> float:
    answer_part = solution_str
    if "<answer>" in answer_part:
        answer_part = extract_answer(answer_part)
        if answer_part is not None:
            if "\\boxed{" in answer_part:
                answer = remove_boxed(last_boxed_only_string(answer_part))
            else:
                answer = answer_part
        else:
            answer = solution_str
            print("can not extract answer")

    elif "<answer>" not in answer_part:
        if "\\boxed{" in answer_part:
            answer = remove_boxed(last_boxed_only_string(answer_part))
        else:
            answer = answer_part

    else:
        answer = solution_str
        print("can not extract answer")
    return answer

def extract_solution(solution_str):
    solution = re.search("#### (\\-?[0-9\\.\\,]+)", solution_str)
    assert solution is not None
    final_solution = solution.group(0)
    final_solution = final_solution.split('#### ')[1].replace(',', '')
    return final_solution

def rollback(s: str) -> str:
    python_pos = s.rfind('<python>')
    if python_pos == -1:
        return s  

    think_end = '</think>'
    start_pos = python_pos
    if python_pos >= len(think_end) and s[python_pos - len(think_end):python_pos] == think_end:
        start_pos = python_pos - len(think_end)

    pos = start_pos - 1
    while pos >= 0 and (s[pos] == '\n' or s[pos] == ' '):
        pos -= 1

    while pos >= 0:
        if s[pos] == '\n':
            return s[:pos + 1]
        if pos > 0 and s[pos - 1:pos + 1] == '. ':
            return s[:pos + 1]
        pos -= 1
    return s[:pos + 1]

def load_model(config):
    model = LLM(
                config['model_path'],
                dtype=config['type'],
                enforce_eager=True,
                trust_remote_code=True,
                max_model_len=config['max_input_len'],
                gpu_memory_utilization=config['gpu_use'],
                tensor_parallel_size=config['gpu_num'],
            )
    tokenizer = AutoTokenizer.from_pretrained(config['model_path'], trust_remote_code=True)
    return model, tokenizer

