    data = []
    if PROMPT_PATH.endswith('.jsonl'):
        with open(PROMPT_PATH, "r", encoding="utf-8") as f:
            for line in f:
                data.append(json.loads(line))
    elif PROMPT_PATH.endswith('.json'):
        with open(PROMPT_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
    else:
        raise ValueError("Input file must be .json or .jsonl")

    QUESTION_TEMPLATE = (
        "{Question}\n"
        "Please think about this question as if you were a human pondering deeply. "
        "Engage in an internal dialogue using expressions such as 'let me think', 'wait', 'Hmm', 'oh, I see', 'let's break it down', etc, or other natural language thought expressions "
        "It's encouraged to include self-reflection or verification in the reasoning process. "
        "Provide your detailed reasoning between the <think> and </think> tags, and then give your final answer between the <answer> and </answer> tags."
    )

    TYPE_TEMPLATE = {
        "multiple choice": " Please provide only the single option letter (e.g., A, B, C, D, etc.) within the <answer> </answer> tags.",
        "numerical": " Please provide the numerical value (e.g., 42 or 3.14) within the <answer> </answer> tags.",
        "OCR": " Please transcribe text from the image/video clearly and provide your text answer within the <answer> </answer> tags.",
        "free-form": " Please provide your text answer within the <answer> </answer> tags.",
        "regression": " Please provide the numerical value (e.g., 42 or 3.14) within the <answer> </answer> tags."
    }


    messages = []

    if 'seed_bench_r1' in dataset_name:
        for example in data:
            messages.append(make_conversation_seed_bench_r1(example))
            example['problem_type'] = 'multiple choice'
    else:
        for x in data:
            if x["problem_type"] == 'multiple choice':
                question = x['problem'] + "Options:\n"
                for op in x["options"]:
                    question += op + "\n"
            else:
                question = x['problem']
            input_text_final = QUESTION_TEMPLATE.format(Question=question) + TYPE_TEMPLATE[x['problem_type']]
            msg = [{
                "role": "user",
                "content": [
                    {
                        "type": x['data_type'],
                        x['data_type']: x['path'],
                    },
                    {
                        "type": "text",
                        "text": input_text_final
                    }
                ]
            }]
            messages.append(msg)

    final_output = []
    rewards = []
    start_idx = 0
    if os.path.exists(OUTPUT_PATH):
        try:
            with open(OUTPUT_PATH, "r", encoding="utf-8") as f:
                existing = json.load(f)
                final_output = existing.get("results", [])
                start_idx = len(final_output)
                for sample in final_output:
                    rewards.append(sample['reward'])
                print(f"Resuming from sample index {start_idx}")
        except Exception as e:
            print(f"Error reading existing output file: {e}")


    def extract_think(output_str):
        pattern = r'<think>\s*(.*?)\s*</think>'
        match = re.search(pattern, output_str, re.DOTALL)
        if match:
            return match.group(1).strip()
        return ""

    def extract_answer(text):
        pattern = r'<answer>\s*(.*?)\s*</answer>'
        match = re.search(pattern, text, re.DOTALL)
        if match:
            return match.group(1).strip()
        return ""

    def normalize_number(num_str):
        try:
            num_str = num_str.replace(',', '')
            return float(num_str)
        except Exception as e:
            return None

    def mean_relative_accuracy(pred, target, start=0.5, end=0.95, interval=0.05):

        if not torch.is_tensor(pred):
            pred = torch.tensor(pred, dtype=torch.float32)
        if not torch.is_tensor(target):
            target = torch.tensor(target, dtype=torch.float32)

        epsilon = 1e-8
        rel_error = torch.abs(pred - target) / (torch.abs(target) + epsilon)

        thresholds = torch.arange(start, end + interval/2, interval, dtype=torch.float32)

        conditions = rel_error < (1 - thresholds)  
        mra = conditions.float().mean()  
        return mra.item()

    def reward_fn(sample, model_output, question_type):
        try:
            output_ans = extract_answer(model_output)
            if output_ans == '':
                output_ans = model_output
            gt_ans = extract_answer(sample.get("solution", ""))
            if question_type == "multiple choice":
                return 1.0 if output_ans.strip() == gt_ans.strip() else 0.0
            elif question_type == "numerical":
                gt_has_decimal = ("." in gt_ans) or ("," in gt_ans)
                out_has_decimal = ("." in output_ans) or ("," in output_ans)
                if gt_has_decimal != out_has_decimal:
                    return 0.0
                gt_number = normalize_number(gt_ans)
                out_number = normalize_number(output_ans)
                if gt_number is None or out_number is None:
                    return 0.0
                return 1.0 if round(gt_number, 2) == round(out_number, 2) else 0.0
            elif question_type == "regression":
                gt_number = normalize_number(gt_ans)
                out_number = normalize_number(output_ans)
                if gt_number is None or out_number is None:
                    return 0.0
                mra = mean_relative_accuracy(out_number, gt_number)
                return mra
            else:
                return 0.0
        except Exception as e:
            return 0.0

    mean_acc = []
    mean_mra = [] 

    t = tqdm(range(start_idx, len(messages), BSZ), desc=f"Processing batches {dataset_name}")
    for i in t:
        batch_messages = messages[i:i + BSZ]
        prompts = [processor.apply_chat_template(msg, tokenize=False, add_generation_prompt=True) for msg in batch_messages]
        try:
            image_inputs, video_inputs, video_kwargs = process_vision_info(batch_messages, return_video_kwargs=True)
            image_idx = 0
            video_idx = 0

            llm_inputs = []

            for idx, prompt in enumerate(prompts):
                sample_mm_data = {}
                sample_video_kw = {}

                for j in range(len(batch_messages[idx][0]['content'])):
                    mm_type = batch_messages[idx][0]['content'][j]['type']
                    if mm_type == 'image':
                        sample_mm_data["image"] = image_inputs[image_idx]
                        image_idx += 1
                    elif mm_type == 'video':
                        sample_mm_data["video"] = video_inputs[video_idx]
                        for key, value in video_kwargs.items():
                            sample_video_kw[key] = value[video_idx]
                        video_idx += 1


                llm_inputs.append({
                    "prompt": prompt,
                    "multi_modal_data": sample_mm_data,
                    "mm_processor_kwargs": sample_video_kw,
                })

            outputs = llm.generate(llm_inputs, sampling_params=sampling_params)
            batch_output_text = [out.outputs[0].text for out in outputs]

        except Exception as e:
            print(e)
            print('error')
            batch_output_text = ['<answer>error</answer>'] * BSZ
            continue

        for j, (sample, model_output) in enumerate(zip(data[i:i+BSZ], batch_output_text), start=i):
            think_chain = extract_think(model_output)
            final_ans = extract_answer(model_output)
            if final_ans == "":
                final_ans = model_output
            sample["output"] = model_output
            sample["prediction"] = final_ans
            q_type = sample.get("problem_type", "")
            sample["reward"] = reward_fn(sample, model_output, q_type)
            sample["correct"] = True if sample["reward"]==1.0 else False
            if sample['problem_type'] != 'regression':
                mean_acc.append(sample["reward"])
            else:
                mean_mra.append(sample["reward"])
            if think_chain:
                sample["process"] = f"<think>{think_chain}</think>"
            final_output.append(sample)
            rewards.append(sample["reward"])
        try:
            with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
                json.dump({"results": final_output}, f, indent=2, ensure_ascii=False)
            print(f"Processed batch {(i - start_idx)//BSZ + 1}, saved {len(final_output)} samples.")
        except Exception as e:
            print(f"Error writing to output file: {e}")

        t.update(1)
        t.set_postfix(reward_mean=np.mean(rewards))

    t.close()
    final_acc={'mean_acc': 0.0, 'mean_mra': 0.0, 'mean_rewards': np.mean(rewards)}
    final_acc['mean_acc'] = torch.tensor(mean_acc).mean().item()
    if mean_mra != []:
        final_acc['mean_mra'] = torch.tensor(mean_mra).mean().item()

    try:
        with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
            json.dump({"results": final_output, "final_acc": [final_acc]}, f, indent=2, ensure_ascii=False)
        print(f"Final accuracy saved to {OUTPUT_PATH}")
    except Exception as e:
        print(f"Error writing final accuracy to output file: {e}")

    print(f"Results saved to {OUTPUT_PATH}")

from contextlib import contextmanager
from typing import Any, Dict, List, Optional, Tuple

from lingua import LanguageDetectorBuilder
from transformers import AutoTokenizer
from vllm import LLM, PoolingParams, SamplingParams

from datatagger.settings.base_tagger_setting import TagMission
from datatagger.settings.tagger_settings_vllm import TaggerSettingsVLLM
from datatagger.tagger.base_tagger import BaseUnifiedTagger
from datatagger.utils.file_utils import load_dataset_from_file, release_gpu_memory


class UnifiedTaggerVLLM(BaseUnifiedTagger):
    def __init__(self, settings: TaggerSettingsVLLM) -> None:
        super().__init__(settings, is_api=False)
        self.settings = settings
        self.vllm_model_path = settings.vllm_model_path
        self.dtype = settings.dtype
        self.quantization = settings.quantization
        self.kv_cache_dtype = settings.kv_cache_dtype
        self.max_model_len = settings.max_model_len
        self.tensor_parallel_size = settings.tensor_parallel_size
        self.gpu_memory_utilization = settings.gpu_memory_utilization
        self._llm_instances = []
        # Initialize language detector if mission is LANGUAGE
        if self.mission == TagMission.LANGUAGE:
            self.logger.info("Building language detector from all languages")
            self.detector = LanguageDetectorBuilder.from_all_languages().build()

        if settings.input_file:
            _, self.checkpoint_data_file, self.checkpoint_state_file = (
                self.get_output_files(
                    settings=settings,
                    tag_mission=self.tag_mission,
                    input_file=settings.input_file,
                )
            )
        else:
            self.checkpoint_data_file = None
            self.checkpoint_state_file = None

        # Dynamically import and initialize milvus_client (if needed)
        self.faiss_client = getattr(self, "faiss_client", None)
        self.milvus_client = None
        if getattr(self, "milvus_store_embeddings", False) or getattr(
            settings, "milvus_store_embeddings", False
        ):
            try:
                from datatagger.utils.milvus_utils import MilvusClient

                self.milvus_client = MilvusClient()
            except ImportError:
                self.logger.error(
                    "Milvus related dependencies are not installed, please install them or disable milvus_store_embeddings."
                )
                raise

    def _create_llm_instance(self, task: str, **kwargs) -> LLM:
        """Create a VLLM instance with common settings."""
        common_params = {
            "model": self.vllm_model_path,
            "dtype": self.settings.dtype,
            "quantization": self.settings.quantization if self.settings.quantization != "None" else None,
            "kv_cache_dtype": self.settings.kv_cache_dtype,
            "max_model_len": self.settings.max_model_len,
            "tensor_parallel_size": self.settings.tensor_parallel_size,
            "gpu_memory_utilization": self.settings.gpu_memory_utilization,
            "trust_remote_code": True,
            "enable_prefix_caching": True,
            "enforce_eager": True,
        }
        common_params.update(kwargs)
        return LLM(**common_params)

    def _create_tokenizer(self) -> Any:
        """Create a tokenizer instance."""
        return AutoTokenizer.from_pretrained(
            self.vllm_model_path,
            use_fast=True,
            trust_remote_code=True,
        )

    def _create_sampling_params(self) -> SamplingParams:
        """Create sampling parameters for generation tasks."""
        return SamplingParams(
            temperature=self.settings.temperature,
            max_tokens=self.settings.max_tokens,
            repetition_penalty=self.settings.repetition_penalty,
            stop=["}"],
            include_stop_str_in_output=True,
        )

    def get_llm(self) -> Tuple[Optional[LLM], Optional[Any], Optional[Any]]:
        """Get LLM instance, parameters, and tokenizer based on mission type."""
        if self.mission == TagMission.LANGUAGE:
            return None, None, None

        if self.mission == TagMission.REWARD:
            self.logger.info(f"Loading reward model from {self.settings.vllm_model_path}")
            llm = self._create_llm_instance(
                task="classify",
                override_pooler_config={"softmax": False}
            )
            tokenizer = AutoTokenizer.from_pretrained(self.settings.vllm_model_path)
            return llm, None, tokenizer

        if self.mission == TagMission.SAFETY:
            self.logger.info("Loading vllm model for SAFETY task...")
            llm = self._create_llm_instance(task="generate")
            tokenizer = self._create_tokenizer()
            params = self._create_sampling_params()
            return llm, params, tokenizer

        if self.mission == TagMission.EMBEDDING:
            self.logger.info("Loading vllm model for EMBEDDING task...")
            llm = self._create_llm_instance(task="embedding")
            tokenizer = self._create_tokenizer()
            params = PoolingParams(dimensions=self.dimension)
            return llm, params, tokenizer

        # Default case for other missions
        self.logger.info(f"Loading vllm model for {self.mission} task...")
        llm = self._create_llm_instance(task="generate")
        tokenizer = self._create_tokenizer()
        params = self._create_sampling_params()
        return llm, params, tokenizer

    def process_batch(
        self,
        batch_indices: List[int],
        dataset: List[Dict[str, Any]],
        llm: Optional[LLM] = None,
        params: Optional[Any] = None,
        tokenizer: Optional[Any] = None,
    ) -> None:
        self.logger.info(
            f"Processing batch for indices: {batch_indices} with mission: {self.mission}"
        )

        if self.mission == TagMission.EMBEDDING:
            prompt_texts = [dataset[idx][self.prompt_field] for idx in batch_indices]
            prompt_embeddings = llm.embed(prompt_texts)
            prompt_emb_list = []
            prompt_metas = []
            for output, idx in zip(prompt_embeddings, batch_indices):
                embedding = output.outputs.embedding
                prompt_emb_list.append(embedding)
                prompt_metas.append(str(dataset[idx].get(self.prompt_field, "")))
            # Directly insert into faiss or milvus
            if self.milvus_store_embeddings and self.milvus_client:
                self.logger.info(
                    f"Inserting {len(prompt_emb_list)} prompt embeddings to Milvus..."
                )
                self.milvus_client.insert_embeddings(prompt_emb_list, prompt_metas)
            if self.faiss_store_embeddings and self.faiss_client:
                self.logger.info(
                    f"Inserting {len(prompt_emb_list)} prompt embeddings to Faiss..."
                )
                self.faiss_client.insert_embeddings(prompt_emb_list, prompt_metas)
            return
        prompts = []
        for idx in batch_indices:
            item = dataset[idx]
            if self.mission == TagMission.SAFETY:
                chat = [
                    {"role": "user", "content": item[self.prompt_field]},
                    {"role": "assistant", "content": item[self.output_field]},
                ]
                template = tokenizer.apply_chat_template(chat, tokenize=False)
            else:
                messages = [
                    {
                        "role": "user",
                        "content": self.mission_processor.get_prompt(
                            item[self.prompt_field],
                            item.get(self.output_field)
                            if self.mission == TagMission.QUALITY
                            else None,
                        ),
                    },
                    {"role": "assistant", "content": "{"},
                ]
                template = tokenizer.apply_chat_template(
                    messages,
                    tokenize=False,
                    add_generation_prompt=True,
                    enable_thinking=self.settings.enable_thinking,
                )
            prompts.append(template)
        outputs = llm.generate(prompts, params)
        for output, idx in zip(outputs, batch_indices):
            response = output.outputs[0].text
            if (
                self.mission != TagMission.SAFETY
                and self.mission != TagMission.EMBEDDING
            ):
                response = "{" + response
            self.mission_processor.process_response(response, dataset[idx])

    def process_batch_with_reward_model(
        self,
        batch_indices: List[int],
        dataset: List[Dict[str, Any]],
        llm: Optional[Any] = None,
        tokenizer: Optional[Any] = None,
    ) -> None:
        self.logger.info(
            f"Processing batch with reward model for indices: {batch_indices}"
        )
        for idx in batch_indices:
            try:
                item = dataset[idx]
                # TODO: Implement support for single question multiple answers to create reward model (RM) and DPO datasets
                # Current implementation processes single question-answer pairs
                chat = [
                    {"role": "user", "content": item[self.prompt_field]},
                    {"role": "assistant", "content": item[self.output_field]},
                ]
                prompt = tokenizer.apply_chat_template(chat, tokenize=False)
                encoded = tokenizer(prompt)
                input_ids = encoded["input_ids"]
                output = llm.encode(prompt_token_ids=input_ids)
                score = output[0].outputs.data
                score_int = score.item()
                dataset[idx]["instruct_reward"] = score_int
                self.logger.debug(
                    f"Successfully processed reward for index {idx}: {score_int}"
                )
            except (ValueError, KeyError, TypeError) as e:
                self.logger.error(
                    f"Data processing error for index {idx}: {str(e)}"
                )
                dataset[idx]["instruct_reward"] = None
            except RuntimeError as e:
                self.logger.error(
                    f"Model runtime error for index {idx}: {str(e)}"
                )
                dataset[idx]["instruct_reward"] = None
            except Exception as e:
                self.logger.error(
                    f"Unexpected error processing item at index {idx}: {str(e)}"
                )
                dataset[idx]["instruct_reward"] = None

    def generate_and_update(
        self, dataset: Optional[List[Dict[str, Any]]] = None
    ) -> None:
        output_file, checkpoint_data_file, checkpoint_state_file = (
            self.get_output_files(
                settings=self.settings,
                tag_mission=self.tag_mission,
                input_file=self.settings.input_file,
            )
        )
        if dataset is None:
            dataset = load_dataset_from_file(self.settings.input_file)
            if self.debug:
                self.logger.warning(
                    "Debug mode enabled. Only processing the first 100 samples."
                )
                dataset = dataset[:100]
        llm, params, tokenizer = self.get_llm()

        def process_batch_fn(batch_indices, dataset):
            if self.mission == TagMission.LANGUAGE:
                self.process_batch_with_language_detection(
                    detector=self.detector,
                    logger=self.logger,
                    batch_indices=batch_indices,
                    dataset=dataset,
                    prompt_field=self.prompt_field,
                )
            elif self.mission == TagMission.REWARD:
                self.process_batch_with_reward_model(
                    batch_indices=batch_indices,
                    dataset=dataset,
                    llm=llm,
                    tokenizer=tokenizer,
                )
            else:
                self.process_batch(
                    batch_indices=batch_indices,
                    dataset=dataset,
                    llm=llm,
                    params=params,
                    tokenizer=tokenizer,
                )

        def postprocess_fn(dataset):
            if self.mission == TagMission.EMBEDDING:
                self.update_similarity_fields(dataset=dataset, field=self.prompt_field)

        self.generate_and_update_with_checkpoint(
            dataset=dataset,
            output_file=output_file,
            checkpoint_data_file=checkpoint_data_file,
            checkpoint_state_file=checkpoint_state_file,
            process_batch_fn=process_batch_fn,
            batch_size=self.batch_size,
            checkpoint_every=self.checkpoint_every,
            logger=self.logger,
            postprocess_fn=postprocess_fn,
        )

    @contextmanager
    def _llm_context(self, llm_instance: Optional[LLM] = None):
        """Context manager for LLM instances with automatic cleanup."""
        if llm_instance is not None:
            self._llm_instances.append(llm_instance)
        try:
            yield llm_instance
        finally:
            if llm_instance is not None:
                release_gpu_memory(llm_instance)
                if llm_instance in self._llm_instances:
                    self._llm_instances.remove(llm_instance)

    def cleanup(self) -> None:
        """Clean up all LLM instances and release GPU memory."""
        for llm_instance in self._llm_instances[:]:  # Copy list to avoid modification during iteration
            release_gpu_memory(llm_instance)
        self._llm_instances.clear()

    def __del__(self) -> None:
        """Ensure cleanup on object destruction."""
        self.cleanup()

    @staticmethod
    def get_settings() -> TaggerSettingsVLLM:
        return TaggerSettingsVLLM()


if __name__ == "__main__":
    settings = TaggerSettingsVLLM()
    tagger = UnifiedTaggerVLLM(settings)
    try:
        tagger.generate_and_update()
    finally:
        tagger.cleanup()

try:
    import torch
    import transformers
    from vllm import LLM, SamplingParams
    from langchain.llms import OpenAI
    from langchain.chat_models import ChatOpenAI
    import bitsandbytes
    from typing import List
    HAS_CUDA = torch.cuda.is_available()
    NUM_GPUS = torch.cuda.device_count() if HAS_CUDA else 0
except ImportError as e:
    print(f"Warning: Some model dependencies not available: {e}")
