class AmazonBedrockServerModel(ApiModel):
    """
    A model class for interacting with Amazon Bedrock Server models through the Bedrock API.

    This class provides an interface to interact with various Bedrock language models,
    allowing for customized model inference, guardrail configuration, message handling,
    and other parameters allowed by boto3 API.

    Parameters:
        model_id (`str`):
            The model identifier to use on Bedrock (e.g. "us.amazon.nova-pro-v1:0").
        client (`boto3.client`, *optional*):
            A custom boto3 client for AWS interactions. If not provided, a default client will be created.
        client_kwargs (dict[str, Any], *optional*):
            Keyword arguments used to configure the boto3 client if it needs to be created internally.
            Examples include `region_name`, `config`, or `endpoint_url`.
        custom_role_conversions (`dict[str, str]`, *optional*):
            Custom role conversion mapping to convert message roles in others.
            Useful for specific models that do not support specific message roles like "system".
            Defaults to converting all roles to "user" role to enable using all the Bedrock models.
        flatten_messages_as_text (`bool`, default `False`):
            Whether to flatten messages as text.
        **kwargs
            Additional keyword arguments passed directly to the underlying API calls.

    Example:
        Creating a model instance with default settings:
        >>> bedrock_model = AmazonBedrockServerModel(
        ...     model_id='us.amazon.nova-pro-v1:0'
        ... )

        Creating a model instance with a custom boto3 client:
        >>> import boto3
        >>> client = boto3.client('bedrock-runtime', region_name='us-west-2')
        >>> bedrock_model = AmazonBedrockServerModel(
        ...     model_id='us.amazon.nova-pro-v1:0',
        ...     client=client
        ... )

        Creating a model instance with client_kwargs for internal client creation:
        >>> bedrock_model = AmazonBedrockServerModel(
        ...     model_id='us.amazon.nova-pro-v1:0',
        ...     client_kwargs={'region_name': 'us-west-2', 'endpoint_url': 'https://custom-endpoint.com'}
        ... )

        Creating a model instance with inference and guardrail configurations:
        >>> additional_api_config = {
        ...     "inferenceConfig": {
        ...         "maxTokens": 3000
        ...     },
        ...     "guardrailConfig": {
        ...         "guardrailIdentifier": "identify1",
        ...         "guardrailVersion": 'v1'
        ...     },
        ... }
        >>> bedrock_model = AmazonBedrockServerModel(
        ...     model_id='anthropic.claude-3-haiku-20240307-v1:0',
        ...     **additional_api_config
        ... )
    """

    def __init__(
        self,
        model_id: str,
        client=None,
        client_kwargs: dict[str, Any] | None = None,
        custom_role_conversions: dict[str, str] | None = None,
        **kwargs,
    ):
        self.client_kwargs = client_kwargs or {}

        # Bedrock only supports `assistant` and `user` roles.
        # Many Bedrock models do not allow conversations to start with the `assistant` role, so the default is set to `user/user`.
        # This parameter is retained for future model implementations and extended support.
        custom_role_conversions = custom_role_conversions or {
            MessageRole.SYSTEM: MessageRole.USER,
            MessageRole.ASSISTANT: MessageRole.USER,
            MessageRole.TOOL_CALL: MessageRole.USER,
            MessageRole.TOOL_RESPONSE: MessageRole.USER,
        }

        super().__init__(
            model_id=model_id,
            custom_role_conversions=custom_role_conversions,
            flatten_messages_as_text=False,  # Bedrock API doesn't support flatten messages, must be a list of messages
            client=client,
            **kwargs,
        )

    def _prepare_completion_kwargs(
        self,
        messages: list[dict[str, str | list[dict]]],
        stop_sequences: list[str] | None = None,
        grammar: str | None = None,
        tools_to_call_from: list[Tool] | None = None,
        custom_role_conversions: dict[str, str] | None = None,
        convert_images_to_image_urls: bool = False,
        **kwargs,
    ) -> dict:
        """
        Overrides the base method to handle Bedrock-specific configurations.

        This implementation adapts the completion keyword arguments to align with
        Bedrock's requirements, ensuring compatibility with its unique setup and
        constraints.
        """
        completion_kwargs = super()._prepare_completion_kwargs(
            messages=messages,
            stop_sequences=None,  # Bedrock support stop_sequence using Inference Config
            grammar=None,  # Bedrock doesn't support grammar
            tools_to_call_from=tools_to_call_from,
            custom_role_conversions=custom_role_conversions,
            convert_images_to_image_urls=convert_images_to_image_urls,
            **kwargs,
        )

        # Not all models in Bedrock support `toolConfig`. Also, smolagents already include the tool call in the prompt,
        # so adding `toolConfig` could cause conflicts. We remove it to avoid issues.
        completion_kwargs.pop("toolConfig", None)

        # The Bedrock API does not support the `type` key in requests.
        # This block of code modifies the object to meet Bedrock's requirements.
        for message in completion_kwargs.get("messages", []):
            for content in message.get("content", []):
                if "type" in content:
                    del content["type"]

        return {
            "modelId": self.model_id,
            **completion_kwargs,
        }

    def create_client(self):
        try:
            import boto3  # type: ignore
        except ModuleNotFoundError as e:
            raise ModuleNotFoundError(
                "Please install 'bedrock' extra to use AmazonBedrockServerModel: `pip install 'smolagents[bedrock]'`"
            ) from e

        return boto3.client("bedrock-runtime", **self.client_kwargs)

    def generate(
        self,
        messages: list[dict[str, str | list[dict]]],
        stop_sequences: list[str] | None = None,
        grammar: str | None = None,
        tools_to_call_from: list[Tool] | None = None,
        **kwargs,
    ) -> ChatMessage:
        completion_kwargs: dict = self._prepare_completion_kwargs(
            messages=messages,
            tools_to_call_from=tools_to_call_from,
            custom_role_conversions=self.custom_role_conversions,
            convert_images_to_image_urls=True,
            **kwargs,
        )

        # self.client is created in ApiModel class
        response = self.client.converse(**completion_kwargs)

        # Get usage
        self.last_input_token_count = response["usage"]["inputTokens"]
        self.last_output_token_count = response["usage"]["outputTokens"]

        # Get first message
        response["output"]["message"]["content"] = response["output"]["message"]["content"][0]["text"]
        return ChatMessage.from_dict(response["output"]["message"], raw=response)


__all__ = [
    "MessageRole",
    "tool_role_conversions",
    "get_clean_message_list",
    "Model",
    "MLXModel",
    "TransformersModel",
    "ApiModel",
    "InferenceClientModel",
    "HfApiModel",
    "LiteLLMModel",
    "LiteLLMRouterModel",
    "OpenAIServerModel",
    "VLLMModel",
    "AzureOpenAIServerModel",
    "AmazonBedrockServerModel",
    "ChatMessage",
]

import argparse
import os
import re
from copy import deepcopy

import pandas as pd
import torch
from natsort import index_natsorted
from tqdm import tqdm
from transformers import AutoTokenizer
from vllm import LLM, SamplingParams

from utils.logger import logger


def extract_output(s, prefix='"rewritten description": '):
    """Customize the function according to the prompt."""
    # Since some LLMs struggles to output strictly formatted JSON strings as specified by the prompt,
    # thus manually parse the output string `{"rewritten description": "your rewritten description here"}`.
    match = re.search(r"{(.+?)}", s, re.DOTALL)
    if not match:
        logger.warning(f"{s} is not in the json format. Return None.")
        return None
    output = match.group(1).strip()
    if output.startswith(prefix):
        output = output[len(prefix) :]
        if output[0] == '"' and output[-1] == '"':
            return output[1:-1]
        else:
            logger.warning(f"{output} does not start and end with the double quote. Return None.")
            return None
    else:
        logger.warning(f"{output} does not start with {prefix}. Return None.")
        return None

"""The file unifies the following two tasks:
1. Caption Rewrite: rewrite the video recaption results by LLMs.
2. Beautiful Prompt: rewrite and beautify the user-uploaded prompt via LLMs.

For the caption rewrite task, the input video_metadata_path should have the following format:
```jsonl
{"video_path_column": "1.mp4", "caption_column": "a man is running in the street."}
...
{"video_path_column": "100.mp4", "caption_column": "a dog is chasing a cat."}
```
The video_path_column in the argparse must be specified.

For the beautiful prompt task, the input video_metadata_path should have the following format:
```jsonl
{"caption_column": "a man is running in the street."}
...
{"caption_column": "a dog is chasing a cat."}
```
The beautiful_prompt_column in the argparse must be specified for the saving purpose.
"""

def parse_args():
    parser = argparse.ArgumentParser(description="Rewrite the video caption by LLMs.")
    parser.add_argument(
        "--video_metadata_path", type=str, required=True, help="The path to the video dataset metadata (csv/jsonl)."
    )
    parser.add_argument(
        "--video_path_column",
        type=str,
        default=None,
        help=(
            "The column contains the video path (an absolute path or a relative path w.r.t the video_folder)."
            "It is conflicted with the beautiful_prompt_column."
        ),
    )
    parser.add_argument(
        "--caption_column",
        type=str,
        default="caption",
        help="The column contains the video caption.",
    )
    parser.add_argument(
        "--beautiful_prompt_column",
        type=str,
        default=None,
        help="The column name for the beautiful prompt column. It is conflicted with the video_path_column.",
    )
    parser.add_argument(
        "--batch_size",
        type=int,
        default=128,
        required=False,
        help="The batch size for vllm inference. Adjust according to the number of GPUs to maximize inference throughput.",
    )
    parser.add_argument(
        "--model_name",
        type=str,
        default="NousResearch/Meta-Llama-3-8B-Instruct",
    )
    parser.add_argument(
        "--prompt",
        type=str,
        required=True,
        help="A string or a txt file contains the prompt.",
    )
    parser.add_argument(
        "--prefix",
        type=str,
        required=True,
        help="The prefix to extract the output from LLMs.",
    )
    parser.add_argument(
        "--answer_template",
        type=str,
        default="",
        help="The anwer template in the prompt. If specified, rewritten results same as the answer template will be removed.",
    )
    parser.add_argument(
        "--max_retry_count",
        type=int,
        default=1,
        help="The maximum retry count to ensure outputs with the valid format from LLMs.",
    )
    parser.add_argument("--saved_path", type=str, required=True, help="The save path to the output results (csv/jsonl).")
    parser.add_argument("--saved_freq", type=int, default=1, help="The frequency to save the output results.")

    args = parser.parse_args()
    return args


def main():
    args = parse_args()

    if args.video_metadata_path.endswith(".csv"):
        video_metadata_df = pd.read_csv(args.video_metadata_path)
    elif args.video_metadata_path.endswith(".jsonl"):
        video_metadata_df = pd.read_json(args.video_metadata_path, lines=True)
    elif args.video_metadata_path.endswith(".json"):
        video_metadata_df = pd.read_json(args.video_metadata_path)
    else:
        raise ValueError(f"The {args.video_metadata_path} must end with .csv, .jsonl or .json.")

    saved_suffix = os.path.splitext(args.saved_path)[1]
    if saved_suffix not in set([".csv", ".jsonl", ".json"]):
        raise ValueError(f"The saved_path must end with .csv, .jsonl or .json.")

    if args.video_path_column is None and args.beautiful_prompt_column is None:
        raise ValueError("Either video_path_column or beautiful_prompt_column should be specified in the arguments.")
    if args.video_path_column is not None and args.beautiful_prompt_column is not None:
        raise ValueError(
            "Both video_path_column and beautiful_prompt_column can not be specified in the arguments at the same time."
        )

    if os.path.exists(args.saved_path):
        if args.saved_path.endswith(".csv"):
            saved_metadata_df = pd.read_csv(args.saved_path)
        elif args.saved_path.endswith(".jsonl"):
            saved_metadata_df = pd.read_json(args.saved_path, lines=True)

        if args.video_path_column is not None:
            # Filter out the unprocessed video-caption pairs by setting the indicator=True.
            merged_df = video_metadata_df.merge(saved_metadata_df, on=args.video_path_column, how="outer", indicator=True)
            video_metadata_df = merged_df[merged_df["_merge"] == "left_only"]
            # Sorting to guarantee the same result for each process.
            video_metadata_df = video_metadata_df.iloc[index_natsorted(video_metadata_df[args.video_path_column])]
            video_metadata_df = video_metadata_df.reset_index(drop=True)
        if args.beautiful_prompt_column is not None:
            # Filter out the unprocessed caption-beautifil_prompt pairs by setting the indicator=True.
            merged_df = video_metadata_df.merge(saved_metadata_df, on=args.caption_column, how="outer", indicator=True)
            video_metadata_df = merged_df[merged_df["_merge"] == "left_only"]
            # Sorting to guarantee the same result for each process.
            video_metadata_df = video_metadata_df.iloc[index_natsorted(video_metadata_df[args.caption_column])]
            video_metadata_df = video_metadata_df.reset_index(drop=True)
        logger.info(
            f"Resume from {args.saved_path}: {len(saved_metadata_df)} processed and {len(video_metadata_df)} to be processed."
        )

    if args.prompt.endswith(".txt") and os.path.exists(args.prompt):
        with open(args.prompt, "r") as f:
            args.prompt = "".join(f.readlines())
    logger.info(f"Prompt: {args.prompt}")

    if args.max_retry_count < 1:
        raise ValueError(f"The max_retry_count {args.max_retry_count} must be greater than 0.")

    if args.video_path_column is not None:
        video_path_list = video_metadata_df[args.video_path_column].tolist()
    if args.caption_column in video_metadata_df.columns:
        sampled_frame_caption_list = video_metadata_df[args.caption_column].tolist()
    else:
        # When two columns with the same name, the dataframe merge operation on will distinguish them by adding 'x' and 'y'.
        sampled_frame_caption_list = video_metadata_df[args.caption_column + "_x"].tolist()

    CUDA_VISIBLE_DEVICES = os.getenv("CUDA_VISIBLE_DEVICES", None)
    tensor_parallel_size = torch.cuda.device_count() if CUDA_VISIBLE_DEVICES is None else len(CUDA_VISIBLE_DEVICES.split(","))
    logger.info(f"Automatically set tensor_parallel_size={tensor_parallel_size} based on the available devices.")

    llm = LLM(model=args.model_name, trust_remote_code=True, tensor_parallel_size=tensor_parallel_size)
    if "Meta-Llama-3" in args.model_name:
        if "Meta-Llama-3-70B" in args.model_name:
            # Llama-3-70B should use the tokenizer from Llama-3-8B
            # https://github.com/vllm-project/vllm/issues/4180#issuecomment-2068292942
            tokenizer = AutoTokenizer.from_pretrained("NousResearch/Meta-Llama-3-8B-Instruct")
        else:
            tokenizer = AutoTokenizer.from_pretrained(args.model_name)
        stop_token_ids = [tokenizer.eos_token_id, tokenizer.convert_tokens_to_ids("<|eot_id|>")]
        sampling_params = SamplingParams(temperature=0.7, top_p=1, max_tokens=1024, stop_token_ids=stop_token_ids)
    else:
        tokenizer = AutoTokenizer.from_pretrained(args.model_name)
        sampling_params = SamplingParams(temperature=0.7, top_p=1, max_tokens=1024)

    if args.video_path_column is not None:
        result_dict = {args.video_path_column: [], args.caption_column: []}
    if args.beautiful_prompt_column is not None:
        result_dict = {args.caption_column: [], args.beautiful_prompt_column: []}

    for i in tqdm(range(0, len(sampled_frame_caption_list), args.batch_size)):
        if args.video_path_column is not None:
            batch_video_path = video_path_list[i : i + args.batch_size]
        batch_caption = sampled_frame_caption_list[i : i + args.batch_size]
        batch_prompt = []
        for caption in batch_caption:
            # batch_prompt.append("user:" + args.prompt + str(caption) + "\n assistant:")
            messages = [
                {"role": "system", "content": "You are a helpful assistant."},
                {"role": "user", "content": args.prompt + "\n" + str(caption)},
            ]
            text = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
            batch_prompt.append(text)

        cur_retry_count = 0
        while cur_retry_count < args.max_retry_count:
            if len(batch_prompt) == 0:
                break

            batch_result = []
            batch_output = llm.generate(batch_prompt, sampling_params)
            batch_output = [output.outputs[0].text.rstrip() for output in batch_output]
            if args.prefix is not None:
                batch_output = [extract_output(output, args.prefix) for output in batch_output]

            if args.video_path_column is not None:
                retry_batch_video_path, retry_batch_prompt = [], []
                for (video_path, prompt, output) in zip(batch_video_path, batch_prompt, batch_output):
                    # Filter out data that does not meet the output format to retry.
                    if output is not None and output != args.answer_template:
                        batch_result.append((video_path, output))
                    else:
                        retry_batch_video_path.append(video_path)
                        retry_batch_prompt.append(prompt)
                if len(batch_result) != 0:
                    batch_video_path, batch_output = zip(*batch_result)
                    result_dict[args.video_path_column].extend(deepcopy(batch_video_path))
                    result_dict[args.caption_column].extend(deepcopy(batch_output))

                batch_video_path, batch_prompt = retry_batch_video_path, retry_batch_prompt
            if args.beautiful_prompt_column is not None:
                retry_batch_caption, retry_batch_prompt = [], []
                for (caption, prompt, output) in zip(batch_caption, batch_prompt, batch_output):
                    # Filter out data that does not meet the output format to retry.
                    if output is not None and output != args.answer_template:
                        batch_result.append((caption, output))
                    else:
                        retry_batch_caption.append(caption)
                        retry_batch_prompt.append(prompt)
                if len(batch_result) != 0:
                    batch_caption, batch_output = zip(*batch_result)
                    result_dict[args.caption_column].extend(deepcopy(batch_caption))
                    result_dict[args.beautiful_prompt_column].extend(deepcopy(batch_output))

                batch_caption, batch_prompt = retry_batch_caption, retry_batch_prompt

            cur_retry_count += 1
            logger.info(
                f"Current retry count/Maximum retry count: {cur_retry_count}/{args.max_retry_count}.: "
                f"Retrying {len(batch_prompt)} prompts with invalid output format."
            )

        # Save the metadata every args.saved_freq.
        if (i // args.batch_size) % args.saved_freq == 0 or (i + 1) * args.batch_size >= len(sampled_frame_caption_list):
            if len(result_dict[args.caption_column]) > 0:
                result_df = pd.DataFrame(result_dict)
                # Append is not supported (oss).
                if args.saved_path.endswith(".csv"):
                    if os.path.exists(args.saved_path):
                        saved_df = pd.read_csv(args.saved_path)
                        result_df = pd.concat([saved_df, result_df], ignore_index=True)
                    result_df.to_csv(args.saved_path, index=False)
                elif args.saved_path.endswith(".jsonl"):
                    if os.path.exists(args.saved_path):
                        saved_df = pd.read_json(args.saved_path, orient="records", lines=True)
                        result_df = pd.concat([saved_df, result_df], ignore_index=True)
                    result_df.to_json(args.saved_path, orient="records", lines=True, force_ascii=False)
                logger.info(f"Save result to {args.saved_path}.")

            result_dict = {args.caption_column: []}
            if args.video_path_column is not None:
                result_dict = {args.video_path_column: [], args.caption_column: []}
            if args.beautiful_prompt_column is not None:
                result_dict = {args.caption_column: [], args.beautiful_prompt_column: []}

if __name__ == "__main__":
    main()

import json
import torch
from PIL import Image
from transformers import AutoTokenizer, AutoConfig, AutoProcessor
from vllm import LLM, SamplingParams
from vllm.assets.image import ImageAsset
from vllm.assets.video import VideoAsset
from vllm.lora.request import LoRARequest
from vllm.multimodal.image import convert_image_mode
from typing import Tuple, List


class Predictor():

    def __init__(self,
                 tensor_parallel_size: int = 1,
                 model_from_pretrained: str = None,
                 resume_path: str = None,
                 **args
                 ):
        '''
        Predictor: LLM预测器 (LLM predictor)

        ### Args:

        `tensor_parallel_size`: 张量并行使用的 GPU 数量（模型被拆分到多个卡）

        `model_from_pretrained`: 预训练模型的路径或名称（如HuggingFace模型名）

        `resume_path`: 如果有预训练的LoRA模型，可以指定路径进行加载
        '''
        self.tp = tensor_parallel_size
        self.model_from_pretrained = model_from_pretrained
        self.lora_path = resume_path
        self.model_init(**args)

    def model_init(self, **args):
        self.config = AutoConfig.from_pretrained(
            self.model_from_pretrained, trust_remote_code=True)
        self.tokenizer = AutoTokenizer.from_pretrained(
            self.model_from_pretrained, padding_side="left", trust_remote_code=True)
        self.model_type = self.config.model_type if hasattr(self.config, 'model_type') else 'llama'
        self.llm = LLM(self.model_from_pretrained, tensor_parallel_size=self.tp, trust_remote_code=True, enable_lora=self.lora_path is not None, **args)
        self.processor = self.tokenizer
        if hasattr(self.config, 'eos_token_id'):
            self.eos_token_id = [self.config.eos_token_id]
        if hasattr(self.config, 'bos_token_id'):
            self.bos_token_id = [self.config.bos_token_id]
        if self.model_type == 'chatglm':
            self.eos_token_id = self.config.eos_token_id
        elif self.model_type == 'llama':
            self.tokenizer.pad_token = self.tokenizer.eos_token
            terminators = [
                self.tokenizer.eos_token_id,
                self.tokenizer.convert_tokens_to_ids("<|eot_id|>")
            ]
            if not hasattr(self, 'eos_token_id'):
                self.eos_token_id = []
            for t in terminators:
                if t is not None:
                    self.eos_token_id.append(t)
        elif self.model_type == "mimo":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
        elif self.model_type == "tinyr1":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
        elif self.model_type == "qwen2_5_vl":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
            self.processor = AutoProcessor.from_pretrained(self.model_from_pretrained, padding_side='left')
        elif self.model_type == "llava":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
            from transformers import LlavaForConditionalGeneration
            self.model =  LlavaForConditionalGeneration.from_pretrained(self.model_from_pretrained, torch_dtype=torch.float16, device_map="auto", trust_remote_code=True)
            self.processor = AutoProcessor.from_pretrained(self.model_from_pretrained, padding_side='left')
        elif self.model_type == "mllama":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
            from transformers import MllamaForConditionalGeneration
            self.model =  MllamaForConditionalGeneration.from_pretrained(self.model_from_pretrained, torch_dtype=torch.float16, device_map="auto", trust_remote_code=True)
            self.processor = AutoProcessor.from_pretrained(self.model_from_pretrained, padding_side='left', trust_remote_code=True)

    def process_model_outputs(self, inputs, outputs, tokenizer):
        responses = []
        for input_ids, output_ids in zip(inputs['input_ids'], outputs):
            response = tokenizer.decode(output_ids[len(input_ids):], skip_special_tokens=True).strip()
            responses.append(response)
        return responses

    def build_chat_input(self, query:list, history=None):
        if history is None:
            history = []
        history.append(query)
        is_mm = self.is_mm(history)
        max_input_tokens = 0
        new_batch_input = self.tokenizer.apply_chat_template(history, add_generation_prompt=True, tokenize=False)
        max_input_tokens = max(max_input_tokens, len(new_batch_input))
        return {
            'text': new_batch_input,
            'max_input_tokens': max_input_tokens,
            'is_mm': is_mm
        }

    def is_mm(self, message: dict | list):
        if not isinstance(message, list):
            message = [message]
        for msg in message:
            if isinstance(msg, dict) and 'content' in msg and isinstance(msg['content'], list):
                for content in msg['content']:
                    if 'type' in content and content['type'] in ['image', 'video']:
                        return True
        return False

    def process_mm(self, query_list:list, history_list=None):
        if history_list is not None:
            assert len(query_list) == len(history_list), "Query and history must have the same length."
            for query, history in zip(query_list, history_list):
                if isinstance(query, str):
                    query = {'role': 'user', 'content': query}
                history.append(query)
        else:
            history_list = [[query] for query in query_list]

        images_list = []
        for history in history_list:
            images = []
            for msg in history:
                if isinstance(msg['content'], list):
                    for content in msg['content']:
                        if isinstance(content, dict) and 'type' in content and content['type'] == 'image':
                            images.append(convert_image_mode(Image.open(content['image']), "RGB"))
            images_list.append(images)
        return images_list

    def prepare_generate(self, query: str | list = '', history: List = None, max_length=512, max_new_tokens=512, num_beams:int=1, top_p: float = 1.0, temperature=0, do_sample: bool = False, build_message=True):
        if not isinstance(query, list):
            query = [query]
            history = [history] if history is not None else None
        is_mm = False
        if build_message:
            inputs = []
            batch_max_len = 0
            for i, t in enumerate(query):
                if isinstance(t, str):
                    t = {'role': 'user', 'content': t}
                if history is not None and len(history) > 0:
                    h_unit = history[i]
                else:
                    h_unit = []
                chat_input = self.build_chat_input(t, h_unit)
                if batch_max_len < chat_input['max_input_tokens']:
                    batch_max_len = chat_input['max_input_tokens']
                inputs.append(chat_input['text'])
                if chat_input['is_mm']:
                    is_mm = True
        else:
            inputs = query
            batch_max_len = 0
            for i in range(len(query)):
                if len(query[i]) > batch_max_len:
                    batch_max_len = len(query[i])

        if is_mm:
            images_list = self.process_mm(query, history)
        else:
            images_list = []

        if len(images_list) > 0:
            new_inputs = []
            for i, text in enumerate(inputs):
                new_inputs.append({
                    "prompt": text,
                    "multi_modal_data": {"image": images_list[i]},
                })
            inputs = new_inputs

        sampling_params = SamplingParams(temperature=temperature, top_p=top_p, max_tokens=max_new_tokens)

        return inputs, sampling_params

    def predict(self, query: str | list = '', history: List = None, max_length=512, max_new_tokens=512, num_beams:int=1, top_p: float = 0.8, temperature=1.0, do_sample: bool = False, build_message=True):
        '''
        Predict method for generating responses from the model.

        ### Args:
        - `query`: The input query or list of queries.
        - `history`: Conversation history, if any.
        - `max_length`: Maximum length of the generated response.
        - `max_new_tokens`: Maximum number of new tokens to generate.
        - `num_beams`: Number of beams for beam search (default is 1).
        - `top_p`: Top-p sampling parameter.
        - `temperature`: Temperature for sampling.
        - `do_sample`: Whether to use sampling or greedy decoding.
        - `build_message`: Whether to build the message format for the model.

        ### Returns:
        - List of generated responses.
        '''

        inputs, sampling_params = self.prepare_generate(query, history, max_length, max_new_tokens, num_beams, top_p, temperature, do_sample, build_message)
        if self.lora_path is not None:
            outputs = self.llm.generate(
                inputs,
                sampling_params,
                lora_request=LoRARequest("custom_lora", 1, self.lora_path)
            )
        else:
            outputs = self.llm.generate(inputs, sampling_params)
        results = []
        for output in outputs:
            prompt = output.prompt
            generated_text = output.outputs[0].text
            results.append(generated_text)
        return results

    def __call__(self, query: str | list = '', history: List = None, max_length=512, max_new_tokens=512, num_beams:int=1, top_p: float = 0.8, temperature=1.0, do_sample: bool = False, build_message=True):
        return self.predict(query, history, max_length, max_new_tokens, num_beams, top_p, temperature, do_sample, build_message)

import json
import math
import time
import base64
import random
import argparse
from tqdm import tqdm
from transformers import AutoProcessor
from vllm import LLM, SamplingParams
# from vision_process import process_vision_info
from qwen_vl_utils import process_vision_info
from torch.utils.data import Dataset, DataLoader
from dataclasses import dataclass, field
import os
os.environ["VLLM_WORKER_MULTIPROC_METHOD"] = "spawn"
# os.environ["CUDA_VISIBLE_DEVICES"] = "0,1,2,3"


def init_model(model_path, tensor_parallel_size):
    llm = LLM(
        model=model_path,
        limit_mm_per_prompt={"image": 1, "video": 1},
        tensor_parallel_size=tensor_parallel_size
    )
    sampling_params = SamplingParams(
        temperature=0,
        top_p=0.001,
        repetition_penalty=1.05,
        max_tokens=2048,
        stop_token_ids=[],
    )
    processor = AutoProcessor.from_pretrained(model_path)
    return llm, sampling_params, processor


class QwenDataset(Dataset):
    def __init__(self, data_list, data_root, processor, video_kwargs=None, complex_prompt=False):
        super(QwenDataset, self).__init__()
        if complex_prompt:
            self.image_prompt = "Please describe the image in detail. Your description should follow these rules:\n"\
                "a) You should describe each object in the image in detail, including its name, number, color, and spatial relationship between objects.\n"\
                "b) You should describe the scene of the image.\n"\
                "c) You should describe the camera angle when shooting this image, such as level angle, high angle, low angle, or dutch angle.\n"\
                "d) You should describe the style of the image, such as realistic, animated, special-effect, old-fashioned and so on.\n"\
                "e) If there are any texts in the image, you should describe the text content.\n"\
                "f) If you know the character in the image, you should tell his or her name.\n"\
                "Directly output your detailed description in a elaborate paragraph, instead of itemizing them in list form. Your description: "
            self.video_prompt = "Please describe the video in detail. Your description should follow these rules:\n"\
                "a) You should describe each events in the video in order, especially focusing on the behavior and action of characters, including people, animals.\n"\
                "b) You should describe each object in the video in detail, including its name, number, color, and spatial relationship between objects.\n"\
                "c) You should describe the scene of the video.\n"\
                "d) You should describe the camera movement when shooting this video, especially the direction, such as pan left, track right, tilt up, boom down, zoom in, dolly out, and so on.\n"\
                "e) You should describe the style of the video, such as realistic, animated, special-effect, old-fashioned and so on.\n"\
                "f) If there are any texts in the video, you should describe the text content.\n"\
                "g) If you know the character in the video, you should tell his or her name.\n"\
                "Directly output your detailed description in a elaborate paragraph, instead of itemizing them in list form. Your description: "
        else:
            self.image_prompt = "Please describe the image in detail."
            self.video_prompt = "Please describe the video in detail."
        self.data_list = data_list
        self.data_root = data_root
        self.processor = processor
        self.video_kwargs = video_kwargs

    def __len__(self):
        return len(self.data_list)

    def __getitem__(self, index):
        data = self.data_list[index]
        llm_input = self.get_llm_input_from_data(data, self.video_kwargs)
        return data, llm_input

    def get_llm_input_from_data(self, data, video_kwargs=None):
        if data['data_type'] == 'image':
            file_path = data['file_path']
            text_prompt = self.image_prompt
            content = [
                {
                    "type": "image",
                    "image": f"file://{os.path.join(self.data_root, file_path)}",
                },
                {
                    "type": "text",
                    "text": text_prompt
                },
            ]
        elif data['data_type'] == 'video':
            file_path = data['file_path']
            text_prompt = self.video_prompt
            content = [
                {
                    "type": "video",
                    "video": f"file://{os.path.join(self.data_root, file_path)}",
                    # "fps": 2.0,
                    # "max_frames": 768,
                },
                {"type": "text", "text": text_prompt},
            ]
            if video_kwargs is not None:
                content[0].update(video_kwargs)
        else:
            raise ValueError("No image or video path in data")

        messages = [
            {"role": "system", "content": "You are a helpful assistant."},
            {
                "role": "user",
                "content": content,
            },
        ]

        prompt = self.processor.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=True,
        )

        image_inputs, video_inputs = process_vision_info(messages)
        mm_data = {}
        if image_inputs is not None:
            mm_data["image"] = image_inputs
        if video_inputs is not None:
            mm_data["video"] = video_inputs

        llm_input = {
            "prompt": prompt,
            "multi_modal_data": mm_data,
        }

        return llm_input

@dataclass
class DataCollator(object):
    def __call__(self, batch):
        datas = []
        llm_inputs = []
        for e in batch:
            datas.append(e[0])
            llm_inputs.append(e[1])
        return datas, llm_inputs


def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("--model_path", type=str, required=True)
    parser.add_argument("--save_root", type=str, required=True)
    parser.add_argument("--benchmark", type=str, required=False, default=None)
    parser.add_argument("--error_save_root", type=str, required=False, default=None)
    parser.add_argument("--is_processing_large_videos", action="store_true")
    parser.add_argument("--num_gpus", type=int, default=4)
    parser.add_argument("--complex_prompt", action='store_true', default=False)
    return parser.parse_args()


def llm_infer(llm, llm_inputs, sampling_params):
    try:
        outputs = llm.generate(llm_inputs, sampling_params=sampling_params)
        generated_texts = [outputs[j].outputs[0].text for j in range(len(llm_inputs))]
    except Exception as e:
        print("Error:", e)
        return None

    return generated_texts

if __name__ == '__main__':
    args = parse_args()
    model_path = args.model_path
    model_name = os.path.basename(model_path)
    tensor_parallel_size = args.num_gpus
    llm, sampling_params, processor = init_model(model_path, tensor_parallel_size)

    anno_root = "../annotations"
    data_root = "../"
    anno_files = [os.path.join(anno_root, filename) for filename in os.listdir(anno_root)]
    if args.benchmark is not None:
        anno_files = [f for f in anno_files if args.benchmark in f]
        assert len(anno_files) == 1
    save_root = args.save_root
    os.makedirs(save_root, exist_ok=True)

    if args.error_save_root is not None:
        os.makedirs(args.error_save_root, exist_ok=True)

    for anno_file in tqdm(anno_files, desc="task"):
        if 'action' in anno_file:
            continue

        task_name = os.path.basename(anno_file).split('.')[0]
        save_file = os.path.join(save_root, f"{task_name}.jsonl")
        if args.error_save_root is not None:
            error_file = os.path.join(args.error_save_root, f"{task_name}.jsonl")
        with open(anno_file, 'r', encoding='utf-8') as f:
            data = [json.loads(l.strip('\n')) for l in f.readlines()]

        data_type = data[0]['data_type']
        if data_type == 'image':
            data_type = 'image'
            batch_size = 4 if '72B' in model_path else 24
        elif data_type == 'video':
            data_type = 'video'
            batch_size = 2 if '72B' in model_path else 4
        else:
            raise ValueError("No image or video path in data")



        print(f"[{task_name}] data length: {len(data)}")
        if os.path.exists(save_file):
            with open(save_file, 'r', encoding='utf-8') as f:
                processed_data = [json.loads(l.strip('\n')) for l in f.readlines()]
            processed_data = [d['file_id'] for d in processed_data]
            remain_data = [d for d in data if d['file_id'] not in processed_data]
            print(f"[{task_name}] Find {len(processed_data)} records, remaining {len(remain_data)} to be processed")
        else:
            remain_data = data
        if len(remain_data) == 0:
            continue

        if args.is_processing_large_videos and 'Qwen2.5' in args.model_path:
            video_kwargs = {
                "max_pixels": 360 * 512,
            }
            batch_size = 1
        elif args.is_processing_large_videos:
            video_kwargs = {
                "max_pixels": 360 * 360,
                "fps": 1.0,
                "max_frames": 384,
            }

        else:
            video_kwargs = None
        dataset = QwenDataset(remain_data, data_root, processor, video_kwargs, complex_prompt=args.complex_prompt)
        dataloader = DataLoader(
            dataset, batch_size=batch_size,
            shuffle=False, num_workers=8,
            collate_fn=DataCollator(), pin_memory=True
        )

        for i, (datas, llm_inputs) in enumerate(tqdm(dataloader, desc=task_name)):
            generated_texts = llm_infer(llm, llm_inputs, sampling_params)
            if generated_texts is None:
                assert data_type == "video"
                for d in datas:
                    llm_inputs = [dataset.get_llm_input_from_data(d)]
                    generated_texts = llm_infer(llm, llm_inputs, sampling_params)
                    if generated_texts is None:
                        if args.error_save_root is not None:
                            with open(error_file, 'a', encoding='utf-8') as f:
                                f.write(json.dumps(d, ensure_ascii=False) + '\n')
                            continue
                    else:
                        with open(save_file, 'a', encoding='utf-8') as f:
                            f.write(json.dumps({'file_id': d['file_id'], 'caption': generated_texts[0]}, ensure_ascii=False) + '\n')
            else:
                with open(save_file, 'a', encoding='utf-8') as f:
                    for k,v in zip(datas, generated_texts):
                        f.write(json.dumps({'file_id':k['file_id'], 'caption': v}, ensure_ascii=False) + '\n')


        if args.error_save_root is not None and os.path.exists(error_file):
            with open(error_file, 'r', encoding='utf-8') as f:
                error_data = [json.loads(l.strip('\n')) for l in f.readlines()]
            if len(error_data) == 0:
                os.remove(error_file)

import os
import logging
from dotenv import load_dotenv
import argparse
from tqdm import tqdm
from transformers import AutoTokenizer, AutoModelForCausalLM
from vllm import LLM, SamplingParams
import openai


os.makedirs(f'logs', exist_ok=True)
logging.basicConfig(filename=f"logs/translation.log", level=logging.INFO, format='%(asctime)s %(levelname)s %(module)s - %(funcName)s: %(message)s', datefmt='%Y-%m-%d %H:%M:%S')


def main(args):

    extensions = {'python': 'py', 'java': 'java'}

    experiment_type = 'no_test'
    if args.use_misleading_test:
        experiment_type = 'misleading_test'
    elif args.use_test:
        experiment_type = 'w_test'

    test_type = 'tests'
    if args.use_misleading_test:
        test_type = 'misleading_tests'

    in_folder = f'translation_dataset/{args.dataset}/{args.source_lang}/code'
    test_folder = f'translation_dataset/{args.dataset}/{args.source_lang}/tests'
    out_folder = f'translation_output/{experiment_type}/{args.model}/{args.dataset}/{args.source_lang}/{args.target_lang}'

    in_files = os.listdir(in_folder)
    print(f'found {len(in_files)} inputs')

    # check for files alraedy extracted
    already_extracted_files = []
    if os.path.exists(out_folder):
        already_extracted_files = os.listdir(out_folder)
        if len(already_extracted_files) > 0:
            already_extracted_files = [x.split('.')[0] for x in already_extracted_files if os.stat(f'{out_folder}/{x}').st_size != 0]

    if len(already_extracted_files) > 0:
        in_files = [x for x in in_files if x.split('.')[0] not in already_extracted_files]

    ext = extensions[args.target_lang]
    device = f'cuda:{args.gpu_id}'

    tokenizer, model = None, None
    if args.model == 'codellama':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("codellama/CodeLlama-13b-Instruct-hf", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("codellama/CodeLlama-13b-Instruct-hf", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'magicoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("ise-uiuc/Magicoder-S-DS-6.7B", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("ise-uiuc/Magicoder-S-DS-6.7B", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'wizardcoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("WizardLM/WizardCoder-15B-V1.0", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("WizardLM/WizardCoder-15B-V1.0", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'deepseekcoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("deepseek-ai/deepseek-coder-6.7b-instruct", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("deepseek-ai/deepseek-coder-6.7b-instruct", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'starcoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("bigcode/starcoder", token=os.environ['STARCODER_AUTH_TOKEN'], cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("bigcode/starcoder", token=os.environ['STARCODER_AUTH_TOKEN'], cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'mistral':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("mistralai/Mistral-7B-Instruct-v0.1", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("mistralai/Mistral-7B-Instruct-v0.1", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'llama2':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained('meta-llama/Llama-2-13b-hf', token=os.environ['LLAMA2_AUTH_TOKEN'], cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained('meta-llama/Llama-2-13b-hf', token=os.environ['LLAMA2_AUTH_TOKEN'], cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'starcoder2':
        kwargs = {}
        model = LLM(model="bigcode/starcoder2-15b", tokenizer="bigcode/starcoder2-15b", **kwargs)

    elif args.model in ['gpt-4', 'gpt-3.5']:
        model = openai.OpenAI(
                    # This is the default and can be omitted
                    api_key=os.environ['OPENAI_API_KEY'],
                )

    # loop over input files
    os.makedirs(out_folder, exist_ok=True)
    for f in tqdm(in_files):

        base_name = f.split('.')[0]

        test_input = open(f'{test_folder}/{base_name}_in.txt', 'r').read()
        test_output = ''
        if args.use_test:
            test_output = open(f'{test_folder}/{base_name}_out.txt', 'r').read()
        elif args.use_misleading_test:
            test_output = open(f'{test_folder}/{base_name}_misleading_out.txt', 'r').read()

        if len(test_input) > 500 or len(test_output) > 500:
            continue

        prompt_file = f'{in_folder}/{f}'

        with open(prompt_file, "r", encoding="ISO-8859-1", errors='ignore') as fin:
            prompt = fin.readlines()

            if args.model == 'codellama':
                if args.use_test or args.use_misleading_test:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n"
                else:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n"
                prompt = f"[INST] <<SYS>>\nYou are an expert {args.target_lang} programmer and assistant\n<</SYS>>\n\n{prompt}[/INST]\n"

            elif args.model == 'magicoder':
                if args.use_test or args.use_misleading_test:
                    prompt = f"You are an exceptionally intelligent coding assistant that consistently delivers accurate and reliable responses to user instructions.\n\n@@ Instruction\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n\n@@ Response\n"
                else:
                    prompt = f"You are an exceptionally intelligent coding assistant that consistently delivers accurate and reliable responses to user instructions.\n\n@@ Instruction\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n\n@@ Response\n"

            elif args.model == 'wizardcoder':
                if args.use_test or args.use_misleading_test:
                    prompt = f"Below is an instruction that describes a task. Write a response that appropriately completes the request.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"
                else:
                    prompt = f"Below is an instruction that describes a task. Write a response that appropriately completes the request.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"

            elif args.model == 'deepseekcoder':
                if args.use_test or args.use_misleading_test:
                    prompt = f"You are an expert Python programmer.Your task is to write a Python function to solve a programming problem.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"
                else:
                    prompt = f"You are an expert Python programmer.Your task is to write a Python function to solve a programming problem.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"

            elif args.model == 'mistral':
                if args.use_test or args.use_misleading_test:
                    prompt = f"[INST] Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n[/INST]\n"
                else:
                    prompt = f"[INST] Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n[/INST]\n"

            elif args.model in ['starcoder', 'starcoder2']:
                if args.use_test or args.use_misleading_test:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + f"\n```\n\n{args.target_lang} code:"
                else:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + f"\n```\n\n{args.target_lang} code:"
                prefix_token = "<fim_prefix>"
                suffix_token = "<fim_suffix><fim_middle>"
                prompt = prefix_token + prompt + suffix_token

            elif args.model in ['gpt-4', 'gpt-3.5']:
                if args.use_test or args.use_misleading_test:
                    prompt = "Translate the following code from " + args.source_lang + " to " + args.target_lang + " and enclose your solution inside ```" + args.target_lang.lower() + "```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n"
                else:
                    prompt = "Translate the following code from " + args.source_lang + " to " + args.target_lang + " and enclose your solution inside ```" + args.target_lang.lower() + "```:\n```\n" + "".join(prompt) + "\n```\n"

            try:

                if args.model in ['starcoder2']:
                    total_input_tokens = len(model.get_tokenizer().encode(prompt))
                    model_max_length = 2048
                    if total_input_tokens >= model_max_length:
                        out_file = f'{out_folder}/{f.split(".")[0]}.{ext}'
                        with open(out_file, 'w') as fot:
                            print("# Token size exceeded.", file=fot)
                        continue
                    max_new_tokens = model_max_length - total_input_tokens
                    vllm_outputs = model.generate(
                        prompt,
                        SamplingParams(
                            temperature=0.0,
                            max_tokens=max_new_tokens,
                            stop=['<|endoftext|>'],
                            top_p=1.0,
                        ),
                        use_tqdm=False,
                    )

                    gen_strs = [x.outputs[0].text.replace("\t", "    ") for x in vllm_outputs]
                    generated_output = gen_strs[0]

                elif args.model in ['gpt-4', 'gpt-3.5']:
                    try:
                        response = model.chat.completions.create(
                            model="gpt-4-1106-preview" if args.model == 'gpt-4' else "gpt-3.5-turbo",
                            messages=[
                                {
                                    "role": "system",
                                    "content": "You are an expert " + args.target_lang + " programmer and assistant"
                                },
                                {
                                    "role": "user",
                                    "content": prompt
                                }
                            ]
                        )
                        generated_output = response.choices[0].message.content
                    except openai.BadRequestError as e:
                        generated_output = f'token size exceeded. {e}'

                else:

                    inputs = tokenizer.encode(prompt, return_tensors="pt").to(device)
                    total_input_tokens = inputs.shape[1]
                    model_max_length = 2048
                    if total_input_tokens >= model_max_length:
                        out_file = f'{out_folder}/{f.split(".")[0]}.{ext}'
                        with open(out_file, 'w') as fot:
                            print("# Token size exceeded.", file=fot)
                        continue
                    max_new_tokens = model_max_length - total_input_tokens

                    raw_outputs = ''
                    raw_outputs = model.generate(
                        inputs,
                        max_new_tokens=max_new_tokens,
                        do_sample=False,
                        pad_token_id=tokenizer.eos_token_id,
                    )

                    generated_output = tokenizer.decode(raw_outputs[0])

                out_file = f'{out_folder}/{f.split(".")[0]}.{ext}'
                with open(out_file, 'w') as fot:
                    print(generated_output, file=fot)

            except (ValueError, FileNotFoundError) as e:
                print(e)
                continue


if __name__ == "__main__":
    load_dotenv()
    parser = argparse.ArgumentParser(description='run translation with open-source models given dataset and languages')
    parser.add_argument('--model', help='model to use for code translation', required=True, type=str)
    parser.add_argument('--dataset', help='dataset to use for code translation', required=True, type=str)
    parser.add_argument('--source_lang', help='source language to use for code translation', required=True, type=str)
    parser.add_argument('--target_lang', help='target language to use for code translation', required=True, type=str)
    parser.add_argument('--gpu_id', help='gpu id to use', required=True, type=int)
    parser.add_argument('--cache_dir', help='cache directory for huggingface models', required=True, type=str)
    parser.add_argument('--use_test', help='use test dataset', action='store_true')
    parser.add_argument('--use_misleading_test', help='use test dataset', action='store_true')
    args = parser.parse_args()

    # Initialize configurations
    source = args.source_lang
    target = args.target_lang
    logging.info(f"translating examples from {source} to {target} using {args.model} and {args.dataset} dataset")
    main(args)

from __future__ import annotations

import os
import sys
import warnings
import math
import logging

import torch
from transformers import StoppingCriteria

from ..base import BaseModel
from .prompt import Qwen2VLPromptMixin
from ...smp import get_gpu_memory, listinstr
from ...dataset import DATASET_MODALITY

VLLM_MAX_IMAGE_INPUT_NUM = 24


def ensure_image_url(image: str) -> str:
    prefixes = ['http://', 'https://', 'file://', 'data:image;']
    if any(image.startswith(prefix) for prefix in prefixes):
        return image
    if os.path.exists(image):
        return 'file://' + image
    raise ValueError(f'Invalid image: {image}')


def ensure_video_url(video: str) -> str:
    prefixes = ['http://', 'https://', 'file://', 'data:video;']
    if any(video.startswith(prefix) for prefix in prefixes):
        return video
    if os.path.exists(video):
        return 'file://' + video
    raise ValueError(f'Invalid video: {video}')


def create_image_content(image_path, min_pixels, max_pixels):
    base64_image, mime_type = encode_image(image_path)
    return {
        "type": "image",
        "image": f"data:{mime_type};base64,{base64_image}",
        'min_pixels': min_pixels,
        'max_pixels': max_pixels
    }


def encode_image(image_path, max_side=None):
    from mimetypes import guess_type
    mime_type, _ = guess_type(image_path)
    if mime_type is None:
        mime_type = "image/jpeg"
    image_format = mime_type.split("/")[-1].upper() if mime_type else "JPEG"

    from PIL import Image
    image = Image.open(image_path)
    # Handle the alpha channel
    if image.mode == "RGBA":
        image = _rgba_to_rgb(image)
    if max_side:
        image = _resize_image(image, max_side)
    encoded_image = _encode_image(image, image_format)

    return encoded_image, mime_type


def _encode_image(image, image_format):
    from io import BytesIO
    with BytesIO() as output:
        image.convert("RGB").save(output, format=image_format)
        import base64
        base64_encoded_data = base64.b64encode(output.getvalue()).decode("utf-8")
    return base64_encoded_data


def _rgba_to_rgb(image):
    from PIL import Image
    background = Image.new("RGBA", image.size, (255, 255, 255, 255))
    return Image.alpha_composite(background, image).convert("RGB")


def _resize_image(image, max_side):
    resize_scale = max_side / max(image.size)
    new_size = (
        int(image.size[0] * resize_scale),
        int(image.size[1] * resize_scale),
    )
    return image.resize(new_size)


def process_video(video_path, num_frames, min_pixels, max_pixels):
    import cv2
    # Open the video file
    cap = cv2.VideoCapture(video_path)
    frame_count = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
    fps = cap.get(cv2.CAP_PROP_FPS)  # Frames per second

    # the sampling rate using max number of frames
    sampling_gap_maxframe = (
        1 if not num_frames else math.ceil(frame_count / num_frames)
    )
    sampling_gap = max(math.ceil(fps / 5), sampling_gap_maxframe)

    frame_number = 0
    images = []

    while True:
        import tempfile
        success, frame = cap.read()
        if not success:
            break
        # Sample frames based on the dynamic sampling rate
        if frame_number % sampling_gap == 0:
            # Create a temporary file for the frame
            with tempfile.NamedTemporaryFile(
                suffix=".jpg", delete=False
            ) as temp_frame:
                cv2.imwrite(temp_frame.name, frame)
                images.append(create_image_content(temp_frame.name, min_pixels, max_pixels))
                os.remove(temp_frame.name)
        frame_number += 1
    if frame_number == 0:
        raise ValueError(f"Failed to read video from {video_path}, check data...")
    logging.info(
        f"Sampled {len(images)}/{frame_number} frames from video {video_path}"
    )
    cap.release()
    return images


class KeywordsStoppingCriteria(StoppingCriteria):
    def __init__(self, keywords, tokenizer, input_ids):
        self.keywords = keywords
        self.keyword_ids = []
        self.max_keyword_len = 0
        for keyword in keywords:
            cur_keyword_ids = tokenizer(keyword).input_ids
            if (
                len(cur_keyword_ids) > 1
                and cur_keyword_ids[0] == tokenizer.bos_token_id
            ):
                cur_keyword_ids = cur_keyword_ids[1:]
            if len(cur_keyword_ids) > self.max_keyword_len:
                self.max_keyword_len = len(cur_keyword_ids)
            self.keyword_ids.append(torch.tensor(cur_keyword_ids))
        self.tokenizer = tokenizer
        self.start_len = input_ids.shape[1]

    def __call__(
        self, output_ids: torch.LongTensor, scores: torch.FloatTensor, **kwargs
    ) -> bool:
        assert output_ids.shape[0] == 1, "Only support batch size 1 (yet)"  # TODO
        offset = min(output_ids.shape[1] - self.start_len, self.max_keyword_len)
        self.keyword_ids = [
            keyword_id.to(output_ids.device) for keyword_id in self.keyword_ids
        ]
        for keyword_id in self.keyword_ids:
            if (output_ids[0, -keyword_id.shape[0]:] == keyword_id).all():
                return True
        outputs = self.tokenizer.batch_decode(
            output_ids[:, -offset:], skip_special_tokens=True
        )[0]
        for keyword in self.keywords:
            if keyword in outputs:
                return True
        return False


CHAT_TEMPLATE = "{% set image_count = namespace(value=0) %}{% set video_count = namespace(value=0) %}{% for message in messages %}<|im_start|>{{ message['role'] }}\n{% if message['content'] is string %}{{ message['content'] }}<|im_end|>\n{% else %}{% for content in message['content'] %}{% if content['type'] == 'image' or 'image' in content or 'image_url' in content %}{% set image_count.value = image_count.value + 1 %}{% if add_vision_id %}Picture {{ image_count.value }}: {% endif %}<|vision_start|><|image_pad|><|vision_end|>{% elif content['type'] == 'video' or 'video' in content %}{% set video_count.value = video_count.value + 1 %}{% if add_vision_id %}Video {{ video_count.value }}: {% endif %}<|vision_start|><|video_pad|><|vision_end|>{% elif 'text' in content %}{{ content['text'] }}{% endif %}{% endfor %}<|im_end|>\n{% endif %}{% endfor %}{% if add_generation_prompt %}<|im_start|>assistant\n{% endif %}"  # noqa: E501

UNTIL = ["<|diff_marker|>"]


class Qwen2VLChat(Qwen2VLPromptMixin, BaseModel):
    INSTALL_REQ = False
    INTERLEAVE = True
    VIDEO_LLM = True

    def __init__(
        self,
        model_path: str,
        min_pixels: int | None = None,
        max_pixels: int | None = None,
        total_pixels: int | None = None,
        max_new_tokens=2048,
        top_p=0.001,
        top_k=1,
        temperature=0.01,
        repetition_penalty=1.0,
        use_custom_prompt: bool = True,
        system_prompt: str | None = None,
        post_process: bool = False,  # if True, will try to only extract stuff in the last \boxed{}.
        verbose: bool = False,
        use_audio_in_video: bool = False,
        **kwargs,
    ):
        super().__init__(use_custom_prompt=use_custom_prompt)
        self.min_pixels = min_pixels
        self.max_pixels = max_pixels
        self.total_pixels = total_pixels
        self.max_new_tokens = max_new_tokens
        if self.total_pixels and self.total_pixels > 24576 * 28 * 28:
            print('The total number of video tokens might become too large, resulting in an overly long input sequence. We recommend lowering **total_pixels** to below **24576 × 28 × 28**.')  # noqa: E501
        self.generate_kwargs = dict(
            max_new_tokens=self.max_new_tokens,
            top_p=top_p,
            top_k=top_k,
            temperature=temperature,
            repetition_penalty=repetition_penalty,
        )
        self.system_prompt = system_prompt
        self.verbose = verbose
        self.post_process = post_process
        self.fps = kwargs.pop('fps', 2)
        self.nframe = kwargs.pop('nframe', 128)
        if self.fps is None and self.nframe is None:
            print("Warning: fps and nframe are both None, \
                  using default nframe/fps setting in qwen-vl-utils/qwen-omni-utils, \
                  the fps/nframe setting in video dataset is omitted")
        self.use_audio_in_video = use_audio_in_video
        self.FRAME_FACTOR = 2
        assert model_path is not None
        self.model_path = model_path
        MODEL_CLS = None

        if listinstr(['omni'], model_path.lower()):
            try:
                from transformers import Qwen2_5OmniForConditionalGeneration, Qwen2_5OmniProcessor
            except Exception as err:
                logging.critical("pip install git+https://github.com/huggingface/transformers@3a1ead0aabed473eafe527915eea8c197d424356")  # noqa: E501
                raise err
            MODEL_CLS = Qwen2_5OmniForConditionalGeneration
            self.processor = Qwen2_5OmniProcessor.from_pretrained(model_path)
        elif listinstr(['2.5', '2_5', 'qwen25', 'mimo'], model_path.lower()):
            from transformers import Qwen2_5_VLForConditionalGeneration, AutoProcessor
            MODEL_CLS = Qwen2_5_VLForConditionalGeneration
            self.processor = AutoProcessor.from_pretrained(model_path)
        else:
            from transformers import Qwen2VLForConditionalGeneration, Qwen2VLProcessor
            MODEL_CLS = Qwen2VLForConditionalGeneration
            self.processor = Qwen2VLProcessor.from_pretrained(model_path)

        gpu_mems = get_gpu_memory()
        max_gpu_mem = max(gpu_mems) if gpu_mems != [] else -1
        assert max_gpu_mem > 0
        self.use_vllm = kwargs.get('use_vllm', False)
        self.use_lmdeploy = kwargs.get('use_lmdeploy', False)
        self.limit_mm_per_prompt = VLLM_MAX_IMAGE_INPUT_NUM
        assert self.use_vllm + self.use_lmdeploy <= 1, "You can only set one flag between `use_vllm` and `use_lmdeploy` to True"  # noqa: E501

        if self.use_vllm:
            from vllm import LLM
            gpu_count = torch.cuda.device_count()
            if gpu_count >= 8:
                tp_size = 8
            elif gpu_count >= 4:
                tp_size = 4
            elif gpu_count >= 2:
                tp_size = 2
            else:
                tp_size = 1
            logging.info(
                f'Using vLLM for {self.model_path} inference with {tp_size} GPUs (available: {gpu_count})'
            )
            import os
            if os.environ.get('VLLM_WORKER_MULTIPROC_METHOD') != 'spawn':
                logging.warning(
                    'VLLM_WORKER_MULTIPROC_METHOD is not set to spawn.'
                    'Use \'export VLLM_WORKER_MULTIPROC_METHOD=spawn\' to avoid potential multi-process issues'
                )
            self.llm = LLM(
                model=self.model_path,
                max_num_seqs=5,
                max_model_len=32768,
                limit_mm_per_prompt={"image": self.limit_mm_per_prompt},
                tensor_parallel_size=tp_size,
                gpu_memory_utilization=kwargs.get("gpu_utils", 0.9),
            )

        elif self.use_lmdeploy:
            from lmdeploy import TurbomindEngineConfig, pipeline, ChatTemplateConfig
            num_gpus = torch.cuda.device_count()
            self.model = pipeline(
                model_path,
                backend_config=TurbomindEngineConfig(session_len=32768, cache_max_entry_count=0.1, tp=num_gpus),
                chat_template_config=ChatTemplateConfig(model_name='qwen2d5-vl'))
            torch.cuda.set_device(0)
            self.device = 'cuda'
        else:
            self.model = MODEL_CLS.from_pretrained(
                model_path, torch_dtype='auto', device_map="auto", attn_implementation='flash_attention_2'
            )
            self.model.eval()

        torch.cuda.empty_cache()

    def _prepare_content(self, inputs: list[dict[str, str]], dataset: str | None = None) -> list[dict[str, str]]:
        """
        inputs list[dict[str, str]], each dict has keys: ['type', 'value']
        """
        content = []
        for s in inputs:
            if s['type'] == 'image':
                item = {'type': 'image', 'image': ensure_image_url(s['value'])}
                if dataset == 'OCRBench':
                    item['min_pixels'] = 10 * 10 * 28 * 28
                    warnings.warn(f"OCRBench dataset uses custom min_pixels={item['min_pixels']}")
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                else:
                    if self.min_pixels is not None:
                        item['min_pixels'] = self.min_pixels
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                if self.total_pixels is not None:
                    item['total_pixels'] = self.total_pixels
            elif s['type'] == 'video':
                item = {
                    'type': 'video',
                    'video': ensure_video_url(s['value'])
                }
                if self.min_pixels is not None:
                    item['min_pixels'] = self.min_pixels
                if self.max_pixels is not None:
                    item['max_pixels'] = self.max_pixels
                if self.total_pixels is not None:
                    item['total_pixels'] = self.total_pixels
                if self.fps is not None:
                    item['fps'] = self.fps
                elif self.nframe is not None:
                    import cv2
                    video = cv2.VideoCapture(s['value'])
                    frame_count = int(video.get(cv2.CAP_PROP_FRAME_COUNT))
                    video.release()
                    if frame_count < self.nframe:
                        new_frame_count = frame_count // self.FRAME_FACTOR * self.FRAME_FACTOR
                        print(f"use {new_frame_count} for {s['value']}")
                        item['nframes'] = new_frame_count
                    else:
                        item['nframes'] = self.nframe
            elif s['type'] == 'text':
                item = {'type': 'text', 'text': s['value']}
            elif s['type'] == 'audio':
                item = {'type':'audio','audio':s['value']}
            else:
                raise ValueError(f"Invalid message type: {s['type']}, {s}")
            content.append(item)
        return content

    def _prepare_content_vllm(self, inputs: list[dict[str, str]], dataset: str | None = None) -> list[dict[str, str]]:
        """
        inputs list[dict[str, str]], each dict has keys: ['type', 'value']
        """
        content = []
        video_inputs = [s for s in inputs if s['type'] == 'video']
        video_count = len(video_inputs)
        cur_image_count = 0
        for s in inputs:
            if s['type'] == 'image':
                item = {'type': 'image', 'image': ensure_image_url(s['value'])}
                if dataset == 'OCRBench':
                    item['min_pixels'] = 10 * 10 * 28 * 28
                    warnings.warn(f"OCRBench dataset uses custom min_pixels={item['min_pixels']}")
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                else:
                    if self.min_pixels is not None:
                        item['min_pixels'] = self.min_pixels
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                if self.total_pixels is not None:
                    item['total_pixels'] = self.total_pixels
                if cur_image_count < self.limit_mm_per_prompt:
                    content.append(item)
                    cur_image_count += 1
                else:
                    logging.warning(
                        f"Number of images exceeds the limit of {self.limit_mm_per_prompt}. "
                        f"Only the first {self.limit_mm_per_prompt} images will be used."
                    )
            elif s['type'] == 'video':
                if video_count > 1:
                    logging.warning(
                        "Multiple videos detected. Using video frames for each video"
                    )
                    if dataset == 'OCRBench':
                        min_pixels = 10 * 10 * 28 * 28
                        warnings.warn(f"OCRBench dataset uses custom min_pixels={min_pixels}")
                        if self.max_pixels is not None:
                            max_pixels = self.max_pixels
                    else:
                        if self.min_pixels is not None:
                            min_pixels = self.min_pixels
                        if self.max_pixels is not None:
                            max_pixels = self.max_pixels
                    import cv2
                    video = cv2.VideoCapture(s['value'])
                    frame_count = int(video.get(cv2.CAP_PROP_FRAME_COUNT))
                    video.release()

                    frames_per_video = max(1, self.limit_mm_per_prompt // video_count)
                    content.append({"type": "text", "text": "<video frames start>"})
                    content.extend(process_video(s['value'], frames_per_video, min_pixels, max_pixels))
                    content.append({"type": "text", "text": "<video frames end>"})

                else:
                    item = {
                        'type': 'video',
                        'video': ensure_video_url(s['value'])
                    }
                    if self.min_pixels is not None:
                        item['min_pixels'] = self.min_pixels
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                    if self.total_pixels is not None:
                        item['total_pixels'] = self.total_pixels
                    if self.fps is not None:
                        item['fps'] = self.fps
                    elif self.nframe is not None:
                        import cv2
                        video = cv2.VideoCapture(s['value'])
                        frame_count = int(video.get(cv2.CAP_PROP_FRAME_COUNT))
                        video.release()
                        if frame_count < self.nframe:
                            new_frame_count = frame_count // self.FRAME_FACTOR * self.FRAME_FACTOR
                            print(f"use {new_frame_count} for {s['value']}")
                            item['nframes'] = new_frame_count
                        else:
                            item['nframes'] = self.nframe
                    content.append(item)
            elif s['type'] == 'text':
                item = {'type': 'text', 'text': s['value']}
                content.append(item)
            else:
                raise ValueError(f"Invalid message type: {s['type']}, {s}")
        return content

    def generate_inner_transformers(self, message, dataset=None):
        if listinstr(['omni'], self.model_path.lower()):
            try:
                from qwen_omni_utils import process_mm_info
            except Exception as err:
                logging.critical("qwen_omni_utils not found, please install it via 'pip install qwen-omni-utils[decord]'")  # noqa: E501
                raise err
        else:
            try:
                from qwen_vl_utils import process_vision_info
            except Exception as err:
                logging.critical("qwen_vl_utils not found, please install it via 'pip install qwen-vl-utils'")  # noqa: E501
                raise err

        messages = []
        if self.system_prompt is not None:
            messages.append({'role': 'system', 'content': self.system_prompt})
        messages.append({'role': 'user', 'content': self._prepare_content(message, dataset=dataset)})
        if self.verbose:
            print(f'\033[31m{messages}\033[0m')

        text = self.processor.apply_chat_template([messages], tokenize=False, add_generation_prompt=True)
        if listinstr(['omni'], self.model_path.lower()):
            audios, images, videos = process_mm_info([messages], use_audio_in_video=self.use_audio_in_video)
            inputs = self.processor(text=text, images=images,audio=audios, videos=videos, padding=True, return_tensors='pt',use_audio_in_video=self.use_audio_in_video)  # noqa: E501
        else:
            images, videos = process_vision_info([messages])
            inputs = self.processor(text=text, images=images, videos=videos, padding=True, return_tensors='pt')  # noqa: E501
        inputs = inputs.to('cuda')

        if listinstr(['omni'], self.model_path.lower()):
            self.generate_kwargs['use_audio_in_video'] = self.use_audio_in_video
            self.generate_kwargs['return_audio'] = False
        generated_ids = self.model.generate(
            **inputs,
            **self.generate_kwargs,
        )
        generated_ids = [
            output_ids[len(input_ids):] for input_ids, output_ids in zip(inputs.input_ids, generated_ids)
        ]
        out = self.processor.tokenizer.batch_decode(
            generated_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False
        )
        response = out[0]
        if self.post_process:
            resp = response.split('\\boxed{')[-1]
            lt = len(resp)
            counter, end = 1, None
            for i in range(lt):
                if resp[i] == '{':
                    counter += 1
                elif resp[i] == '}':
                    counter -= 1
                if counter == 0:
                    end = i
                    break
                elif i == lt - 1:
                    end = lt
                    break
            if end is not None:
                response = resp[:end]

        if self.verbose:
            print(f'\033[32m{response}\033[0m')
        return response

    def generate_inner_lmdeploy(self, message, dataset=None):
        from lmdeploy import GenerationConfig
        gen_config = GenerationConfig(
            max_new_tokens=self.max_new_tokens,
            top_p=self.generate_kwargs['top_p'],
            top_k=self.generate_kwargs['top_k'],
            temperature=self.generate_kwargs['temperature'],
            repetition_penalty=self.generate_kwargs['repetition_penalty'],
        )
        gen_config.random_seed = None
        messages_list = self.message_to_lmdeploy(message, system_prompt=self.system_prompt)
        assert len(messages_list) == 1
        response = self.model(messages_list, gen_config=gen_config)[0]
        response = response.text
        return response

    def generate_inner_vllm(self, message, dataset=None):
        from vllm import SamplingParams

        if listinstr(['omni'], self.model_path.lower()):
            try:
                from qwen_omni_utils import process_mm_info
            except Exception as err:
                logging.critical("qwen_omni_utils not found, please install it via 'pip install qwen-omni-utils[decord]'")  # noqa: E501
                raise err
        else:
            try:
                from qwen_vl_utils import process_vision_info
            except Exception as err:
                logging.critical("qwen_vl_utils not found, please install it via 'pip install qwen-vl-utils'")  # noqa: E501
                raise err

        messages = []
        if self.system_prompt is not None:
            messages.append({'role': 'system', 'content': self.system_prompt})
        messages.append({'role': 'user', 'content': self._prepare_content_vllm(message, dataset=dataset)})
        if self.verbose:
            print(f'\033[31m{messages}\033[0m')

        text = self.processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        if listinstr(['omni'], self.model_path.lower()):
            audios, images, videos = process_mm_info(messages, use_audio_in_video=self.use_audio_in_video)
        else:
            images, videos = process_vision_info(messages)
        print('finishing process vision info in vllm.')

        if DATASET_MODALITY(dataset) == 'VIDEO' and 'megabench' not in dataset.lower():
            assert len(videos) == 1
            videos_nd = [videos[0].detach().cpu().numpy().transpose(0, 2, 3, 1)]

            video_inputs = {
                "prompt": text[0],
                "multi_modal_data": {"video": videos_nd[0]},
                "mm_processor_kwargs":{}
            }
            if self.use_audio_in_video:
                import vllm
                assert not vllm.envs.VLLM_USE_V1, ("V1 does not support use_audio_in_video. Please launch this example with `VLLM_USE_V1=0`.")  # noqa: E501
                video_inputs["multi_modal_data"]["audio"] = audios[0]
                video_inputs['mm_processor_kwargs']['use_audio_in_video'] = True
            if videos_nd[0].shape[0] > VLLM_MAX_IMAGE_INPUT_NUM:
                print('video input sequence may be too long for vllm, Maybe cannot generate response for VLLM')
        sampling_params = SamplingParams(
            temperature=0.0, max_tokens=self.max_new_tokens, stop_token_ids=None
        )
        if images:
            outputs = self.llm.generate(
                {
                    "prompt": text,
                    "multi_modal_data": {"image": images},
                },
                sampling_params=sampling_params,
            )
        elif videos_nd:
            outputs = self.llm.generate(
                video_inputs,
                sampling_params=sampling_params,
            )
        else:
            outputs = self.llm.generate(
                {
                    "prompt": text,
                },
                sampling_params=sampling_params,
            )

        for o in outputs:
            generated_text = o.outputs[0].text

        if self.post_process:
            resp = generated_text.split('\\boxed{')[-1]
            lt = len(resp)
            counter, end = 1, None
            for i in range(lt):
                if resp[i] == '{':
                    counter += 1
                elif resp[i] == '}':
                    counter -= 1
                if counter == 0:
                    end = i
                    break
                elif i == lt - 1:
                    end = lt
                    break
            if end is not None:
                generated_text = resp[:end]

        if self.verbose:
            print(f'\033[32m{generated_text}\033[0m')
        return generated_text

    def generate_inner(self, message, dataset=None):
        if self.use_vllm:
            return self.generate_inner_vllm(message, dataset=dataset)
        elif self.use_lmdeploy:
            return self.generate_inner_lmdeploy(message, dataset=dataset)
        else:
            return self.generate_inner_transformers(message, dataset=dataset)


class Qwen2VLChatAguvis(Qwen2VLChat):
    def __init__(self, mode=None, **kwargs):
        self.mode = mode
        super().__init__(**kwargs)
        self.processor.max_pixels = self.max_pixels
        self.processor.min_pixels = self.min_pixels

    def generate_inner(self, message, dataset=None):
        try:
            from qwen_vl_utils import process_vision_info
        except Exception as err:
            logging.critical(
                "qwen_vl_utils not found, please install it via 'pip install qwen-vl-utils'"
            )
            raise err

        messages = []
        user_message = []
        for item in message:
            if "role" in item.keys():
                if item["role"] == "system":
                    self.system_prompt = item["value"]
                else:
                    item.pop("role")
                    user_message.append(item)
            else:
                user_message.append(item)
        message = user_message

        if self.system_prompt is not None:
            messages.append({"role": "system", "content": self.system_prompt})
        messages.append(
            {"role": "user", "content": self._prepare_content(message, dataset=dataset)}
        )
        if self.verbose:
            print(f"\033[31m{messages}\033[0m")

        text = self.processor.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=False,
            chat_template=CHAT_TEMPLATE,
        )
        # TODO: provide current action's low-level instruction
        # if False:
        #     # If low-level instruction is provided
        #     # We enforce using "Action: {low_level_instruction} to guide generation"
        #     recipient_text = f"<|im_start|>assistant<|recipient|>all\nAction: {low_level_instruction}\n"
        if self.mode == "force-plan":
            recipient_text = "<|im_start|>assistant<|recipient|>all\nThought: "
        elif self.mode == "force-plan-l1":
            recipient_text = "<|im_start|>assistant<|recipient|>all\nAction: "
        elif self.mode == "force-plan-l3":
            recipient_text = "<|im_start|>assistant<|recipient|>all\nObservation: "
        elif self.mode == "grounding":
            recipient_text = "<|im_start|>assistant<|recipient|>os\n"
        elif self.mode == "force-plan-free":
            recipient_text = "<|im_start|>assistant<|recipient|>all\n"
        elif self.mode == "self-plan":
            recipient_text = "<|im_start|>assistant<|recipient|>"
        else:
            raise ValueError(f"Invalid mode: {self.mode}")
        text += recipient_text
        # print(text)

        images, videos = process_vision_info([messages])
        inputs = self.processor(
            text=[text], images=images, videos=videos, padding=True, return_tensors="pt"
        )
        inputs = inputs.to("cuda")

        # stop_str = "<|diff_marker|>"
        # keywords = [stop_str]
        # stopping_criteria = KeywordsStoppingCriteria(
        #     keywords, self.processor.tokenizer, inputs.input_ids
        # )

        generated_ids = self.model.generate(
            **inputs,
            **self.generate_kwargs,
            # stopping_criteria=[stopping_criteria],
        )
        generated_ids = [
            output_ids[len(input_ids):]
            for input_ids, output_ids in zip(inputs.input_ids, generated_ids)
        ]
        out = self.processor.tokenizer.batch_decode(
            generated_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False
        )
        response = out[0]
        # for term in UNTIL:
        #     if len(term) > 0:
        #         response = response.split(term)[0]

        if self.post_process:
            resp = response.split("\\boxed{")[-1]
            lt = len(resp)
            counter, end = 1, None
            for i in range(lt):
                if resp[i] == "{":
                    counter += 1
                elif resp[i] == "}":
                    counter -= 1
                if counter == 0:
                    end = i
                    break
                elif i == lt - 1:
                    end = lt
                    break
            if end is not None:
                response = resp[:end]

        if self.verbose:
            print(f"\033[32m{response}\033[0m")
        return response

from abc import ABC, abstractmethod
import time
from typing import List, Optional, Dict, TypedDict, Any
import logging
from tqdm import tqdm
from utils import gpus_needed
import os

from openai import OpenAI, APIError
from anthropic import Anthropic, APIConnectionError, RateLimitError, APIStatusError
from google import genai
from google.genai import types

import pdb

logger = logging.getLogger(__name__)

class Message(TypedDict):
    role: str
    content: str

class ModelWrapper(ABC):
    """Abstract base class for model API wrappers."""

    def __init__(
        self,
        model_name: str,
        temperature: float = 0.7,
        max_tokens: int = 1000,
        top_p: float = 1.0,
        max_retries: int = 3,
        initial_retry_delay: float = 1.0,
        **kwargs
    ):
        """
        Initialize the model wrapper.

        Args:
            model_name: Name of the model to use
            temperature: Sampling temperature (0-1)
            max_tokens: Maximum number of tokens to generate
            top_p: Top-p sampling parameter
            max_retries: Maximum number of retry attempts
            initial_retry_delay: Initial delay between retries (seconds)
            **kwargs: Additional model-specific parameters
        """
        self.model_name = model_name
        self.temperature = temperature
        self.max_tokens = max_tokens
        self.top_p = top_p
        self.max_retries = max_retries
        self.initial_retry_delay = initial_retry_delay
        self.additional_params = kwargs

    @abstractmethod
    def generate(self, messages: List[Message]) -> str:
        """Generate a response for a single prompt."""
        pass

    @abstractmethod
    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        """Generate responses for multiple prompts."""
        pass

    @classmethod
    def create(cls, model_name: str, **kwargs) -> 'ModelWrapper':
        """Factory method to create appropriate model wrapper instance."""
        if model_name in OpenAIReasoningClient.REASONING_MODELS:
            return OpenAIReasoningClient(model_name, **kwargs)
        elif "gpt" in model_name.lower():
            return OpenAIClient(model_name, **kwargs)
        elif "claude" in model_name.lower():
            return AnthropicClient(model_name, **kwargs)
        elif "gemini" in model_name.lower():
            return GoogleGeminiClient(model_name, **kwargs)
        elif "openrouter" in model_name.lower():
            return OpenRouterClient(model_name, **kwargs)
        elif "lambda" in model_name.lower():
            return LambdaClient(model_name, **kwargs)
        else:
            return VLLMClient(model_name, **kwargs)

    def _exponential_backoff(self, attempt: int) -> None:
        """Implement exponential backoff between retries."""
        if attempt < self.max_retries:
            delay = self.initial_retry_delay * (2 ** attempt)
            time.sleep(delay)

class OpenAIClient(ModelWrapper):

    def __init__(self, model_name: str, **kwargs):
        super().__init__(model_name, **kwargs)
        self.client = OpenAI()

    def generate(self, messages: List[Message]) -> str:
        for attempt in range(self.max_retries):
            try:
                response = self.client.chat.completions.create(
                    model=self.model_name,
                    messages=messages,
                    temperature=self.temperature,
                    max_completion_tokens=self.max_tokens,
                    top_p=self.top_p,
                    **self.additional_params
                )
                return response.choices[0].message.content
            except APIError as e:
                logger.warning(f"OpenAI API error (attempt {attempt + 1}/{self.max_retries}): {str(e)} for prompt {messages}")
                if attempt == self.max_retries - 1:
                    logger.error(f"Failed after {self.max_retries} attempts: {str(e)}")
                    return None
                self._exponential_backoff(attempt)

    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        #TODO: implement batch API for message_lists that are sufficiently long
        responses = []
        for messages in tqdm(messages_list, desc='Batch Generation'):
            responses.append(self.generate(messages))
        return responses

class OpenAIReasoningClient(ModelWrapper):
    REASONING_MODELS = ['o1', 'o1-pro', 'o3', 'o3-mini', 'o4-mini']

    def __init__(self, model_name: str, **kwargs):
        if model_name not in self.REASONING_MODELS:
            raise ValueError(f"Model {model_name} is not a supported reasoning model. Supported models are: {self.REASONING_MODELS}")

        # Override default parameters with reasoning-specific ones
        kwargs['reasoning_effort'] = kwargs.get('reasoning_effort', 'medium')
        kwargs['response_format'] = kwargs.get('response_format', {'type': 'text'})

        super().__init__(model_name, **kwargs)
        self.max_tokens = 32768
        self.client = OpenAI()

    def generate(self, messages: List[Message]) -> str:
        for attempt in range(self.max_retries):
            try:
                response = self.client.chat.completions.create(
                    model=self.model_name,
                    messages=messages,
                    max_completion_tokens=self.max_tokens,
                    **self.additional_params
                )
                return response.choices[0].message.content
            except APIError as e:
                logger.warning(f"OpenAI API error (attempt {attempt + 1}/{self.max_retries}): {str(e)} for prompt {messages}")
                if attempt == self.max_retries - 1:
                    logger.error(f"Failed after {self.max_retries} attempts: {str(e)}")
                    return None
                self._exponential_backoff(attempt)

    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        responses = []
        for messages in tqdm(messages_list, desc='Batch Generation'):
            responses.append(self.generate(messages))
        return responses

class LambdaClient(ModelWrapper):
    """
    A ModelWrapper for Lambda-based models
    """
    DEEPSEEK_MODELS = {"lambda-deepseek-r1": "deepseek-r1-671b", "lambda-deepseek-v3": "deepseek-v3-0324"}

    def __init__(
        self,
        model_name: str,
        **kwargs
    ):
        """
        :param model_name: e.g. "deepseek/deepseek-r1:free" or "deepseek/deepseek-v3:free"
        :param api_key:    your LAMBDA_API_KEY (will fall back to env var if omitted)
        :param kwargs: other hyperparams (temperature, max_tokens, top_p, max_retries, additional_params) 
        """
        model_name = self.DEEPSEEK_MODELS.get(model_name, model_name)
        kwargs['reasoning_effort'] = kwargs.get('reasoning_effort', 'low')

        super().__init__(model_name, **kwargs)
        self.api_key       = os.getenv("LAMBDA_API_KEY")
        self.base_url      = "https://api.lambda.ai/v1"
        self.max_tokens = 32768

        self.client = OpenAI(
            base_url=self.base_url,
            api_key=self.api_key
        )

    def generate(self, messages: List[Message]) -> str:
        """
        Generate a completion from the list of messages.
        Returns the assistant's reply (string) or None on failure.
        """
        messages[0]['content'] = "**IMPORTANT RULES:** Do not reason too long about your response. Providing a reasonable response in the correct format is the most important thing!\n\n" + messages[0]['content']
        messages[0]['content'] += "\n\nAgain, please be concise and efficient in your reasoning and response."

        if "plain string" in messages[0]['content']:
            response_format = {"type": "text"}
        elif "Example format:" and "JSON" in messages[0]['content']:
            response_format = {"type": "json_object"}

        for attempt in range(self.max_retries):
            try:
                response = self.client.chat.completions.create(
                    model=self.model_name,
                    messages=messages,
                    temperature=self.temperature,
                    max_completion_tokens=self.max_tokens,
                    top_p=self.top_p,
                    response_format=response_format,
                    **self.additional_params
                )
                return response.choices[0].message.content
            except APIError as e:
                logger.warning(
                    f"[Lambda] API error (attempt {attempt+1}/{self.max_retries}): {e}"
                )
                if attempt == self.max_retries - 1:
                    logger.error(f"[Lambda] giving up after {self.max_retries} tries")
                    return None
                self._exponential_backoff(attempt)
            except Exception as e:
                # catch anything else (network, serialization, etc.)
                logger.error(f"[Lambda] unexpected error: {e}", exc_info=True)
                return None

    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        responses = []
        for messages in tqdm(messages_list, desc='Batch Generation'):
            responses.append(self.generate(messages))
        return responses

class OpenRouterClient(ModelWrapper):
    """
    A ModelWrapper for OpenRouter-based models (e.g. deepseek/deepseek-r1:free or deepseek/deepseek-v3:free).
    """
    DEEPSEEK_MODELS = {"openrouter-deepseek-r1": "deepseek/deepseek-r1:free", "openrouter-deepseek-v3": "deepseek/deepseek-v3:free"}

    def __init__(
        self,
        model_name: str,
        extra_headers: Dict[str, str] = None,
        extra_body: Dict[str, Any]    = None,
        **kwargs
    ):
        """
        :param model_name: e.g. "deepseek/deepseek-r1:free" or "deepseek/deepseek-v3:free"
        :param api_key:    your OPENROUTER_API_KEY (will fall back to env var if omitted)
        :param base_url:   the OpenRouter base URL (defaults to "https://openrouter.ai/api/v1")
        :param extra_headers: optional HTTP headers (e.g. {"HTTP-Referer": ..., "X-Title": ...})
        :param extra_body:    optional extra body to pass through
        :param kwargs: other hyperparams (temperature, max_tokens, top_p, max_retries, additional_params) 
        """
        # Override default parameters with reasoning-specific ones
        model_name = self.DEEPSEEK_MODELS.get(model_name, model_name)

        super().__init__(model_name, **kwargs)
        self.api_key       = os.getenv("OPENROUTER_API_KEY")
        self.base_url      = "https://openrouter.ai/api/v1"
        self.extra_headers = extra_headers or {}
        self.extra_body    = extra_body.update({"reasoning": {"effort": "low", "exclude": False}}) if extra_body else {"reasoning": {"effort": "low", "exclude": False}}
        self.max_tokens = 32768

        self.client = OpenAI(
            base_url=self.base_url,
            api_key=self.api_key
        )

    def generate(self, messages: List[Message]) -> str:
        """
        Generate a completion from the list of messages.
        Returns the assistant's reply (string) or None on failure.
        """
        messages[0]['content'] = "**IMPORTANT RULES:** Do not think too hard about your response. Providing a response quickly in the correct format is the most important thing!\n\n" + messages[0]['content']
        messages[0]['content'] += "\n\nAgain, limit your thinking and just go with your gut instinct."

        # Copy the extra body from the constructor
        extra_body = self.extra_body.copy()

        if "Example format:" and "JSON" in messages[0]['content']:
            extra_body["response_format"] = {"type": "json_object"}

        for attempt in range(self.max_retries):
            try:
                response = self.client.chat.completions.create(
                    model=self.model_name,
                    messages=messages,
                    temperature=self.temperature,
                    max_tokens=self.max_tokens,
                    top_p=self.top_p,
                    extra_headers=self.extra_headers,
                    extra_body=extra_body,
                    **self.additional_params
                )
                return response.choices[0].message.content
            except APIError as e:
                logger.warning(
                    f"[OpenRouter] API error (attempt {attempt+1}/{self.max_retries}): {e}"
                )
                if attempt == self.max_retries - 1:
                    logger.error(f"[OpenRouter] giving up after {self.max_retries} tries")
                    return None
                self._exponential_backoff(attempt)
            except Exception as e:
                # catch anything else (network, serialization, etc.)
                logger.error(f"[OpenRouter] unexpected error: {e}", exc_info=True)
                return None

    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        responses = []
        for messages in tqdm(messages_list, desc='Batch Generation'):
            responses.append(self.generate(messages))
        return responses

class AnthropicClient(ModelWrapper):

    def __init__(self, model_name: str, **kwargs):
        super().__init__(model_name, **kwargs)
        self.client = Anthropic()

    def generate(self, messages: List[Message]) -> str:

        if messages[0]['role'] == 'system':
            system = messages[0]['content']
            messages = messages[1:]
        else:
            system = 'You are a helpful assistant.'

        for attempt in range(self.max_retries):
            try:
                response = self.client.messages.create(
                    model=self.model_name,
                    system=system,
                    messages=messages,
                    max_tokens=self.max_tokens,
                    temperature=self.temperature,
                    top_p=self.top_p,
                    **self.additional_params
                )
                return response.content[0].text

            except (APIConnectionError, RateLimitError, APIStatusError) as e:
                logger.warning(f"Anthropic API error (attempt {attempt + 1}/{self.max_retries}): {str(e)}")
                if attempt == self.max_retries - 1:
                    logger.error(f"Failed after {self.max_retries} attempts: {str(e)} for prompt {messages}")
                    return None
                self._exponential_backoff(attempt)

    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        #TODO: implement batch API for message_lists that are sufficiently long
        responses = []
        for messages in tqdm(messages_list, desc='Batch Generation'):
            responses.append(self.generate(messages))
        return responses

class VLLMClient(ModelWrapper):

    def __init__(self, model_name: str, **kwargs):
        from vllm import LLM, SamplingParams

        super().__init__(model_name, **kwargs)
        try:
            self.llm = LLM(
                model=model_name, 
                gpu_memory_utilization=0.9, 
                tensor_parallel_size = gpus_needed(model_name),
                max_model_len=4096)

            self.sampling_params = SamplingParams(
                temperature=self.temperature,
                max_tokens=self.max_tokens,
                top_p=self.top_p,
                **self.additional_params
            )
        except Exception as e:
            raise Exception(f"Failed to initialize vLLM model: {str(e)}")

    def format_messages_for_llama(self, messages: List[Message]) -> str:
        formatted_msg = []
        for message in messages:
            formatted_msg.append(f"<|start_header_id|>{message['role']}<|end_header_id|>\n\n{message['content']}<|eot_id|>")
        formatted_str = '<|begin_of_text|>' + '\n\n'.join(formatted_msg)

        if messages[-1]['role'] == 'assistant':
            formatted_str += f"<|start_header_id|>user<|end_header_id|>\n\n"
        else:
            formatted_str += f"<|start_header_id|>assistant<|end_header_id|>\n\n"

        return(formatted_str)

    def generate(self, messages: List[Message]) -> str:
        formatted_msg = self.format_messages_for_llama(messages)
        print(formatted_msg)
        response = self.llm.generate([formatted_msg], sampling_params=self.sampling_params)
        return response[0].outputs[0].text

    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        formatted_msgs = [self.format_messages_for_llama(messages) for messages in messages_list]
        response = self.llm.generate(formatted_msgs, sampling_params=self.sampling_params)
        return [out.outputs[0].text for out in response]

class GoogleGeminiClient(ModelWrapper):
    def __init__(self, model_name: str, **kwargs):
        super().__init__(model_name, **kwargs)
        self.api_key = os.environ.get("GOOGLE_API_KEY")
        self.client = genai.Client(api_key=self.api_key)
        self.model_name = model_name

    def generate(self, messages: List[Message]) -> str:
        prompt = self._format_messages(messages)
        attempt = 0
        while attempt < self.max_retries:
            try:
                response = self.client.models.generate_content(
                    model = self.model_name,
                    contents = prompt,
                    config=types.GenerateContentConfig(
                        temperature=self.temperature,
                        max_output_tokens=self.max_tokens,
                        top_p=self.top_p,
                        **self.additional_params
                    )
                )
                return response.text
            except Exception as e:
                logger.warning(f"Gemini API error (attempt {attempt + 1}/{self.max_retries}): {str(e)} for prompt {messages}")
                if attempt == self.max_retries - 1:
                    logger.error(f"Failed after {self.max_retries} attempts: {str(e)}")
                    return None
                self._exponential_backoff(attempt)
                attempt += 1
        return ""

    def batch_generate(self, messages_list: List[List[Message]]) -> List[str]:
        responses = []
        for messages in messages_list:
            responses.append(self.generate(messages))
        return responses

    def _format_messages(self, messages: List[Message]) -> str:
        return "\n".join([f"{msg['content']}" for msg in messages])

import argparse
import json
import tqdm
import torch
import pathlib
import pickle
import os
import logging
from common.generate_questions_dataset import calculate_md5
from vllm import LLM, SamplingParams

llm = None
sampling_params = None


def answer_questions(question_dataset_path=None, dataset_output_path=None, prompt_path=None):
    with open(question_dataset_path) as json_file:
        entity_question_answers_claims_questions = json.load(json_file)

    with open(prompt_path) as file:
        prompt = file.read()

    basename = pathlib.Path(dataset_output_path).stem
    if not os.path.exists(".cache/"+basename+"/"):
        os.mkdir(".cache/"+basename+"/")

    entity_question_answers_claims_questions_answers = {}
    for entity, question_answers_claims_questions in tqdm.tqdm(
        entity_question_answers_claims_questions.items()
    ):
        entity_question_answers_claims_questions_answers[entity] = {}
        for (
            question,
            answers_claims_questions,
        ) in question_answers_claims_questions.items():
            entity_question_answers_claims_questions_answers[entity][question] = {}
            for answer, claims_questions in answers_claims_questions.items():
                entity_question_answers_claims_questions_answers[entity][question][
                    answer
                ] = {}
                for claim, fact_question in claims_questions.items():
                    cache_name = calculate_md5(fact_question)
                    cache_file = ".cache/" + basename + "/"+ cache_name + ".cache"
                    if os.path.exists(cache_file):
                        with open(cache_file, "rb") as cacheFile:
                            answers = pickle.load(cacheFile)
                    else:
                        prompts = [prompt.replace("{question}", fact_question)]
                        outputs = llm.generate(prompts*20, sampling_params)
                        answers = [output.outputs[0].text.strip() for output in outputs]
                        with open(cache_file, "wb") as f:
                            pickle.dump(answers, f)

                    entity_question_answers_claims_questions_answers[entity][question][
                        answer
                    ][claim] = {
                        "question": fact_question,
                        "answers": answers,
                    }


    with open(dataset_output_path, "w") as outfile:
        json.dump(entity_question_answers_claims_questions_answers, outfile)

