def flatten_openai_responses(responses: list[Completion]) -> list[Completion]:
    # assert all(len(response.choices) == chunk_size for response in responses)
    completions = list[Completion]()
    for idx, response in enumerate(responses):
        completions.extend(
            Completion(
                id=f"{response.id}:{idx}",
                created=response.created,
                object=response.object,
                model=response.model,
                choices=[choice],
                system_fingerprint=response.system_fingerprint,
            )
            for choice in response.choices
        )
    return completions


@dataclass(frozen=True)
class Args:
    seed_data_files: list[str] = field(
        metadata={"help": "Path to the seed code snippets"}
    )
    max_new_data: int
    push: str
    model: str
    instruct_mode: InstructMode

    use_vllm_server: bool = field(default=True)
    seed_code_start_index: int = field(default=0)
    continue_from: str | None = field(default=None)

    # Keep the following arguments unchanged for reproducibility
    seed: int = field(default=3407)

    temperature: float = field(default=0.7)
    max_output_tokens: int = field(default=1536)
    prompting_mode: Literal["chat", "completion"] = field(default="completion")
    num_fewshots: int = field(default=8)

    async_micro_batch_size: int = field(
        default=1,
        metadata={
            "help": "Number of prompts to batch in a single async request."
            "Won't be effective if `use_vllm_server` is False."
            "It should be divisible by `num_batched_requests` for a balance load"
            "if multiple vllm instances are served through a round-robin load balancer."
        },
    )
    num_batched_requests: int = field(
        default=1, metadata={"help": "Number of requests to send concurrently"}
    )
    num_sample_per_request: int = field(
        default=32, metadata={"help": "Number of samples to generate per request"}
    )
    sleep: float | None = field(
        default=None, metadata={"help": "Sleep between requests in seconds"}
    )
    delay: float | None = field(
        default=None, metadata={"help": "Delay between batched requests in seconds"}
    )

    tag: str = field(
        default="",
        metadata={
            "help": "Custom tag as part of the output filename, not affecting the fingerprint"
        },
    )
    save_dir: str = field(default="./")

    def fingerprint(self, fewshot: "Fewshot | None") -> str:
        args = (
            self.seed_data_files,
            self.seed,
            self.prompting_mode,
            self.num_fewshots,
            self.temperature,
            self.model,
            self.max_output_tokens,
            fewshot,
        )
        return utils.compute_fingerprint(*args, hash_length=5)


@dataclass(frozen=True)
class Property:
    category: str
    language: str
    concepts: list[str]
    difficulty: str

    @staticmethod
    def random_exercise(concepts: list[str], language: str) -> "Property":
        category = random.choice(
            [
                "function implementation",
                "function implementation",
                "class implementation",
                "program implementation",
            ]
        )
        difficulty = random.choice(["easy", "medium", "hard"])
        return Property(
            category=category,
            language=language,
            concepts=concepts,
            difficulty=difficulty,
        )

    def concepts_prompt(self) -> str:
        return ", ".join(self.concepts)

    def prompt(self) -> str:
        category = f"category: {self.category}"
        language = f"language: {self.language}"
        difficulty = f"difficulty: {self.difficulty}"
        concepts = f"concepts: {self.concepts_prompt()}"
        return "\n".join([category, language, difficulty, concepts])

    def to_json(self) -> dict[str, str | list[str]]:
        return dict(
            category=self.category,
            language=self.language,
            concepts=self.concepts,
            difficulty=self.difficulty,
        )

    @staticmethod
    def from_json(data: dict) -> "Property":
        assert all(
            isinstance(data[key], str) for key in ["category", "language", "difficulty"]
        )
        assert isinstance(data["concepts"], list)
        return Property(
            category=data["category"],
            language=data["language"],
            concepts=data["concepts"],
            difficulty=data["difficulty"],
        )


@dataclass(frozen=True)
class Example:
    property: Property
    snippet: str
    instruction: str
    response: str
    tests: str

    @staticmethod
    def prefix_template(mode: InstructMode) -> str:
        if mode == "I->R":
            if LLAMA3:
                template = (
                    "### Instruction {index} \n{instruction}\n\n### Response {index}\n"
                )
            else:
                template = (
                    "<instruction>\n{instruction}\n</instruction>\n\n<response>\n"
                )
            return template
        elif mode == "S->C":
            return "### Snippet\n{snippet}\n\n### Concepts\n"
        elif mode == "C->I":
            return "### Properties\n{property}\n\n### Task\n"
        elif mode == "S->I":
            return "### Snippet\n{snippet}\n\n### Task\n"
        else:
            assert False

    def prompt(
        self,
        mode: InstructMode,
        return_in_separate: bool = False,
        index: int | None = None,
    ) -> str | tuple[str, str]:
        assert index is None or (mode == "I->R" and LLAMA3)
        if mode == "I->R":
            kwargs = dict(instruction=self.instruction)
            if LLAMA3:
                assert index is not None
                kwargs["index"] = str(index)
                suffix = f"{self.response}\n\n### Tests {index}\n{self.tests}"
            else:
                suffix = (
                    f"{self.response}\n</response>\n\n<tests>\n{self.tests}\n</tests>"
                )
        elif mode == "S->C":
            kwargs = dict(snippet=self.snippet)
            suffix = self.property.concepts_prompt()
        elif mode == "C->I":
            property_prompt = self.property.prompt()
            # num_words = len(self.instruction.split())
            # property_prompt += f"\nnum_words: {num_words}"
            kwargs = dict(property=property_prompt)
            suffix = self.instruction
        elif mode == "S->I":
            kwargs = dict(snippet=self.snippet)
            suffix = self.instruction
        else:
            assert False
        prefix = self.prefix_template(mode).format(**kwargs)
        if return_in_separate:
            return prefix, suffix
        else:
            return prefix + suffix


@dataclass(frozen=True)
class Fewshot:
    sys_i_r: str
    sys_c_i: str
    sys_s_c: str
    sys_s_i: str

    examples: list[Example]

    def system_prompt(self, mode: InstructMode) -> str:
        attr_name = "sys_" + mode.replace("->", "_").replace("-", "_").lower()
        return getattr(self, attr_name)

    def valid_examples(self, mode: InstructMode) -> list[Example]:
        return self.examples

    def random_prompt(
        self,
        mode: InstructMode,
        num_fewshots: int,
        prompting_mode: Literal["chat", "completion"],
        **format_args: str,
    ) -> str:
        valid_examples = self.valid_examples(mode)
        assert (
            0 < num_fewshots <= len(valid_examples)
        ), f"{num_fewshots=}, {len(valid_examples)=}"
        examples = random.sample(valid_examples, k=num_fewshots)
        assert len(examples) == num_fewshots

        body = "\n\n".join(
            f"## Example {idx + 1}\n{example.prompt(mode, index=idx + 1 if LLAMA3 and mode == 'I->R' else None)}"
            for idx, example in enumerate(examples)
        )
        prefix_template = Example.prefix_template(mode)
        if mode == "I->R" and LLAMA3:
            format_args["index"] = str(len(examples) + 1)
        prefix = f"## Example {len(examples) + 1}\n" + prefix_template.format(
            **format_args
        )
        system_prompt = self.system_prompt(mode)
        full_prompt = f"{system_prompt}\n\n{body}\n\n{prefix}"
        assert prompting_mode == "completion", "Only completion is supported for now"
        return full_prompt


def parse_property(content: str) -> Property | None:
    content = content.strip()
    lines = content.split("\n")
    if len(lines) != 4:
        return None
    try:
        lines = [line[line.index(":") + 1 :].strip() for line in lines]
    except ValueError:
        return None
    category, language, difficulty, concepts_str = lines
    concepts = list(map(str.strip, concepts_str.split(",")))
    return Property(category, language, concepts, difficulty)


def get_ossinstruct_fewshots() -> Fewshot:
    content = Path("prompts/self-ossinstruct-fewshot.txt").read_text().strip()
    splits = re.split(r"### Example \d+", content)
    system_prompt = splits[0].strip()
    sys_pattern = r"### System: I->R|### System: C->I|### System: S->C|### System: S->I"
    _, i_r, c_i, s_c, s_i = list(map(str.strip, re.split(sys_pattern, system_prompt)))
    if LLAMA3:
        i_r = f"{i_r}\n\nFor each '## Example' below, make sure you provide a '### Response' and a '### Tests' section."
    examples_str = [example.strip() for example in splits[1:]]
    assert len(examples_str) == 10, len(examples_str)
    examples = list[Example]()
    for example_str in examples_str:
        pattern = (
            r"\[Code\]\n|\[Property\]\n|\[Instruction\]\n|\[Response\]\n|\[Tests\]\n"
        )
        _, snippet, property, instruction, response, tests = re.split(
            pattern, example_str
        )
        snippet = snippet.rstrip()
        property = parse_property(property)
        assert property is not None
        instruction = instruction.strip()
        response = response.strip()
        tests = tests.strip()
        example = Example(property, snippet, instruction, response, tests)
        examples.append(example)
    return Fewshot(
        sys_i_r=i_r,
        sys_c_i=c_i,
        sys_s_c=s_c,
        sys_s_i=s_i,
        examples=examples,
    )


def parse_generated_content(content: str, instruct_mode: InstructMode) -> dict | None:
    if instruct_mode == "I->R":
        return dict(response=content.strip())
    elif instruct_mode == "S->C":
        concepts = list(map(str.strip, content.split(",")))
        return dict(concepts=concepts)
    elif instruct_mode == "C->I":
        return dict(instruction=content.strip())
    elif instruct_mode == "S->I":
        return dict(instruction=content.strip())
    else:
        assert False


def build_kwargs(instruct_mode: InstructMode, example: dict) -> dict[str, str]:
    kwargs = dict[str, str]()
    if instruct_mode == "I->R":
        kwargs["instruction"] = example["instruction"]
    elif instruct_mode in ["S->C", "S->I"]:
        kwargs["snippet"] = example["seed"]
    elif instruct_mode == "C->I":
        lang = example.get("data_dir", "dummy_key_not_in_example")
        language = LANGUAGE_MAP.get(lang, "C++")
        property = Property.random_exercise(example["concepts"], language=language)
        property_prompt = property.prompt()
        kwargs["property"] = property_prompt
        kwargs["property_obj"] = property  # type: ignore
    else:
        assert False
    return kwargs


def get_readable_prefix(instruct_mode: InstructMode, example: dict) -> str:
    mode_pattern = instruct_mode.split("->")[0]
    mode_map = {
        "I": "Instruction",
        "S": "Seed",
        "R": "Response",
        "C": "Concepts",
        "P": "Property",
    }
    prefix = "\n\n".join(
        f"@@@{mode_map[mode]}\n{example[mode_map[mode].lower()]}"
        for mode in mode_pattern
    )
    return prefix


async def main():
    args = cast(Args, HfArgumentParser(Args).parse_args_into_dataclasses()[0])
    # Sanity check
    assert args.num_batched_requests % args.async_micro_batch_size == 0
    if args.async_micro_batch_size > 1:
        assert (
            args.num_sample_per_request == 1
        ), "Only support 1 sample with batched async requests"
    if args.use_vllm_server:
        openai_client = utils.OpenAIClient()
    path = args.seed_data_files
    for root, dir, files in os.walk(path):
        fh = os.path.join(path+files[0])
    raw_dataset: Dataset = load_dataset(
        "json",
        fh,
        split="train",
        num_proc=utils.N_CORES,
    )
    id_key = "seed"
    if os.getenv("IGNORE_SEED_CHECK") is None:
            assert len(set(d[id_key] for d in raw_dataset)) == len(
        raw_dataset
    ), "Duplicate seeds appear in the dataset"
    else:
        print("[Warning] Ignoring seed check")

    # Every run should produce the same data as long as the default params are not changed
    start_index = args.seed_code_start_index
    end_index = min(start_index + args.max_new_data, len(raw_dataset))
    raw_dataset = raw_dataset.select(range(start_index, end_index))
    dataset = raw_dataset.to_list()

    assert args.prompting_mode == "completion", "Only completion is supported for now"
    fewshot = get_ossinstruct_fewshots()
    data_fingerprint = args.fingerprint(fewshot)
    timestamp = utils.timestamp()

    if args.continue_from is not None:
        if os.getenv("IGNORE_FINGERPRINT") is None:
            assert (
                data_fingerprint in args.continue_from
            ), f"Fingerprint mismatch: {data_fingerprint}"
        assert f"-{start_index}-" in args.continue_from, "Index mismatch"
        old_path = Path(args.continue_from)
        assert old_path.exists()
        old_data = utils.read_jsonl(old_path)
        assert len(old_data) > 0
        last_seed = old_data[-1][id_key]
        # Find seed
        seed_index = next(
            idx for idx, d in enumerate(dataset) if d[id_key] == last_seed
        )
        n_skipped = seed_index + 1
        # n_skipped = last_index - start_index + 1
        print(f"Continuing from {old_path} with {n_skipped} seed snippets skipped")
        f_out = old_path.open("a")
    else:
        tag = "" if args.tag == "" else f"-{args.tag}"
        mode_str = args.instruct_mode.replace("->", "_").lower()
        path = Path(
            args.save_dir,
            f"data{tag}-{mode_str}-{data_fingerprint}-{start_index}-{timestamp}.jsonl",
        )
        assert not path.exists()
        f_out = path.open("w")
        print("Saving to", path)
        n_skipped = 0
    dataset = dataset[n_skipped:]
    chunked_dataset = list(
        utils.chunked(dataset, n=args.num_batched_requests)
    )
    pbar = tqdm(chunked_dataset)
    n_succeeded = 0

    if not args.use_vllm_server:
        from vllm import LLM, SamplingParams, RequestOutput
        import torch

        # # TO RUN ON MAC
        # if torch.backends.mps.is_available():
        #     device = "mps"
        #     tensor_parallel_size = 1  # MPS currently does not support tensor parallelism
        # else:
        #     device = "cpu"
        #     tensor_parallel_size = 1

        # # Initialize the LLM engine with the appropriate device
        # engine = LLM(args.model, tensor_parallel_size=tensor_parallel_size, device=device)
        engine = LLM(args.model, tensor_parallel_size=torch.cuda.device_count())

        def vllm_response_to_openai(response: RequestOutput) -> Completion:
            created = 0
            choices = list[CompletionChoice]()
            for output in response.outputs:
                choice = CompletionChoice(
                    text=output.text,
                    index=0,
                    finish_reason=(
                        "stop" if output.finish_reason == "stop" else "length"
                    ),
                )
                choices.append(choice)
            model = "not-specified"
            id = response.request_id
            return Completion(
                id=id,
                created=created,
                object="text_completion",
                model=model,
                choices=choices,
                system_fingerprint="None",
            )

    for chunk_index, examples in enumerate(pbar):
        # map to the index in the original seed snippets
        effective_index = (
            chunk_index * args.num_batched_requests + start_index + n_skipped
        )
        print("Effective index:", effective_index)
        if chunk_index > 0 and args.sleep is not None:
            print(f"Sleeping for {args.sleep} seconds...")
            time.sleep(args.sleep)
        # assert index + start_index == example["index"]
        request_params = list[dict[str, Any]]()
        all_prompts = list[str]()
        for index, example in enumerate(examples):
            seed = args.seed + effective_index + index
            random.seed(seed)
            kwargs = build_kwargs(args.instruct_mode, example)
            prompt = fewshot.random_prompt(
                args.instruct_mode,
                args.num_fewshots,
                prompting_mode=args.prompting_mode,
                **kwargs,
            )
            prompt = prompt.rstrip()
            all_prompts.append(prompt)
            max_new_tokens = args.max_output_tokens
            params: dict = dict(
                model=args.model,
                max_tokens=max_new_tokens,
                n=args.num_sample_per_request,
                temperature=args.temperature,
                seed=seed,
            )
            params["prompt"] = prompt
            params["stop"] = ["## Example"]
            if args.instruct_mode == "I->R":
                params["stop"].append("</tests>")
            request_params.append(params)
        assert len(request_params) == len(examples)
        print(f"Ready to make {len(request_params)} requests")
        if args.use_vllm_server:
            dispatch_requests = (
                openai_client.dispatch_chat_completions
                if args.prompting_mode == "chat"
                else openai_client.dispatch_completions
            )
            if args.async_micro_batch_size == 1:
                responses = await dispatch_requests(request_params, delay=args.delay)
            else:
                # Construct micro batches for async requests
                assert args.num_sample_per_request == 1
                request_params_batched: list[dict[str, Any]] = []
                request_params_chunks = utils.chunked(
                    request_params, args.async_micro_batch_size
                )
                for request_params_chunk in request_params_chunks:
                    request_param = {
                        k: v
                        for k, v in request_params_chunk[0].items()
                        if k != "prompt"
                    }
                    request_param["prompt"] = [
                        req["prompt"] for req in request_params_chunk
                    ]
                    request_params_batched.append(request_param)
                n_async_chunks = (
                    args.num_batched_requests // args.async_micro_batch_size
                )
                assert len(request_params_batched) in [
                    n_async_chunks,
                    n_async_chunks + 1,
                ], (request_params_batched, n_async_chunks)
                print(
                    f"Ready to make {len(request_params_batched)} batched async requests"
                )
                responses_batched = await dispatch_requests(
                    request_params_batched, delay=args.delay
                )
                responses = flatten_openai_responses(responses_batched)
                assert len(responses) == len(examples)
        else:
            stop = ["## Example"]
            if args.instruct_mode == "I->R":
                stop.append("</tests>")
            sampling_params = SamplingParams(
                temperature=args.temperature,
                max_tokens=args.max_output_tokens,
                seed=args.seed + effective_index,
                n=args.num_sample_per_request,
                stop=stop,
            )
            vllm_responses = engine.generate(all_prompts, sampling_params)
            responses = list(map(vllm_response_to_openai, vllm_responses))

        assert len(examples) == len(responses)
        for prompt, example, response in zip(all_prompts, examples, responses):
            if isinstance(response, BaseException):
                print("Exception when generating response:", response)
                continue

            fingerprint = response.system_fingerprint
            original_mapping = {
                k: v for k, v in example.items() if k not in ["prompt", "fingerprint"]
            }

            success_parsing_res: list[dict] = []

            for choice in response.choices:
                if choice.finish_reason in ["stop", "eos_token"]:
                    if args.prompting_mode == "chat":
                        content = choice.message.content
                    else:
                        content = choice.text
                    parsing_result = parse_generated_content(
                        content, args.instruct_mode
                    )
                    if parsing_result is None:
                        print("[WRONG FORMAT]")
                        print("@@@Prompt", prompt, sep="\n", end="\n\n")
                        print("@@@Response", content, sep="\n", end="\n\n")
                        continue
                    success_parsing_res.append(parsing_result)
                else:
                    print("Failed reason:", choice.finish_reason)

            n_failed_samples = args.num_sample_per_request - len(success_parsing_res)
            print(f"✅ Success samples: {len(success_parsing_res)}")
            print(f"❌ Failed samples: {n_failed_samples}")

            if len(success_parsing_res) == 0:
                print("No successful choices")
                continue

            data = dict(
                prompt=prompt,
                fingerprint=fingerprint,
                **original_mapping,
            )
            if args.num_sample_per_request > 1:
                data["parsing_result"] = success_parsing_res
                prefix = prompt
            else:
                assert len(success_parsing_res) == 1
                parsing_result = success_parsing_res[0]
                data = dict(**data, **parsing_result)
                prefix = prompt

            print(
                "@@@Prefix",
                prefix,
                f"@@@Generation (1 example)",
                content,
                sep="\n",
                end="\n\n",
            )
            n_succeeded += 1
            new_ds = datasets.Dataset.from_dict(data)
            new_ds.push_to_hub(args.push, private=True)
        total_requests = chunk_index * args.num_batched_requests + len(examples)
        pbar.set_description(f"Success ratio: {n_succeeded} / {total_requests}")

if __name__ == "__main__":
    ### ARGS FOR RUNNING THE SCRIPT
    # seed_data_files=an778/cppHeaderFiles
    # model=/project/phan/codellama/StarCoder
    # instruct_mode = “S->C” | “C->I” | “I->R” (in order)
    # use_vllm_server=True
    # push=an778/self-oss-instruct-sc2-concepts | an778/self-oss-instruct-sc2-instructions | an778/self-oss-instruct-sc2-responses (based on output of instruction mode)
    asyncio.run(main())

"""
This file gets surprisals from a conditional generation VLM
"""

import pandas as pd
import torch
from vllm import LLM, SamplingParams
from util import DotDict
from pyprojroot import here
from PIL import Image


def get_prompts(data_filepath, image_type):
    df = pd.read_csv(here(data_filepath))

    if image_type is None:
        image = None
    elif image_type == "allshapes":
        image = Image.open(here("data/tangrams/all-tangrams-screenshot.png"))
    else:
        raise ValueError(f"Invalid image type: {image_type}")

    return list(df["words"]), image


def main(config):

    sampling_params = SamplingParams(temperature=1.0, prompt_logprobs=0)
    model = LLM(
        config.model_name,
        dtype=torch.bfloat16,
        gpu_memory_utilization=0.8,
        max_model_len=1024,
        max_num_seqs=16,
        enforce_eager=True,
        # tensor_parallel_size=4,
    )

    prompts, image = get_prompts(config.data_filepath, config.image_type)

    if config.image_type is None:
        outputs = model.generate(
            prompts,
            sampling_params,
        )
    else:
        outputs = model.generate(
            [
                {"prompt": prompt, "multi_modal_data": {"image": image}}
                for prompt in prompts
            ],
            sampling_params,
        )

    rows = []
    for prompt_idx in range(len(prompts)):
        output = outputs[prompt_idx]
        word_level_logprobs = []
        curr_word = ""
        curr_logprob = 0
        for token in output.prompt_logprobs[1:]:
            assert len(token.values()) == 1
            token = list(token.values())[0]
            if not token.decoded_token or token.decoded_token[0] != " ":
                curr_word += token.decoded_token
                curr_logprob += token.logprob
            else:
                word_level_logprobs.append((curr_word, curr_logprob))
                curr_word = token.decoded_token[1:]
                curr_logprob = token.logprob

        if curr_word:
            word_level_logprobs.append((curr_word, curr_logprob))

        for i, (word, logprob) in enumerate(word_level_logprobs):
            rows.append(
                {
                    "full_text": prompts[prompt_idx],
                    "word_idx": i,
                    "word": word,
                    "logprob": logprob,
                }
            )

    df_logprobs = pd.DataFrame(rows)

    input_filename = config.data_filepath.split("/")[-1].split(".")[0]
    if config.image_type is None:
        df_logprobs.to_csv(
            here(
                f"data/logprobs/{input_filename}-logprobs-{config.model_name.replace('/', '--')}.csv"
            ),
            index=False,
        )
    else:
        df_logprobs.to_csv(
            here(
                f"data/logprobs/{input_filename}-logprobs-{config.model_name.replace('/', '--')}-{config.image_type}.csv"
            ),
            index=False,
        )


if __name__ == "__main__":

    text_config = DotDict(
        {
            "model_name": "meta-llama/Llama-3.1-8B",
            "data_filepath": "data/raw-data/expt_4_games_concat.csv",
            "image_type": None,
        }
    )

    # main(text_config)

    multimodal_config = DotDict(
        {
            "model_name": "meta-llama/Llama-3.2-11B-Vision",
            "data_filepath": "data/raw-data/expt_4_games_concat.csv",
            "image_type": "allshapes",
        }
    )

    main(multimodal_config)

    # TODO: run on the role data

import os
import time
from tqdm import tqdm
from typing import Any, Dict, List, Literal, Optional, Tuple, Union
import numpy as np
import threading
from coderm.prompts import py_prompt, py_prompt_2shot_lcb, py_prompt_2shot_lcb_chat, Conversation, Prompt, py_prompt_evolve
from coderm.utils import markdown_codeblock_extract
import torch

from abc import ABC, abstractmethod


EVOLVED_SEP = "# ==== EVOLVED CODE ===="


class Completion:
    def __init__(self, code: str, cumulative_logprob: float, num_tokens: int, orm_score: Optional[float] = None):
        self.code = code
        self.cumulative_logprob = cumulative_logprob
        self.num_tokens = num_tokens
        self.orm_score = orm_score

    def to_dict(self) -> Dict[str, Any]:
        d = {
            "code": self.code,
            "cumulative_logprob": self.cumulative_logprob,
            "num_tokens": self.num_tokens,
        }

        if self.orm_score is not None:
            d["orm_score"] = self.orm_score

        return d

    def __repr__(self) -> str:
        return f"Completion({self.code}, {self.cumulative_logprob}, {self.num_tokens})"

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "Completion":
        assert "code" in d, "Missing 'code' key"
        assert "cumulative_logprob" in d, "Missing 'cumulative_logprob' key"
        assert "num_tokens" in d, "Missing 'num_tokens' key"
        return Completion(
            d["code"],
            d["cumulative_logprob"],
            d["num_tokens"],
            orm_score=d.get("orm_score", None),
        )


def autodetect_dtype_str() -> str:
    if torch.cuda.is_bf16_supported():
        return "bfloat16"
    else:
        return "auto"


def autodetect_dtype() -> torch.dtype:
    if torch.cuda.is_bf16_supported():
        return torch.bfloat16
    else:
        return torch.float16


def model_factory(
        kind: str,
        name: str,
        num_gpus=1,
        evolver_e=5,
        rm=None,
):
    if kind == "base":
        return HFModel(name, num_gpus=num_gpus, prompt_fn=py_prompt)
    elif kind == "few-shot":
        return HFModel(name, num_gpus=num_gpus, prompt_fn=py_prompt_2shot_lcb)
    elif kind == "few-shot-cot":
        return HFModel(name, num_gpus=num_gpus, prompt_fn=lambda q, c: py_prompt_2shot_lcb(q, c, cot=True))
    elif kind == "few-shot-chat":
        return HFModel(name, num_gpus=num_gpus, prompt_fn=py_prompt_2shot_lcb_chat, is_chat=True)
    elif kind == "openai":
        return OpenAIChatModel(name, prompt_fn=py_prompt_2shot_lcb_chat)
    elif kind == "evolver":
        if rm is None:
            raise ValueError(
                "OutcomeRewardModel is required for evolver model. Set with the 'rm' parameter.")
        return EvolverModel(name, rm, num_gpus=num_gpus, evolver_e=evolver_e)
    else:
        raise ValueError(f"Unknown model kind: {kind}")


class BaseModel(ABC):
    # init method
    def __init__(self, model_name: str):
        self.model_name = model_name

    @abstractmethod
    def generate_with_info(self, prompts: List[Prompt], **kwargs) -> List[Completion]:
        pass

    @abstractmethod
    def format_prompt(self, question: str, code: str = "", public_tests: Optional[Dict[str, Any]] = None, tests: Optional[Dict[str, Any]] = None, solutions: Optional[List[str]] = None) -> Prompt:
        pass

    def free_memory(self):
        pass  # only used for local models

    def get_name(self) -> str:
        return self.model_name

    def generate(self, prompts: List[Prompt], **kwargs) -> List[str]:
        completions = self.generate_with_info(prompts, **kwargs)
        return [c.code for c in completions]

    def prefix_starter_code(self) -> bool:
        # whether the model requires to prefix starter code to responses
        # chat models do not require this
        return True


class ClassificationModel(ABC):
    def __init__(self, model_name: str):
        self.model_name = model_name

    def get_name(self) -> str:
        return self.model_name

    @abstractmethod
    def score(self, contents: List[str]) -> List[Tuple[float, float]]:
        pass


class HFModel(BaseModel):
    def __init__(
            self,
            model_name: str,
            num_gpus=1,
            prompt_fn=py_prompt,
            is_chat=False,
    ):
        super().__init__(model_name)
        from vllm import LLM
        model_lower = model_name.lower()
        self.model = LLM(
            model_name,
            tensor_parallel_size=num_gpus,
            enforce_eager=True,
            dtype=autodetect_dtype_str(),
            max_model_len=8192 if "deepseek" in model_lower else None,
            gpu_memory_utilization=1.0 if "deepseek" in model_lower else 0.9,
            trust_remote_code=True,
        )
        self.tokenizer = self.model.get_tokenizer()
        self.num_gpus = num_gpus
        self.prompt_fn = prompt_fn
        self.is_chat = is_chat

    def generate_with_info(self, prompts: List[Prompt], **kwargs) -> List[Completion]:
        from vllm import SamplingParams
        kwargs = kwargs.copy()
        stop = kwargs.pop("stop", [])
        stop.append("# START NEW CODE")  # for few-shot prompts
        stop.append(EVOLVED_SEP)  # for evaluating base evolver
        gens = self.model.generate(
            prompts=prompts,
            sampling_params=SamplingParams(
                top_p=kwargs.pop("top_p", 0.95),
                temperature=kwargs.pop("temperature", 0.0),
                max_tokens=kwargs.pop("max_tokens", 4096),
                stop=stop,
            ),
            use_tqdm=kwargs.pop("use_tqdm", False),
        )
        outs = []
        for gen in gens:
            gen = gen.outputs[0]
            outs.append(Completion(
                post_process_markdown(
                    gen.text) if self.is_chat else gen.text,
                gen.cumulative_logprob,
                len(gen.token_ids),
            ))
        return outs

    def free_memory(self):
        from vllm.distributed.parallel_state import destroy_model_parallel
        import torch
        import gc
        destroy_model_parallel()
        del self.model.llm_engine.model_executor.driver_worker
        del self.model
        gc.collect()
        torch.cuda.empty_cache()
        if self.num_gpus > 1:
            # NOTE: unfortunately no way to free main process when TP>1 :(
            import ray
            ray.shutdown()

    def format_prompt(self, question: str, code: str = "", public_tests: Optional[Dict[str, Any]] = None, tests: Optional[Dict[str, Any]] = None, solutions: Optional[List[str]] = None) -> str:
        prompt = self.prompt_fn(question, code)
        if isinstance(prompt, list):  # Conversation
            prompt = self.tokenizer.apply_chat_template(
                prompt, add_generation_prompt=True, tokenize=False)
            self.is_chat = True  # if it wasn't true before

        return prompt

    def prefix_starter_code(self) -> bool:
        return not self.is_chat


def detect_first_unused_device() -> str:
    import torch
    for i in range(torch.cuda.device_count()):
        if not torch.cuda.memory_reserved(i):
            return f"cuda:{i}"
    print("WARNING: No available GPU detected, using CPU. Specify --device to use a specific device.")
    return "cpu"


class OutcomeRewardModel(ClassificationModel):
    def __init__(self, model_name: str, device=None, pos_idx=1):
        super().__init__(model_name)
        from transformers import AutoModelForSequenceClassification, AutoTokenizer

        if device is None:
            device = detect_first_unused_device()

        self.device = device
        self.tokenizer = AutoTokenizer.from_pretrained(
            model_name, add_eos_token=True)
        extra_kwargs = {}
        if self.device == "auto":
            extra_kwargs["device_map"] = "auto"

        self.model = AutoModelForSequenceClassification.from_pretrained(
            model_name,
            torch_dtype=autodetect_dtype(),
            use_flash_attention_2=True,
            use_cache=False,
            **extra_kwargs
        )

        if self.device != "auto":
            self.model = self.model.to(self.device)
        else:
            self.device = "cuda"  # patch up for generation later

        self.model = self.model.eval()
        # figure out if it's a 2-label classification or regression model
        if self.model.config.num_labels == 2:
            self.is_classification = True
        else:
            self.is_classification = False
        self.pos_idx = pos_idx

    def score(self, contents: List[str], **kwargs) -> List[Tuple[float, float]]:
        max_length = kwargs.get("max_length", 4096)
        with torch.no_grad():
            inputs = self.tokenizer(
                contents,
                return_tensors="pt",
                padding=True,
                truncation=True,
                max_length=max_length,
            ).to(self.device)
            outputs = self.model(**inputs)
            logits = outputs.logits
            scores = []
            if self.is_classification:
                probs = torch.nn.functional.softmax(logits, dim=-1)
                probs = probs.cpu().to(torch.float32).numpy()
                for prob in probs:
                    scores.append((float(prob[0]), float(prob[1])))
            else:
                # model is trained with MSE loss, so we can interpret the output as a probability
                # (since it's a single scalar value), should be in [0, 1]
                probs = logits.cpu().to(torch.float32).numpy()
                for prob in probs:
                    scores.append((float(1 - prob), float(prob)))

            return scores


EvolutionStrategy = Literal["cma", "es", "random", "best"]


class EvolverModel(HFModel):
    def __init__(
        self,
        model_name: str,
        rm_name: str,
        num_gpus=1,
        evolver_e=5,  # maximum number of iterations
        evolver_n=1,  # number of candidates to generate from each prompt
        evolver_strategy: EvolutionStrategy = "best",
        rm_device=None,
        prompt_fn=py_prompt,
        evol_prompt_fn=py_prompt_evolve,
    ):
        super().__init__(model_name, num_gpus=num_gpus, prompt_fn=prompt_fn)
        self.rm = OutcomeRewardModel(rm_name, device=rm_device)
        self.evolver_e = evolver_e
        self.evolver_n = evolver_n
        self.evol_prompt_fn = evol_prompt_fn
        self.evolver_strategy = evolver_strategy

    def evolve_prompt(self, prompt: Prompt, program: Optional[str]) -> str:
        assert isinstance(
            prompt, str), "Prompt must be a string for evolver model"

        if program is None:
            evol_prompt = prompt
        else:
            evol_prompt = self.evol_prompt_fn(prompt + program)

        return evol_prompt

    def generate_with_info(self, prompts: List[Prompt], **kwargs) -> List[Completion]:
        state = [{"pool": []} for _ in prompts]

        # warn if temperature=0.0 and self.evolver_n > 1
        if self.evolver_n > 1 and kwargs.get("temperature", 0.0) == 0.0:
            print(
                "WARNING: temperature=0.0 and evolver_n > 1 may result in duplicate completions")

        for _ in tqdm(range(self.evolver_e), desc="Evolver iterations"):
            evolve_prompts = []
            og_prompts = []
            for j, prompt in enumerate(prompts):
                pool = state[j]["pool"]

                to_evolve = None
                if len(pool) > 0:
                    if self.evolver_strategy == "random":
                        to_evolve = np.random.choice(pool).code
                    elif self.evolver_strategy == "best":
                        to_evolve = max(pool, key=lambda c: c.orm_score).code
                    else:
                        raise NotImplementedError(
                            f"Evolution strategy {self.evolver_strategy} not implemented")
                else:
                    to_evolve = None

                evolve_prompts.append(self.evolve_prompt(prompt, to_evolve))
                og_prompts.append(prompt)

            completions = super().generate_with_info(evolve_prompts, **kwargs)

            for j, (completion, og_prompt) in enumerate(zip(completions, og_prompts)):
                to_score = og_prompt + completion.code
                score = self.rm.score([to_score])[0][self.rm.pos_idx]
                completion.orm_score = score
                state[j]["pool"].append(completion)

        bests = []
        for i in range(len(prompts)):
            pool = state[i]["pool"]
            best = max(pool, key=lambda c: c.orm_score)
            bests.append(best)

        return bests

    def format_prompt(self, question: str, code: str = "", public_tests: Optional[Dict[str, Any]] = None, tests: Optional[Dict[str, Any]] = None, solutions: Optional[List[str]] = None) -> str:
        return self.prompt_fn(question, code)  # not the evolve one!


def post_process_markdown(new: str) -> str:
    try:
        extracted = markdown_codeblock_extract(new)
    except Exception as e:
        print(f"Failed to extract codeblock from {new}: {e}")
        extracted = new
    return extracted.strip()


def logprobs_to_cumulative(logprobs):  # NOTE: normalized
    c = 0
    for l in logprobs:
        c += l
    return c / len(logprobs)


class OpenAIChatModel(BaseModel):
    def __init__(self, model_name: str, prompt_fn=py_prompt_2shot_lcb_chat):
        super().__init__(model_name)
        from openai import Client
        api_key = os.environ.get("OPENAI_API_KEY")
        if api_key is None:
            raise ValueError("OPENAI_API_KEY is not set")
        self.client = Client(api_key=api_key)
        self.prompt_fn = prompt_fn

    def generate_with_info(self, prompts: List[Prompt], **kwargs) -> List[Completion]:
        completions: List[Optional[Completion]] = [None] * len(prompts)
        threads = []

        def generate_completion(prompt, i):
            import openai
            while True:
                try:
                    response = self.client.chat.completions.create(
                        model=self.model_name,
                        messages=prompt,
                        max_tokens=kwargs.get("max_tokens", 3076),
                        logprobs=True,
                        stop=kwargs.get("stop", []),
                        temperature=kwargs.get("temperature", 0.0),
                        top_p=kwargs.get("top_p", 1.0),
                    )
                except openai.RateLimitError as e:
                    print("OpenAI API Rate limited, waiting 30s...", e)
                    time.sleep(30)
                    continue
                break
            choice = response.choices[0]
            o = choice.message.content
            logprobs = choice.logprobs.content  # type: ignore
            assert o is not None, "OpenAI returned a null response"
            assert logprobs is not None, "OpenAI returned a null logprobs"
            logprobs = [l.logprob for l in logprobs]
            num_tokens = len(logprobs)
            proc = post_process_markdown(o)
            cumulative_logprob = logprobs_to_cumulative(logprobs)
            completions[i] = Completion(
                proc, cumulative_logprob, num_tokens)

        for i, prompt in enumerate(prompts):
            thread = threading.Thread(
                target=generate_completion, args=(prompt, i))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        assert all(
            c is not None for c in completions), "Some completions are missing -- threading bug?"

        return completions  # type: ignore

    def format_prompt(self, question: str, code: str = "", public_tests: Optional[Dict[str, Any]] = None, tests: Optional[Dict[str, Any]] = None, solutions: Optional[List[str]] = None) -> Conversation:
        return self.prompt_fn(question, code)

    def prefix_starter_code(self) -> bool:
        return False

