        max_new_tokens = self.max_new_tokens + len(
            self.tokenizer.encode(prompt, return_tensors="pt")[0]
        )

        raw_outputs = self.model.generate(
            input_tokens,
            max_new_tokens=max_new_tokens,
            stopping_criteria=scores,
