        self, prompt: str, do_sample: bool = True, num_samples: int = 200
    ) -> List[str]:
        prompt = prompt.strip()  # starcoder2 needs this, bad
        return HFTorchDecoder.codegen(self, prompt, do_sample, num_samples)


class StarCoderInfill(HFTorchDecoder):
    def __init__(self, name: str, **kwargs) -> None:
        super().__init__(name, **kwargs)
        self.prefix_token = "<fim_prefix>"
        self.suffix_token = "<fim_suffix><fim_middle>"

    def codegen(
        self, prompt: str, do_sample: bool = True, num_samples: int = 200
    ) -> List[str]:
        if self.temperature == 0:
            assert not do_sample
            assert num_samples == 1

        input = self.prefix_token + prompt + self.suffix_token
        input_tokens = self.tokenizer.encode(input, return_tensors="pt").to(self.device)
        scores = StoppingCriteriaList(
            [
                EndOfFunctionCriteria(
                    start_length=len(input_tokens[0]),
                    eos=self.eos,
                    tokenizer=self.tokenizer,
                )
            ]
        )
        temperature = max(self.temperature, 1e-2)
        raw_outputs = self.model.generate(
            input_tokens,
            max_new_tokens=self.max_new_tokens,
            stopping_criteria=scores,
            do_sample=do_sample,
            top_p=0.95,
            top_k=None,
            temperature=temperature,
            num_return_sequences=min(self.batch_size, num_samples),
            output_scores=True,
            return_dict_in_generate=True,
            repetition_penalty=1.0,
            pad_token_id=self.tokenizer.eos_token_id,
        )
        gen_seqs = raw_outputs.sequences[:, len(input_tokens[0]) :]
        gen_strs = self.tokenizer.batch_decode(
            gen_seqs, skip_special_tokens=self.skip_special_tokens
        )
        outputs = []
        # removes eos tokens.
        for output in gen_strs:
            min_index = 10000
            for eos in self.eos:
                if eos in output:
                    min_index = min(min_index, output.index(eos))
            outputs.append(output[:min_index])
        return outputs


def make_model(name: str, batch_size: int = 1, temperature: float = 0.8):
    if name == "claude-3":
        return AnthropicDecoder(
            batch_size=batch_size,
            name="claude",
            temperature=temperature,
            model_name="claude-3-opus-20240229",
            conversational=True,
        )
    elif name == "claude-3-haiku":  # cheaper model
        return AnthropicDecoder(
            batch_size=batch_size,
            name="claude",
            temperature=temperature,
            model_name="claude-3-haiku-20240307",
            conversational=True,
        )
    elif name == "claude-2":
        return AnthropicDecoder(
            batch_size=batch_size,
            name="claude",
            temperature=temperature,
            model_name="claude-2.1",
            conversational=True,
        )
    elif name == "gemini-pro":
        return GeminiChatDecoder(
            batch_size=batch_size,
            name="gemini-pro",
            temperature=temperature,
            model_name="models/gemini-pro",
            conversational=True,
        )
    elif name == "palm":
        return PalmDecoder(
            batch_size=batch_size,
            name="palm",
            temperature=temperature,
            model_name="models/text-bison-001",
            conversational=True,
        )
    elif name == "chatgpt":
        return OpenAIChatDecoder(
            batch_size=batch_size,
            name="ChatGPT",
            temperature=temperature,
            model_name="gpt-3.5-turbo",
            conversational=True,
        )
    elif name == "gpt-4-turbo":
        return OpenAIChatDecoder(
            batch_size=batch_size,
            name="GPT4",
            temperature=temperature,
            model_name="gpt-4-turbo-preview",
            conversational=True,
        )
    elif name in ["gpt-4", "gpt-4-1106-preview"]:
        return OpenAIChatDecoder(
            batch_size=batch_size,
            name="GPT4",
            temperature=temperature,
            model_name=name,
            conversational=True,
        )
    elif name.startswith("starcoder2"):
        import re

        pattern = re.compile(r"starcoder2-(\d+)b")
        matches = pattern.findall(name)
        nb = int(matches[0])
        assert float(nb) > 0
        return StarCoder2(
            batch_size=batch_size,
            name=f"bigcode/{name}",
            temperature=temperature,
        )
    elif name.startswith("starcoder"):
        return StarCoderInfill(
            batch_size=batch_size, name=f"bigcode/{name}", temperature=temperature
        )
    elif name.startswith("code-llama-"):
        import re

        pattern = re.compile(r"code-llama-(\d+\.?\d*)b(.*)")
        matches = pattern.findall(name)[0]
        nb = matches[0]
        assert float(nb) > 0

        if "instruct" in name:
            if float(nb) < 69:  # nice
                return CodeLlamaInstructSmall(
                    batch_size=batch_size,
                    name=f"codellama/CodeLlama-{nb}b-Instruct-hf",
                    temperature=temperature,
                )
            else:
                return CodeLlamaInstructLarge(
                    batch_size=batch_size,
                    name=f"codellama/CodeLlama-{nb}b-Instruct-hf",
                    temperature=temperature,
                )
        elif "python" in name:
            return HFTorchDecoder(
                batch_size=batch_size,
                name=f"codellama/CodeLlama-{nb}b-Python-hf",
                temperature=temperature,
            )
        else:
            return VLlmDecoder(
                batch_size=batch_size,
                name=f"codellama/CodeLlama-{nb}b-hf",
                temperature=temperature,
            )
    elif name.startswith("deepseek-coder"):
        import re

        # format deepseek-coder-{nb}b*
        pattern = re.compile(r"deepseek-coder-(\d+\.?\d*)b(.*)")
        matches = pattern.findall(name)[0]
        nb = matches[0]
        assert float(nb) > 0

        if "instruct" in name:
            return DeepSeekInstruct(
                batch_size=batch_size,
                name=f"deepseek-ai/{name}",
                temperature=temperature,
                conversational=True,
            )
        else:
            return HFTorchDecoder(
                batch_size=batch_size,
                name=f"deepseek-ai/deepseek-coder-{nb}b-base",
                temperature=temperature,
            )
    elif name == "magicoder-s-ds-6.7b":
        return MagicCoderInstruct(
            batch_size=batch_size,
            name=f"ise-uiuc/Magicoder-S-DS-6.7B",
            temperature=temperature,
            conversational=True,
        )
    elif name == "magicoder-s-cl-7b":
        return MagicCoderInstruct(
            batch_size=batch_size,
            name=f"ise-uiuc/Magicoder-S-CL-7B",
            temperature=temperature,
            conversational=True,
        )
    elif name.startswith("wizardcoder-34b"):
        return WizardCoderDecoder(
            batch_size=batch_size,
            name=f"WizardLM/WizardCoder-Python-34B-V1.0",
            temperature=temperature,
            conversational=True,
        )
    elif name.startswith("wizardcoder-33b-1.1"):
        return WizardCoderDecoder(
            batch_size=batch_size,
            name=f"WizardLM/WizardCoder-33B-V1.1",
            temperature=temperature,
            conversational=True,
        )
    elif name == "phind-code-llama-34b-v2":
        return HFTorchDecoder(
            batch_size=batch_size,
            name="Phind/Phind-CodeLlama-34B-v2",
            temperature=temperature,
        )
    elif name.startswith("mistral-7b"):
        if "instruct" in name:
            if name.endswith("-v02"):
                return MistralInstruct(
                    batch_size=batch_size,
                    name="mistralai/Mistral-7B-Instruct-v0.2",
                    temperature=temperature,
                    conversational=True,
                )
            else:
                return MistralInstruct(
                    batch_size=batch_size,
                    name="mistralai/Mistral-7B-Instruct-v0.1",
                    temperature=temperature,
                    conversational=True,
                )
        else:
            return HFTorchDecoder(
                batch_size=batch_size,
                name="mistralai/Mistral-7B-v0.1",
                temperature=temperature,
            )
    elif name.startswith("mixtral-8x7b"):
        if "instruct" in name:
            return MixtralSPMXInstruct(
                batch_size=batch_size,
                name="mistralai/Mixtral-8x7B-Instruct-v0.1",
                temperature=temperature,
                conversational=True,
            )
        else:
            return HFTorchDecoder(
                batch_size=batch_size,
                name="mistralai/Mixtral-8x7B-v0.1",
                temperature=temperature,
            )
    elif name == "stable-code-3b":
        return HFTorchDecoder(
            batch_size=batch_size,
            name="stabilityai/stable-code-3b",
            temperature=temperature,
        )
    elif name == "speechless-codellama-34b":
        return Alpaca(
            batch_size=batch_size,
            name="uukuguy/speechless-codellama-34b-v2.0",
            temperature=temperature,
        )
    elif name == "openchat":
        return OpenChat(
            batch_size=batch_size,
            name="openchat/openchat-3.5-0106",
            temperature=temperature,
        )
    elif name.startswith("code-millenials-34b"):
        return Alpaca(
            batch_size=batch_size,
            name="budecosystem/code-millenials-34b",
            temperature=temperature,
            conversational=True,
        )
    elif name == "phi-2":
        return VLlmDecoder(
            batch_size=batch_size,
            name="microsoft/phi-2",
            temperature=temperature,
        )
    elif name.startswith("qwen"):
        # format deepseek-coder-{nb}b*
        import re

        pattern = re.compile(r"qwen-(\d+\.?\d*)b(.*)")
        matches = pattern.findall(name)[0]
        nb = matches[0]
        assert float(nb) > 0

        if "1.5" in name:
            return QwenInstruct(
                batch_size=batch_size,
                name=f"Qwen/Qwen1.5-{nb}B-Chat",
                temperature=temperature,
                conversational=True,
            )
        else:
            return QwenInstruct(
                batch_size=batch_size,
                name=f"Qwen/Qwen-{nb}B-Chat",
                temperature=temperature,
                conversational=True,
            )
    elif name.startswith("xwincoder-34b"):
        return XwinCoder(
            batch_size=batch_size, name="Xwin-LM/XwinCoder-34B", temperature=temperature
        )
    elif name.startswith("gemma"):
        import re

        pattern = re.compile(r"gemma-(\d+\.?\d*)b(.*)")
        matches = pattern.findall(name)[0]
        nb = matches[0]
        assert float(nb) > 0
        if "instruct" in name:
            return GemmaInstruct(
                batch_size=batch_size,
                name=f"google/gemma-{nb}b-it",
                temperature=temperature,
                conversational=True,
            )
        else:
            return HFTorchDecoder(
                batch_size=batch_size,
                name=f"google/gemma-{nb}b",
                temperature=temperature,
            )

    raise ValueError(f"Invalid model name: {name}")

# SPDX-License-Identifier: Apache-2.0
"""
This example shows how to use vLLM for running offline inference with
the explicit/implicit prompt format on enc-dec LMMs for text generation.
"""
import time
from collections.abc import Sequence
from dataclasses import asdict
from typing import NamedTuple

from vllm import LLM, EngineArgs, PromptType, SamplingParams
from vllm.assets.audio import AudioAsset
from vllm.assets.image import ImageAsset
from vllm.utils import FlexibleArgumentParser


class ModelRequestData(NamedTuple):
    engine_args: EngineArgs
    prompts: Sequence[PromptType]


def run_florence2():
    engine_args = EngineArgs(
        model="microsoft/Florence-2-large",
        tokenizer="Isotr0py/Florence-2-tokenizer",
        max_num_seqs=8,
        trust_remote_code=True,
        limit_mm_per_prompt={"image": 1},
        dtype="half",
    )

    prompts = [
        {   # implicit prompt with task token
            "prompt": "<DETAILED_CAPTION>",
            "multi_modal_data": {
                "image": ImageAsset("stop_sign").pil_image
            },
        },
        {   # explicit encoder/decoder prompt
            "encoder_prompt": {
                "prompt": "Describe in detail what is shown in the image.",
                "multi_modal_data": {
                    "image": ImageAsset("cherry_blossom").pil_image
                },
            },
            "decoder_prompt": "",
        },
    ]

    return ModelRequestData(
        engine_args=engine_args,
        prompts=prompts,
    )


def run_mllama():
    engine_args = EngineArgs(
        model="meta-llama/Llama-3.2-11B-Vision-Instruct",
        max_model_len=8192,
        max_num_seqs=2,
        limit_mm_per_prompt={"image": 1},
        dtype="half",
    )

    prompts = [
        {   # Implicit prompt
            "prompt": "<|image|><|begin_of_text|>What is the content of this image?",   # noqa: E501
            "multi_modal_data": {
                "image": ImageAsset("stop_sign").pil_image,
            },
        },
        {   # Explicit prompt
            "encoder_prompt": {
                "prompt": "<|image|>",
                "multi_modal_data": {
                    "image": ImageAsset("stop_sign").pil_image,
                },
            },
            "decoder_prompt": "<|image|><|begin_of_text|>Please describe the image.",   # noqa: E501
        },
    ]

    return ModelRequestData(
        engine_args=engine_args,
        prompts=prompts,
    )


def run_whisper():
    engine_args = EngineArgs(
        model="openai/whisper-large-v3-turbo",
        max_model_len=448,
        max_num_seqs=16,
        limit_mm_per_prompt={"audio": 1},
        dtype="half",
    )

    prompts = [
        {   # Test implicit prompt
            "prompt": "<|startoftranscript|>",
            "multi_modal_data": {
                "audio": AudioAsset("mary_had_lamb").audio_and_sample_rate,
            },
        },
        {   # Test explicit encoder/decoder prompt
            "encoder_prompt": {
                "prompt": "",
                "multi_modal_data": {
                    "audio": AudioAsset("winning_call").audio_and_sample_rate,
                },
            },
            "decoder_prompt": "<|startoftranscript|>",
        }
    ]

    return ModelRequestData(
        engine_args=engine_args,
        prompts=prompts,
    )


model_example_map = {
    "florence2": run_florence2,
    "mllama": run_mllama,
    "whisper": run_whisper,
}


def parse_args():
    parser = FlexibleArgumentParser(
        description='Demo on using vLLM for offline inference with '
        'vision language models for text generation')
    parser.add_argument('--model-type',
                        '-m',
                        type=str,
                        default="mllama",
                        choices=model_example_map.keys(),
                        help='Huggingface "model_type".')
    parser.add_argument("--seed",
                        type=int,
                        default=None,
                        help="Set the seed when initializing `vllm.LLM`.")
    return parser.parse_args()


def main(args):
    model = args.model_type
    if model not in model_example_map:
        raise ValueError(f"Model type {model} is not supported.")

    req_data = model_example_map[model]()

    # Disable other modalities to save memory
    default_limits = {"image": 0, "video": 0, "audio": 0}
    req_data.engine_args.limit_mm_per_prompt = default_limits | dict(
        req_data.engine_args.limit_mm_per_prompt or {})

    engine_args = asdict(req_data.engine_args) | {"seed": args.seed}
    llm = LLM(**engine_args)

    prompts = req_data.prompts

    # Create a sampling params object.
    sampling_params = SamplingParams(
        temperature=0,
        top_p=1.0,
        max_tokens=64,
        skip_special_tokens=False,
    )

    start = time.time()

    # Generate output tokens from the prompts. The output is a list of
    # RequestOutput objects that contain the prompt, generated
    # text, and other information.
    outputs = llm.generate(prompts, sampling_params)

    # Print the outputs.
    for output in outputs:
        prompt = output.prompt
        generated_text = output.outputs[0].text
        print(f"Decoder prompt: {prompt!r}, "
              f"Generated text: {generated_text!r}")

    duration = time.time() - start

    print("Duration:", duration)
    print("RPS:", len(prompts) / duration)


if __name__ == "__main__":
    args = parse_args()
    main(args)

from typing import Optional, List, Dict, Any

import time

from flagevalmm.server.utils import parse_args
from flagevalmm.server.server_dataset import ServerDataset
from flagevalmm.models.base_model_adapter import BaseModelAdapter
from flagevalmm.prompt.prompt_tools import encode_image

import re
from vllm import LLM
from vllm import SamplingParams


def get_images_symbol_index(text):
    pattern = r"<image (\d+)>"
    matches = re.findall(pattern, text)
    return [int(num) - 1 for num in matches]


class CustomDataset(ServerDataset):
    def __getitem__(self, index):
        data = self.get_data(index)
        question_id = data["question_id"]
        img_path = data["img_path"]
        qs = data["question"]
        idx = get_images_symbol_index(qs)
        img_path_idx = []
        idx = set(idx)
        for i in idx:
            if i < len(img_path):
                img_path_idx.append(img_path[i])
            else:
                print("[warning] image index out of range")
        return question_id, img_path_idx, qs


class ModelAdapterVllm(BaseModelAdapter):
    def model_init(self, task_info: Dict):
        ckpt_path = task_info["model_path"]
        with self.accelerator.main_process_first():
            self.model = LLM(
                model=ckpt_path,
                tokenizer_mode="mistral",
                limit_mm_per_prompt={"image": 18},
                max_model_len=32768,
            )
        self.sampling_params = SamplingParams(max_tokens=8192, temperature=0.7)

    def build_message(
        self,
        query: str,
        system_prompt: Optional[str] = None,
        image_paths: List[str] = [],
        past_messages: Optional[List] = None,
    ) -> str:
        messages = past_messages if past_messages else []
        if system_prompt:
            messages.append({"role": "system", "content": system_prompt})
        messages.append(
            {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": query,
                    },
                ],
            },
        )
        for img_path in image_paths:
            base64_image = encode_image(img_path, max_size=4 * 1024 * 1024)
            messages[-1]["content"].append(
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/jpeg;base64,{base64_image}",
                    },
                },
            )
        return messages

    def run_one_task(self, task_name: str, meta_info: Dict[str, Any]):
        results = []
        cnt = 0
        data_loader = self.create_data_loader(
            CustomDataset, task_name, batch_size=1, num_workers=0
        )
        start_time = time.perf_counter()
        for question_id, img_path, qs in data_loader:
            cnt += 1
            question_id = question_id[0]
            img_path_flaten = [p[0] for p in img_path]
            qs = qs[0]

            messages = self.build_message(qs, image_paths=img_path_flaten)
            try:
                outputs = self.model.chat(
                    messages=messages, sampling_params=self.sampling_params
                )
                result = outputs[0].outputs[0].text
            except Exception as e:
                print(e)
                result = str(e)
                engine = self.model.llm_engine
                # get all request_id
                request_ids = []
                for scheduler in engine.scheduler:
                    for seq_group in scheduler.running:
                        request_ids.append(seq_group.request_id)
                engine.abort_request(request_ids)

            results.append(
                {"question_id": question_id, "question": qs, "answer": result}
            )
            self.accelerator.print(f"{qs}\n{result}\n\n")
        rank = self.accelerator.state.local_process_index

        # save results for the rank
        self.save_result(results, meta_info, rank=rank)
        self.accelerator.wait_for_everyone()

        if self.accelerator.is_main_process:
            correct_num = self.collect_results_and_save(meta_info)
            total_time = time.perf_counter() - start_time
            print(
                f"Total time: {total_time}\nAverage time:{total_time / cnt}\nResults_collect number: {correct_num}"
            )

        print("rank", rank, "finished")


if __name__ == "__main__":
    args = parse_args()
    model_adapter = ModelAdapterVllm(
        server_ip=args.server_ip,
        server_port=args.server_port,
        timeout=args.timeout,
        extra_cfg={"model_path": "mistralai/Pixtral-12B-2409"},
    )
    model_adapter.run()

#!/usr/bin/env python3
# pylint: disable=import-outside-toplevel, unused-argument
"""
vLLM / Triton environment & cache-key checker
vLLM cache generator
"""

from __future__ import annotations

import argparse
import hashlib
import json
import logging
import os
import sys
from pathlib import Path
from typing import Any, Dict, List, Tuple

LOGGER = logging.getLogger(Path(__file__).stem)
try:
    import torch  # noqa: E402
except ImportError as exc:
    LOGGER.error("torch not installed: %s", exc)
    sys.exit(1)


MAX_LINE = 100

###############################################################################
# Helper functions
###############################################################################


def gpu_info() -> Dict[str, Any]:
    """Return a structured description of visible GPUs or a CPU-only marker."""
    if not torch.cuda.is_available():
        return {"gpu_type": "CPU-only", "gpu_count": 0}

    gpus: List[Dict[str, Any]] = []
    for idx in range(torch.cuda.device_count()):
        props = torch.cuda.get_device_properties(idx)
        entry: Dict[str, Any] = {
            "name": props.name,
            "total_memory_gb": round(props.total_memory / 2**30, 2),
        }
        # Optional vendor-specific fields
        if hasattr(props, "major"):
            entry["compute_capability"] = f"{props.major}.{props.minor}"
        if hasattr(props, "gcn_arch_name"):
            entry["architecture"] = props.gcn_arch_name
        gpus.append(entry)

    backend = "AMD ROCm" if getattr(torch.version, "hip", None) else "NVIDIA CUDA"
    return {"gpu_type": backend, "gpu_count": len(gpus), "gpus": gpus}


TRACKED_ENV: Tuple[str, ...] = (
    # vLLM
    "VLLM_CACHE_ROOT",
    "VLLM_ATTENTION_BACKEND",
    "VLLM_USE_TRITON",
    "VLLM_USE_XFORMERS",
    # Inductor
    "TORCHINDUCTOR_MAX_AUTOTUNE",
    "TORCHINDUCTOR_FORCE_DISABLE_CACHES",
    "TORCHINDUCTOR_DEBUG",
    "TORCHINDUCTOR_TRACE",
)


def collect_vllm_profile(model: str) -> Dict[str, Any]:
    """Return versions, hardware, and env-var snapshot relevant to vLLM."""
    try:
        import vllm  # noqa: E402
    except ImportError as exc:
        LOGGER.error("vLLM not installed: %s", exc)
        sys.exit(1)

    try:
        import triton  # noqa: E402
    except ImportError as exc:
        LOGGER.error("Triton not installed: %s", exc)
        sys.exit(1)

    versions: Dict[str, str] = {
        "python_version": f"{sys.version_info.major}.{sys.version_info.minor}",
        "torch_version": torch.__version__,
        "vllm_version": vllm.__version__,
        "triton_version": triton.__version__,
    }
    if torch.cuda.is_available() and torch.version.cuda:
        versions["cuda_version_torch"] = torch.version.cuda
    if getattr(torch.version, "hip", None):
        versions["rocm_version_torch"] = torch.version.hip
    try:
        versions["cudnn_version"] = str(torch.backends.cudnn.version())
    except (AttributeError, RuntimeError):
        versions["cudnn_version"] = "n/a"

    env_vars = {k: os.environ[k] for k in TRACKED_ENV if k in os.environ}

    return {
        "versions": versions,
        "hardware": gpu_info(),
        "environment_variables": env_vars,
        "vllm_engine_configuration": {
            "model": model,
            "tensor_parallel_size": 1,
            "pipeline_parallel_size": 1,
            "max_model_len": 8192,
        },
    }


def _blk(title: str, mapping: Dict[str, Any]) -> str:
    """Pretty, aligned key→value block with stable ordering and multi-line values."""
    if not mapping:
        return f"{title}\n  <none>"

    items = sorted(mapping.items(), key=lambda kv: kv[0])
    pad = max(len(k) for k, _ in items)

    lines: List[str] = [title]
    for k, v in items:
        val_str = (
            json.dumps(v, separators=(",", ":"))
            if isinstance(v, (dict, list))
            else str(v)
        )
        first, *rest = val_str.splitlines()
        lines.append(f"  {k:<{pad}} : {first}")
        for line in rest:
            lines.append(" " * (pad + 5) + line)
    return "\n".join(lines)


###############################################################################
# Triton helpers
###############################################################################


def _lazy_triton_import():
    """Return the `triton` module or None (already logged) if missing."""
    try:
        import triton  # noqa: E402

        return triton
    except ImportError as exc:
        LOGGER.error("Triton required for cache-key generation: %s", exc)
        return None


def _triton_invalid_env(_triton) -> Dict[str, str]:
    """Return Triton env-vars that invalidate its kernel cache."""
    try:
        from triton._C.libtriton import get_cache_invalidating_env_vars  # noqa: E402

        return get_cache_invalidating_env_vars()
    except (ImportError, AttributeError) as exc:
        LOGGER.debug("Triton env-invalidators unavailable: %s", exc)
        return {}


def _triton_target() -> str:
    """Return backend-arch-warp descriptor of the active Triton target."""
    try:
        from triton.runtime.driver import driver  # noqa: E402

        tgt = driver.active.get_current_target()
        return f"{tgt.backend}-{tgt.arch}-{tgt.warp_size}"
    except (ImportError, RuntimeError) as exc:
        LOGGER.warning("Cannot query Triton target: %s", exc)
        return "unknown-backend-0-0"


def _triton_extern_libs() -> str:
    """Return a JSON string describing external libs linked into Triton kernels."""
    from triton.runtime.jit import JITFunction  # noqa: E402
    from triton.runtime.driver import driver  # noqa: E402

    kernels: List[JITFunction] = []
    for module in list(sys.modules.values()):
        if module is None:
            continue
        kernels.extend(
            val for val in module.__dict__.values() if isinstance(val, JITFunction)
        )

    if not kernels:
        return "{}"

    device = driver.active.get_current_device()
    cache = kernels[0].device_caches[device][2]
    opts = cache.parse_options({})
    return json.dumps(dict(opts.extern_libs), sort_keys=True, separators=(",", ":"))


def generate_triton_components(
    src_hash: str | None = None,
) -> Tuple[str, Dict[str, Any]]:
    """Return (cache_key, detailed_component_dict) for Triton’s kernel cache."""
    triton = _lazy_triton_import()
    if triton is None:
        return "n/a", {"note": "Triton not available; cache-key omitted"}

    comp: Dict[str, Any] = {}

    # noinspection PyProtectedMember
    comp["triton_key"] = triton.compiler.compiler.triton_key()  # type: ignore[attr-defined]

    src_digest = hashlib.sha256((src_hash or "dummy_source").encode()).hexdigest()
    comp["source"] = {"hash": src_digest}

    backend = _triton_target()
    backend_digest = hashlib.sha256(backend.encode()).hexdigest()
    comp["backend"] = {"info": backend, "hash": backend_digest}

    opts = {
        "debug": os.getenv("TRITON_DEBUG", "0") == "1",
        "extern_libs": _triton_extern_libs(),
    }
    opts_digest = hashlib.sha256(
        json.dumps(opts, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    comp["options"] = {"values": opts, "hash": opts_digest}

    env = _triton_invalid_env(triton)
    env_digest = hashlib.sha256(
        json.dumps(env, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    comp["environment"] = {"variables": env, "hash": env_digest}

    composite = "-".join(
        (
            comp["triton_key"],
            src_digest,
            backend_digest,
            opts_digest,
            env_digest,
        )
    )
    cache_key = hashlib.sha256(composite.encode()).hexdigest()
    comp["final_composite"] = composite
    LOGGER.debug("Triton final hash: %s", cache_key)
    return cache_key, comp


###############################################################################
# Hash helpers
###############################################################################


def vllm_hash(vllm_prof: Dict[str, Any]) -> str:
    """Return SHA-256 of the canonicalised vLLM profile."""
    blob = json.dumps(vllm_prof, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(blob.encode()).hexdigest()


def global_hash(vllm_prof: Dict[str, Any], triton_comp: Dict[str, Any]) -> str:
    """Return a digest that flips if *any* vLLM or Triton determinant changes."""
    blob = json.dumps(
        vllm_prof, sort_keys=True, separators=(",", ":")
    ) + triton_comp.get("final_composite", "")
    return hashlib.sha256(blob.encode()).hexdigest()


###############################################################################
# CLI & I/O helpers
###############################################################################


def parse_cli() -> argparse.Namespace:
    """Build and parse the command-line interface."""
    parser = argparse.ArgumentParser(
        description="Dump vLLM & Triton cache changers; optionally save JSON."
    )
    parser.add_argument("-v", "--verbose", action="store_true", help="DEBUG logging")
    parser.add_argument("--json", action="store_true", help="Emit JSON only")
    parser.add_argument(
        "-m",
        "--model",
        required=True,
        help="Model name or path (e.g. ibm/granite-7B)",
    )
    return parser.parse_args()


def run_demo_generation(model: str) -> None:
    """Load a model with vLLM and run a tiny prompt set to populate caches."""
    try:
        from vllm import LLM, SamplingParams  # noqa: E402
    except ImportError as exc:
        LOGGER.error("vLLM not installed: %s", exc)
        sys.exit(1)

    prompts = [
        "Hello, my name is",
        "The president of the United States is",
        "The capital of France is",
        "The future of AI is",
    ]
    llm = LLM(model=model)
    outputs = llm.generate(prompts, SamplingParams(temperature=0.8, top_p=0.95))

    border = "-" * MAX_LINE
    LOGGER.info("\nGenerated Outputs:\n%s", border)
    for out in outputs:
        LOGGER.info("Prompt  : %r", out.prompt)
        LOGGER.info("Output  : %r", out.outputs[0].text)
        LOGGER.info(border)


def dump_summary(
    vllm_prof: Dict[str, Any], triton_comp: Dict[str, Any], triton_key: str
) -> None:
    """Print a human-readable summary of collected information."""
    sep = "=" * MAX_LINE
    LOGGER.info(sep)
    LOGGER.info("vLLM / Torch-Inductor Environment")
    LOGGER.info(sep)
    LOGGER.info(_blk("\n▶ Versions", vllm_prof["versions"]))
    LOGGER.info(_blk("\n▶ Hardware", vllm_prof["hardware"]))
    LOGGER.info(_blk("\n▶ Environment Variables", vllm_prof["environment_variables"]))
    LOGGER.info(sep)

    LOGGER.info("\nTriton Cache-Key")
    LOGGER.info("-" * MAX_LINE)
    if "note" in triton_comp:
        LOGGER.info(triton_comp["note"])
    else:
        LOGGER.info("cache_key : %s", triton_key)
    LOGGER.info("-" * MAX_LINE)


###############################################################################
# Main entry-point
###############################################################################


def main() -> None:
    """Script entry: parse CLI, collect data, run demo, emit results."""
    args = parse_cli()

    logging.basicConfig(
        level=logging.DEBUG if args.verbose else logging.INFO,
        format="%(asctime)s %(levelname)-8s %(message)s",
        handlers=[logging.StreamHandler(sys.stdout)],
    )

    if not torch.cuda.is_available():
        LOGGER.warning("CUDA/ROCm device NOT detected – proceeding on CPU.")

    vllm_prof = collect_vllm_profile(args.model)
    triton_key, triton_comp = generate_triton_components()

    result = {
        "vllm_profile": vllm_prof,
        "triton_components": triton_comp,
        "hashes": {
            "vllm_hash": vllm_hash(vllm_prof),
            "triton_cache_key": triton_key,
            "global_cache_hash": global_hash(vllm_prof, triton_comp),
        },
    }

    if args.json:
        print(json.dumps(result, indent=2, sort_keys=True))

        cache_root = Path(os.getenv("VLLM_ROOT_CACHE", Path.home() / ".cache" / "vllm"))
        cache_root.mkdir(parents=True, exist_ok=True)
        file_path = cache_root / "metadata.json"
        file_path.write_text(json.dumps(result, indent=2, sort_keys=True))
        LOGGER.info("Successfully wrote JSON to: %s", file_path)
    else:
        dump_summary(vllm_prof, triton_comp, triton_key)
        LOGGER.info(
            "\nGLOBAL CACHE HASH\n%s\n%s",
            "=" * MAX_LINE,
            result["hashes"]["global_cache_hash"],
        )
        LOGGER.info("%s", "=" * MAX_LINE)

    run_demo_generation(args.model)


if __name__ == "__main__":
    main()

