class CacheManager:
    """Centralized cache management system"""

    def __init__(self, config: CacheConfig):
        self.config = config
        self.logger = logging.getLogger(__name__)

        # Initialize Redis if enabled
        self.redis_client = None
        if config.enable_redis and redis:
            try:
                self.redis_client = redis.Redis(
                    host=config.redis_host,
                    port=config.redis_port,
                    db=config.redis_db,
                    password=config.redis_password,
                    decode_responses=True
                )
                self.redis_client.ping()
                self.logger.info("Redis cache connected successfully")
            except Exception as e:
                self.logger.warning(f"Redis connection failed: {e}. Using memory cache only.")
                self.redis_client = None

        # Initialize in-memory caches
        self.query_cache = TTLCache(maxsize=config.query_cache_size, ttl=config.query_cache_ttl)
        self.embedding_cache = TTLCache(maxsize=config.embedding_cache_size, ttl=config.embedding_cache_ttl)
        self.search_cache = TTLCache(maxsize=config.search_cache_size, ttl=config.search_cache_ttl)
        self.conversation_cache = TTLCache(maxsize=500, ttl=config.conversation_cache_ttl)

        # LRU cache for frequently accessed data
        self.chunk_cache = LRUCache(maxsize=1000)
        self.metadata_cache = LRUCache(maxsize=2000)

    def _get_cache_key(self, prefix: str, *args) -> str:
        """Generate cache key from arguments"""
        key_data = "_".join(str(arg) for arg in args)
        return f"{prefix}:{hashlib.md5(key_data.encode()).hexdigest()}"

    def get_query_result(self, query: str, context_hash: str = "") -> Optional[Dict[str, Any]]:
        """Get cached query result"""
        cache_key = self._get_cache_key("query", query, context_hash)

        # Try Redis first
        if self.redis_client:
            try:
                cached = self.redis_client.get(cache_key)
                if cached:
                    return json.loads(cached)
            except Exception as e:
                self.logger.warning(f"Redis get error: {e}")

        # Fallback to memory cache
        return self.query_cache.get(cache_key)

    def set_query_result(self, query: str, result: Dict[str, Any], context_hash: str = "") -> None:
        """Cache query result"""
        cache_key = self._get_cache_key("query", query, context_hash)

        # Store in Redis
        if self.redis_client:
            try:
                self.redis_client.setex(
                    cache_key, 
                    self.config.query_cache_ttl, 
                    json.dumps(result, default=str)
                )
            except Exception as e:
                self.logger.warning(f"Redis set error: {e}")

        # Store in memory cache
        self.query_cache[cache_key] = result

    def get_embedding(self, text: str) -> Optional[np.ndarray]:
        """Get cached embedding"""
        cache_key = self._get_cache_key("embedding", text)

        if self.redis_client:
            try:
                cached = self.redis_client.get(cache_key)
                if cached:
                    return np.frombuffer(eval(cached), dtype=np.float32)
            except Exception as e:
                self.logger.warning(f"Redis embedding get error: {e}")

        return self.embedding_cache.get(cache_key)

    def set_embedding(self, text: str, embedding: np.ndarray) -> None:
        """Cache embedding"""
        cache_key = self._get_cache_key("embedding", text)

        if self.redis_client:
            try:
                self.redis_client.setex(
                    cache_key,
                    self.config.embedding_cache_ttl,
                    str(embedding.tobytes())
                )
            except Exception as e:
                self.logger.warning(f"Redis embedding set error: {e}")

        self.embedding_cache[cache_key] = embedding

    def get_search_results(self, query: str, filters: Dict = None) -> Optional[List[Tuple]]:
        """Get cached search results"""
        cache_key = self._get_cache_key("search", query, str(filters or {}))

        if self.redis_client:
            try:
                cached = self.redis_client.get(cache_key)
                if cached:
                    return pickle.loads(eval(cached))
            except Exception as e:
                self.logger.warning(f"Redis search get error: {e}")

        return self.search_cache.get(cache_key)

    def set_search_results(self, query: str, results: List[Tuple], filters: Dict = None) -> None:
        """Cache search results"""
        cache_key = self._get_cache_key("search", query, str(filters or {}))

        if self.redis_client:
            try:
                self.redis_client.setex(
                    cache_key,
                    self.config.search_cache_ttl,
                    str(pickle.dumps(results))
                )
            except Exception as e:
                self.logger.warning(f"Redis search set error: {e}")

        self.search_cache[cache_key] = results

    def get_conversation_context(self, session_id: str) -> Optional[List[Dict]]:
        """Get conversation history"""
        cache_key = f"conv:{session_id}"

        if self.redis_client:
            try:
                cached = self.redis_client.get(cache_key)
                if cached:
                    return json.loads(cached)
            except Exception as e:
                self.logger.warning(f"Redis conversation get error: {e}")

        return self.conversation_cache.get(cache_key)

    def update_conversation_context(self, session_id: str, messages: List[Dict]) -> None:
        """Update conversation history"""
        cache_key = f"conv:{session_id}"

        if self.redis_client:
            try:
                self.redis_client.setex(
                    cache_key,
                    self.config.conversation_cache_ttl,
                    json.dumps(messages)
                )
            except Exception as e:
                self.logger.warning(f"Redis conversation set error: {e}")

        self.conversation_cache[cache_key] = messages

    def invalidate_query_cache(self, pattern: str = None) -> None:
        """Invalidate query cache"""
        if pattern:
            # Invalidate specific pattern
            keys_to_delete = [key for key in self.query_cache.keys() if pattern in key]
            for key in keys_to_delete:
                del self.query_cache[key]
        else:
            # Clear all
            self.query_cache.clear()

        if self.redis_client and pattern:
            try:
                keys = self.redis_client.keys(f"query:*{pattern}*")
                if keys:
                    self.redis_client.delete(*keys)
            except Exception as e:
                self.logger.warning(f"Redis invalidation error: {e}")

    def get_cache_stats(self) -> Dict[str, Any]:
        """Get cache statistics"""
        stats = {
            "query_cache": {
                "size": len(self.query_cache),
                "max_size": self.query_cache.maxsize,
                "hits": getattr(self.query_cache, 'hits', 0),
                "misses": getattr(self.query_cache, 'misses', 0)
            },
            "embedding_cache": {
                "size": len(self.embedding_cache),
                "max_size": self.embedding_cache.maxsize
            },
            "search_cache": {
                "size": len(self.search_cache),
                "max_size": self.search_cache.maxsize
            },
            "redis_connected": self.redis_client is not None
        }

        if self.redis_client:
            try:
                info = self.redis_client.info()
                stats["redis_info"] = {
                    "used_memory_human": info.get("used_memory_human"),
                    "connected_clients": info.get("connected_clients"),
                    "keyspace_hits": info.get("keyspace_hits", 0),
                    "keyspace_misses": info.get("keyspace_misses", 0)
                }
            except Exception as e:
                stats["redis_error"] = str(e)

        return stats


class DocumentProcessor:
    """Handles preprocessing of various document types"""

    def __init__(self):
        self.cobol_patterns = {
            'program_id': r'PROGRAM-ID\.\s+([A-Z0-9-]+)',
            'call': r'CALL\s+[\'"]([A-Z0-9-]+)[\'"]',
            'copy': r'COPY\s+([A-Z0-9-]+)',
            'table': r'EXEC\s+SQL\s+.*?FROM\s+([A-Z0-9_.]+)',
            'vsam': r'SELECT\s+([A-Z0-9-]+)\s+ASSIGN',
            'paragraph': r'^[0-9A-Z-]+\.',
            'field': r'[0-9]+\s+([A-Z0-9-]+)',
            'business_logic': r'(CORPORATE|SECURITY|TRANSACTION|REPORTING|TRANSFER|ORDER)'
        }

    def extract_cobol_metadata(self, content: str, filename: str) -> CobolMetadata:
        """Extract COBOL-specific metadata"""
        program_name = self._extract_pattern(content, 'program_id') or Path(filename).stem
        paragraphs = self._extract_all_patterns(content, 'paragraph')
        called_programs = self._extract_all_patterns(content, 'call')
        copybooks = self._extract_all_patterns(content, 'copy')
        db2_tables = self._extract_all_patterns(content, 'table')
        vsam_files = self._extract_all_patterns(content, 'vsam')
        fields_used = self._extract_all_patterns(content, 'field')
        business_logic_sections = self._extract_all_patterns(content, 'business_logic')

        return CobolMetadata(
            program_name=program_name,
            paragraphs=paragraphs,
            called_programs=called_programs,
            copybooks=copybooks,
            db2_tables=db2_tables,
            vsam_files=vsam_files,
            fields_used=fields_used,
            business_logic_sections=business_logic_sections
        )

    def _extract_pattern(self, content: str, pattern_name: str) -> Optional[str]:
        """Extract single pattern match"""
        pattern = self.cobol_patterns.get(pattern_name)
        if pattern:
            match = re.search(pattern, content, re.IGNORECASE | re.MULTILINE)
            return match.group(1) if match else None
        return None

    def _extract_all_patterns(self, content: str, pattern_name: str) -> List[str]:
        """Extract all pattern matches"""
        pattern = self.cobol_patterns.get(pattern_name)
        if pattern:
            matches = re.findall(pattern, content, re.IGNORECASE | re.MULTILINE)
            return list(set(matches))  # Remove duplicates
        return []

    def classify_business_domain(self, content: str, filename: str) -> str:
        """Classify document into business domain"""
        content_lower = content.lower()
        filename_lower = filename.lower()

        domain_keywords = {
            'corporate_actions': ['corporate', 'dividend', 'split', 'merger', 'spin-off'],
            'security_transactions': ['security', 'trade', 'settlement', 'clearing'],
            'reporting': ['report', 'stmt', 'summary', 'balance'],
            'db2_operations': ['db2', 'sql', 'table', 'select', 'insert'],
            'money_transfers': ['transfer', 'payment', 'wire', 'ach'],
            'orders': ['order', 'buy', 'sell', 'cancel', 'modify']
        }

        for domain, keywords in domain_keywords.items():
            if any(keyword in content_lower or keyword in filename_lower for keyword in keywords):
                return domain

        return 'general'

    def chunk_document(self, content: str, chunk_size: int = 1000, overlap: int = 200) -> List[str]:
        """Chunk document by semantic boundaries"""
        # For COBOL, chunk by paragraphs
        if 'PROGRAM-ID' in content:
            return self._chunk_cobol(content, chunk_size, overlap)
        else:
            return self._chunk_generic(content, chunk_size, overlap)

    def _chunk_cobol(self, content: str, chunk_size: int, overlap: int) -> List[str]:
        """Chunk COBOL code by paragraphs"""
        lines = content.split('\n')
        chunks = []
        current_chunk = []
        current_size = 0

        for line in lines:
            # Check if line starts a new paragraph
            if re.match(r'^[0-9A-Z-]+\.', line.strip()):
                if current_chunk and current_size > chunk_size:
                    chunks.append('\n'.join(current_chunk))
                    # Keep overlap
                    overlap_lines = current_chunk[-overlap//20:]
                    current_chunk = overlap_lines
                    current_size = sum(len(l) for l in overlap_lines)

            current_chunk.append(line)
            current_size += len(line)

        if current_chunk:
            chunks.append('\n'.join(current_chunk))

        return chunks

    def _chunk_generic(self, content: str, chunk_size: int, overlap: int) -> List[str]:
        """Generic text chunking"""
        words = content.split()
        chunks = []

        for i in range(0, len(words), chunk_size - overlap):
            chunk = ' '.join(words[i:i + chunk_size])
            chunks.append(chunk)

        return chunks

    def process_pdf(self, file_path: str) -> str:
        """Extract text from PDF"""
        try:
            with open(file_path, 'rb') as file:
                reader = PyPDF2.PdfReader(file)
                text = ""
                for page in reader.pages:
                    text += page.extract_text()
                return text
        except Exception as e:
            logger.error(f"Error processing PDF {file_path}: {e}")
            return ""

    def process_docx(self, file_path: str) -> str:
        """Extract text from DOCX"""
        try:
            doc = docx.Document(file_path)
            text = ""
            for paragraph in doc.paragraphs:
                text += paragraph.text + "\n"
            return text
        except Exception as e:
            logger.error(f"Error processing DOCX {file_path}: {e}")
            return ""

    def process_markdown(self, file_path: str) -> str:
        """Extract text from Markdown"""
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                md_content = file.read()
                html = markdown.markdown(md_content)
                soup = BeautifulSoup(html, 'html.parser')
                return soup.get_text()
        except Exception as e:
            logger.error(f"Error processing Markdown {file_path}: {e}")
            return ""


class VectorStore:
    """Manages vector embeddings and retrieval"""

    def __init__(self, embedding_model_name: str = "all-MiniLM-L6-v2", use_gpu: bool = True):
        self.device = 'cuda' if torch.cuda.is_available() and use_gpu else 'cpu'
        self.embedding_model = SentenceTransformer(embedding_model_name, device=self.device)
        self.dimension = self.embedding_model.get_sentence_embedding_dimension()

        # Initialize FAISS index
        self.faiss_index = faiss.IndexFlatIP(self.dimension)  # Inner product for cosine similarity
        if use_gpu and torch.cuda.is_available():
            self.faiss_index = faiss.index_cpu_to_gpu(faiss.StandardGpuResources(), 0, self.faiss_index)

        # Initialize ChromaDB for metadata
        self.chroma_client = chromadb.Client(Settings(allow_reset=True, anonymized_telemetry=False))
        self.collection = self.chroma_client.create_collection(
            name="mainframe_docs",
            metadata={"hnsw:space": "cosine"}
        )

        # Document storage
        self.documents: Dict[str, DocumentChunk] = {}
        self.chunk_id_to_index: Dict[str, int] = {}

    def add_documents(self, chunks: List[DocumentChunk]) -> None:
        """Add document chunks to vector store"""
        if not chunks:
            return

        # Generate embeddings
        texts = [chunk.content for chunk in chunks]
        embeddings = self.embedding_model.encode(texts, convert_to_tensor=False, show_progress_bar=True)

        # Normalize embeddings for cosine similarity
        embeddings = embeddings / np.linalg.norm(embeddings, axis=1, keepdims=True)

        # Add to FAISS
        start_index = self.faiss_index.ntotal
        self.faiss_index.add(embeddings.astype('float32'))

        # Add to ChromaDB and internal storage
        for i, chunk in enumerate(chunks):
            chunk.embedding = embeddings[i]
            self.documents[chunk.chunk_id] = chunk
            self.chunk_id_to_index[chunk.chunk_id] = start_index + i

            # Add to ChromaDB
            self.collection.add(
                embeddings=[embeddings[i].tolist()],
                documents=[chunk.content],
                metadatas=[chunk.metadata],
                ids=[chunk.chunk_id]
            )

    def search(self, query: str, top_k: int = 10, filter_metadata: Dict = None) -> List[Tuple[DocumentChunk, float]]:
        """Search for similar documents"""
        # Encode query
        query_embedding = self.embedding_model.encode([query], convert_to_tensor=False)
        query_embedding = query_embedding / np.linalg.norm(query_embedding, axis=1, keepdims=True)

        # Search in FAISS
        scores, indices = self.faiss_index.search(query_embedding.astype('float32'), top_k)

        results = []
        for score, idx in zip(scores[0], indices[0]):
            if idx == -1:  # No more results
                break

            # Find chunk by index
            chunk_id = None
            for cid, cidx in self.chunk_id_to_index.items():
                if cidx == idx:
                    chunk_id = cid
                    break

            if chunk_id and chunk_id in self.documents:
                chunk = self.documents[chunk_id]

                # Apply metadata filter if provided
                if filter_metadata:
                    match = all(chunk.metadata.get(k) == v for k, v in filter_metadata.items())
                    if not match:
                        continue

                results.append((chunk, float(score)))

        return results

    def get_program_references(self, program_name: str) -> List[DocumentChunk]:
        """Get all chunks that reference a specific program"""
        results = []
        for chunk in self.documents.values():
            if program_name.upper() in chunk.content.upper():
                results.append(chunk)
        return results

    def save_index(self, path: str) -> None:
        """Save vector index to disk"""
        os.makedirs(path, exist_ok=True)

        # Save FAISS index
        faiss.write_index(self.faiss_index, os.path.join(path, "faiss.index"))

        # Save documents and metadata
        with open(os.path.join(path, "documents.pkl"), 'wb') as f:
            pickle.dump(self.documents, f)

        with open(os.path.join(path, "chunk_mapping.pkl"), 'wb') as f:
            pickle.dump(self.chunk_id_to_index, f)

    def load_index(self, path: str) -> None:
        """Load vector index from disk"""
        # Load FAISS index
        self.faiss_index = faiss.read_index(os.path.join(path, "faiss.index"))

        # Load documents and metadata
        with open(os.path.join(path, "documents.pkl"), 'rb') as f:
            self.documents = pickle.load(f)

        with open(os.path.join(path, "chunk_mapping.pkl"), 'rb') as f:
            self.chunk_id_to_index = pickle.load(f)


class CachedVectorStore(VectorStore):
    """Enhanced vector store with caching capabilities"""

    def __init__(self, embedding_model_name: str = "all-MiniLM-L6-v2", use_gpu: bool = True, cache_manager: CacheManager = None):
        super().__init__(embedding_model_name, use_gpu)
        self.cache_manager = cache_manager
        self.embedding_cache_hits = 0
        self.embedding_cache_misses = 0
        self.search_cache_hits = 0
        self.search_cache_misses = 0

    def _get_cached_embedding(self, text: str) -> Optional[np.ndarray]:
        """Get embedding from cache"""
        if not self.cache_manager:
            return None

        cached = self.cache_manager.get_embedding(text)
        if cached is not None:
            self.embedding_cache_hits += 1
            return cached

        self.embedding_cache_misses += 1
        return None

    def _cache_embedding(self, text: str, embedding: np.ndarray) -> None:
        """Cache embedding"""
        if self.cache_manager:
            self.cache_manager.set_embedding(text, embedding)

    def encode_with_cache(self, texts: List[str]) -> np.ndarray:
        """Encode texts with caching"""
        embeddings = []
        texts_to_encode = []
        indices_to_encode = []

        # Check cache for each text
        for i, text in enumerate(texts):
            cached_embedding = self._get_cached_embedding(text)
            if cached_embedding is not None:
                embeddings.append(cached_embedding)
            else:
                embeddings.append(None)
                texts_to_encode.append(text)
                indices_to_encode.append(i)

        # Encode uncached texts
        if texts_to_encode:
            new_embeddings = self.embedding_model.encode(texts_to_encode, convert_to_tensor=False)
            new_embeddings = new_embeddings / np.linalg.norm(new_embeddings, axis=1, keepdims=True)

            # Cache new embeddings and update results
            for i, (text, embedding) in enumerate(zip(texts_to_encode, new_embeddings)):
                self._cache_embedding(text, embedding)
                embeddings[indices_to_encode[i]] = embedding

        return np.array(embeddings)

    def add_documents(self, chunks: List[DocumentChunk]) -> None:
        """Add document chunks to vector store with caching"""
        if not chunks:
            return

        # Generate embeddings with caching
        texts = [chunk.content for chunk in chunks]
        embeddings = self.encode_with_cache(texts)

        # Add to FAISS
        start_index = self.faiss_index.ntotal
        self.faiss_index.add(embeddings.astype('float32'))

        # Add to ChromaDB and internal storage
        for i, chunk in enumerate(chunks):
            chunk.embedding = embeddings[i]
            self.documents[chunk.chunk_id] = chunk
            self.chunk_id_to_index[chunk.chunk_id] = start_index + i

            # Cache chunk data
            if self.cache_manager:
                self.cache_manager.chunk_cache[chunk.chunk_id] = chunk

            # Add to ChromaDB
            self.collection.add(
                embeddings=[embeddings[i].tolist()],
                documents=[chunk.content],
                metadatas=[chunk.metadata],
                ids=[chunk.chunk_id]
            )

    def search(self, query: str, top_k: int = 10, filter_metadata: Dict = None) -> List[Tuple[DocumentChunk, float]]:
        """Search for similar documents with caching"""
        # Check cache first
        if self.cache_manager:
            cached_results = self.cache_manager.get_search_results(query, filter_metadata)
            if cached_results is not None:
                self.search_cache_hits += 1
                return cached_results[:top_k]  # Respect top_k limit
            self.search_cache_misses += 1

        # Encode query with caching
        query_embedding = self._get_cached_embedding(query)
        if query_embedding is None:
            query_embedding = self.embedding_model.encode([query], convert_to_tensor=False)[0]
            query_embedding = query_embedding / np.linalg.norm(query_embedding)
            self._cache_embedding(query, query_embedding)

        # Search in FAISS
        scores, indices = self.faiss_index.search(
            query_embedding.reshape(1, -1).astype('float32'), 
            top_k * 2  # Get more results for filtering
        )

        results = []
        for score, idx in zip(scores[0], indices[0]):
            if idx == -1:
                break

            # Find chunk by index
            chunk_id = None
            for cid, cidx in self.chunk_id_to_index.items():
                if cidx == idx:
                    chunk_id = cid
                    break

            if chunk_id and chunk_id in self.documents:
                chunk = self.documents[chunk_id]

                # Apply metadata filter if provided
                if filter_metadata:
                    match = all(chunk.metadata.get(k) == v for k, v in filter_metadata.items())
                    if not match:
                        continue

                results.append((chunk, float(score)))

        # Limit to top_k
        results = results[:top_k]

        # Cache results
        if self.cache_manager:
            self.cache_manager.set_search_results(query, results, filter_metadata)

        return results


class AgenticRAG:
    """Agentic RAG system with multi-step reasoning"""

    def __init__(self, vector_store: VectorStore, llm_model_path: str):
        self.vector_store = vector_store
        self.llm = None
        self.llm_model_path = llm_model_path
        self.sampling_params = SamplingParams(
            temperature=0.1,
            top_p=0.9,
            max_tokens=4096,
            stop=["<|endoftext|>", "</s>"]
        )

    def load_llm(self):
        """Load vLLM model"""
        if self.llm is None:
            logger.info(f"Loading LLM model from {self.llm_model_path}")
            self.llm = LLM(
                model=self.llm_model_path,
                tensor_parallel_size=1,
                gpu_memory_utilization=0.8,
                max_model_len=8192
            )
            logger.info("LLM model loaded successfully")

    def generate_response(self, prompt: str) -> str:
        """Generate response using local LLM"""
        if self.llm is None:
            self.load_llm()

        outputs = self.llm.generate([prompt], self.sampling_params)
        return outputs[0].outputs[0].text.strip()

    def analyze_query(self, query: str) -> Dict[str, Any]:
        """Analyze user query to determine search strategy"""
        analysis_prompt = f"""
        Analyze this query about mainframe legacy code and determine the search strategy:
        Query: "{query}"

        Respond with a JSON object containing:
        - "query_type": one of ["field_usage", "program_flow", "business_logic", "data_lineage", "general"]
        - "entities": list of specific programs, fields, tables mentioned
        - "business_domain": likely business domain
        - "requires_program_retrieval": true if specific programs need to be retrieved first
        - "search_keywords": list of keywords for semantic search

        JSON:
        """

        response = self.generate_response(analysis_prompt)
        try:
            return json.loads(response)
        except:
            # Fallback analysis
            return {
                "query_type": "general",
                "entities": [],
                "business_domain": "general",
                "requires_program_retrieval": False,
                "search_keywords": query.split()
            }

    def multi_step_retrieval(self, query: str, analysis: Dict[str, Any]) -> List[DocumentChunk]:
        """Perform multi-step retrieval based on query analysis"""
        all_chunks = []

        # Step 1: Direct program retrieval if needed
        if analysis["requires_program_retrieval"]:
            for entity in analysis["entities"]:
                program_chunks = self.vector_store.get_program_references(entity)
                all_chunks.extend(program_chunks)

        # Step 2: Semantic search
        search_results = self.vector_store.search(
            query=query, 
            top_k=15,
            filter_metadata={"business_domain": analysis["business_domain"]} if analysis["business_domain"] != "general" else None
        )

        semantic_chunks = [chunk for chunk, score in search_results]
        all_chunks.extend(semantic_chunks)

        # Step 3: Entity-specific search
        for entity in analysis["entities"]:
            entity_results = self.vector_store.search(query=entity, top_k=5)
            entity_chunks = [chunk for chunk, score in entity_results]
            all_chunks.extend(entity_chunks)

        # Remove duplicates while preserving order
        seen = set()
        unique_chunks = []
        for chunk in all_chunks:
            if chunk.chunk_id not in seen:
                seen.add(chunk.chunk_id)
                unique_chunks.append(chunk)

        return unique_chunks[:20]  # Limit to top 20 chunks

    def generate_answer(self, query: str, context_chunks: List[DocumentChunk]) -> str:
        """Generate comprehensive answer using retrieved context"""
        # Group chunks by source for better organization
        chunks_by_source = {}
        for chunk in context_chunks:
            source = chunk.source_file
            if source not in chunks_by_source:
                chunks_by_source[source] = []
            chunks_by_source[source].append(chunk)

        # Build context
        context_parts = []
        for source, chunks in chunks_by_source.items():
            context_parts.append(f"\n=== {source} ===")
            for chunk in chunks:
                context_parts.append(f"[Chunk {chunk.chunk_index}/{chunk.total_chunks}]")
                context_parts.append(chunk.content)
                context_parts.append("---")

        context = "\n".join(context_parts)

        # Construct prompt
        prompt = f"""
        You are an expert at analyzing mainframe legacy codebases, particularly COBOL, JCL, and DB2 systems.

        User Question: {query}

        Based on the following code snippets and documentation, provide a comprehensive answer:

        {context}

        Instructions:
        1. Provide a direct answer to the user's question
        2. Reference specific code sections when relevant
        3. Explain any technical concepts clearly
        4. If the question involves data flow or program relationships, trace them step by step
        5. Include recommendations or best practices if applicable
        6. If information is incomplete, clearly state what additional context would be helpful

        Answer:
        """

        return self.generate_response(prompt)

    async def process_query(self, query: str) -> Dict[str, Any]:
        """Process user query with agentic approach"""
        start_time = time.time()

        # Step 1: Analyze query
        analysis = self.analyze_query(query)

        # Step 2: Multi-step retrieval
        context_chunks = self.multi_step_retrieval(query, analysis)

        # Step 3: Generate answer
        answer = self.generate_answer(query, context_chunks)

        processing_time = time.time() - start_time

        return {
            "answer": answer,
            "analysis": analysis,
            "context_chunks": [
                {
                    "source": chunk.source_file,
                    "content_preview": chunk.content[:200] + "..." if len(chunk.content) > 200 else chunk.content,
                    "business_domain": chunk.business_domain,
                    "metadata": chunk.metadata
                } for chunk in context_chunks
            ],
            "processing_time": processing_time,
            "chunks_retrieved": len(context_chunks)
        }


class StreamingAgenticRAG(AgenticRAG):
    """Enhanced RAG system with streaming and caching"""

    def __init__(self, vector_store: CachedVectorStore, llm_model_path: str, cache_manager: CacheManager = None):
        super().__init__(vector_store, llm_model_path)
        self.cache_manager = cache_manager
        self.conversation_contexts = weakref.WeakValueDictionary()

    def generate_response_streaming(self, prompt: str, session_id: str = None) -> AsyncIterator[str]:
        """Generate streaming response using local LLM"""
        if self.llm is None:
            self.load_llm()

        # Check for cached response first
        if self.cache_manager and session_id:
            cached_result = self.cache_manager.get_query_result(prompt, session_id)
            if cached_result:
                # Stream cached response
                answer = cached_result.get("answer", "")
                return self._stream_text(answer)

        # Generate new response
        outputs = self.llm.generate([prompt], self.sampling_params)
        response = outputs[0].outputs[0].text.strip()

        # Cache the response
        if self.cache_manager and session_id:
            self.cache_manager.set_query_result(prompt, {"answer": response}, session_id)

        return self._stream_text(response)

    async def _stream_text(self, text: str) -> AsyncIterator[str]:
        """Stream text in chunks"""
        if not self.cache_manager or not self.cache_manager.config.enable_streaming:
            yield text
            return

        chunk_size = self.cache_manager.config.stream_chunk_size
        delay = self.cache_manager.config.stream_delay

        for i in range(0, len(text), chunk_size):
            chunk = text[i:i + chunk_size]
            yield chunk
            if delay > 0:
                await asyncio.sleep(delay)

    def get_conversation_context(self, session_id: str) -> List[Dict]:
        """Get conversation context with caching"""
        if not self.cache_manager:
            return []

        return self.cache_manager.get_conversation_context(session_id) or []

    def update_conversation_context(self, session_id: str, query: str, response: str) -> None:
        """Update conversation context"""
        if not self.cache_manager:
            return

        context = self.get_conversation_context(session_id)
        context.append({
            "timestamp": datetime.now().isoformat(),
            "query": query,
            "response": response
        })

        # Keep only last 10 exchanges
        if len(context) > 10:
            context = context[-10:]

        self.cache_manager.update_conversation_context(session_id, context)

    async def process_query_streaming(self, query: str, session_id: str = None) -> AsyncIterator[Dict[str, Any]]:
        """Process user query with streaming response"""
        start_time = time.time()

        # Check for exact cached query first
        if self.cache_manager and session_id:
            cached_result = self.cache_manager.get_query_result(query, session_id)
            if cached_result:
                # Stream cached result
                async for chunk in self._stream_text(cached_result["answer"]):
                    yield {
                        "type": "answer_chunk",
                        "content": chunk,
                        "cached": True
                    }

                yield {
                    "type": "complete",
                    "analysis": cached_result.get("analysis", {}),
                    "context_chunks": cached_result.get("context_chunks", []),
                    "processing_time": time.time() - start_time,
                    "cached": True
                }
                return

        # Yield analysis start
        yield {"type": "status", "message": "Analyzing query..."}

        # Step 1: Analyze query (cached)
        analysis = self.analyze_query(query)
        yield {"type": "analysis", "content": analysis}

        # Step 2: Multi-step retrieval (cached)
        yield {"type": "status", "message": "Retrieving relevant context..."}
        context_chunks = self.multi_step_retrieval(query, analysis)

        yield {
            "type": "context_info",
            "chunks_retrieved": len(context_chunks),
            "sources": list(set(chunk.source_file for chunk in context_chunks))
        }

        # Step 3: Generate answer with streaming
        yield {"type": "status", "message": "Generating response..."}

        # Build context for LLM
        chunks_by_source = {}
        for chunk in context_chunks:
            source = chunk.source_file
            if source not in chunks_by_source:
                chunks_by_source[source] = []
            chunks_by_source[source].append(chunk)

        context_parts = []
        for source, chunks in chunks_by_source.items():
            context_parts.append(f"\n=== {source} ===")
            for chunk in chunks:
                context_parts.append(f"[Chunk {chunk.chunk_index}/{chunk.total_chunks}]")
                context_parts.append(chunk.content)
                context_parts.append("---")

        context = "\n".join(context_parts)

        # Get conversation context
        conversation_history = ""
        if session_id:
            conv_context = self.get_conversation_context(session_id)
            if conv_context:
                recent_context = conv_context[-3:]  # Last 3 exchanges
                conversation_history = "\n\nRecent conversation:\n"
                for ctx in recent_context:
                    conversation_history += f"User: {ctx['query']}\nAssistant: {ctx['response'][:200]}...\n"

        # Construct prompt
        prompt = f"""
        You are an expert at analyzing mainframe legacy codebases, particularly COBOL, JCL, and DB2 systems.

        {conversation_history}

        User Question: {query}

        Based on the following code snippets and documentation, provide a comprehensive answer:

        {context}

        Instructions:
        1. Provide a direct answer to the user's question
        2. Reference specific code sections when relevant
        3. Explain any technical concepts clearly
        4. If the question involves data flow or program relationships, trace them step by step
        5. Include recommendations or best practices if applicable
        6. If information is incomplete, clearly state what additional context would be helpful

        Answer:
        """

        # Stream the response
        full_response = ""
        async for chunk in self.generate_response_streaming(prompt, session_id):
            full_response += chunk
            yield {
                "type": "answer_chunk",
                "content": chunk,
                "cached": False
            }

        processing_time = time.time() - start_time

        # Update conversation context
        if session_id:
            self.update_conversation_context(session_id, query, full_response)

        # Cache the complete result
        complete_result = {
            "answer": full_response,
            "analysis": analysis,
            "context_chunks": [
                {
                    "source": chunk.source_file,
                    "content_preview": chunk.content[:200] + "..." if len(chunk.content) > 200 else chunk.content,
                    "business_domain": chunk.business_domain,
                    "metadata": chunk.metadata
                } for chunk in context_chunks
            ],
            "processing_time": processing_time,
            "chunks_retrieved": len(context_chunks)
        }

        if self.cache_manager and session_id:
            self.cache_manager.set_query_result(query, complete_result, session_id)

        # Final completion message
        yield {
            "type": "complete",
            "analysis": analysis,
            "context_chunks": complete_result["context_chunks"],
            "processing_time": processing_time,
            "chunks_retrieved": len(context_chunks),
            "cached": False
        }


class MainframeAnalyzer:
    """Main system orchestrator"""

    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.document_processor = DocumentProcessor()
        self.vector_store = VectorStore(
            embedding_model_name=config.get("embedding_model", "all-MiniLM-L6-v2"),
            use_gpu=config.get("use_gpu", True)
        )
        self.rag_system = AgenticRAG(
            vector_store=self.vector_store,
            llm_model_path=config["llm_model_path"]
        )

        # Processing queue
        self.processing_queue = Queue()
        self.processing_thread = None
        self.is_processing = False

        # Database for metadata
        self.init_database()

    def init_database(self):
        """Initialize SQLite database for metadata storage"""
        self.db_path = self.config.get("db_path", "mainframe_analyzer.db")
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()

        cursor.execute('''
            CREATE TABLE IF NOT EXISTS documents (
                id TEXT PRIMARY KEY,
                filename TEXT,
                file_type TEXT,
                business_domain TEXT,
                upload_date TIMESTAMP,
                chunk_count INTEGER,
                metadata TEXT
            )
        ''')

        cursor.execute('''
            CREATE TABLE IF NOT EXISTS processing_status (
                id TEXT PRIMARY KEY,
                status TEXT,
                progress REAL,
                error_message TEXT,
                created_at TIMESTAMP,
                updated_at TIMESTAMP
            )
        ''')

        conn.commit()
        conn.close()

    def start_background_processing(self):
        """Start background processing thread"""
        if self.processing_thread is None or not self.processing_thread.is_alive():
            self.processing_thread = threading.Thread(target=self._process_queue)
            self.processing_thread.daemon = True
            self.processing_thread.start()

    def _process_queue(self):
        """Background processing loop"""
        while True:
            try:
                if not self.processing_queue.empty():
                    task = self.processing_queue.get()
                    self._process_document_task(task)
                    self.processing_queue.task_done()
                else:
                    time.sleep(1)
            except Exception as e:
                logger.error(f"Error in processing queue: {e}")

    def _process_document_task(self, task: Dict[str, Any]):
        """Process a single document task"""
        try:
            file_path = task["file_path"]
            task_id = task["task_id"]
            file_type = task.get("file_type", "text")

            self._update_processing_status(task_id, "processing", 0.1)

            # Extract text based on file type
            if file_type == "pdf":
                content = self.document_processor.process_pdf(file_path)
            elif file_type == "docx":
                content = self.document_processor.process_docx(file_path)
            elif file_type == "markdown":
                content = self.document_processor.process_markdown(file_path)
            else:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()

            self._update_processing_status(task_id, "processing", 0.3)

            # Extract metadata (for COBOL files)
            filename = os.path.basename(file_path)
            if any(ext in filename.lower() for ext in ['.cob', '.cobol', '.cbl']):
                cobol_metadata = self.document_processor.extract_cobol_metadata(content, filename)
                metadata = asdict(cobol_metadata)
            else:
                metadata = {"file_type": file_type}

            self._update_processing_status(task_id, "processing", 0.5)

            # Classify business domain
            business_domain = self.document_processor.classify_business_domain(content, filename)

            # Chunk content
            chunks_text = self.document_processor.chunk_document(content)

            self._update_processing_status(task_id, "processing", 0.7)

            # Create document chunks
            chunks = []
            for i, chunk_text in enumerate(chunks_text):
                chunk_id = hashlib.md5(f"{filename}_{i}".encode()).hexdigest()
                chunk = DocumentChunk(
                    chunk_id=chunk_id,
                    content=chunk_text,
                    source_file=filename,
                    file_type=file_type,
                    business_domain=business_domain,
                    metadata={**metadata, "chunk_index": i, "total_chunks": len(chunks_text)},
                    chunk_index=i,
                    total_chunks=len(chunks_text)
                )
                chunks.append(chunk)

            # Add to vector store
            self.vector_store.add_documents(chunks)

            # Save to database
            self._save_document_metadata(filename, file_type, business_domain, len(chunks), metadata)

            self._update_processing_status(task_id, "completed", 1.0)

            logger.info(f"Successfully processed {filename} - {len(chunks)} chunks")

        except Exception as e:
            logger.error(f"Error processing document {task.get('file_path', 'unknown')}: {e}")
            self._update_processing_status(task_id, "error", 0.0, str(e))

    def _update_processing_status(self, task_id: str, status: str, progress: float, error_message: str = None):
        """Update processing status in database"""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()

        cursor.execute('''
            INSERT OR REPLACE INTO processing_status 
            (id, status, progress, error_message, created_at, updated_at)
            VALUES (?, ?, ?, ?, datetime('now'), datetime('now'))
        ''', (task_id, status, progress, error_message))

        conn.commit()
        conn.close()

    def _save_document_metadata(self, filename: str, file_type: str, business_domain: str, chunk_count: int, metadata: Dict):
        """Save document metadata to database"""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()

        doc_id = hashlib.md5(filename.encode()).hexdigest()
        cursor.execute('''
            INSERT OR REPLACE INTO documents 
            (id, filename, file_type, business_domain, upload_date, chunk_count, metadata)
            VALUES (?, ?, ?, ?, datetime('now'), ?, ?)
        ''', (doc_id, filename, file_type, business_domain, chunk_count, json.dumps(metadata)))

        conn.commit()
        conn.close()

    def add_document(self, file_path: str, file_type: str = None) -> str:
        """Add document to processing queue"""
        if file_type is None:
            file_type = self._detect_file_type(file_path)

        task_id = hashlib.md5(f"{file_path}_{time.time()}".encode()).hexdigest()

        task = {
            "task_id": task_id,
            "file_path": file_path,
            "file_type": file_type
        }

        self.processing_queue.put(task)
        self._update_processing_status(task_id, "queued", 0.0)

        # Start processing if not already running
        self.start_background_processing()

        return task_id

    def _detect_file_type(self, file_path: str) -> str:
        """Detect file type from extension"""
        ext = Path(file_path).suffix.lower()
        type_mapping = {
            '.pdf': 'pdf',
            '.docx': 'docx',
            '.doc': 'docx',
            '.md': 'markdown',
            '.markdown': 'markdown',
            '.cob': 'cobol',
            '.cobol': 'cobol',
            '.cbl': 'cobol',
            '.jcl': 'jcl',
            '.sql': 'sql'
        }
        return type_mapping.get(ext, 'text')

    def get_processing_status(self, task_id: str) -> Dict[str, Any]:
        """Get processing status for a task"""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()

        cursor.execute('SELECT * FROM processing_status WHERE id = ?', (task_id,))
        result = cursor.fetchone()
        conn.close()

        if result:
            return {
                "task_id": result[0],
                "status": result[1],
                "progress": result[2],
                "error_message": result[3],
                "created_at": result[4],
                "updated_at": result[5]
            }
        return None

    def get_documents_summary(self) -> Dict[str, Any]:
        """Get summary of processed documents"""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()

        # Get document counts by type
        cursor.execute('''
            SELECT file_type, business_domain, COUNT(*), SUM(chunk_count)
            FROM documents 
            GROUP BY file_type, business_domain
        ''')

        results = cursor.fetchall()
        conn.close()

        summary = {
            "total_documents": 0,
            "total_chunks": 0,
            "by_type": {},
            "by_domain": {}
        }

        for file_type, business_domain, doc_count, chunk_count in results:
            summary["total_documents"] += doc_count
            summary["total_chunks"] += chunk_count or 0

            if file_type not in summary["by_type"]:
                summary["by_type"][file_type] = {"documents": 0, "chunks": 0}
            summary["by_type"][file_type]["documents"] += doc_count
            summary["by_type"][file_type]["chunks"] += chunk_count or 0

            if business_domain not in summary["by_domain"]:
                summary["by_domain"][business_domain] = {"documents": 0, "chunks": 0}
            summary["by_domain"][business_domain]["documents"] += doc_count
            summary["by_domain"][business_domain]["chunks"] += chunk_count or 0

        return summary

    async def query(self, question: str) -> Dict[str, Any]:
        """Process user query"""
        return await self.rag_system.process_query(question)

    def generate_documentation(self, topic: str, max_chunks: int = 50) -> str:
        """Generate comprehensive documentation for a topic"""
        # Search for relevant chunks
        search_results = self.vector_store.search(query=topic, top_k=max_chunks)
        chunks = [chunk for chunk, score in search_results]

        if not chunks:
            return f"No documentation found for topic: {topic}"

        # Group by source file for organized documentation
        chunks_by_source = {}
        for chunk in chunks:
            source = chunk.source_file
            if source not in chunks_by_source:
                chunks_by_source[source] = []
            chunks_by_source[source].append(chunk)

        # Generate documentation in chunks, then combine
        doc_sections = []

        for source, source_chunks in chunks_by_source.items():
            # Generate section for this source
            context = "\n".join([chunk.content for chunk in source_chunks[:10]])  # Limit context

            prompt = f"""
            Generate comprehensive documentation for the topic "{topic}" based on the following code from {source}:

            {context}

            Focus on:
            1. Purpose and functionality
            2. Key components and their roles
            3. Data flow and dependencies
            4. Business logic explanation
            5. Usage patterns and examples

            Format as a clear, well-structured section.
            """

            section = self.rag_system.generate_response(prompt)
            doc_sections.append(f"## {source}\n\n{section}")

        # Combine all sections
        combined_docs = "\n\n".join(doc_sections)

        # Generate final consolidated documentation
        final_prompt = f"""
        Create a comprehensive, well-organized documentation for "{topic}" by consolidating the following sections:

        {combined_docs}

        Structure the final documentation with:
        1. Executive Summary
        2. System Overview
        3. Detailed Components
        4. Data Flow and Dependencies
        5. Implementation Details
        6. Best Practices and Recommendations

        Make it professional and suitable for technical documentation.
        """

        return self.rag_system.generate_response(final_prompt)

    def save_state(self, path: str):
        """Save system state"""
        os.makedirs(path, exist_ok=True)
        self.vector_store.save_index(os.path.join(path, "vector_store"))

        # Copy database
        import shutil
        shutil.copy2(self.db_path, os.path.join(path, "database.db"))

    def load_state(self, path: str):
        """Load system state"""
        vector_store_path = os.path.join(path, "vector_store")
        if os.path.exists(vector_store_path):
            self.vector_store.load_index(vector_store_path)

        # Load database
        db_path = os.path.join(path, "database.db")
        if os.path.exists(db_path):
            import shutil
            shutil.copy2(db_path, self.db_path)


class CachedMainframeAnalyzer(MainframeAnalyzer):
    """Enhanced MainframeAnalyzer with comprehensive caching"""

    def __init__(self, config: Dict[str, Any]):
        # Initialize cache configuration
        cache_config = CacheConfig(
            enable_redis=config.get("enable_redis", False),
            redis_host=config.get("redis_host", "localhost"),
            redis_port=config.get("redis_port", 6379),
            redis_db=config.get("redis_db", 0),
            redis_password=config.get("redis_password"),
            query_cache_size=config.get("query_cache_size", 1000),
            query_cache_ttl=config.get("query_cache_ttl", 3600),
            embedding_cache_size=config.get("embedding_cache_size", 5000),
            embedding_cache_ttl=config.get("embedding_cache_ttl", 7200),
            enable_streaming=config.get("enable_streaming", True),
            stream_chunk_size=config.get("stream_chunk_size", 50),
            stream_delay=config.get("stream_delay", 0.01)
        )

        self.cache_manager = CacheManager(cache_config)

        # Initialize base components
        self.config = config
        self.document_processor = DocumentProcessor()
        self.vector_store = CachedVectorStore(
            embedding_model_name=config.get("embedding_model", "all-MiniLM-L6-v2"),
            use_gpu=config.get("use_gpu", True),
            cache_manager=self.cache_manager
        )
        self.rag_system = StreamingAgenticRAG(
            vector_store=self.vector_store,
            llm_model_path=config["llm_model_path"],
            cache_manager=self.cache_manager
        )

        # Processing queue and database
        self.processing_queue = Queue()
        self.processing_thread = None
        self.is_processing = False
        self.init_database()

    async def query_streaming(self, question: str, session_id: str = None) -> AsyncIterator[Dict[str, Any]]:
        """Process user query with streaming response and caching"""
        async for result in self.rag_system.process_query_streaming(question, session_id):
            yield result

    def get_cache_stats(self) -> Dict[str, Any]:
        """Get comprehensive cache statistics"""
        stats = self.cache_manager.get_cache_stats()

        # Add vector store cache stats
        if hasattr(self.vector_store, 'embedding_cache_hits'):
            stats["vector_store"] = {
                "embedding_cache_hits": self.vector_store.embedding_cache_hits,
                "embedding_cache_misses": self.vector_store.embedding_cache_misses,
                "search_cache_hits": self.vector_store.search_cache_hits,
                "search_cache_misses": self.vector_store.search_cache_misses,
                "embedding_hit_rate": (
                    self.vector_store.embedding_cache_hits / 
                    max(self.vector_store.embedding_cache_hits + self.vector_store.embedding_cache_misses, 1) * 100
                ),
                "search_hit_rate": (
                    self.vector_store.search_cache_hits / 
                    max(self.vector_store.search_cache_hits + self.vector_store.search_cache_misses, 1) * 100
                )
            }

        return stats

    def invalidate_cache(self, pattern: str = None) -> None:
        """Invalidate cache entries"""
        self.cache_manager.invalidate_query_cache(pattern)
        logger.info(f"Cache invalidated for pattern: {pattern}")

    def warm_cache(self, common_queries: List[str]) -> None:
        """Pre-warm cache with common queries"""
        logger.info("Warming cache with common queries...")
        for query in common_queries:
            try:
                # This will cache the embeddings and search results
                asyncio.run(self.query_streaming(query, "cache_warm"))
            except Exception as e:
                logger.warning(f"Failed to warm cache for query '{query}': {e}")
        logger.info("Cache warming completed")


