# Global analyzer instance
analyzer = None

@app.on_event("startup")
async def startup_event():
    """Initialize the analyzer on startup"""
    global analyzer

    config = {
        "llm_model_path": os.getenv("LLM_MODEL_PATH", "/path/to/your/model"),
        "embedding_model": "all-MiniLM-L6-v2",
        "use_gpu": True,
        "db_path": "mainframe_analyzer.db",

        # Cache configuration
        "enable_redis": os.getenv("ENABLE_REDIS", "false").lower() == "true",
        "redis_host": os.getenv("REDIS_HOST", "localhost"),
        "redis_port": int(os.getenv("REDIS_PORT", "6379")),
        "redis_db": int(os.getenv("REDIS_DB", "0")),
        "redis_password": os.getenv("REDIS_PASSWORD"),

        # Cache sizes and TTLs
        "query_cache_size": int(os.getenv("QUERY_CACHE_SIZE", "1000")),
        "query_cache_ttl": int(os.getenv("QUERY_CACHE_TTL", "3600")),
        "embedding_cache_size": int(os.getenv("EMBEDDING_CACHE_SIZE", "5000")),
        "embedding_cache_ttl": int(os.getenv("EMBEDDING_CACHE_TTL", "7200")),

        # Streaming configuration
        "enable_streaming": os.getenv("ENABLE_STREAMING", "true").lower() == "true",
        "stream_chunk_size": int(os.getenv("STREAM_CHUNK_SIZE", "50")),
        "stream_delay": float(os.getenv("STREAM_DELAY", "0.01"))
    }

    analyzer = CachedMainframeAnalyzer(config)

    # Warm cache with common queries if specified
    common_queries = os.getenv("COMMON_QUERIES", "").split(";")
    if common_queries and common_queries[0]:
        analyzer.warm_cache(common_queries)

    logger.info("Cached Mainframe Analyzer initialized")

