        <script>
            let processingTasks = new Set();
            let currentFiles = [];

            // Initialize the application
            document.addEventListener('DOMContentLoaded', function() {
                setupEventListeners();
                updateStats();
                checkModelStatus();
            });

            function setupEventListeners() {
                const uploadArea = document.getElementById('uploadArea');
                const fileInput = document.getElementById('fileInput');

                // Drag and drop handlers
                uploadArea.addEventListener('dragover', handleDragOver);
                uploadArea.addEventListener('dragleave', handleDragLeave);
                uploadArea.addEventListener('drop', handleDrop);
                uploadArea.addEventListener('click', () => fileInput.click());

                // File input handler
                fileInput.addEventListener('change', handleFileSelect);
            }

            function handleDragOver(e) {
                e.preventDefault();
                e.currentTarget.classList.add('dragover');
            }

            function handleDragLeave(e) {
                e.preventDefault();
                e.currentTarget.classList.remove('dragover');
            }

            function handleDrop(e) {
                e.preventDefault();
                e.currentTarget.classList.remove('dragover');
                const files = Array.from(e.dataTransfer.files);
                uploadFiles(files);
            }

            function handleFileSelect(e) {
                const files = Array.from(e.target.files);
                uploadFiles(files);
            }

            async function uploadFiles(files) {
                for (const file of files) {
                    await uploadSingleFile(file);
                }
            }

            async function uploadSingleFile(file) {
                const formData = new FormData();
                formData.append('file', file);

                try {
                    showMessage('system', `Uploading ${file.name}...`);

                    const response = await fetch('/upload', {
                        method: 'POST',
                        body: formData
                    });

                    if (response.ok) {
                        const result = await response.json();
                        processingTasks.add(result.task_id);

                        showMessage('system', `${file.name} uploaded successfully. Processing...`);
                        monitorProcessing(result.task_id, file.name);

                        currentFiles.push({
                            name: file.name,
                            type: result.file_type,
                            status: 'processing'
                        });

                        updateFileList();
                    } else {
                        const error = await response.json();
                        showMessage('system', `Error uploading ${file.name}: ${error.detail}`);
                    }
                } catch (error) {
                    showMessage('system', `Error uploading ${file.name}: ${error.message}`);
                }
            }

            async function monitorProcessing(taskId, filename) {
                const maxAttempts = 60; // 5 minutes max
                let attempts = 0;

                const checkInterval = setInterval(async () => {
                    try {
                        const response = await fetch(`/status/${taskId}`);
                        if (response.ok) {
                            const status = await response.json();

                            updateProgressBar(status.progress * 100);

                            if (status.status === 'completed') {
                                clearInterval(checkInterval);
                                processingTasks.delete(taskId);
                                showMessage('system', `✅ ${filename} processed successfully!`);
                                updateProgressBar(0);
                                updateStats();

                                // Update file status
                                const fileIndex = currentFiles.findIndex(f => f.name === filename);
                                if (fileIndex !== -1) {
                                    currentFiles[fileIndex].status = 'completed';
                                    updateFileList();
                                }
                            } else if (status.status === 'error') {
                                clearInterval(checkInterval);
                                processingTasks.delete(taskId);
                                showMessage('system', `❌ Error processing ${filename}: ${status.error_message}`);
                                updateProgressBar(0);
                            }
                        }

                        attempts++;
                        if (attempts >= maxAttempts) {
                            clearInterval(checkInterval);
                            processingTasks.delete(taskId);
                            showMessage('system', `⏰ Processing timeout for ${filename}`);
                            updateProgressBar(0);
                        }
                    } catch (error) {
                        console.error('Error checking status:', error);
                    }
                }, 5000); // Check every 5 seconds
            }

            function updateProgressBar(progress) {
                const progressFill = document.getElementById('progressFill');
                const statusPanel = document.getElementById('processingStatus');

                if (progress > 0 && progress < 100) {
                    statusPanel.style.display = 'block';
                    progressFill.style.width = `${progress}%`;
                } else {
                    statusPanel.style.display = 'none';
                }
            }

            async function updateStats() {
                try {
                    const response = await fetch('/stats');
                    if (response.ok) {
                        const stats = await response.json();
                        document.getElementById('totalDocs').textContent = stats.total_documents;
                        document.getElementById('totalChunks').textContent = stats.total_chunks;
                    }
                } catch (error) {
                    console.error('Error updating stats:', error);
                }
            }

            function updateFileList() {
                const fileList = document.getElementById('fileList');

                if (currentFiles.length === 0) {
                    fileList.innerHTML = `
                        <div style="text-align: center; color: #7f8c8d; padding: 20px;">
                            No files uploaded yet
                        </div>
                    `;
                    return;
                }

                fileList.innerHTML = currentFiles.map(file => `
                    <div class="file-item">
                        <div>
                            <div class="file-name">${file.name}</div>
                            <div style="font-size: 0.8em; color: #6c757d;">
                                Status: ${file.status}
                            </div>
                        </div>
                        <div class="file-type">${file.type}</div>
                    </div>
                `).join('');
            }

            function handleKeyPress(event) {
                if (event.key === 'Enter') {
                    sendMessage();
                }
            }

            async function sendMessage() {
                const input = document.getElementById('chatInput');
                const message = input.value.trim();

                if (!message) return;

                // Generate session ID if not exists
                if (!window.sessionId) {
                    window.sessionId = 'session_' + Math.random().toString(36).substr(2, 9);
                }

                // Clear input and disable send button
                input.value = '';
                const sendButton = document.getElementById('sendButton');
                sendButton.disabled = true;

                // Show user message
                showMessage('user', message);

                // Show loading indicator
                const loadingIndicator = document.getElementById('loadingIndicator');
                loadingIndicator.classList.add('show');

                try {
                    // Check if streaming is supported using fetch
                    await handleStreamingResponse(message);

                } catch (error) {
                    showMessage('assistant', `Sorry, I couldn't process your request: ${error.message}`);
                } finally {
                    // Hide loading indicator and re-enable send button
                    loadingIndicator.classList.remove('show');
                    sendButton.disabled = false;
                }
            }

            async function handleStreamingResponse(message) {
                try {
                    const response = await fetch('/query', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json'
                        },
                        body: JSON.stringify({ 
                            question: message,
                            session_id: window.sessionId,
                            stream: false
                        })
                    });

                    if (response.ok) {
                        const result = await response.json();
                        showMessage('assistant', result.answer);

                        if (result.context_chunks && result.context_chunks.length > 0) {
                            const contextInfo = `
                                <div style="margin-top: 15px; padding: 10px; background: #f8f9fa; border-radius: 8px; font-size: 0.9em;">
                                    <strong>📋 Context:</strong> Retrieved ${result.chunks_retrieved} chunks 
                                    from ${new Set(result.context_chunks.map(c => c.source)).size} files
                                    in ${result.processing_time.toFixed(2)}s
                                    ${result.cached ? ' (cached ⚡)' : ''}
                                </div>
                            `;

                            const lastMessage = document.querySelector('.message.assistant:last-child');
                            lastMessage.innerHTML += contextInfo;
                        }
                    } else {
                        const error = await response.json();
                        showMessage('assistant', `Sorry, I encountered an error: ${error.detail}`);
                    }
                }
            }

            function showMessage(type, content) {
                const messagesContainer = document.getElementById('chatMessages');
                const messageDiv = createMessage(type, content);
                messagesContainer.appendChild(messageDiv);
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
            }

            function createMessage(type, content) {
                const messageDiv = document.createElement('div');
                messageDiv.className = `message ${type}`;
                messageDiv.innerHTML = content;
                return messageDiv;
            }

            async function checkModelStatus() {
                try {
                    const response = await fetch('/health');
                    if (!response.ok) {
                        showMessage('system', '⚠️ Model not loaded. Please check server configuration.');
                    }
                } catch (error) {
                    showMessage('system', '⚠️ Unable to connect to analyzer service.');
                }
            }
        </script>
    </body>
    </html>
    """

@app.post("/upload")
async def upload_file(file: UploadFile = File(...)):
    """Upload and process a document"""
    if not analyzer:
        raise HTTPException(status_code=503, detail="Analyzer not initialized")

    # Save uploaded file temporarily
    temp_dir = "temp_uploads"
    os.makedirs(temp_dir, exist_ok=True)

    file_path = os.path.join(temp_dir, file.filename)
    with open(file_path, "wb") as buffer:
        content = await file.read()
        buffer.write(content)

    # Add to processing queue
    task_id = analyzer.add_document(file_path)

    return {
        "message": "File uploaded successfully",
        "filename": file.filename,
        "task_id": task_id,
        "file_type": analyzer._detect_file_type(file_path)
    }

@app.get("/status/{task_id}")
async def get_processing_status(task_id: str):
    """Get processing status for a task"""
    if not analyzer:
        raise HTTPException(status_code=503, detail="Analyzer not initialized")

    status = analyzer.get_processing_status(task_id)
    if not status:
        raise HTTPException(status_code=404, detail="Task not found")

    return status

@app.get("/stats")
async def get_system_stats():
    """Get system statistics"""
    if not analyzer:
        raise HTTPException(status_code=503, detail="Analyzer not initialized")

    stats = analyzer.get_documents_summary()

    # Add cache stats if available
    if hasattr(analyzer, 'get_cache_stats'):
        cache_stats = analyzer.get_cache_stats()
        stats["cache"] = cache_stats

    return stats

@app.post("/query")
async def query_documents(request: dict):
    """Query the document corpus"""
    if not analyzer:
        raise HTTPException(status_code=503, detail="Analyzer not initialized")

    question = request.get("question", "")
    session_id = request.get("session_id", "default")
    stream = request.get("stream", False)

    if not question:
        raise HTTPException(status_code=400, detail="Question is required")

    if stream and hasattr(analyzer, 'query_streaming'):
        # Return streaming response
        async def generate():
            async for chunk in analyzer.query_streaming(question, session_id):
                yield f"data: {json.dumps(chunk)}\n\n"
            yield f"data: [DONE]\n\n"

        return StreamingResponse(generate(), media_type="text/plain")
    else:
        # Return regular response
        result = await analyzer.query(question)
        return result

@app.post("/generate-docs")
async def generate_documentation(request: dict):
    """Generate documentation for a topic"""
    if not analyzer:
        raise HTTPException(status_code=503, detail="Analyzer not initialized")

    topic = request.get("topic", "")
    max_chunks = request.get("max_chunks", 50)

    if not topic:
        raise HTTPException(status_code=400, detail="Topic is required")

    documentation = analyzer.generate_documentation(topic, max_chunks)
    return {"documentation": documentation, "topic": topic}

@app.post("/cache/invalidate")
async def invalidate_cache(request: dict = None):
    """Invalidate cache entries"""
    if not analyzer or not hasattr(analyzer, 'invalidate_cache'):
        raise HTTPException(status_code=503, detail="Cache not available")

    pattern = None
    if request:
        pattern = request.get("pattern")

    analyzer.invalidate_cache(pattern)
    return {"message": f"Cache invalidated for pattern: {pattern}"}

@app.get("/health")
async def health_check():
    """Health check endpoint"""
    if not analyzer:
        raise HTTPException(status_code=503, detail="Analyzer not initialized")

    return {
        "status": "healthy",
        "analyzer_type": type(analyzer).__name__,
        "has_cache": hasattr(analyzer, 'cache_manager'),
        "timestamp": datetime.now().isoformat()
    }

@app.get("/api/docs")
async def get_api_docs():
    """Get API documentation"""
    return {
        "endpoints": {
            "POST /upload": "Upload a document for processing",
            "GET /status/{task_id}": "Get processing status",
            "GET /stats": "Get system statistics",
            "POST /query": "Query the document corpus",
