API_KEY = 'PERSPECTIVE_API_KEY'


def trim_text(text):
    """
    Trim text if its size is exceeding Perspective API limit of 20 KB
    """
    LEN = 20480
    byte_text = text.encode("utf-8")

    if len(byte_text) > LEN:
        text = byte_text[:LEN]
        # try to decode the string, it is unsucessful we split the bytes of a multi-byte character
        while True:
            try:
                text = text.decode()
                break
            except:
                LEN-=1
                text = byte_text[:LEN]

    return text

def perspective_api_call(text, language=None):

        text = trim_text(text)

        try:
            client = discovery.build(
                "commentanalyzer",
                "v1alpha1",
                developerKey=API_KEY,
                discoveryServiceUrl="https://commentanalyzer.googleapis.com/$discovery/rest?version=v1alpha1",
                static_discovery=False,
            )

            analyze_request = {
                'comment': { 'text': text},
                'requestedAttributes': {
                                        'TOXICITY': {},
                                        'SEVERE_TOXICITY': {},
                                        'IDENTITY_ATTACK': {},
                                        'INSULT': {},
                                        'PROFANITY': {},
                                        'THREAT': {}
                                        },
                # 'languages': [language],
            }

            if language is not None:
                analyze_request['languages'] = [language]

            response = client.comments().analyze(body=analyze_request).execute()
            return response
        except Exception as e:
            print(f'Error {e}')
            return {}



class BaseModel(object):
    def get_model(self, model_name):
        pass

