import json, jsonlines
import math
import argparse
import logging
from tqdm import tqdm
from openai import OpenAI
import torch
from transformers import AutoProcessor, AutoTokenizer
from vllm import LLM, SamplingParams
from qwen_vl_utils import process_vision_info


logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


def read_json_field(filename):
    try:
        with open(filename, 'r') as file:
            data = json.load(file)
        return data
    except FileNotFoundError:
        logging.error("The file was not found.")
    except json.JSONDecodeError:
        logging.error("There was an error decoding the JSON file.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")


def write_data_to_json_file(data, file_path):
    try:
        with open(file_path, 'w') as file:
            json.dump(data, file, ensure_ascii=False, indent=4)
        logging.info(f"Data successfully written to {file_path}")
    except Exception as e:
        logging.error(f"An error occurred: {e}")

def load_tokenizer_and_vllm(config, eos_token=None):

    model_path = config["models"]["teacher"]
    logging.info(f"Loading processor & vLLM model from {model_path}")

    # 1. Use AutoProcessor, which integrates the tokenizer, image_processor, and video_processor
    processor = AutoProcessor.from_pretrained(model_path, trust_remote_code=True)

    # 2. eos / pad token 处理（与官方示例保持一致，不再显式改 pad_token）
    if eos_token:
        eos_token_id = processor.tokenizer.convert_tokens_to_ids(eos_token)
        logging.info(f"eos_token {eos_token} from user input")
    elif hasattr(processor.tokenizer, "eos_token_id") and processor.tokenizer.eos_token_id is not None:
        eos_token_id = processor.tokenizer.eos_token_id
        eos_token = processor.tokenizer.convert_ids_to_tokens(eos_token_id)
        logging.info(f"Initial eos_token_id {eos_token_id} from tokenizer")
    else:
        raise ValueError("No available eos_token or eos_token_id.")

    # 3. 设置 tokenizer 的 eos 相关字段（pad_token 保持 None，由 vLLM 自动处理）
    try:
        processor.tokenizer.eos_token = eos_token
        processor.tokenizer.eos_token_id = eos_token_id
    except Exception as e:
        logging.warning(f"[WARNING] Cannot set eos_token: {e}")

    logging.info(
        f"processor.tokenizer eos_token: {processor.tokenizer.eos_token}, "
        f"eos_token_id: {processor.tokenizer.eos_token_id}"
    )

    num_gpus = torch.cuda.device_count()
    llm = LLM(
        model=model_path,
        tensor_parallel_size=num_gpus,
        trust_remote_code=True,
        limit_mm_per_prompt={"image": 10, "video": 10},   # 可按需调整
        # 其余超参沿用原 config
        gpu_memory_utilization=config["inference"].get("gpu_memory_utilization", 0.9),
        max_model_len=config["inference"].get("max_model_len", 4096),
        enforce_eager=config["inference"].get("enforce_eager", False),
    )

    logging.info("Qwen2.5-VL vLLM model loaded successfully")
    #return processor, llm

    return processor, llm

def generate_teacher_response_batch(processor, llm, data_list, config, batch_size=32):

    outcomes = []
    sampling_params = SamplingParams(
        n = 1,
        top_k = 1,
        temperature=config["inference"]["temperature"],
        seed = config["inference"]["seed"],
        max_tokens = config["inference"]["max_new_tokens"],
    )
    batches = [data_list[i:i + batch_size] for i in range(0, len(data_list), batch_size)]
    for batch in tqdm(batches, desc="Generating responses"):
        new_batch = []
        batch_outcomes = []
        for sample in batch:
            batch_outcomes.append(sample)
            prompt = processor.apply_chat_template(
                sample,
                tokenize=False,
                add_generation_prompt=True,
            )
            image_inputs, video_inputs = process_vision_info(sample)

            mm_data = {}
            if image_inputs is not None:
                mm_data["image"] = image_inputs

            sample_inputs = {
                "prompt": prompt,
                "multi_modal_data": mm_data,
            }
            new_batch.append(sample_inputs)
        outputs = llm.generate(new_batch, sampling_params=sampling_params)
        for b in range(len(batch_outcomes)):

            generated_text = outputs[b].outputs[0].text
            out={
                "role": "assistant",
                "content": [
                    {
                        "type": "text",
                        "text": generated_text,
                    }
                ],
            }
            batch_outcomes[b].append(out)
        outcomes.extend(batch_outcomes)
    write_data_to_json_file(outcomes, config["dataset"]["labeled_path"])

def generate_teacher_logits_batch(processor, llm, data_list, config, batch_size=32):

    outcomes = []
    sampling_params = SamplingParams(
        n = 1,
        top_k = 1,
        temperature=config["inference"]["temperature"],
        seed = config["inference"]["seed"],
        skip_special_tokens=False,
        max_tokens = config["inference"]["max_new_tokens"],
        logprobs=config["inference"]["top_logits_num"],
    )
    batches = [data_list[i:i + batch_size] for i in range(0, len(data_list), batch_size)]
    logits=[]
    for batch in tqdm(batches, desc="Generating responses"):
        new_batch = []
        batch_outcomes = []
        for sample in batch:
            batch_outcomes.append(sample)
            prompt = processor.apply_chat_template(
                sample,
                tokenize=False,
                add_generation_prompt=True,
            )
            image_inputs, video_inputs = process_vision_info(sample)

            mm_data = {}
            if image_inputs is not None:
                mm_data["image"] = image_inputs

            sample_inputs = {
                "prompt": prompt,
                "multi_modal_data": mm_data,
            }
            new_batch.append(sample_inputs)
        outputs = llm.generate(new_batch, sampling_params=sampling_params)
        logits+=[output.outputs[0].logprobs for output in outputs]

        for b in range(len(batch_outcomes)):

            generated_text = outputs[b].outputs[0].text
            out={
                "role": "assistant",
                "content": [
                    {
                        "type": "text",
                        "text": generated_text,
                    }
                ],
            }
            batch_outcomes[b].append(out)
        outcomes.extend(batch_outcomes)

    for logit in logits:
        for pos in logit:
            for k,v in pos.items():
                pos[k]=math.exp(v.logprob)

    with jsonlines.open(config["dataset"]["logits_path"], mode='w') as writer:
        for row in logits:
            #for item in row:
            writer.write(row)

    write_data_to_json_file(outcomes, config["dataset"]["labeled_path"])




def generate_teacher_response_api(data_list, config):
    client = OpenAI(
        api_key = config["inference"]["api_key"],
        base_url = config["inference"]["base_url"]
    )
    models = client.models.list()
    model = models.data[0].id
    logging.info(model)
    system_prompt = config["inference"]["system_prompt"]
    if system_prompt == "":
        system_prompt = "You are a helpful assistant."
    outcomes = []
    for text, image in tqdm(data_list, desc="Call remote model and generating responses"):
        messages = [
            {
                "role": "system",
                "content": system_prompt
            },
            {
                "role": "user",
                "content": [
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": image
                        },
                    },
                    {
                        "type": "text",
                        "text": text
                    }
                ]
            }
        ]
        completion = client.chat.completions.create(
            messages = messages,
            model = model,
            max_completion_tokens = config["inference"]["max_new_tokens"]
        )
        result = completion.choices[0].message.content
        outcomes.append({'instruction': text, 'image': image, 'output': result})
    write_data_to_json_file(outcomes, config["dataset"]["labeled_path"])


def infer_with_teacher_model(config):
    logging.info('Generating distillation data from the teacher model!')
    data_list = read_json_field(config["dataset"]["instruction_path"])

    try:
        job_type =  config["job_type"]
        if job_type == "mmkd_black_box_api":
            generate_teacher_response_api(data_list, config)
        elif job_type == "mmkd_black_box_local":
            tokenizer, llm = load_tokenizer_and_vllm(config)
            generate_teacher_response_batch(tokenizer, llm, data_list, config)
        elif job_type == "mmkd_white_box":

            tokenizer, llm = load_tokenizer_and_vllm(config)
            generate_teacher_logits_batch(tokenizer, llm, data_list, config)
        else:
            logging.error(f"Invalid job type: {job_type}")
            raise ValueError(f"Invalid job type: {job_type}")
    except ValueError as e:
        logging.error(f"Training job terminated: {e}")
        return


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--config', type=str, required=True, help='path to the json config file')
    args = parser.parse_args()
    config = json.load(open(args.config))
    infer_with_teacher_model(config)


if __name__ == "__main__":
    main()

import json
import time
from vllm import LLM, SamplingParams

# Initialize vLLM
model_name = "meta-llama/Meta-Llama-3.1-8B-Instruct"  # or your local model path
#quantization="bitsandbytes",load_format="bitsandbytes"
llm = LLM(model=model_name)
sampling_params = SamplingParams(temperature=1.0, max_tokens=800)

def make_api_call(messages, max_tokens, is_final_answer=False, custom_llm=None):
    global llm
    if custom_llm is not None:
        llm = custom_llm

    # Prepare the prompt
    prompt = "\n".join([f"{m['role'].capitalize()}: {m['content']}" for m in messages])

    for attempt in range(3):
        try:
            outputs = llm.generate([prompt], sampling_params)
            response_text = outputs[0].outputs[0].text.strip()
            if is_final_answer:
                return response_text
            else:
                try:
                    return json.loads(response_text)
                except json.JSONDecodeError:
                    # Fallback: try to extract JSON substring if possible
                    start = response_text.find('{')
                    end = response_text.rfind('}') + 1
                    if start != -1 and end != -1:
                        json_str = response_text[start:end]
                        return json.loads(json_str)
                    else:
                        return {"title": "Error", "content": "Response not in JSON format.", "next_action": "final_answer"}
        except Exception as e:
            if attempt == 2:
                if is_final_answer:
                    return {"title": "Error", "content": f"Failed to generate final answer after 3 attempts. Error: {str(e)}"}
                else:
                    return {"title": "Error", "content": f"Failed to generate step after 3 attempts. Error: {str(e)}", "next_action": "final_answer"}
            time.sleep(1)

def generate_response(prompt, custom_llm=None):
    messages = [
        {"role": "system", "content": """You are an expert AI assistant that explains your reasoning step by step. For each step, provide a title that describes what you're doing in that step, along with the content. Decide if you need another step or if you're ready to give the final answer. Respond in JSON format with 'title', 'content', and 'next_action' (either 'continue' or 'final_answer') keys. USE AS MANY REASONING STEPS AS POSSIBLE. AT LEAST 3. BE AWARE OF YOUR LIMITATIONS AS AN LLM AND WHAT YOU CAN AND CANNOT DO. IN YOUR REASONING, INCLUDE EXPLORATION OF ALTERNATIVE ANSWERS. CONSIDER YOU MAY BE WRONG, AND IF YOU ARE WRONG IN YOUR REASONING, WHERE IT WOULD BE. FULLY TEST ALL OTHER POSSIBILITIES. YOU CAN BE WRONG. WHEN YOU SAY YOU ARE RE-EXAMINING, ACTUALLY RE-EXAMINE, AND USE ANOTHER APPROACH TO DO SO. DO NOT JUST SAY YOU ARE RE-EXAMINING. USE AT LEAST 3 METHODS TO DERIVE THE ANSWER. USE BEST PRACTICES.

Example of a valid JSON response:
{
"title": "Identifying Key Information",
"content": "To begin solving this problem, we need to carefully examine the given information and identify the crucial elements that will guide our solution process. This involves...",
"next_action": "continue"
}```
"""},
{"role": "user", "content": prompt},
{"role": "assistant", "content": "Thank you! I will now think step by step following my instructions, starting at the beginning after decomposing the problem."}
]


    steps = []
    step_count = 1
    total_thinking_time = 0

    while True:
        start_time = time.time()
        step_data = make_api_call(messages, 300, False, custom_llm)
        end_time = time.time()
        thinking_time = end_time - start_time
        total_thinking_time += thinking_time

        steps.append((f"Step {step_count}: {step_data.get('title', 'Unknown')}", step_data.get('content', ''), thinking_time))

        messages.append({"role": "assistant", "content": json.dumps(step_data)})

        if step_data.get('next_action', 'final_answer') == 'final_answer' or step_count > 25:
            break

        step_count += 1

        yield steps, None

    # Generate final answer
    messages.append({"role": "user", "content": "Please provide the final answer based solely on your reasoning above. Do not use JSON formatting. Only provide the text response without any titles or preambles. Retain any formatting as instructed by the original prompt, such as exact formatting for free response or multiple choice."})

    start_time = time.time()
    final_data = make_api_call(messages, 800, True, custom_llm)
    end_time = time.time()
    thinking_time = end_time - start_time
    total_thinking_time += thinking_time

    steps.append(("Final Answer", final_data, thinking_time))

    yield steps, total_thinking_time

import abc
import prompts


class Model(abc.ABC):
    def get_repo(self, target_lang):
        ...

    def create(self, model_path, params):
        ...

    def translate_batch(self, texts, from_lang, to_lang, params):
        ...


class GenericModel(Model):
    """
    Lower level than pipe to properly run batching
    See https://github.com/meta-llama/llama3/issues/114#issuecomment-2127131096
    """

    def __init__(self):
        self.padding_side = "left"
        self.dtype = "bfloat16"

    def create(self, model_path, params):
        from transformers import AutoModelForCausalLM, AutoTokenizer

        # use bfloat16 for supported models and GPUS
        self.model = AutoModelForCausalLM.from_pretrained(
            model_path, torch_dtype=self.dtype, device_map="auto"
        )
        # gemma returns empty strings with default padding side (left)
        self.tokenizer = AutoTokenizer.from_pretrained(model_path, padding_side=self.padding_side)

    def get_chat_prompt(self, text, from_lang, to_lang, prompt_type):
        system_prompt, user_prompt = prompts.prompts[prompt_type](
            text=text, from_lang_code=from_lang, to_lang_code=to_lang
        )
        return [
            {
                "role": "system",
                "content": system_prompt,
            },
            {"role": "user", "content": user_prompt},
        ]

    def get_prompt(self, text, from_lang, to_lang, prompt_type):
        chat_style_prompt = self.get_chat_prompt(text, from_lang, to_lang, prompt_type)
        chat_prompt = self.tokenizer.apply_chat_template(
            chat_style_prompt, tokenize=False, add_generation_prompt=True
        )
        return chat_prompt

    def translate_batch(self, texts, from_lang, to_lang, params):
        import toolz

        prompt_type = params["prompt"]
        prompts = [self.get_prompt(text, from_lang, to_lang, prompt_type) for text in texts]

        max_input_tokens = max(len(tokens) for tokens in self.tokenizer(texts).input_ids)
        max_tok_alpha = params["max_tok_alpha"]
        max_new_tokens = int(max_tok_alpha * max_input_tokens)

        outputs = self.parse_outputs(self.run(max_new_tokens, params, prompts))

        num_candidates = params["decoding"].get("num_return_sequences") or params["decoding"].get(
            "n", 1
        )
        assert len(outputs) == num_candidates * len(texts)
        batch_results = (
            list(toolz.partition_all(num_candidates, outputs)) if num_candidates > 1 else outputs
        )
        return batch_results

    def run(self, max_new_tokens, params, prompts):
        import torch

        inputs = self.tokenizer(
            # pad to the longest sequence in a batch, never truncate (default)
            # padding negatively affects quality, ideally the input should be sorted by length and split to batches to make lines of similar size
            prompts,
            return_tensors="pt",
            padding="longest",
            truncation=False,
        ).to(self.model.device)
        # Translation
        with torch.inference_mode():
            generated_ids = self.model.generate(
                **inputs, max_new_tokens=max_new_tokens, **params["decoding"]
            )
            outputs = self.tokenizer.batch_decode(generated_ids, skip_special_tokens=True)

        return outputs

    def parse_outputs(self, outputs):
        # it returns ...\n{output}
        processed_outputs = []
        for output in outputs:
            parts = output.strip().split("\n")
            processed_outputs.append(parts[-1].strip())
        return processed_outputs


class Qwen3(GenericModel):
    def __init__(self, size, active, fp8, instruct):
        super().__init__()
        self.size = size
        self.fp8 = fp8
        self.active = active
        self.instruct = instruct

    def get_prompt(self, text, from_lang, to_lang, prompt_type):
        chat_style_prompt = self.get_chat_prompt(text, from_lang, to_lang, prompt_type)
        # add enable_thinking=False
        chat_prompt = self.tokenizer.apply_chat_template(
            chat_style_prompt, tokenize=False, add_generation_prompt=True, enable_thinking=False
        )
        return chat_prompt

    def get_repo(self, target_lang):
        suffix = ""
        # add support for MoE models
        if self.active:
            suffix += f"-A{self.active}B"
        # add support for Instruct models
        if self.instruct:
            suffix += "-Instruct-2507"
        # add support for float8 quantization
        if self.fp8:
            suffix += "-FP8"
        return f"Qwen/Qwen3-{self.size}B{suffix}"


class GptOss(GenericModel):
    def __init__(self, size):
        super().__init__()
        self.size = size

    def get_repo(self, target_lang):
        return f"openai/gpt-oss-{self.size}b"


class Gemma3(GenericModel):
    def __init__(self, size):
        super().__init__()
        self.size = size
        # It's the only option that works with batch_size > 1 but the results are lower quality, so there must be a bug
        self.padding_side = "right"

    def get_repo(self, target_lang):
        return f"google/gemma-3-{self.size}b-it"

    def get_chat_prompt(self, text, from_lang, to_lang, prompt_type):
        system_prompt, user_prompt = prompts.prompts[prompt_type](
            text=text, from_lang_code=from_lang, to_lang_code=to_lang
        )
        return [
            {
                "role": "system",
                "content": [
                    {
                        "type": "text",
                        "text": system_prompt,
                    }
                ],
            },
            {"role": "user", "content": [{"type": "text", "text": user_prompt}]},
        ]


class Gemma3n(Gemma3):
