        for k, v in env_vars.items():
            os.environ[k] = str(v)

        torch.cuda.set_device(torch.device("cuda", 0))

        if not torch.distributed.is_initialized():
            torch.distributed.init_process_group(
                backend="nccl", device_id=torch.device("cuda:0")
            )

        self.rank = int(os.environ["RANK"])
        self.model = AutoModel.from_pretrained("gpt2").cuda().bfloat16()

        self.model._apply(lambda t: t.fill_(1.0))

    def get_model_metadata(self):
        return {k: (v.dtype, v.shape) for k, v in self.model.state_dict().items()}

    def register_parameter_server(self, parameter_server):
        self.parameter_server = parameter_server

    def sync_weights(self):
        ray.get(self.parameter_server.acquire_state_dict_lock.remote())
        self.parameter_server.receive_from_trainer.remote()
        for k, v in self.model.state_dict().items():
            torch.distributed.send(v, 1)
        ray.get(self.parameter_server.release_state_dict_lock.remote())


@remote(num_cpus=1, num_gpus=1)
class DummyCollector:
    def __init__(self, weight_receiver, tp_size):
        from torchtune.dev.rl.workers.datacollectors import VLLMWorkerWrapper
        from vllm import LLM
        from vllm.model_executor.layers.vocab_parallel_embedding import (
            VocabParallelEmbedding,
        )

        os.environ["VLLM_USE_V1"] = "0"

        class TestVLLMWorkerWrapper(VLLMWorkerWrapper):
            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)

            def _check_weights_changed(self, fill_val) -> bool:
                """
                Check if the weights are updated to fill_val.
                """
                weights_updated = True
                for name, p in self.model_runner.model.named_parameters():
                    mod, child_name = name.rsplit(".", 1)
                    parent_module = self.model_runner.model.get_submodule(mod)
                    # TODO: vLLM pads embeddings with zeros, so not the full embedding will be filled with fill_val
                    if not isinstance(parent_module, VocabParallelEmbedding):
                        weights_updated = weights_updated and torch.allclose(
                            p, torch.empty_like(p).fill_(fill_val)
                        )
                return weights_updated

        self.inference_server = LLM(
            "gpt2",
            enforce_eager=True,
            dtype="bfloat16",
            worker_cls=TestVLLMWorkerWrapper,
            tensor_parallel_size=tp_size,
        )

        self.weight_update_receiver = weight_receiver
        self.weight_update_receiver.register_collector(self)

    def update_policy_weights_(self) -> None:
        self.weight_update_receiver()

    def check_weights_changed(self, fill_val) -> bool:
        return self.inference_server.collective_rpc(
            "_check_weights_changed", args=(fill_val,)
        )


@pytest.mark.skipif(not _has_ray or not _has_vllm, reason="requires ray and vllm")
@skip_if_lt_python_310()
class TestParamServer:
    def _get_env_vars(self, rank, world_size) -> dict[str, str]:
        env_vars = {
            "RANK": str(rank),
            "WORLD_SIZE": str(world_size),
            "MASTER_ADDR": "127.0.0.1",
            "MASTER_PORT": "29500",
        }
        return env_vars

    def _get_config(self, tp_size: int = 1):
        config_str = f"""
inference:
    tensor_parallel_dim: {tp_size}
        """
        cfg = OmegaConf.create(config_str)
        return cfg

    @pytest.mark.integration_test
    @gpu_test(gpu_count=2)
    @rl_test()
    def test_receive_from_trainer(self) -> None:
        import ray
        from torchtune.dev.rl.workers import VLLMParameterServer

        ray.init(num_cpus=10, num_gpus=2)

        try:
            trainer_handle = DummyTrainer.remote(self._get_env_vars(0, 2))
            cfg = self._get_config()
            ps_handle = VLLMParameterServer.remote(
                cfg, None, None, self._get_env_vars(1, 2)
            )
            trainer_handle.register_parameter_server.remote(ps_handle)
            model_metadata = ray.get(trainer_handle.get_model_metadata.remote())
            ps_handle.register_model_metadata.remote(model_metadata)
            ps_weights = ray.get(ps_handle._get_server_weights.remote())

            for k, v in model_metadata.items():
                assert ps_weights[k].dtype == v[0]
                assert ps_weights[k].shape == v[1]
                assert torch.equal(ps_weights[k], torch.zeros_like(ps_weights[k]))

            ray.get(trainer_handle.sync_weights.remote())

            updated_ps_weights = ray.get(ps_handle._get_server_weights.remote())
            for k, v in model_metadata.items():
                assert torch.equal(
                    updated_ps_weights[k], torch.ones_like(updated_ps_weights[k])
                )
        finally:
            ray.shutdown()

    @pytest.mark.integration_test
    @gpu_test(gpu_count=4)
    @pytest.mark.parametrize("tp_size", (1, 2))
    @rl_test()
    def test_send_to_generator(self, tp_size) -> None:
        import ray

        ray.init(num_cpus=10, num_gpus=2 + tp_size)

        try:
            from torchtune.dev.rl.workers import (
                VLLMHFWeightUpdateReceiver,
                VLLMParameterServer,
            )
            from transformers import AutoModel
            from vllm.utils import get_ip, get_open_port

            model = AutoModel.from_pretrained("gpt2").cuda().to(torch.bfloat16)
            model_metadata = {
                k: (v.dtype, v.shape) for k, v in model.state_dict().items()
            }

            trainer_handle = DummyTrainer.remote(self._get_env_vars(0, 2))
            ip, port, worker_idx = get_ip(), get_open_port(), 0
            cfg = self._get_config(tp_size=tp_size)
            ps_handle = VLLMParameterServer.remote(
                cfg, [ip], [port], self._get_env_vars(1, 2)
            )
            weight_receiver = VLLMHFWeightUpdateReceiver(
                ip, port, model_metadata, ps_handle, worker_idx
            )
            collector_handle = DummyCollector.options(num_gpus=tp_size).remote(
                weight_receiver, tp_size
            )

            trainer_handle.register_parameter_server.remote(ps_handle)
            ray.get(ps_handle.register_model_metadata.remote(model_metadata))
            ray.get(trainer_handle.sync_weights.remote())

            ray.get(collector_handle.update_policy_weights_.remote())
            assert all(ray.get(collector_handle.check_weights_changed.remote(1.0)))
        finally:
            ray.shutdown()

import os

import json
import logging
from typing import Dict, List, Optional

import ray
from fastapi import FastAPI
from ray import serve
from starlette.requests import Request
from starlette.responses import Response

from vllm import LLM, SamplingParams

logger = logging.getLogger("ray.serve")

app = FastAPI()

@serve.deployment(name="VLLMDeployment")
@serve.ingress(app)
class VLLMDeployment:
    def __init__(
        self,
        model_id,
        num_tpu_chips,
        max_model_len,
        tokenizer_mode,
        dtype,
    ):
        self.llm = LLM(
            model=model_id,
            tensor_parallel_size=num_tpu_chips,
            max_model_len=max_model_len,
            dtype=dtype,
            download_dir=os.environ['VLLM_XLA_CACHE_PATH'],  # Error if not provided.
            tokenizer_mode=tokenizer_mode,
            enforce_eager=True,
        )

    @app.post("/v1/generate")
    async def generate(self, request: Request):
        request_dict = await request.json()
        prompts = request_dict.pop("prompt")
        max_toks = int(request_dict.pop("max_tokens"))
        print("Processing prompt ", prompts)
        sampling_params = SamplingParams(temperature=0.7,
                                         top_p=1.0,
                                         n=1,
                                         max_tokens=max_toks)

        outputs = self.llm.generate(prompts, sampling_params)
        for output in outputs:
            prompt = output.prompt
            generated_text = ""
            token_ids = []
            for completion_output in output.outputs:
                generated_text += completion_output.text
                token_ids.extend(list(completion_output.token_ids))

            print("Generated text: ", generated_text)
            ret = {
                "prompt": prompt,
                "text": generated_text,
                "token_ids": token_ids,
            }

        return Response(content=json.dumps(ret))

def get_num_tpu_chips() -> int:
    if "TPU" not in ray.cluster_resources():
        # Pass in TPU chips when the current Ray cluster resources can't be auto-detected (i.e for autoscaling).
        if os.environ.get('TPU_CHIPS') is not None:
            return int(os.environ.get('TPU_CHIPS'))
        return 0
    return int(ray.cluster_resources()["TPU"])

def get_max_model_len() -> Optional[int]:
    if 'MAX_MODEL_LEN' not in os.environ or os.environ['MAX_MODEL_LEN'] == "":
        return None
    return int(os.environ['MAX_MODEL_LEN'])

def get_tokenizer_mode() -> str:
    if 'TOKENIZER_MODE' not in os.environ or os.environ['TOKENIZER_MODE'] == "":
        return "auto"
    return os.environ['TOKENIZER_MODE']

def get_dtype() -> str:
    if 'DTYPE' not in os.environ or os.environ['DTYPE'] == "":
        return "auto"
    return os.environ['DTYPE']

def build_app(cli_args: Dict[str, str]) -> serve.Application:
    """Builds the Serve app based on CLI arguments."""
    ray.init(ignore_reinit_error=True, address="ray://localhost:10001")

    model_id = os.environ['MODEL_ID']

    num_tpu_chips = get_num_tpu_chips()
    pg_resources = []
    pg_resources.append({"CPU": 1})  # for the deployment replica
    for i in range(num_tpu_chips):
        pg_resources.append({"CPU": 1, "TPU": 1})  # for the vLLM actors

    # Use PACK strategy since the deployment may use more than one TPU node.
    return VLLMDeployment.options(
        placement_group_bundles=pg_resources,
        placement_group_strategy="PACK").bind(model_id, num_tpu_chips, get_max_model_len(), get_tokenizer_mode(), get_dtype())

model = build_app({})

import logging
from typing import List, Optional

from langchain.schema import Generation
from transformers import AutoTokenizer

from autolabel.cache import BaseCache
from autolabel.configs import AutolabelConfig
from autolabel.models import BaseModel
from autolabel.schema import ErrorType, LabelingError, RefuelLLMResult

logger = logging.getLogger(__name__)


class VLLMModel(BaseModel):
    DEFAULT_PARAMS = {
        "max_tokens": 1024,
        "temperature": 0,
        "top_p": 1.0,
    }

    def __init__(
        self,
        config: AutolabelConfig,
        cache: BaseCache = None,
        tokenizer: Optional[AutoTokenizer] = None,
    ) -> None:
        super().__init__(config, cache, tokenizer)
        try:
            from transformers import AutoTokenizer
            from vllm import LLM, SamplingParams
        except ImportError:
            raise ImportError(
                "vllm is required to use the vllm LLM. Please install it with the following command: pip install vllm",
            )

        self.tokenizer = (
            tokenizer
            if tokenizer
            else AutoTokenizer.from_pretrained(self.config.model_name())
        )
        self.params = SamplingParams(
            max_tokens=self.DEFAULT_PARAMS["max_tokens"],
            temperature=self.DEFAULT_PARAMS["temperature"],
            top_p=self.DEFAULT_PARAMS["top_p"],
            use_beam_search=True,
            best_of=5,
            logprobs=1,
        )
        self.model_name = self.config.model_name()
        self.llm = LLM(
            model=self.config.model_name(),
            tensor_parallel_size=self.config.model_params().get(
                "tensor_parallel_size", 1,
            ),
        )

    def _label(self, prompts: List[str]) -> RefuelLLMResult:
        generations = []
        errors = []
        latencies = []
        for prompt in prompts:
            try:
                messages = [{"role": "user", "content": prompt}]
                tokenized_prompt = self.tokenizer.apply_chat_template(
                    messages, add_generation_prompt=True,
                )
                if len(tokenized_prompt) > 4096:
                    logger.warning(
                        f"Input is greater than 4096 tokens: {len(tokenized_prompt)}",
                    )
                response = self.llm.generate(
                    prompt_token_ids=[tokenized_prompt],
                    sampling_params=self.params,
                    use_tqdm=False,
                )
                generations.append(
                    [
                        Generation(
                            text=response[0]
                            .outputs[0]
                            .text.strip()
                            .replace("<|eot_id|>", ""),
                            generation_info=(
                                {
                                    "logprobs": {
                                        "top_logprobs": self._process_confidence_request(
                                            response[0].outputs[0].logprobs,
                                        ),
                                    },
                                }
                                if self.config.confidence()
                                else None
                            ),
                        ),
                    ],
                )
                errors.append(None)
                latencies.append(0)
            except Exception as e:
                # This signifies an error in generating the response using RefuelLLm
                logger.error(
                    f"Unable to generate prediction: {e}",
                )
                generations.append([Generation(text="")])
                errors.append(
                    LabelingError(
                        error_type=ErrorType.LLM_PROVIDER_ERROR, error_message=str(e),
                    ),
                )
                latencies.append(0)
        return RefuelLLMResult(
            generations=generations, errors=errors, latencies=latencies,
        )

    def _process_confidence_request(self, logprobs):
        resp = []
        for item in logprobs:
            key = list(item.keys())[0]
            curr_logprob_obj = item[key]
            resp.append({curr_logprob_obj.decoded_token: curr_logprob_obj.logprob})
        return resp

    def get_cost(self, prompt: str, label: Optional[str] = "") -> float:
        return 0

    def returns_token_probs(self) -> bool:
        return True

    def get_num_tokens(self, prompt: str) -> int:
        return len(self.tokenizer.encode(prompt))

