import sys

class Main:
    def main(self):
        input = self.FastScanner()
        n = input.nextInt()
        map = {}
        for i in range(n):
            val = input.nextInt()
            map[val] = map.get(val, 0) + 1
        max = -1
        for entry in map.items():
            value = entry[1]
            max = max if max > value else value
        print(max, len(map))

    class FastScanner:
        def __init__(self):
            self.buf = sys.stdin.readline
            self.tokens = None

        def next(self):
            while self.tokens is None or len(self.tokens) == 0:
                self.tokens = self.buf().split()
            if (self.tokens is None or len(self.tokens) == 0):
                return ''
            token = self.tokens[0]
            self.tokens = self.tokens[1:]
            return token

        def nextInt(self):
            return int(self.next())

        def nextLong(self):
            return int(self.next())

        def nextDouble(self):
            return float(self.next)

        def nextLine(self):
            return self.buf()

if __name__ == "__main__":
    obj = Main()
    obj.main()


