import sys

class FastScanner:
    def __init__(self):
        self.buf = sys.stdin.readline
        self.tokens = None

    def has_next(self):
        while self.tokens is None or len(self.tokens) == 0:
            self.tokens = self.buf().split()
        #some warning need if no input or below line 
        if (self.tokens is None or len(self.tokens) == 0):
            return False
        return True

    def next_int(self):
        if not self.has_next():
            return None
        val = self.tokens.pop(0)
        return int(val)

    def next_str(self):
        if not self.has_next():
            return None
        val = self.tokens.pop(0)
        return val

def main():
    input = FastScanner()
    n = input.next_int()
    map = {}
    for i in range(n):
        val = input.next_int()
        map[val] = map.get(val, 0) + 1
    max = -1
    for entry in map.items():
        value = entry[1]
        max = max if max > value else value
    print(max, len(map))

if __name__ == "__main__":
    main()

