                tensor_parallel_size=ngpus,
            )
    elif name == "wizardcoder-33b":
        return VLlmDecoder(
            batch_size=batch_size,
            name="WizardLM/WizardCoder-33B-V1.1",
            temperature=temperature,
            conversational=True,
