from lcb_runner.runner.base_runner import BaseRunner


class VLLMRunner(BaseRunner):
    def __init__(self, args, model):
        super().__init__(args, model)
        model_tokenizer_path = (
            model.model_name if args.local_model_path is None else args.local_model_path
        )
        self.llm = LLM(
            model=model_tokenizer_path,
            tokenizer=model_tokenizer_path,
            tensor_parallel_size=args.tensor_parallel_size,
            # dtype=args.dtype,
            enforce_eager=True,
            max_model_len=4096,
            disable_custom_all_reduce=True,
            enable_prefix_caching=args.enable_prefix_caching,
            trust_remote_code=args.trust_remote_code,
        )
        self.sampling_params = SamplingParams(
            n=self.args.n,
            max_tokens=self.args.max_tokens,
            temperature=self.args.temperature,
            top_p=self.args.top_p,
            frequency_penalty=0,
            presence_penalty=0,
            stop=self.args.stop,
        )

    def _run_single(self, prompt: str) -> list[str]:
        pass

    def run_batch(self, prompts: list[str]) -> list[list[str]]:
        outputs = [None for _ in prompts]
        remaining_prompts = []
        remaining_indices = []
        for prompt_index, prompt in enumerate(prompts):
            if self.args.use_cache and prompt in self.cache:
                if len(self.cache[prompt]) == self.args.n:
                    outputs[prompt_index] = self.cache[prompt]
                    continue
            remaining_prompts.append(prompt)
            remaining_indices.append(prompt_index)
        if remaining_prompts:
            vllm_outputs = self.llm.generate(remaining_prompts, self.sampling_params)
            if self.args.use_cache:
                assert len(remaining_prompts) == len(vllm_outputs)
                for index, remaining_prompt, vllm_output in zip(
                    remaining_indices, remaining_prompts, vllm_outputs
                ):
                    self.cache[remaining_prompt] = [o.text for o in vllm_output.outputs]
                    outputs[index] = [o.text for o in vllm_output.outputs]
            else:
                for index, vllm_output in zip(remaining_indices, vllm_outputs):
                    outputs[index] = [o.text for o in vllm_output.outputs]
        return outputs

import pytest
from loguru import logger

from speculators.convert.eagle.eagle3_converter import Eagle3Converter


class TestEagle3vLLM:
    def setup_method(self):
        self.prompts = [
            "The capital of France is",
            "The president of the US is",
            "My name is",
        ]

    @pytest.fixture
    def temp_cache_dir(self, tmp_path, monkeypatch):
        cache_dir = tmp_path / "hf_cache"
        cache_dir.mkdir(exist_ok=True)
        monkeypatch.setenv("HF_HOME", str(cache_dir))
        return cache_dir

    def _run_vllm_engine(self, model_path):
        from vllm import LLM, SamplingParams  # type: ignore

        sampling_params = SamplingParams(temperature=0.80, top_p=0.95, max_tokens=20)
        llm = LLM(model=model_path, max_model_len=1024, gpu_memory_utilization=0.8)
        outputs = llm.generate(self.prompts, sampling_params)
        logger.info(outputs)

        for output in outputs:
            token_ids = output.outputs[0].token_ids
            assert len(token_ids) == 20
            assert all(isinstance(token, int) for token in token_ids)

    @pytest.mark.smoke
    @pytest.mark.parametrize(
        "model_info",
        [
            {
                "unconverted_model": "yuhuili/EAGLE3-LLaMA3.1-Instruct-8B",
                "base_model": "meta-llama/Meta-Llama-3.1-8B-Instruct",
            },
            {
                "unconverted_model": "nm-testing/Speculator-Qwen3-8B-Eagle3",
                "base_model": "Qwen/Qwen3-8B",
                "norm_before_residual": True,
            },
        ],
    )
    def test_convert_run_vllm_engine_eagle3(self, model_info, temp_cache_dir, tmp_path):
        pytest.importorskip("vllm", reason="vLLM is not installed")

        unconverted_model = model_info.get("unconverted_model")
        base_model = model_info.get("base_model")
        norm_before_residual = model_info.get("norm_before_residual", False)
        converted_path = tmp_path / unconverted_model.split("/")[-1]
        converter = Eagle3Converter()

        converter.convert(
            input_path=unconverted_model,
            output_path=converted_path,
            base_model=base_model,
            cache_dir=temp_cache_dir,
            norm_before_residual=norm_before_residual,
        )
        self._run_vllm_engine(model_path=str(converted_path))

    @pytest.mark.smoke
    @pytest.mark.parametrize(
        "model_path",
        [
            "nm-testing/SpeculatorLlama3-1-8B-Eagle3-converted-0717-quantized",
            "nm-testing/Speculator-Qwen3-8B-Eagle3-converted-071-quantized",
        ],
    )
    def test_vllm_engine_eagle3(self, model_path):
        pytest.importorskip("vllm", reason="vLLM is not installed")
        self._run_vllm_engine(model_path=model_path)

