def gpt4o(prompt):
    response = openai.chat.completions.create(
        model="gpt-4o",
        messages=[
            {"role": "system", "content": "You are a helpful assistant that ranks groups of questions by relevance to a user query."},
            {"role": "user", "content": prompt}
        ],
        temperature=0.0
    )

    ranked_groups = response.choices[0].message.content.strip()
    return ranked_groups


def deepseek(prompt):
    url = "https://api.deepseek.com/v1/chat/completions"  
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {deepseek_api_key}"
    }
    data = {
        "model": "deepseek-chat",   
        "messages": [
            {"role": "system", "content": "You are a helpful assistant that ranks groups of questions by relevance to a user query."},
            {"role": "user", "content": prompt}
        ]
    }

    try:
        response = requests.post(url, headers=headers, json=data)
        response_json = response.json()

        if response.status_code != 200:
            raise Exception(f"DeepSeek API error: {response_json}")

        ranked_groups = response_json["choices"][0]["message"]["content"].strip()
        return ranked_groups
    except Exception as e:
        print(f"API call error: {str(e)}")
        print(f"response: {response.text if 'response' in locals() else 'No response'}")
        return None

class Llama3_3_70B:
    def __init__(self, model_name="meta-llama/Llama-3.3-70B-Instruct", gpu_memory_utilization=0.9, max_model_len=50000, gpu_ids=[0, 1, 2, 3]):
        self.model_name = model_name
        os.environ["CUDA_VISIBLE_DEVICES"] = ",".join(map(str, gpu_ids))

        self.llm = LLM(
            model=model_name, 
            tensor_parallel_size=len(gpu_ids),
            gpu_memory_utilization=gpu_memory_utilization,
            max_model_len=max_model_len,
            trust_remote_code=True,
            dtype="bfloat16",
        )
        self.sampling_params = SamplingParams(
            temperature=0.0,
            top_p=0.9,
            max_tokens=1024
        )

    def generate(self, prompt):
        outputs = self.llm.generate([prompt], self.sampling_params)
        return outputs[0].outputs[0].text

    def chat(self, messages):
        prompt = ""
        for message in messages:
            role = message["role"]
            content = message["content"]

            if role == "system":
                prompt += f"<|system|>\n{content}\n"
            elif role == "user":
                prompt += f"<|user|>\n{content}\n"
            elif role == "assistant":
                prompt += f"<|assistant|>\n{content}\n"

        prompt += "<|assistant|>\n"

        return self.generate(prompt)

    def extract_ranking(self, result):
        ranking_pattern = re.search(r'(\d+(?:,\s*\d+)+)', result)
        if ranking_pattern:
            return ranking_pattern.group(1)
        return None


llama_model = None

def llama70b(prompt):
    global llama_model

    if llama_model is None:
        llama_model = Llama3_3_70B(
            gpu_memory_utilization=0.9,
            max_model_len=50000,
            gpu_ids=[0, 1, 2, 3]
        )
        print("Llama 3.3 70B model initialized.")

    chat_messages = [
        {"role": "system", "content": "You are a helpful assistant that ranks groups of questions by relevance to a user query."},
        {"role": "user", "content": prompt}
    ]

    chat_result = llama_model.chat(chat_messages)
    ranked_groups = llama_model.extract_ranking(chat_result)
    if ranked_groups:
        print("\nranking:")
        print(ranked_groups)

    return ranked_groups



