def process_query(row_data, before_eval=False):
    idx, row = row_data
    query = row['question']
    gt_source = row['source_title'] 

    if gt_source and isinstance(gt_source, str):
        if gt_source.startswith('[') and gt_source.endswith(']'):
            try:
                gt_source_list = ast.literal_eval(gt_source)
                if isinstance(gt_source_list, list) and len(gt_source_list) > 0:
                    gt_source = gt_source_list[0] 
            except (SyntaxError, ValueError):
                pass

    if gt_source and not gt_source.endswith('.txt'):
        gt_source = f"{gt_source}.txt"

    result = {
        "idx": idx,
        "query": query,
        "gt_source": gt_source,
        "hit_at_1": False,
        "hit_at_3": False,
        "hit_at_5": False,
        "hit_at_10": False,
        "reciprocal_rank": 0
    }

    retrieved = ast.literal_eval(row['retrieved_questions'])
    retrieved = retrieved[:top_k]

    if before_eval:
        ranked_sources = []
        seen_sources = set()

        for item in retrieved:
            source = item['source']
            if source not in seen_sources:
                seen_sources.add(source)
                ranked_sources.append(source)

        gt_found = False
        for rank, source in enumerate(ranked_sources, 1):
            if source == gt_source and not gt_found:
                gt_found = True
                result["reciprocal_rank"] = 1.0 / rank

                if rank <= 1:
                    result["hit_at_1"] = True
                    result["hit_at_3"] = True
                    result["hit_at_5"] = True
                    result["hit_at_10"] = True
                elif rank <= 3:
                    result["hit_at_3"] = True
                    result["hit_at_5"] = True
                    result["hit_at_10"] = True
                elif rank <= 5:
                    result["hit_at_5"] = True
                    result["hit_at_10"] = True
                elif rank <= 10:
                    result["hit_at_10"] = True

        result["ranked_sources"] = [(i+1, i+1, source) for i, source in enumerate(ranked_sources)]
        result["ranked_groups"] = ",".join(str(i+1) for i in range(len(ranked_sources)))

        return result

    source_groups = defaultdict(list)
    for item in retrieved:
        source_groups[item['source']].append(item)

    group_mapping = {}
    questions_text = ""

    for i, (source, items) in enumerate(source_groups.items(), 1):
        group_mapping[i] = source
        questions_text += f"\nGroup {i}:\n"

        for j, item in enumerate(items):
            questions_text += f"- {item['question']} (cos score: {item['score']})\n"


    prompt = f"""
            User query: "{query}"

            Retrieved questions (grouped by source):
            {questions_text}

            Each question belongs to a source group (e.g., same document or generator). Some questions may be semantically similar because they come from the same source.

            Please rank the TOP 5 source groups by how relevant and helpful their associated questions are for answering the user's query. Within each group, consider the best representative question to assess relevance.

            Your goal is to select and rank the top 5 most useful groups such that the most useful ones are listed first, based on semantic similarity to the user's query.

            IMPORTANT: Only include the 5 MOST RELEVANT group numbers in your ranking. If there are fewer than 5 groups total, include all of them.

            Output only the group numbers in ranked order, separated by commas.
            Example output: 2,1,4,3,5
            """


    try:
        if args.qclusterer == "gpt-4o":
            ranked_groups = gpt4o(prompt)
        elif args.qclusterer == "deepseek":
            ranked_groups = deepseek(prompt)
        elif args.qclusterer == "llama70b":
            try:
                ranked_groups = llama70b(prompt)
            except Exception as e:
                result["error"] = f"Llama70b error: {str(e)}"
                return result
        elif args.qclusterer == "qwen72b":
            try:
                ranked_groups = qwen72b(prompt)
            except Exception as e:
                result["error"] = f"Qwen72b error: {str(e)}"
                return result
        elif args.qclusterer == "qwen7b":
            try:
                ranked_groups = qwen7b(prompt)
            except Exception as e:
                result["error"] = f"Qwen7b error: {str(e)}"
                return result
        elif args.qclusterer == "llama8b":
            try:
                ranked_groups = llama8b(prompt)
            except Exception as e:
                result["error"] = f"Llama8b error: {str(e)}"
                return result

        result["ranked_groups"] = ranked_groups

        print(f"prompt: {prompt}")
        print(f"ranked_groups: {ranked_groups}")

        try:
            ranked_group_numbers = [int(g.strip()) for g in ranked_groups.split(',')]
            result["ranked_sources"] = []

            gt_found = False
            for rank, group_num in enumerate(ranked_group_numbers, 1):
                if group_num in group_mapping:
                    source = group_mapping[group_num]
                    result["ranked_sources"].append((rank, group_num, source))


                    if source == gt_source and not gt_found:
                        gt_found = True
                        result["reciprocal_rank"] = 1.0 / rank

                        if rank <= 1:
                            result["hit_at_1"] = True
                            result["hit_at_3"] = True
                            result["hit_at_5"] = True
                            result["hit_at_10"] = True
                        elif rank <= 3:
                            result["hit_at_3"] = True
                            result["hit_at_5"] = True
                            result["hit_at_10"] = True
                        elif rank <= 5:
                            result["hit_at_5"] = True
                            result["hit_at_10"] = True
                        elif rank <= 10:
                            result["hit_at_10"] = True
                else:
                    result["ranked_sources"].append((rank, group_num, "wrong group number"))

        except Exception as e:
            result["error"] = f"ranking result parsing error: {str(e)}"
            result["parsing_error"] = True  # 파싱 에러 플래그 추가

    except Exception as e:
        result["error"] = f"OpenAI API call error: {str(e)}"

    return result

if not os.path.exists(file_path):
    print(f"file does not exist: {file_path}")
    sys.exit(1)
else:
    df = pd.read_csv(file_path)

    max_workers = 100

    results = []

    # llama70b -> multi-processing X
    if args.qclusterer == "llama70b" or args.qclusterer == "qwen72b" or args.qclusterer == "qwen7b" or args.qclusterer == "llama8b":
        for row_data in tqdm.tqdm(df.iterrows(), total=len(df), desc="query processing"):
            result = process_query(row_data, args.before_eval)
            results.append(result)

            idx = result["idx"]
            query = result["query"]
            gt_source = result["gt_source"]

            print(f"\noriginal question {idx+1}: {query}")
            print(f"Ground Truth source: {gt_source}")

            if "error" in result:
                print(f"error: {result['error']}")
                if "parsing_error" in result and result["parsing_error"]:
                    total_parsing_errors += 1
            else:
                print(f"\ngroup ranking result: {result['ranked_groups']}")
                print("\nranked source groups:")

                for rank, group_num, source in result["ranked_sources"]:
                    print(f"{rank}th: Group {group_num} (Source: {source})")

                if result["hit_at_1"]:
                    total_hits_at_1 += 1
                    print(f"✓ Ground Truth source '{gt_source}' is in the top 1 result.")
                if result["hit_at_3"]:
                    total_hits_at_3 += 1
                    print(f"✓ Ground Truth source '{gt_source}' is in the top 3 results.")
                if result["hit_at_5"]:
                    total_hits_at_5 += 1
                    print(f"✓ Ground Truth source '{gt_source}' is in the top 5 results.")
                if result["hit_at_10"]:
                    total_hits_at_10 += 1
                    print(f"✓ Ground Truth source '{gt_source}' is in the top 10 results.")
                else:
                    print(f"✗ Ground Truth source '{gt_source}' is not in the top 10 results.")

                if result["reciprocal_rank"] > 0:
                    rank = int(1.0 / result["reciprocal_rank"])
                    print(f"Ground Truth source '{gt_source}' rank: {rank} (reciprocal rank: {result['reciprocal_rank']:.4f})")
                else:
                    print(f"Ground Truth source '{gt_source}' is not in the results.")

                total_reciprocal_rank += result["reciprocal_rank"]

            total_queries += 1
    else:
        # other models -> multi-processing
        with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_row = {executor.submit(process_query, row_data, args.before_eval): row_data for row_data in df.iterrows()}

            for future in tqdm.tqdm(concurrent.futures.as_completed(future_to_row), total=len(future_to_row), desc="query processing"):
                row_data = future_to_row[future]
                try:
                    result = future.result()
                    results.append(result)

                    idx = result["idx"]
                    query = result["query"]
                    gt_source = result["gt_source"]

                    print(f"\noriginal question {idx+1}: {query}")
                    print(f"Ground Truth source: {gt_source}")

                    if "error" in result:
                        print(f"error: {result['error']}")
                        if "parsing_error" in result and result["parsing_error"]:
                            total_parsing_errors += 1
                    else:
                        print(f"\ngroup ranking result: {result['ranked_groups']}")
                        print("\nranked source groups:")

                        for rank, group_num, source in result["ranked_sources"]:
                            print(f"{rank}th: Group {group_num} (Source: {source})")

                        if result["hit_at_1"]:
                            total_hits_at_1 += 1
                            print(f"✓ Ground Truth source '{gt_source}' is in the top 1 result.")
                        if result["hit_at_3"]:
                            total_hits_at_3 += 1
                            print(f"✓ Ground Truth source '{gt_source}' is in the top 3 results.")
                        if result["hit_at_5"]:
                            total_hits_at_5 += 1
                            print(f"✓ Ground Truth source '{gt_source}' is in the top 5 results.")
                        if result["hit_at_10"]:
                            total_hits_at_10 += 1
                            print(f"✓ Ground Truth source '{gt_source}' is in the top 10 results.")
                        else:
                            print(f"✗ Ground Truth source '{gt_source}' is not in the top 10 results.")

                        if result["reciprocal_rank"] > 0:
                            rank = int(1.0 / result["reciprocal_rank"])
                            print(f"Ground Truth source '{gt_source}' rank: {rank} (reciprocal rank: {result['reciprocal_rank']:.4f})")
                        else:
                            print(f"Ground Truth source '{gt_source}' is not in the results.")

                        total_reciprocal_rank += result["reciprocal_rank"]

                    total_queries += 1

                except Exception as exc:
                    print(f"error occurred during processing: {exc}")

    if total_queries > 0:
        recall_at_1 = total_hits_at_1 / total_queries
        recall_at_3 = total_hits_at_3 / total_queries
        recall_at_5 = total_hits_at_5 / total_queries
        recall_at_10 = total_hits_at_10 / total_queries
        mrr = total_reciprocal_rank / total_queries
        mrr_at_5 = sum(min(r["reciprocal_rank"], 1.0 if r["hit_at_5"] else 0.0) for r in results) / total_queries
        parsing_error_rate = total_parsing_errors / total_queries if total_queries > 0 else 0  

        print("\n=== final evaluation results ===")
        print(f"Recall@1: {recall_at_1:.4f} ({total_hits_at_1}/{total_queries})")
        print(f"Recall@3: {recall_at_3:.4f} ({total_hits_at_3}/{total_queries})")
        print(f"Recall@5: {recall_at_5:.4f} ({total_hits_at_5}/{total_queries})")
        print(f"Recall@10: {recall_at_10:.4f} ({total_hits_at_10}/{total_queries})")
        print(f"MRR: {mrr:.4f}")
        print(f"MRR@5: {mrr_at_5:.4f}")
        print(f"Parsing Errors: {total_parsing_errors}/{total_queries} ({parsing_error_rate:.4f})")  
    else:
        print("\n=== no processed queries, so evaluation metrics cannot be calculated ===")

    qclustered_sources = []
    reciprocal_ranks = []
    for result in results:
        if "ranked_sources" in result:
            sources = [source for _, _, source in result["ranked_sources"] if source != "wrong group number"]
            qclustered_sources.append(sources)
            reciprocal_ranks.append(result["reciprocal_rank"])
        else:
            qclustered_sources.append([])
            reciprocal_ranks.append(0)

    sorted_results = sorted(results, key=lambda x: x["idx"])
    sorted_qclustered_sources = [qclustered_sources[result["idx"]] for result in sorted_results]
    sorted_reciprocal_ranks = [reciprocal_ranks[result["idx"]] for result in sorted_results]

    df['qclustered_sources'] = sorted_qclustered_sources
    df['reciprocal_rank'] = sorted_reciprocal_ranks

    output_file = os.path.splitext(file_path)[0] + "_qcluster.csv"
    df.to_csv(output_file, index=False)
    print(f"\nreordered results saved: {output_file}")

from typing import Dict, Optional, Tuple
from abc import ABC, abstractmethod

import torch
from torch import nn
from transformers.generation import GenerationConfig
from transformers import AutoModelForCausalLM, AutoTokenizer
from vllm import LLM, SamplingParams

from ..prm import BaseProcessRewardModel
from inferenceKit.utils import update_single_config, update_sampling_params_from_generation_config

class BaseLargeLanguageModel(nn.Module):
    def __init__(self, model_path, **kwargs):
        super().__init__()
        self.device = kwargs.pop("device", torch.cuda.current_device)
        self.device_map = kwargs.pop("device_map", None) or self.device

        self.base_config = self._load_config(model_path)
        self.config = self._default_config(self.base_config)
        self.config, _, _ = update_single_config(self.config, copy=True, **kwargs)

        self.model_path = model_path
        self.model, self.tokenizer = self._load_model(model_path)

    def _load_config(self, model_path):
        try:
            config = GenerationConfig.from_pretrained(model_path)
        except:
            config = GenerationConfig()
        return config

    def _load_model(self, model_path):
        if model_path != None:
            model = AutoModelForCausalLM.from_pretrained(
                model_path, 
                device_map=self.device_map, 
                torch_dtype=self.config.dtype, 
                attn_implementation="flash_attention_2" if self.config.flash_attn else None,
                )
            tokenizer = AutoTokenizer.from_pretrained(model_path)
        return model, tokenizer

    def _default_config(self, base_config=None):
        config = base_config or GenerationConfig()
        return config

    @torch.inference_mode()
    def generate(self, inputs, generation_config: GenerationConfig, **kwargs):
        outputs = self.model.generate(inputs, generation_config, **kwargs)
        return outputs

class DefaultLargeLanguageModel(BaseLargeLanguageModel):
    def __init__(self, model_path, **kwargs):
        super().__init__(model_path, **kwargs)


    def _default_config(self, base_config=None):
        config = super()._default_config(base_config)

        config.do_sample = True
        config.num_beams = 4
        config.max_new_tokens = 2048
        return config

    @torch.inference_mode()
    def generate(self, inputs, generation_config: GenerationConfig, **kwargs):
        return self.model.generate(inputs, generation_config, tokenizer=self.tokenizer, **kwargs)


class VLLMLargeLanguageModel(BaseLargeLanguageModel):
    def __init__(self, model_path, **kwargs):
        super().__init__(model_path, **kwargs)

    def _load_model(self, model_path):
        if model_path != None:
            model = LLM(
                model_path, 
                dtype=self.config.dtype, 
                # skip_tokenizer_init=True
                )
            tokenizer = model.get_tokenizer()
        return model, tokenizer

    def _default_config(self, base_config=None):
        config = super()._default_config(base_config)

        config.do_sample = True
        config.num_beams = 4
        config.max_new_tokens = 2048
        return config

    @torch.inference_mode()
    def generate(self, inputs, generation_config: GenerationConfig, **kwargs):
        samplingParams = SamplingParams(**kwargs)
        samplingParams = update_sampling_params_from_generation_config(samplingParams, generation_config)
        return self.model.generate(inputs, samplingParams, use_tqdm=False)

"""LLM Wrapper with caching, async, retries, and cost tracking."""
import transformers
from vllm import LLM, SamplingParams
import asyncio
import hashlib
import json
import logging
import os
from pathlib import Path
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Union, Callable, Type

import diskcache as dc
from together import Together
import openai
import tenacity
import tqdm.asyncio

from .config import MODEL_COSTS, RETRY_CONFIG

logging.getLogger("openai").setLevel(logging.WARNING)
logging.getLogger("httpx").setLevel(logging.WARNING)
BYTES_PER_GB = 1024 * 1024 * 1024

@dataclass
class LLMConfig:
    """Configuration for LLM providers and caching"""

    cache_size_gb: int = 2
    cache_policy: str = "least-recently-used"
    max_concurrent_requests: int = 64


class TokenCounter:
    CHARS_PER_TOKEN = 4

    def __init__(self, model: str):
        costs = MODEL_COSTS.get(model, {"input": 0.0, "output": 0.0})
        self.input_cost, self.output_cost = costs["input"], costs["output"]
        self.input_total = self.output_total = self.input_new = self.output_new = 0

    @staticmethod
    def format_token_count(tokens: float) -> str:
        return (
            f"{tokens/1_000_000:.2f}M"
            if tokens > 1_000_000
            else f"{tokens/1000:.1f}k" if tokens > 1000 else str(int(tokens))
        )

    def _update(self, prompt, response):
        if "usage" in response.raw_response:
            usage = response.raw_response["usage"]
            input_tokens, output_tokens = usage["prompt_tokens"], usage["completion_tokens"]
        else:
            input_tokens = len(prompt) / self.CHARS_PER_TOKEN
            output_tokens = len(response.text) / self.CHARS_PER_TOKEN

        self.input_total += input_tokens
        self.output_total += output_tokens
        if not response.cached:
            self.input_new += input_tokens
            self.output_new += output_tokens

    def update(self, prompt, responses):
        for response in responses:
            self._update(prompt, response)

    def print_cost(self):
        def calc_stats(input_tokens, output_tokens):
            cost = (input_tokens * self.input_cost + output_tokens * self.output_cost) / 1_000_000
            return (
                cost,
                self.format_token_count(input_tokens),
                self.format_token_count(output_tokens),
            )

        total_cost, total_in, total_out = calc_stats(self.input_total, self.output_total)
        new_cost, new_in, new_out = calc_stats(self.input_new, self.output_new)

        print(f"Total: ${total_cost:.4f} ({total_in} input, {total_out} output)")
        print(f"New: ${new_cost:.4f} ({new_in} input, {new_out} output)")


@dataclass
class LLMResponse:
    """Standardized response format across different LLM providers"""

    provider: str
    model: str
    raw_response: Dict[str, Any]
    text: str
    cached: bool = False


class BaseProvider(ABC):
    """A wrapper for interacting with LLM providers. Supports local caching, async, retries, and cost tracking."""

    def __init__(self, model: str, config: LLMConfig = LLMConfig()):
        self.model = model
        self.config = config
        self.token_counter = TokenCounter(model)

        cache_root = os.getenv("LLM_WRAPPER_CACHE_ROOT", os.path.expanduser("~/.cache"))
        model_name_safe = model.replace("/", "_")[-20:]
        current_dir = os.path.basename(os.getcwd())
        cache_dir = f"{cache_root}/llm_wrapper/{current_dir}/{model_name_safe}"
        os.makedirs(cache_dir, exist_ok=True)

        self.cache = dc.Cache(
            cache_dir,
            size_limit=self.config.cache_size_gb * BYTES_PER_GB,
            eviction_policy=self.config.cache_policy,
        )
        print(f"Cache path: {self.cache.directory}")
        print(
            f"Current cache size: {self.cache.volume() / BYTES_PER_GB:.2f}/{self.config.cache_size_gb}GB"
        )

    def _generate_cache_key(self, prompt: str, system_prompt: str = "", **kwargs) -> str:
        """Generate deterministic cache key for a single message."""
        components = [
            self.provider,
            self.model,
            (
                hashlib.sha256(system_prompt.encode()).hexdigest()
                if system_prompt
                else "no_system_prompt"
            ),
            hashlib.sha256(json.dumps(prompt).encode()).hexdigest(),
            hashlib.sha256(
                "|".join(f"{k}:{str(v)}" for k, v in sorted(kwargs.items())).encode()
            ).hexdigest(),
        ]
        return hashlib.sha256("|".join(components).encode()).hexdigest()

    def get_cached_response(
        self, prompt: str, system_prompt: str = "", **kwargs
    ) -> Optional[List[LLMResponse]]:
        cached = self.cache.get(self._generate_cache_key(prompt, system_prompt, **kwargs))
        if not cached:
            return None
        return [
            LLMResponse(
                text=choice["message"]["content"],
                raw_response=cached["raw_response"],
                provider=self.provider,
                model=self.model,
                cached=True,
            )
            for choice in cached["raw_response"]["choices"]
        ]

    def generate(
        self,
        prompts: Union[str, List[str]],
        system_prompt: Optional[str] = None,
        text_only: bool = True,
        silent: bool = False,
        force_new: bool = False,
        **kwargs: Any,
    ) -> Union[List[List[str]], List[List[LLMResponse]]]:
        prompts = [prompts] if isinstance(prompts, str) else prompts
        cached_responses = [
            None if force_new else self.get_cached_response(p, system_prompt, **kwargs)
            for p in prompts
        ]

        uncached_idxs = [i for i, r in enumerate(cached_responses) if r is None]
        if uncached_idxs:
            uncached_prompts = [prompts[i] for i in uncached_idxs]
            new_responses = self.generate_uncached(
                uncached_prompts, system_prompt, silent, **kwargs
            )
            for i, resp in zip(uncached_idxs, new_responses):
                cached_responses[i] = resp
                key = self._generate_cache_key(prompts[i], system_prompt, **kwargs)
                self.cache[key] = {"raw_response": resp[0].raw_response}

        return [
            [r.text for r in responses] if text_only else responses
            for responses in cached_responses
        ]

    @abstractmethod
    def generate_uncached(
        self, prompts: List[str], system_prompt: str = "", **kwargs
    ) -> List[List[LLMResponse]]:
        pass

    def estimate_tokens(
        self, prompts: Union[str, List[str]], responses: List[List[LLMResponse]]
    ) -> None:
        """Update token counter with prompt and response tokens."""
        prompts = [prompts] if isinstance(prompts, str) else prompts
        for prompt, response_list in zip(prompts, responses):
            self.token_counter.update(prompt, response_list)

    def print_cost(self) -> None:
        self.token_counter.print_cost()


def create_retry_decorator(
    max_retries: int = RETRY_CONFIG["max_retries"],
    base_delay: float = RETRY_CONFIG["base_delay"],
    max_delay: float = RETRY_CONFIG["max_delay"],
) -> Callable:
    """Create a retry decorator with exponential backoff."""
    return tenacity.retry(
        stop=tenacity.stop_after_attempt(max_retries),
        wait=tenacity.wait_exponential(multiplier=base_delay, min=base_delay, max=max_delay),
        retry=tenacity.retry_if_exception_type(RETRY_CONFIG["retry_exceptions"]),
        before_sleep=lambda retry_state: logging.warning(
            f"Retrying after {retry_state.next_action.sleep} seconds due to {retry_state.outcome.exception()}"
        ),
        retry_error_callback=lambda retry_state: retry_state.outcome.result(),
    )


class APIProviderMixin:
    """A mixin for interacting with LLM providers that use API calls."""

    async def _generate_single(
        self, prompt: str, system_prompt: str = "", **kwargs
    ) -> List[LLMResponse]:
        """Generate a single chat completion with caching."""
        messages = [{"role": "user", "content": prompt}]
        if system_prompt:
            messages = [{"role": "system", "content": system_prompt}] + messages
        responses = await self._chat_completions_create(messages, **kwargs)
        return responses

    async def _generate(
        self, prompts: List[str], system_prompt: str = "", **kwargs
    ) -> List[List[LLMResponse]]:
        semaphore = asyncio.Semaphore(value=self.config.max_concurrent_requests)
        pbar = kwargs.pop("progress_bar", None)

        async def run_single(prompt: str) -> List[LLMResponse]:
            async with semaphore:
                response = await self._generate_single(prompt, system_prompt, **kwargs)
                if pbar:
                    pbar.update(1)
                return response

        return await asyncio.gather(*[run_single(p) for p in prompts])

    def generate_uncached(
        self,
        prompts: Union[str, List[str]],
        system_prompt: Optional[str] = None,
        silent: bool = False,
        **kwargs: Any,
    ) -> List[List[str]] | List[List[LLMResponse]]:
        async def _async_generate() -> List[List[LLMResponse]]:
            prompt_list = prompts if isinstance(prompts, list) else [prompts]

            pbar = tqdm.asyncio.tqdm(
                total=len(prompt_list), desc="Generating responses", disable=silent
            )
            all_responses = await self._generate(
                prompts=prompt_list, system_prompt=system_prompt, progress_bar=pbar, **kwargs
            )
            pbar.close()

            if not silent:
                self.estimate_tokens(prompts, all_responses)
                self.print_cost()
            return all_responses

        try:
            try:
                loop = asyncio.get_running_loop()
                is_running = loop.is_running()
            except RuntimeError:
                loop = None
                is_running = False

            if is_running:
                import nest_asyncio

                nest_asyncio.apply()
                return loop.run_until_complete(_async_generate())
            else:
                return asyncio.run(_async_generate())
        except KeyboardInterrupt:
            print("Received interrupt signal, shutting down gracefully...")
            raise
        except Exception as e:
            print(f"Error during response generation: {str(e)}")
            raise


class OpenAIProvider(APIProviderMixin, BaseProvider):
    provider = "openai"
    reasoning_models = ["o1", "o3", "o1-mini", "o3-mini", "o4-mini"]

    def __init__(self, model: str):
        super().__init__(model)
        self.client = openai.AsyncOpenAI()

    @create_retry_decorator()
    async def _chat_completions_create(
        self, messages: List[Dict[str, str]], **kwargs: Any
    ) -> List[LLMResponse]:
        """OpenAI-specific implementation of chat completion."""
        # Handle max_tokens parameter for different model requirements
        if self.model in self.reasoning_models:
            if "max_tokens" in kwargs:
                kwargs["max_completion_tokens"] = kwargs.pop("max_tokens")
            kwargs.pop("temperature", None)
            kwargs.pop("top_p", None)

        response = await self.client.chat.completions.create(
            model=self.model, messages=messages, **kwargs
        )
        return [
            LLMResponse(
                text=choice.message.content,
                raw_response=response.model_dump(),
                provider=self.provider,
                model=self.model,
                cached=False,
            )
            for choice in response.choices
        ]


class TogetherProvider(APIProviderMixin, BaseProvider):
    provider = "together"

    def __init__(self, model: str):
        super().__init__(model=model)
        self.client = Together()

    @create_retry_decorator()
    async def _chat_completions_create(
        self, messages: List[Dict[str, str]], **kwargs: Any
    ) -> List[LLMResponse]:
        """Together-specific implementation of chat completion."""
        response = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: self.client.chat.completions.create(
                model=self.model, messages=messages, **kwargs
            ),
        )
        return [
            LLMResponse(
                text=choice.message.content,
                raw_response=response.model_dump(),
                provider=self.provider,
                model=self.model,
                cached=False,
            )
            for choice in response.choices
        ]


class vLLMProvider(BaseProvider):
    provider = "vllm"

    def __init__(
        self, model: str, context_length: int = 1024, compile_model: bool = False, **kwargs
    ):
        self.compile_model = compile_model
        self.set_vllm_environment()
        super().__init__(model=model)
        self.context_length = context_length
        self.tokenizer = transformers.AutoTokenizer.from_pretrained(model)
        self.llm = None

    def lazy_load_model(self):
        if self.llm is None:
            self.llm = LLM(
                model=self.model,
                dtype="bfloat16",
                trust_remote_code=True,
                max_model_len=self.context_length,
                max_seq_len_to_capture=self.context_length,
                enforce_eager=not self.compile_model
            )

    def set_vllm_environment(self):
        os.environ["TOKENIZERS_PARALLELISM"] = "false"
        local_scratch = "/scr-ssd" if os.path.exists("/scr-ssd") else "/scr"
        os.environ["VLLM_CACHE_ROOT"] = os.path.join(local_scratch, "yoonho", "vllm_cache")
        os.environ["TORCH_CUDA_ARCH_LIST"] = "9.0;8.9+PTX"
        if "TRANSFORMERS_CACHE" in os.environ:
            os.environ["HF_HOME"] = os.environ["TRANSFORMERS_CACHE"]
            del os.environ["TRANSFORMERS_CACHE"]

        if self.compile_model:
            os.environ["VLLM_USE_PRECOMPILED"] = "1"
            os.environ["VLLM_ALLOW_LONG_MAX_MODEL_LEN"] = "1"
            os.environ["VLLM_ATTENTION_BACKEND"] = "FLASHINFER"
        else:
            os.environ["TORCH_COMPILE_DISABLE"] = "1"
            os.environ["TORCH_DYNAMO_DISABLE"] = "1"
            os.environ["VLLM_USE_PRECOMPILED"] = "0"
            os.environ["VLLM_ALLOW_LONG_MAX_MODEL_LEN"] = "0"
            os.environ["VLLM_ATTENTION_BACKEND"] = "PYTORCH"

    def generate_uncached(
        self, prompts: List[str], system_prompt: str = "", silent: bool = False, **kwargs: Any
    ) -> List[List[LLMResponse]]:
        """Generate responses for uncached prompts using vLLM."""
        self.lazy_load_model()  # Ensure model is loaded

        conversations = []
        for prompt in prompts:
            conversation = [{"role": "user", "content": prompt}]
            if system_prompt:
                conversation = [{"role": "system", "content": system_prompt}] + conversation
            conversations.append(conversation)
        conversations_chat = self.tokenizer.apply_chat_template(conversations, tokenize=False)

        sampling_params = SamplingParams(
            max_tokens=kwargs.get("max_tokens", self.context_length),
            temperature=kwargs.get("temperature", 0.6),
            top_p=kwargs.get("top_p", 1.0),
            n=kwargs.get("n", 1),
        )

        all_responses = self.llm.generate(conversations_chat, sampling_params=sampling_params)
        llm_response_list = []
        for prompt_outputs in all_responses:
            llm_responses = []
            choices = []
            for output in prompt_outputs.outputs:
                choices.append({
                    "message": {"content": output.text, "role": "assistant"},
                    "finish_reason": output.finish_reason
                })

            raw_response = {
                "choices": choices,
                "model": self.model,
                "usage": {
                    "prompt_tokens": len(self.tokenizer.encode(prompt_outputs.prompt)),
                    "completion_tokens": sum(len(self.tokenizer.encode(output.text)) for output in prompt_outputs.outputs),
                    "total_tokens": len(self.tokenizer.encode(prompt_outputs.prompt)) + 
                                  sum(len(self.tokenizer.encode(output.text)) for output in prompt_outputs.outputs)
                },
            }

            for output in prompt_outputs.outputs:
                llm_responses.append(
                    LLMResponse(
                        text=output.text,
                        raw_response=raw_response,
                        provider=self.provider,
                        model=self.model,
                        cached=False,
                    )
                )
            llm_response_list.append(llm_responses)

        if not silent:
            self.estimate_tokens(prompts, llm_response_list)
            self.print_cost()

        return llm_response_list


class Provider:
    """Factory class to create the appropriate provider instance."""

    @classmethod
    def _get_provider_class(cls, model: str) -> Type[BaseProvider]:
        together_models = [m.id for m in Together().models.list()]
        if model in OpenAIProvider.reasoning_models or "gpt" in model:
            return OpenAIProvider
        elif model in together_models:
            return TogetherProvider
        else:
            return vLLMProvider

    def __new__(cls, model: str = None, **kwargs) -> BaseProvider:
        return cls._get_provider_class(model)(model=model, **kwargs)

