def copy_current_script(destination_folder):
    current_script = os.path.abspath(__file__)
    destination_file = os.path.join(destination_folder, os.path.basename(current_script))
    shutil.copy(current_script, destination_file)
copy_current_script(export_dir)

data = generate_prompt(cluster=use_cluster)
llm = LLM(model_id, tensor_parallel_size=gpus, trust_remote_code=True, load_format='auto', 
          gpu_memory_utilization=0.9, enforce_eager=False, disable_custom_all_reduce=True)
sampling_params = SamplingParams(n=n, max_tokens=1024, top_p=0.95)

perplexities = {}
for i in tqdm(range(0, len(data['name']), batch_size), total=math.ceil(len(data['name']) / batch_size)):
    if 'text' in data:
        prompts = data['text'][i : i + batch_size]
        outputs = llm.generate(prompts, sampling_params, use_tqdm=False)
    else:
        prompt_token_ids = data['input_ids'][i : i + batch_size]
        outputs = llm.generate(prompt_token_ids=prompt_token_ids, sampling_params=sampling_params, use_tqdm=False)
    names = data['name'][i : i + batch_size]
    for j in range(len(names)):
        perplexities[names[j]] = {}
        for k in range(len(outputs[j].outputs)):
            perplexity = math.exp(-outputs[j].outputs[k].cumulative_logprob / len(outputs[j].outputs[k].token_ids))
            perplexities[names[j]][k] = perplexity
            file_thread = threading.Thread(target=file_processing, args=(os.path.join(export_dir, f'{names[j]}-{k}.txt'), outputs[j].outputs[k].text.strip()))
            file_thread.start()

with open(os.path.join(export_dir, 'perplexity.pkl'), 'wb') as f:
    pickle.dump(perplexities, f)

import os
import time
import openai
import torch

from tqdm import tqdm
from copy import deepcopy
from vllm import LLM, SamplingParams
from typing import List, Dict, Any, Tuple
from tqdm.contrib.concurrent import process_map
from concurrent.futures import ProcessPoolExecutor


class GPTAzureChatGenerator(object):
    def __init__(self, model_name: str):
        self.model_name = model_name
        self.error_types = {
            "continue_error": [
                "timed out",
                "Connection error",
                "Connection reset by peer",
                "Remote end closed connection without response",
                "occurred in violation of protocol",
                "Failed to resolve",
                "TLSV1_ALERT_INTERNAL_ERROR",
                "Error communicating",
                "The server is overloaded or not ready yet",
                "upstream_error",
                "new_api_error",
                "当前分组上游负载已饱和",
                "Lock wait timeout exceeded"
            ],
            "sleep_error": [
                "call rate limit",
                "token rate limit"
            ],
            "ignore_error": [
                "content",
                "reduce the length"
            ]
        }

    def generate_single(self, packed_data: List[tuple]) -> List[Tuple[str, float]]:
        from openai import AzureOpenAI
        from openai.types.chat import ChatCompletion

        sentence, engine, config = packed_data
        client = AzureOpenAI(
            api_version="2023-07-y-preview",
            azure_endpoint="https://yfllm01.openai.azure.com/",
            api_key="REDACTED_CREDENTIAL"
        )

        while True:
            try:
                completion: ChatCompletion = client.chat.completions.create(
                    model=engine,
                    messages=[{"role": "user", "content": sentence}],
                    **config)
                return [(x.message.content, 1.0) for x in completion.choices]
            except Exception as e:
                continue_flag = False
                sleep_flag = False
                ignore_flag = False
                for x in self.error_types['continue_error']:
                    if x in str(e):
                        continue_flag = True
                for x in self.error_types['sleep_error']:
                    if x in str(e):
                        sleep_flag = True
                        continue_flag = True
                for x in self.error_types['ignore_error']:
                    if x in str(e):
                        ignore_flag = True
                if sleep_flag:
                    time.sleep(5)
                if continue_flag:
                    continue
                if not ignore_flag:
                    print(e)
                return [""]

    def generate(self, source: List[str], config: Dict[str, Any]) -> List[List[Tuple[str, float]]]:
        config = deepcopy(config)
        if config['parallel']:
            config.pop('parallel')
            if 'batch_size' in config:
                config.pop('batch_size')
            packed_data = [(x, self.model_name, config) for x in source]
            with ProcessPoolExecutor(max_workers=os.cpu_count() // 2) as _:
                result: List[List[str]] = list(process_map(
                    self.generate_single, packed_data, max_workers=os.cpu_count() // 2, chunksize=1))
        else:
            config.pop('parallel')
            result: List[List[str]] = [self.generate_single(
                (x, self.model_name, config)) for x in tqdm(source)]
        return result


