        input = f"""<|im_start|>system
You are an intelligent programming assistant to produce Python algorithmic solutions<|im_end|>
<|im_start|>user
Can you complete the following Python function?
```python
{prompt}
```
<|im_end|>
<|im_start|>assistant
```python
"""
        return VLlmDecoder.codegen(self, input, do_sample, num_samples)


def make_model(
    model_type: str,
    model_size: str,
    model_path: str,
    batch_size: int = 1,
    temperature: float = 0.8,
    dataset: str = None,
    tensor_parallel_size = 1
):
    if model_type == "codeqwen" or model_type == "qwen2":
        if "chat" in model_size.lower():
            if "awq" in model_size.lower():
                return AWQChatML(
                    batch_size=batch_size,
                    name=model_path,
                    temperature=temperature,
                    max_new_tokens=2048,
                    tensor_parallel_size = tensor_parallel_size
                )
            else:
                return ChatML(
                    batch_size=batch_size,
                    name=model_path,
                    temperature=temperature,
                    max_new_tokens=2048,
                    tensor_parallel_size = tensor_parallel_size
                )
        else:
            return VLlmDecoder(
                batch_size=batch_size,
                name=model_path,
                temperature=temperature,
                dataset=dataset,
                tensor_parallel_size = tensor_parallel_size
            )
    elif model_type=="llama3":
        if "chat" in model_size.lower():
            return Llama3Chat(
                batch_size=batch_size,
                name=model_path,
                temperature=temperature,
                max_new_tokens=2048,
                tensor_parallel_size = tensor_parallel_size
            )
        else:
            return VLlmDecoder(
                batch_size=batch_size,
                name=model_path,
                temperature=temperature,
                dataset=dataset,
                tensor_parallel_size = tensor_parallel_size
            )
    elif model_type=="gemma2":
        if "chat" in model_size.lower():
            return Gemma2Chat(
                batch_size=batch_size,
                name=model_path,
                temperature=temperature,
                max_new_tokens=2048,
                tensor_parallel_size = tensor_parallel_size
            )
        else:
            return VLlmDecoder(
                batch_size=batch_size,
                name=model_path,
                temperature=temperature,
                dataset=dataset,
                tensor_parallel_size = tensor_parallel_size
            )
    else:
        raise ValueError(f"Invalid model name: {model_type}@{model_size}")

#!/usr/bin/env python3

import os
# Set environment variables before importing numpy
os.environ['MKL_THREADING_LAYER'] = 'GNU'
os.environ['MKL_SERVICE_FORCE_INTEL'] = '1'
# Set C compiler environment variable
os.environ['CC'] = 'gcc'  # or 'clang' depending on your system

import argparse
import json
import re
import time
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Any, Union

import numpy as np
import yaml
from tqdm import tqdm
from vllm import LLM, SamplingParams
from transformers import AutoTokenizer

def load_config(config_path: str) -> dict:
    """Load configuration from YAML file."""
    try:
        with open(config_path, 'r') as f:
            return yaml.safe_load(f)
    except Exception as e:
        raise RuntimeError(f"Failed to load config file: {e}")

def load_prompts(prompts_path: str) -> List[Dict]:
    """Load prompts from JSON file."""
    try:
        with open(prompts_path, 'r') as f:
            data = json.load(f)
            if 'prompts' not in data:
                raise ValueError("JSON file must contain a 'prompts' key")
            return data['prompts']
    except Exception as e:
        raise RuntimeError(f"Failed to load prompts file: {e}")

def calculate_entropy(logits: np.ndarray) -> float:
    """Calculate entropy from logits."""
    try:
        probs = np.exp(logits) / np.sum(np.exp(logits))
        return -np.sum(probs * np.log(probs))
    except Exception:
        return 0.0  # Return 0 if calculation fails

def escape_regex(text: str) -> str:
    """Escape special regex characters in a string."""
    return re.escape(text)

def extract_answer(text: str, answer_tag: str) -> Optional[str]:
    """Extract answer from text using XML tags."""
    try:
        pattern = f"{escape_regex(answer_tag)}(.*?)</{escape_regex(answer_tag[1:])}"
        match = re.search(pattern, text, re.DOTALL)
        return match.group(1).strip() if match else None
    except Exception:
        return None

def score_exact_match(
    answer: str,
    canonical: str,
    case_sensitive: bool,
    allow_partial: bool
) -> bool:
    """Score exact match answers."""
    try:
        if not case_sensitive:
            answer = answer.lower()
            canonical = canonical.lower()

        if allow_partial:
            return canonical in answer
        return answer == canonical
    except Exception:
        return False

def score_numeric(
    answer: str,
    canonical: Union[int, float],
    tolerance: float,
    allow_scientific: bool
) -> bool:
    """Score numeric answers."""
    try:
        # Clean the answer string
        answer = answer.strip()

        # Handle scientific notation
        if not allow_scientific:
            # Remove scientific notation indicators
            answer = re.sub(r'[eE][+-]?\d+', '', answer)

        # Try to parse the answer as a number
        parsed = float(answer)

        # Handle integer comparison if canonical is an integer
        if isinstance(canonical, int):
            parsed = int(parsed)

        return abs(parsed - canonical) <= tolerance
    except (ValueError, TypeError):
        return False

def score_list(
    answer: str,
    canonical: List[Any],
    order_matters: bool,
    allow_partial: bool,
    separators: List[str]
) -> bool:
    """Score list answers."""
    try:
        # Try to split the answer using different separators
        for sep in separators:
            try:
                # Split and clean each item
                items = [item.strip().lower() for item in answer.split(sep)]
                items = [item for item in items if item]  # Remove empty items

                # Convert canonical to lowercase for string comparison
                canonical_lower = [str(x).lower() for x in canonical]

                # Try to convert items to numbers if canonical is numeric
                if all(isinstance(x, (int, float)) for x in canonical):
                    items = [float(item) for item in items]
                    canonical_lower = canonical  # Use original for numeric comparison

                if order_matters:
                    if allow_partial:
                        return all(item in canonical_lower for item in items)
                    return items == canonical_lower
                else:
                    if allow_partial:
                        return all(item in canonical_lower for item in items)
                    return set(items) == set(canonical_lower)
            except (ValueError, TypeError):
                continue

        return False
    except Exception:
        return False

def check_format_correctness(text: str, answer_tag: str) -> bool:
    """Check if the response contains properly formatted answer tags."""
    try:
        return f"{answer_tag}" in text and f"</{answer_tag[1:]}" in text
    except Exception:
        return False

def check_content_correctness(
    text: str,
    scoring_config: Dict,
    answer_tag: str
) -> bool:
    """Check if the response matches the scoring criteria."""
    try:
        answer = extract_answer(text, answer_tag)
        if answer is None:
            return False

        scoring_type = scoring_config['type']
        canonical = scoring_config['canonical_answer']

        if scoring_type == 'exact_match':
            return score_exact_match(
                answer,
                canonical,
                scoring_config.get('case_sensitive', False),
                scoring_config.get('allow_partial', False)
            )
        elif scoring_type == 'numeric':
            return score_numeric(
                answer,
                canonical,
                scoring_config.get('tolerance', 0),
                scoring_config.get('allow_scientific_notation', True)
            )
        elif scoring_type == 'list':
            return score_list(
                answer,
                canonical,
                scoring_config.get('order_matters', False),
                scoring_config.get('allow_partial', False),
                scoring_config.get('separators', [',', ';', 'and', '&'])
            )
        else:
            raise ValueError(f"Unknown scoring type: {scoring_type}")
    except Exception:
        return False

def generate_completions(
    model: LLM,
    tokenizer: AutoTokenizer,
    prompt: str,
    sampling_params: SamplingParams,
    num_completions: int
) -> List[Dict]:
    """Generate multiple completions for a single prompt using chat format."""
    try:
        outputs = []
        # Format the prompt as a chat message
        conversation = [{"role": "user", "content": prompt}]

        # Apply chat template
        input_ids = tokenizer.apply_chat_template(
            conversation=conversation,
            tokenize=True,
            add_generation_prompt=True,
            return_tensors="pt"
        )

        # Convert to string for VLLM
        formatted_prompt = tokenizer.decode(input_ids[0])

        for _ in range(num_completions):
            output = model.generate(formatted_prompt, sampling_params)
            outputs.extend(output)
        return outputs
    except Exception as e:
        print(f"Error generating completions: {e}")
        return []

def process_completion(
    completion: Dict,
    answer_tag: str,
    scoring_config: Dict
) -> Dict:
    """Process a single completion and extract relevant information."""
    try:
        # Extract the actual completion text and token information from the RequestOutput object
        if hasattr(completion, 'outputs') and completion.outputs:
            output = completion.outputs[0]
            text = output.text
            # Get token IDs if available
            token_ids = output.token_ids if hasattr(output, 'token_ids') else []
            # Create token-level information
            tokens = []
            if token_ids:
                # Split text into words to match with token IDs
                words = text.split()
                for i, token_id in enumerate(token_ids):
                    if i < len(words):
                        tokens.append({
                            'id': token_id,
                            'text': words[i]
                        })
        else:
            text = str(completion)
            tokens = []

        # Check correctness
        format_correct = check_format_correctness(text, answer_tag)
        content_correct = check_content_correctness(text, scoring_config, answer_tag)

        return {
            'text': text,
            'tokens': tokens,
            'format_correct': format_correct,
            'content_correct': content_correct
        }
    except Exception as e:
        print(f"Error processing completion: {e}")
        return {
            'text': str(completion),
            'tokens': [],
            'format_correct': False,
            'content_correct': False
        }

def save_results(
    results: Dict,
    output_dir: Path,
    prompt_id: str,
    save_individual: bool
) -> None:
    """Save results to file(s)."""
    try:
        if save_individual:
            prompt_file = output_dir / f"prompt_{prompt_id}.json"
            with open(prompt_file, 'w') as f:
                json.dump(results, f, indent=2)
    except Exception as e:
        print(f"Error saving results: {e}")

def create_sampling_params(strategy: Dict) -> SamplingParams:
    """Create sampling parameters from strategy configuration."""
    params = {}

    # Only add parameters if they exist in the strategy
    if 'temperature' in strategy:
        params['temperature'] = strategy['temperature']
    if 'top_p' in strategy:
        params['top_p'] = strategy['top_p']
    if 'max_tokens' in strategy:
        params['max_tokens'] = strategy['max_tokens']
    if 'min_p' in strategy:
        params['min_p'] = strategy['min_p']

    print("Sampling params: ", params)

    return SamplingParams(**params)

def validate_model_path(model_path: str) -> bool:
    """Validate that the model path exists and contains necessary files."""
    path = Path(model_path)
    if not path.exists():
        return False

    # Check for common model files
    required_files = ['config.json', 'pytorch_model.bin']
    return all((path / file).exists() for file in required_files)

def main():
    parser = argparse.ArgumentParser(description='Generate completions using VLLM')
    parser.add_argument('--config', required=True, help='Path to config file')
    parser.add_argument('--prompts', required=True, help='Path to prompts JSON file')
    parser.add_argument('--output', required=True, help='Output directory')
    parser.add_argument('--num-completions', type=int, default=40, help='Number of completions per prompt')
    args = parser.parse_args()

    try:
        # Load configuration
        print("Loading configuration...")
        config = load_config(args.config)

        # Initialize model
        model_path = config['model']['name']
        print(f"Initializing model from: {model_path}")

        # Check if it's a local path
        if os.path.exists(model_path):
            print("Using local model files")
            if not validate_model_path(model_path):
                print("Warning: Local model path may be incomplete. Required files:")
                print("  - config.json")
                print("  - pytorch_model.bin")
        else:
            print("Model not found locally, will download from HuggingFace")

        print("This may take a few minutes for large models...")
        start_time = time.time()
        try:
            # Initialize tokenizer
            tokenizer = AutoTokenizer.from_pretrained(model_path, trust_remote_code=True)

            # Initialize model
            model = LLM(
                model=model_path,
                dtype=config['model']['dtype'],
                trust_remote_code=config['model']['trust_remote_code']
            )
            load_time = time.time() - start_time
            print(f"Model loaded successfully in {load_time:.2f} seconds")
        except Exception as e:
            raise RuntimeError(f"Failed to initialize model: {e}")

        # Load prompts
        print("Loading prompts...")
        prompts = load_prompts(args.prompts)
        print(f"Loaded {len(prompts)} prompts")

        # Create output directory
        output_dir = Path(args.output)
        output_dir.mkdir(parents=True, exist_ok=True)
        (output_dir / 'prompts').mkdir(exist_ok=True)

        # Initialize results storage
        all_results = []

        # Process each prompt
        print("\nGenerating completions...")
        for prompt in tqdm(prompts, desc="Processing prompts"):
            prompt_results = {
                'prompt': {
                    'id': prompt['id'],
                    'text': prompt['text'],
                    'scoring': prompt['scoring'],
                    'tokens': []  # TODO: Add tokenization of prompt
                },
                'completions': []
            }

            # Generate completions for each sampling strategy
            for strategy in config['sampling_strategies']:
                sampling_params = create_sampling_params(strategy)

                completions = generate_completions(
                    model,
                    tokenizer,
                    prompt['text'],
                    sampling_params,
                    args.num_completions
                )

                for completion in completions:
                    processed = process_completion(
                        completion,
                        config['scoring']['format']['answer_tag'],
                        prompt['scoring']
                    )

                    completion_result = {
                        'model': config['model']['name'],
                        'sampling_args': strategy,
                        **processed
                    }

                    prompt_results['completions'].append(completion_result)

            # Save individual results
            if config['output']['save_individual']:
                save_results(
                    prompt_results,
                    output_dir / 'prompts',
                    prompt['id'],
                    True
                )

            all_results.append(prompt_results)

        # Save consolidated results
        if config['output']['save_consolidated']:
            print("\nSaving consolidated results...")
            metadata = {
                'timestamp': datetime.now().isoformat(),
                'model': config['model']['name'],
                'num_prompts': len(prompts),
                'num_completions_per_prompt': args.num_completions,
                'sampling_strategies': config['sampling_strategies']
            }

            consolidated = {
                'metadata': metadata,
                'results': all_results
            }

            with open(output_dir / 'all_results.json', 'w') as f:
                json.dump(consolidated, f, indent=2)
            print("Done!")

    except Exception as e:
        print(f"Error in main execution: {e}")
        raise

if __name__ == '__main__':
    main()

import os

import subprocess
from openai import OpenAI
import google.generativeai as genai
from vllm import LLM, SamplingParams
import time


def get_free_gpu(use_gpu_num):
    # Use nvidia-smi command to get GPU usage information
    result = subprocess.run(['nvidia-smi', '--query-gpu=index,memory.free', '--format=csv,noheader,nounits'], 
                            stdout=subprocess.PIPE, text=True)
    # Parse the output
    gpu_info = result.stdout.strip().split('\n')
    free_gpus = [(int(info.split(',')[0]), int(info.split(',')[1])) for info in gpu_info]

    # Sort by free memory in descending order
    free_gpus.sort(key=lambda x: x[1], reverse=True)

    # Return GPU IDs with the most free memory
    return ",".join(str(i[0]) for i in free_gpus[:use_gpu_num])



class LLMInfer(object):
    def __init__(self, model_path, temperature=0.001, top_p=1, max_tokens=1000, language="zh", max_model_len=8192, tensor_parallel_size=1) -> None:
        gpu_ids = get_free_gpu(use_gpu_num=tensor_parallel_size)
        os.environ["CUDA_VISIBLE_DEVICES"] = gpu_ids
        self.sampling_params = SamplingParams(
        temperature=0.0, max_tokens=1024, top_p=0.9
        )
        from transformers import AutoTokenizer
        self.tokenizer = AutoTokenizer.from_pretrained(model_path, trust_remote_code=True)
        self.llm = LLM(model=model_path, dtype="float16", trust_remote_code=True, max_model_len=max_model_len, tensor_parallel_size=tensor_parallel_size,
                gpu_memory_utilization=0.9)

    def _format_prompt(self, messages):
        # Qwen is using its prompting mode, not the tool use mode
        """
        "chat_template": "{%- if tools %}\n    {{- '<|im_start|>system\\n' }}\n    {%- if messages[0]['role'] == 'system' %}\n        {{- messages[0]['content'] }}\n    {%- else %}\n        {{- 'You are Qwen, created by Alibaba Cloud. You are a helpful assistant.' }}\n    {%- endif %}\n    {{- \"\\n\\n# Tools\\n\\nYou may call one or more functions to assist with the user query.\\n\\nYou are provided with function signatures within <tools></tools> XML tags:\\n<tools>\" }}\n    {%- for tool in tools %}\n        {{- \"\\n\" }}\n        {{- tool | tojson }}\n    {%- endfor %}\n    {{- \"\\n</tools>\\n\\nFor each function call, return a json object with function name and arguments within <tool_call></tool_call> XML tags:\\n<tool_call>\\n{\\\"name\\\": <function-name>, \\\"arguments\\\": <args-json-object>}\\n</tool_call><|im_end|>\\n\" }}\n{%- else %}\n    {%- if messages[0]['role'] == 'system' %}\n        {{- '<|im_start|>system\\n' + messages[0]['content'] + '<|im_end|>\\n' }}\n    {%- else %}\n        {{- '<|im_start|>system\\nYou are Qwen, created by Alibaba Cloud. You are a helpful assistant.<|im_end|>\\n' }}\n    {%- endif %}\n{%- endif %}\n{%- for message in messages %}\n    {%- if (message.role == \"user\") or (message.role == \"system\" and not loop.first) or (message.role == \"assistant\" and not message.tool_calls) %}\n        {{- '<|im_start|>' + message.role + '\\n' + message.content + '<|im_end|>' + '\\n' }}\n    {%- elif message.role == \"assistant\" %}\n        {{- '<|im_start|>' + message.role }}\n        {%- if message.content %}\n            {{- '\\n' + message.content }}\n        {%- endif %}\n        {%- for tool_call in message.tool_calls %}\n            {%- if tool_call.function is defined %}\n                {%- set tool_call = tool_call.function %}\n            {%- endif %}\n            {{- '\\n<tool_call>\\n{\"name\": \"' }}\n            {{- tool_call.name }}\n            {{- '\", \"arguments\": ' }}\n            {{- tool_call.arguments | tojson }}\n            {{- '}\\n</tool_call>' }}\n        {%- endfor %}\n        {{- '<|im_end|>\\n' }}\n    {%- elif message.role == \"tool\" %}\n        {%- if (loop.index0 == 0) or (messages[loop.index0 - 1].role != \"tool\") %}\n            {{- '<|im_start|>user' }}\n        {%- endif %}\n        {{- '\\n<tool_response>\\n' }}\n        {{- message.content }}\n        {{- '\\n</tool_response>' }}\n        {%- if loop.last or (messages[loop.index0 + 1].role != \"tool\") %}\n            {{- '<|im_end|>\\n' }}\n        {%- endif %}\n    {%- endif %}\n{%- endfor %}\n{%- if add_generation_prompt %}\n    {{- '<|im_start|>assistant\\n' }}\n{%- endif %}\n",
        """
        formatted_prompt = ""

        for message in messages:
            formatted_prompt += f"<|im_start|>{message['role']}\n{message['content']}<|im_end|>\n"

        formatted_prompt += "<|im_start|>assistant\n"

        return formatted_prompt

    def inference(self, system_prompt, user_prompt):
        messages = [{"role": "system", "content": system_prompt}, {"role": "user", "content": user_prompt}]
        prompt = self.tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        question = [prompt, ]
        outputs = self.llm.generate(question, self.sampling_params, use_tqdm=False)
        if len(question) == 1:
            result = outputs[0].outputs[0].text
        else:
            result = []
            for idx, output in enumerate(outputs):
                out_generated_text = output.outputs[0].text
                result.append(out_generated_text)
        return result


class Llama(LLMInfer):
    def __init__(self, model_path, temperature=0.001, top_p=1, max_tokens=1000, language="zh", max_model_len=8192, tensor_parallel_size=2) -> None:
        super().__init__(model_path, temperature, top_p, max_tokens, language, max_model_len, tensor_parallel_size)


class Deepseek(object):
    def __init__(self, model_name, model_path=None, temperature=0.001, top_p=1, max_tokens=1000, language="zh") -> None:
        api_key = os.getenv("DEEPSEEK_API_KEY")
        base_url = "https://api.deepseek.com"
        self.model_name = model_name
        self.client = OpenAI(api_key=api_key, timeout=1000, max_retries=1, base_url=base_url)

    def creat_message(self, system_prompt=None, user_prompt=None, few_shot_examples=None):
        messages = []
        if system_prompt:
            messages = [{"role": "system", "content": system_prompt}]
        if few_shot_examples:
            for item in few_shot_examples:
                user, assistant = item["user"], item["assistant"]
                messages.append({"role": "system", "name": "example_user", "content": user})
                messages.append({"role": "system", "name": "example_assistant", "content": assistant})
        if user_prompt:
            messages.append({"role": "user", "content": user_prompt})
        return messages

import time

class YourClass:
    def __init__(self, model_name):
        self.model_name = model_name
        self.last_request_time = 0  # To track the time of the last request


    def inference(self, system_prompt, user_prompt):
        messages = self.creat_message(system_prompt=system_prompt, user_prompt=user_prompt)
        result = self.request_openai(messages=messages, model=self.model_name)
        return result


class Gemini(object):
    def __init__(self, model_name, model_path=None, temperature=0.001, top_p=1, max_tokens=1000, language="zh") -> None:
        genai.configure(api_key=os.getenv("GEMINI_API_KEY"), transport='rest')
        self.model_name = model_name
        self.last_request_time = 0  # To track the time of the last request

    def creat_message(self, system_prompt=None, user_prompt=None, few_shot_examples=None):
        messages = []
        if few_shot_examples:
            for item in few_shot_examples:
                user, assistant = item["user"], item["assistant"]
                messages.append({"role": "model", "parts": user})
                messages.append({"role": "model", "parts": assistant})
        if user_prompt:
            messages.append({"role": "user", "parts": user_prompt})
        return messages

    def request_gemini(self, system_prompt, messages):
        try:
            # Check time difference from the last request
            current_time = time.time()
            if current_time - self.last_request_time < 7:
                # Sleep if the time difference is less than 6 seconds
                time.sleep(7 - (current_time - self.last_request_time))

            model = genai.GenerativeModel(self.model_name, system_instruction=system_prompt)
            response = model.generate_content(messages)
            result = response.text
            self.last_request_time = time.time()
            return result

        except Exception as e:
            raise e

    def inference(self, system_prompt, user_prompt):
        messages = self.creat_message(system_prompt=system_prompt, user_prompt=user_prompt)
        result = self.request_gemini(system_prompt=system_prompt, messages=messages)
        return result

class Kimi(object):
    def __init__(self, model_name, model_path=None, temperature=0.001, top_p=1, max_tokens=1000, language="zh") -> None:
        api_key = os.getenv("KIMI_API_KEY")
        base_url = os.getenv("KIMI_BASE_URL")
        self.model_name = model_name
        self.client = OpenAI(api_key=api_key, timeout=1000, max_retries=1, base_url=base_url)

    def creat_message(self, system_prompt=None, user_prompt=None):
        messages = []
        if system_prompt:
            messages = [{"role": "system", "content": system_prompt}]
        if user_prompt:
            messages.append({"role": "user", "content": user_prompt})
        return messages

    def inference(self, system_prompt, user_prompt):
        messages = self.creat_message(system_prompt=system_prompt, user_prompt=user_prompt)
        response = self.client.chat.completions.create(  
            model = self.model_name,
            messages=messages,
            max_tokens=1024,
            temperature=0.0
        )
        return response.choices[0].message.content


model_dict = {}
def get_model(model_name, model_path):
    global model_dict
    if model_name in model_dict:
        model = model_dict[model_name]
    else:
        model_name_lower = model_name.lower()
        if "qwen" in model_name_lower:
            model = LLMInfer(model_path)
        elif "llama" in model_name_lower:
            model = Llama(model_path)
        elif "deepseek" in model_name_lower:
            model = Deepseek(model_name)
        elif "gemini" in model_name_lower:
            model = Gemini(model_name)
        elif "kimi" in model_name_lower:
            model = Kimi(model_name)
        elif model_path:
            model = Llama(model_path)
        else:
            raise("Unsupported model")
        model_dict[model_name] = model
    return model

import json
import os
from abc import ABC, abstractmethod
from typing import List
from warnings import warn

# Communism
os.environ["HF_HOME"] = os.environ.get("HF_HOME", "/JawTitan/huggingface/")

import openai
import torch
from transformers import (
    AutoModelForCausalLM,
    AutoModelForSeq2SeqLM,
    AutoTokenizer,
    StoppingCriteria,
    StoppingCriteriaList,
)
from vllm import LLM, SamplingParams

from evalplus.gen.util.api_request import make_auto_request

EOS = ["<|endoftext|>", "<|endofmask|>", "</s>"]


# Adopted from https://github.com/huggingface/transformers/pull/14897
class EndOfFunctionCriteria(StoppingCriteria):
    def __init__(self, start_length, eos, tokenizer, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.start_length = start_length
        self.eos = eos
        self.tokenizer = tokenizer
        self.end_length = {}

    def __call__(self, input_ids, scores, **kwargs):
        """Returns true if all generated sequences contain any of the end-of-function strings."""
        decoded_generations = self.tokenizer.batch_decode(
            input_ids[:, self.start_length :]
        )
        done = []
        for index, decoded_generation in enumerate(decoded_generations):
            finished = any(
                [stop_string in decoded_generation for stop_string in self.eos]
            )
            if (
                finished and index not in self.end_length
            ):  # ensures first time we see it
                for stop_string in self.eos:
                    if stop_string in decoded_generation:
                        self.end_length[index] = len(
                            input_ids[
                                index,  # get length of actual generation
                                self.start_length : -len(
                                    self.tokenizer.encode(
                                        stop_string,
                                        add_special_tokens=False,
                                        return_tensors="pt",
                                    )[0]
                                ),
                            ]
                        )
            done.append(finished)
        return all(done)


class DecoderBase(ABC):
    def __init__(
        self,
        name: str,
        batch_size: int = 1,
        temperature: float = 0.8,
        max_new_tokens: int = 512,
        conversational: bool = False,
        max_conversational_new_tokens: int = 1024,
    ) -> None:
        print("Initializing a decoder model: {} ...".format(name))
        self.name = name
        self.batch_size = batch_size
        self.temperature = temperature
        self.eos = EOS
        self.skip_special_tokens = False
        self.max_new_tokens = (
            max_conversational_new_tokens if conversational else max_new_tokens
        )
        self.conversational = conversational

    @abstractmethod
    def codegen(
        self, prompt: str, do_sample: bool = True, num_samples: int = 200
    ) -> List[str]:
        pass

    def __repr__(self) -> str:
        return self.name

    def __str__(self) -> str:
        return self.name


class VLlmDecoder(DecoderBase):
    def __init__(self, name: str, **kwargs) -> None:
        super().__init__(name, **kwargs)

        kwargs = {"tensor_parallel_size": int(os.getenv("VLLM_N_GPUS", "1"))}
        if "CodeLlama" in name:
            kwargs["dtype"] = "bfloat16"
        elif "code-millenials" in name:
            kwargs["dtype"] = "float16"
        elif "uukuguy/speechless-code-mistral-7b-v1.0" == name:
            kwargs["dtype"] = "float16"
        elif "uukuguy/speechless-codellama-34b-v2.0" == name:
            kwargs["dtype"] = "float16"
        elif "CodeBooga" in name:
            kwargs["dtype"] = "float16"
        elif "WizardCoder" in name:
            kwargs["dtype"] = "float16"
        elif "deepseek" in name:
            kwargs["dtype"] = "bfloat16"
        elif "mixtral" in name.lower():
            kwargs["dtype"] = "bfloat16"
        elif "solar" in name:
            kwargs["dtype"] = "float16"
        elif "mistral" in name.lower():
            kwargs["dtype"] = "bfloat16"
        elif "phi" in name.lower():
            kwargs["dtype"] = "float16"
            kwargs["trust_remote_code"] = True
        elif "openchat" in name.lower():
            kwargs["dtype"] = "bfloat16"

        self.llm = LLM(model=name, max_model_len=2048, **kwargs)

    def codegen(
        self, prompt: str, do_sample: bool = True, num_samples: int = 200
    ) -> List[str]:
        if do_sample:
            assert self.temperature > 0, "Temperature must be greater than 0!"
        batch_size = min(self.batch_size, num_samples)

        vllm_outputs = self.llm.generate(
            [prompt] * batch_size,
            SamplingParams(
                temperature=self.temperature,
                max_tokens=self.max_new_tokens,
                top_p=0.95 if do_sample else 1.0,
                stop=self.eos,
            ),
            use_tqdm=False,
        )

        gen_strs = [x.outputs[0].text.replace("\t", "    ") for x in vllm_outputs]
        return gen_strs


# chatml format
