                lambda input: ({"system": input}, gr.update(open=False)),
                inputs=[systemPromptInput],
                outputs=[setting, system_prompt_modal]
            )
            system_prompt_modal.cancel(lambda: gr.update(open=False), outputs=[system_prompt_modal])

            codeBtn.click(lambda: gr.update(open=True), outputs=[code_drawer])
            code_drawer.close(lambda: gr.update(open=False), outputs=[code_drawer])

            historyBtn.click(
                lambda h: (gr.update(open=True), h),
                inputs=[history],
                outputs=[history_drawer, history_output]
            )
            history_drawer.close(lambda: gr.update(open=False), outputs=[history_drawer])

            btn.click(
                generate_code,
                inputs=[input, setting, history],
                outputs=[code_output, history, preview, state_tab, code_drawer]
            )

            clear_btn.click(lambda: [], outputs=[history])

        return interface

    # Continue with existing chat interface code...
    pipeline = get_pipeline(name)
    inputs, outputs, preprocess, postprocess = get_interface_args(pipeline, name)
    fn = get_fn(name, preprocess, postprocess, api_key, local=local)

    if examples:
        formatted_examples = [[example, False] for example in examples]
        kwargs["examples"] = formatted_examples

    if pipeline == "chat":
        interface = gr.ChatInterface(
            fn=fn,
            additional_inputs=inputs,
            multimodal=True,
            **kwargs
        )
    else:
        interface = gr.Interface(fn=fn, inputs=inputs, outputs=outputs, **kwargs)

    return interface

# More details about the model:
#     https://github.com/deepseek-ai/DeepSeek-R1
# export HF_ENDPOINT=https://hf-mirror.com
from typing import Any, List

from openai.types.chat import ChatCompletionUserMessageParam, ChatCompletionAssistantMessageParam
from vllm import LLM, SamplingParams
from vllm.entrypoints.chat_utils import ChatCompletionMessageParam
from zerolan.data.pipeline.llm import LLMQuery, LLMPrediction, Conversation, RoleEnum

from common.abs_model import AbstractModel
from common.decorator import log_model_loading, issue_solver
from llm.deepseek.config import DeepSeekModelConfig


class DeepSeekLLMModel(AbstractModel):

    def __init__(self, config: DeepSeekModelConfig):
        super().__init__()
        self.model_id: str = "deepseek-ai/DeepSeek-R1-Distill-Llama-8B"
        self._model_path: str = config.model_path
        self._max_length: int = config.max_length if config.max_length is not None else 23000
        self._model = None

    @log_model_loading("deepseek-ai/DeepSeek-R1-Distill-Llama-8B")
    @issue_solver()
    def load_model(self):
        self._model = LLM(model=self._model_path, max_model_len=self._max_length, tensor_parallel_size=2)

    def predict(self, llm_query: LLMQuery):
        text, messages = self._to_deepseek_format(llm_query)
        messages.append(ChatCompletionUserMessageParam(content=text, role="user"))
        # See https://github.com/deepseek-ai/DeepSeek-R1?tab=readme-ov-file#usage-recommendations
        # Set the temperature within the range of 0.5-0.7 (0.6 is recommended) to prevent endless repetitions or incoherent outputs.
        outputs = self._model.chat(messages, SamplingParams(temperature=0.6))
        response = outputs[0].outputs[0].text
        messages.append(ChatCompletionAssistantMessageParam(content=response, role="assistant"))
        return self._to_pipeline_format(response, messages)

    def stream_predict(self, *args, **kwargs) -> Any:
        raise NotImplementedError("Not implemented yet")

    @staticmethod
    def _to_pipeline_format(response: str, messages: List[ChatCompletionMessageParam]) -> LLMPrediction:
        history = [Conversation(role=chat['role'], content=chat['content']) for chat in messages]
        llm_response = LLMPrediction(response=response, history=history)
        return llm_response

    @staticmethod
    def _to_deepseek_format(llm_query: LLMQuery):
        text = llm_query.text
        history = []
        for chat in llm_query.history:
            if chat.role == RoleEnum.user:
                history.append(ChatCompletionUserMessageParam(content=chat.content, role="user"))
            elif chat.role == RoleEnum.assistant:
                history.append(ChatCompletionAssistantMessageParam(content=chat.content, role="assistant"))

        return text, history

import argparse
import json
import re
import jsonlines
from fraction import Fraction
from vllm import LLM, SamplingParams
import sys
MAX_INT = sys.maxsize

def is_number(s):
    try:
        float(s)
        return True
    except ValueError:
        pass
    try:
        import unicodedata
        unicodedata.numeric(s)
        return True
    except (TypeError, ValueError):
        pass
    return False

def extract_answer_number(completion):
    text = completion.split('The answer is: ')
    if len(text) > 1:
        extract_ans = text[-1].strip()
        match = re.search(r'[\-+]?\d*[\.,/]?\d+', extract_ans)
        if match:
            if '/' in match.group():
                denominator = match.group().split('/')[1]
                numerator = match.group().split('/')[0]
                if is_number(denominator) == True and is_number(numerator) == True:
                    if denominator == '0':
                        return round(float(numerator.replace(',', '')))
                    else:
                        frac = Fraction(match.group().replace(',', ''))
                        num_numerator = frac.numerator
                        num_denominator = frac.denominator
                        return round(float(num_numerator / num_denominator))
                else:
                    return None
            else:
                if float(match.group().replace(',', '')) == float('inf'):
                    return None
                return round(float(match.group().replace(',', '')))
        else:
            return None
    else:
        return None

def batch_data(data_list, batch_size=1):
    n = len(data_list) // batch_size
    batch_data = []
    for i in range(n-1):
        start = i * batch_size
        end = (i+1)*batch_size
        batch_data.append(data_list[start:end])

    last_start = (n-1) * batch_size
    last_end = MAX_INT
    batch_data.append(data_list[last_start:last_end])
    return batch_data


def gsm8k_test(model, data_path, start=0, end=MAX_INT, batch_size=1, tensor_parallel_size=1):
    INVALID_ANS = "[invalid]"
    gsm8k_ins = []
    gsm8k_answers = []
    problem_prompt = (
        "Below is an instruction that describes a task. "
        "Write a response that appropriately completes the request.\n\n"
        "### Instruction:\n{instruction}\n\n### Response: Let's think step by step."
    )
    print('promt =====', problem_prompt)
    with open(data_path,"r+", encoding="utf8") as f:
        for idx, item in enumerate(jsonlines.Reader(f)):
            temp_instr = problem_prompt.format(instruction=item["query"])
            gsm8k_ins.append(temp_instr)
            temp_ans = item['response'].split('#### ')[1]
            temp_ans = int(temp_ans.replace(',', ''))
            gsm8k_answers.append(temp_ans)

    gsm8k_ins = gsm8k_ins[start:end]
    gsm8k_answers = gsm8k_answers[start:end]
    print('lenght ====', len(gsm8k_ins))
    batch_gsm8k_ins = batch_data(gsm8k_ins, batch_size=batch_size)

    stop_tokens = ["Question:", "Question", "USER:", "USER", "ASSISTANT:", "ASSISTANT", "Instruction:", "Instruction", "Response:", "Response"]
    sampling_params = SamplingParams(temperature=0.0, top_p=1, max_tokens=512, stop=stop_tokens)
    print('sampleing =====', sampling_params)
    llm = LLM(model=model,tensor_parallel_size=tensor_parallel_size)
    result = []
    res_completions = []
    for idx, (prompt, prompt_answer) in enumerate(zip(batch_gsm8k_ins, gsm8k_answers)):
        if isinstance(prompt, list):
            pass
        else:
            prompt = [prompt]

        completions = llm.generate(prompt, sampling_params)
        for output in completions:
            prompt = output.prompt
            generated_text = output.outputs[0].text
            res_completions.append(generated_text)

    invalid_outputs = []
    for idx, (prompt, completion, prompt_answer) in enumerate(zip(gsm8k_ins, res_completions, gsm8k_answers)):
        doc = {'question': prompt}
        y_pred = extract_answer_number(completion)
        if y_pred != None:
            result.append(float(y_pred) == float(prompt_answer))
        else:
            result.append(False)
            temp = {'question': prompt, 'output': completion, 'answer': prompt_answer}
            invalid_outputs.append(temp)
    acc = sum(result) / len(result)
    # print('len invalid outputs ====', len(invalid_outputs), ', valid_outputs===', invalid_outputs)
    print('start===', start, ', end====', end)
    print('gsm8k length====', len(result), ', gsm8k acc====', acc)


def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("--model", type=str)  # model path
    parser.add_argument("--data_file", type=str, default='')  # data path
    parser.add_argument("--start", type=int, default=0) #start index
    parser.add_argument("--end", type=int, default=MAX_INT)  # end index
    parser.add_argument("--batch_size", type=int, default=400)  # batch_size
    parser.add_argument("--tensor_parallel_size", type=int, default=8)  # tensor_parallel_size
    return parser.parse_args()
if __name__ == "__main__":
    args = parse_args()
    gsm8k_test(model=args.model, data_path=args.data_file, start=args.start, end=args.end, batch_size=args.batch_size, tensor_parallel_size=args.tensor_parallel_size)

import copy
import json
from abc import ABC, abstractmethod
from typing import List, Union

from transformers import AutoTokenizer
from vllm import LLM, SamplingParams

PROMPT_TEMPLATE = """"Please act as an impartial judge and evaluate the quality of the responses provided by two AI assistants to the user question displayed below. You should choose the assistant that follows the user\'s instructions and answers the user\'s question better.
Your evaluation should consider factors such as the helpfulness, relevance, accuracy, depth, creativity, and level of detail of their responses. Avoid any position biases and ensure that the order in which the responses were presented does not influence your decision. Do not allow the length of the responses to influence your evaluation. Do not favor certain names of the assistants. Be as objective as possible.
Please directly output your final verdict by strictly following this format: "[[A]]" if assistant A is better, "[[B]]" if assistant B is better.

[User Question]
{question}

[The Start of Assistant A's Answer]
{answer_a}
[The End of Assistant A's Answer]

[The Start of Assistant B's Answer]
{answer_b}
[The End of Assistant B's Answer]
"""


class GenerativePredictor(ABC):
    @abstractmethod
    def compare_fn(
        self,
        question: Union[str, List[str]],
        answer1: Union[str, List[str]],
        answer2: Union[str, List[str]],
    ) -> Union[str, List[str]]:
        pass


class VllmPredictor(GenerativePredictor):
    def __init__(self, model_name, tensor_parallel_size: int = 1, max_model_len: int = 8192):
        self.llm = LLM(model=model_name, tensor_parallel_size=tensor_parallel_size, max_model_len=max_model_len)
        self.tokenizer = AutoTokenizer.from_pretrained(model_name)
        self.sampling_params = SamplingParams(temperature=0.)

    def compare_fn(self, question: str, answer_a: str, answer_b: str) -> Union[str, List[str]]:
        if isinstance(question, str):
            question, answer_a, answer_b = [question], [answer_a], [answer_b]  # type: ignore

        judge_prompts = []
        for ques, ans_a, ans_b in zip(question, answer_a, answer_b):
            judge_prompt = PROMPT_TEMPLATE.format(question=ques, answer_a=ans_a, answer_b=ans_b)
            judge_prompt = self.tokenizer.apply_chat_template(
                [{"role": "user", "content": judge_prompt}],
                tokenize=False, add_generation_prompt=True,
            )
            judge_prompts.append(judge_prompt)
            # print(judge_prompt)

        outputs = self.llm.generate(judge_prompts, self.sampling_params, use_tqdm=False)
        judgments = [output.outputs[0].text for output in outputs]

        results = []
        for judgment in judgments:
            if "[[A]]" in judgment:
                results.append("A")
            elif "[[B]]" in judgment:
                results.append("B")
            else:
                results.append("error")
        return results[0] if len(results) == 1 else results


class SelfTaughtPredictor(VllmPredictor):
    SELF_TAUGHT_WITH_SYSTEM_PROMPT = [
        {
            "role": "system",
            "content": 'Please act as an impartial judge and evaluate the quality of the responses provided by two AI assistants to the user question displayed below. You should choose the assistant that follows the user\'s instructions and answers the user\'s question better. Your evaluation should consider factors such as the helpfulness, relevance, accuracy, depth, creativity, and level of detail of their responses. Begin your evaluation by comparing the two responses and provide a short explanation. Avoid any position biases and ensure that the order in which the responses were presented does not influence your decision. Do not allow the length of the responses to influence your evaluation. Do not favor certain names of the assistants. Be as objective as possible. After providing your explanation, output your final verdict by strictly following this format: \\"[[A]]\\" if assistant A is better, \\"[[B]]\\" if assistant B is better.',
        },
        {
            "role": "user",
            "content": """[User Question]
{input}

[The Start of Assistant A's Answer]
{response_a}
[The End of Assistant A's Answer]

[The Start of Assistant B's Answer]
{response_b}
[The End of Assistant B's Answer]
""",
        },
    ]

    def compare_fn(self, question: str, answer_a: str, answer_b: str) -> Union[str, List[str]]:
        if isinstance(question, str):
            question, answer_a, answer_b = [question], [answer_a], [answer_b]  # type: ignore

        judge_prompts = []
        for ques, ans_a, ans_b in zip(question, answer_a, answer_b):
            conversation = copy.copy(self.SELF_TAUGHT_WITH_SYSTEM_PROMPT)
            conversation[-1]["content"] = conversation[-1]["content"].format(input=ques, response_a=ans_a, response_b=ans_b)
            judge_prompt = self.tokenizer.apply_chat_template(conversation, tokenize=False, add_generation_prompt=True)
            judge_prompts.append(judge_prompt)
            # print(judge_prompt)

        outputs = self.llm.generate(judge_prompts, self.sampling_params, use_tqdm=False)
        judgments = [output.outputs[0].text for output in outputs]

        results = []
        for judgment in judgments:
            if "[[A]]" in judgment:
                results.append("A")
            elif "[[B]]" in judgment:
                results.append("B")
            else:
                results.append("error")
        return results[0] if len(results) == 1 else results


class ConQwen2Predictor(VllmPredictor):
    CON_J_PROMPT = """作为一个评价专家，给定一个问题和它的两个可能的回答，请选出哪一个回答在连贯性、准确性、覆盖度和上述定义的整体质量方面最为符合。请用JSON格式输出你的判断, 其中"原因"是你提供的解释，"更好的回答"是整数类型的1或2，例如{{"原因": "你的解释", "更好的回答": 1}}。以下是问题和候选回答的内容：
    \n问题：{instruction}
回答1：{output_1}
回答2：{output_2}"""

    def compare_fn(self, question: str, answer_a: str, answer_b: str) -> Union[str, List[str]]:
        if isinstance(question, str):
            question, answer_a, answer_b = [question], [answer_a], [answer_b]  # type: ignore

        judge_prompts = []
        for ques, ans_a, ans_b in zip(question, answer_a, answer_b):
            user_prompt = self.CON_J_PROMPT.format(instruction=ques, output_1=ans_a, output_2=ans_b)
            system_prompt = ""
            messages = [
                {"role": "system", "content": system_prompt, },
                {"role": "user", "content": user_prompt},
            ]
            judge_prompt = self.tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
            judge_prompts.append(judge_prompt)
            # print(judge_prompt)

        outputs = self.llm.generate(judge_prompts, self.sampling_params, use_tqdm=False)
        judgments = [output.outputs[0].text for output in outputs]

        results = []
        for judgment in judgments:
            try:
                result = json.loads(judgment.strip())["更好的回答"]
                if int(result) == 1:
                    results.append("A")
                elif int(result) == 2:
                    results.append("B")
                else:
                    results.append("error")
            except Exception:
                results.append("error")
        return results[0] if len(results) == 1 else results


class OffsetBias2Predictor(VllmPredictor):
    prompt_template = """You are a helpful assistant in evaluating the quality of the outputs for a given instruction. Your goal is to select the best output for the given instruction.

Select the Output (a) or Output (b) that is better for the given instruction. The two outputs are generated by two different AI chatbots respectively.
Do NOT provide any explanation for your choice.
Do NOT say both / neither are good.
You should answer using ONLY “Output (a)” or “Output (b)”. Do NOT output any other words.
Here are some rules of the evaluation:
(1) You should prioritize evaluating whether the output honestly/precisely/closely executes the instruction, then consider its helpfulness, accuracy, level of detail, harmlessness, etc.
(2) Outputs should NOT contain more/less than what the instruction asks for, as such outputs do NOT precisely execute the instruction.
(3) You should avoid any potential bias and your judgment should be as objective as possible. For example, the order in which the outputs were presented should NOT affect your judgment, as Output (a) and Output (b) are **equally likely** to be the better.

# Instruction:
{input}
# Output (a):
{output_1}
# Output (b):
{output_2}
# Which is better, Output (a) or Output (b)? Your response should be either “Output (a)” or “Output (b)”:"""

    def compare_fn(self, question: str, answer_a: str, answer_b: str) -> Union[str, List[str]]:
        if isinstance(question, str):
            question, answer_a, answer_b = [question], [answer_a], [answer_b]  # type: ignore

        judge_prompts = []
        for ques, ans_a, ans_b in zip(question, answer_a, answer_b):
            user_message = self.prompt_template.format(input=ques, output_1=ans_a, output_2=ans_b)
            conversation = [{"role": "user", "content": user_message}]
            judge_prompt = self.tokenizer.apply_chat_template(
                conversation,
                tokenize=False,
                add_generation_prompt=True
            )
            judge_prompts.append(judge_prompt)
            # print(judge_prompt)

        outputs = self.llm.generate(judge_prompts, self.sampling_params, use_tqdm=False)
        judgments = [output.outputs[0].text for output in outputs]

        results = []
        for judgment in judgments:
            if judgment == "Output (a)":
                results.append("A")
            elif judgment == "Output (b)":
                results.append("B")
            else:
                results.append("error")
        return results[0] if len(results) == 1 else results


class CompassJudgerPredictor(VllmPredictor):
    prompt_template = """**Input**: ```Please read the dialogue between the two assistants and the user to determine which assistant performed better during the conversation.Here is the dialogue content:
[Dialogue Begin]
User: {input}
Assistant A: {output_1}
Assistant B: {output_2}
[Dialogue End]
If you believe Assistant A performed better, please output A directly.\nIf you believe Assistant B performed better, please output B directly.\nDo not output any other content, just the option. Please output:```"""

    def compare_fn(self, question: str, answer_a: str, answer_b: str) -> Union[str, List[str]]:
        if isinstance(question, str):
            question, answer_a, answer_b = [question], [answer_a], [answer_b]  # type: ignore

        judge_prompts = []
        for ques, ans_a, ans_b in zip(question, answer_a, answer_b):
