import pytest

from vllm import SamplingParams
from vllm.config import ModelConfig
from vllm.entrypoints.openai.protocol import ChatCompletionRequest

MODEL_NAME = "Qwen/Qwen1.5-7B"


def test_max_tokens_none():
    """max_tokens=None should be allowed"""
    SamplingParams(temperature=0.01, top_p=0.1, max_tokens=None)


@pytest.fixture(scope="module")
def model_config():
    return ModelConfig(
        MODEL_NAME,
        seed=0,
        dtype="float16",
    )


@pytest.fixture(scope="module")
def default_max_tokens():
    return 4096


def test_sampling_params_from_request_with_no_guided_decoding_backend(
        model_config, default_max_tokens):
    # guided_decoding_backend is not present at request level
    request = ChatCompletionRequest.model_validate({
        'messages': [{
            'role': 'user',
            'content': 'Hello'
        }],
        'model':
        MODEL_NAME,
        'response_format': {
            'type': 'json_object',
        },
    })

    sampling_params = request.to_sampling_params(
        default_max_tokens,
        model_config.logits_processor_pattern,
    )
    # we do not expect any backend to be present and the default
    # guided_decoding_backend at engine level will be used.
    assert sampling_params.guided_decoding.backend is None


@pytest.mark.parametrize("request_level_guided_decoding_backend,expected",
                         [("xgrammar", "xgrammar"), ("guidance", "guidance"),
                          ("outlines", "outlines")])
def test_sampling_params_from_request_with_guided_decoding_backend(
        request_level_guided_decoding_backend: str, expected: str,
        model_config, default_max_tokens):

    request = ChatCompletionRequest.model_validate({
        'messages': [{
            'role': 'user',
            'content': 'Hello'
        }],
        'model':
        MODEL_NAME,
        'response_format': {
            'type': 'json_object',
        },
        'guided_decoding_backend':
        request_level_guided_decoding_backend,
    })

    sampling_params = request.to_sampling_params(
        default_max_tokens,
        model_config.logits_processor_pattern,
    )
    # backend correctly identified in resulting sampling_params
    assert sampling_params.guided_decoding.backend == expected

import logging
from multiprocessing import pool
from time import sleep  # Import sleep from the time module
import random
import os
import yaml
from pathlib import Path
from typing import Any, Callable, Collection, Optional, Type, TypeVar

from openai import AuthenticationError, BadRequestError, OpenAI
from tqdm import tqdm
from transformers import AutoTokenizer

from .config import LLMConfig

Q = TypeVar("Q", bound=Callable[..., Any])

logger = logging.getLogger(__name__)


class FakeCompletions:
    def __init__(self, results):
        # make it so that this works
        # Completions = FakeChatCompletions(results)
        # c = [choice.message.content for choice in Completions.choices]

        self.results = results[0]

    @property
    def choices(self):
        return [
            type(
                "Choice",
                (),
                {
                    "text": res.text,
                    "logprobs": res.logprobs,
                },
            )()
            for res in self.results.outputs
        ]


class FakeChatCompletions:
    def __init__(self, results):
        # make it so that this works
        # Completions = FakeChatCompletions(results)
        # c = [choice.message.content for choice in Completions.choices]

        self.results = results[0]

    @property
    def choices(self):
        return [
            type(
                "Choice",
                (),
                {
                    "message": type("Message", (), {"content": res.text})(),
                    "logprobs": res.logprobs,
                },
            )()
            for res in self.results.outputs
        ]


class DummyClient:
    @property
    def completions(self):
        return self

    def __init__(self, dummy_message: str = "(A) debug") -> None:
        self.dummy_message = dummy_message
        self.chat = self

    def create(self, **kwargs):
        dummy_message = self.dummy_message

        class DummyChoice:
            def __init__(self):
                self.message = type("DummyMessage", (), {"content": dummy_message})()
                self.logprobs = None

        class DummyResponse:
            def __init__(self):
                self.choices = [DummyChoice()]

        return DummyResponse()


class LLMEngine:
    def __init__(self, llm_config: LLMConfig) -> None:
        self._config = llm_config
        self._load_models()
        self.hosted_vllm = False
        self.prepare_llm(
            model_name=llm_config.model_name,
            port=llm_config.port,
            tokenizer=llm_config.tokenizer,
            need_tokenizer=llm_config.need_tokenizer,
        )

        logger.info(f"Initialized LLM Engine with model: {self._model_name_str}")
        logger.info(f"API Provider: {self._api_provider}")
        logger.info(f"is_instruct: {self._is_instruct}")
        logger.info(f"is_reasoning: {self._is_reasoning}")

    def _load_models(self) -> None:
        models_path = Path(__file__).parent.parent / "models" / "models.yaml"
        try:
            with open(models_path, "r") as f:
                models = yaml.safe_load(f)
                self.model_list = models["models"]
        except Exception as e:
            logger.error(f"Error loading models.yaml: {e}")
            self.model_list = []

    def prepare_llm(
        self,
        model_name: str,
        port: int,
        tokenizer: str = None,
        need_tokenizer: bool = False,
    ) -> None:
        if "localhost" == model_name:  # local serving
            self.client = OpenAI(
                api_key="EMPTY",
                base_url=f"http://localhost:{port}/v1",  # base_url=f"http://127.0.0.1:{port}/v1",
            )
            # get model name
            models = self.client.models.list()
            model = next(iter(models)).id
            self._model_name_str = model.split("/")[-1]

            llm = next(
                (llm for llm in self.model_list if llm["model_name"] == model), None
            )
            self._model_name = model
            self._api_provider = "localhost"
            if llm is None:
                logger.error(f"Unrecognized local model: {model}")
                self._is_instruct = self._config.is_instruct
                self._is_reasoning = self._config.is_reasoning
            else:
                self._is_instruct = llm["is_instruct"]
                self._is_reasoning = llm["is_reasoning"]
        else:
            # get match in LLMS
            llm = next(
                (llm for llm in self.model_list if llm["model_name"] == model_name),
                None,
            )
            if llm is None:  # model not found in models.yaml
                model = model_name
                self._model_name = model
                self._model_name_str = model.split("/")[-1]
                self._api_provider = None
                self._is_instruct = self._config.is_instruct
                self._is_reasoning = self._config.is_reasoning
                logger.warning(
                    f"Unrecognized model: {model} - default is_instruct = {self._config.is_instruct}, is_reasoning = {self._config.is_reasoning}"
                )
            else:
                model = llm["model_name"]
                self._model_name = model
                self._model_name_str = model.split("/")[-1]
                self._api_provider = llm["api_provider"]
                self._is_instruct = llm["is_instruct"]
                self._is_reasoning = llm["is_reasoning"]
            if self._api_provider == "openai":  # openai
                self.client = OpenAI(
                    api_key=os.environ.get("OPENAI_API_KEY"),
                    base_url="https://api.openai.com/v1",
                )

                if self._config.stop:
                    if len(self._config.stop) > 4:
                        self._config.stop = self._config.stop[:4]

            elif self._api_provider == "deepseek":  # deepseek
                self.client = OpenAI(
                    api_key=os.environ.get("DEEPSEEK_API_KEY"),
                    base_url="https://api.deepseek.com",
                )

            elif self._api_provider == "google":  # google
                self.client = OpenAI(
                    api_key=os.environ.get("GOOGLE_API_KEY"),
                    base_url="https://generativelanguage.googleapis.com/v1beta/openai/",
                )

            elif self._api_provider == "dummy":  # dummy
                self.client = DummyClient()

            else:
                import torch
                from vllm import LLM

                num_gpus = (
                    self._config.num_gpus
                    if self._config.num_gpus >= 0
                    else torch.cuda.device_count()
                )
                if num_gpus == 0:
                    logger.warning("No GPUs found, using CPU for vLLM.")
                    self.client = LLM(model=model, tokenizer=tokenizer)
                else:
                    logger.info(f"Using {num_gpus} GPUs for vLLM.")
                if "mistral" in model.lower():
                    self.client = LLM(
                        model=model,
                        tokenizer=tokenizer,
                        tokenizer_mode="mistral",
                        tensor_parallel_size=num_gpus,
                    )
                else:
                    self.client = LLM(
                        model=model, tokenizer=tokenizer, tensor_parallel_size=num_gpus
                    )

                self.hosted_vllm = True

                # raise ValueError(f"Invalid API provider: {self._api_provider}")

        try:
            if tokenizer is not None and isinstance(tokenizer, str) and need_tokenizer:
                self.tokenizer = AutoTokenizer.from_pretrained(tokenizer)
            elif need_tokenizer:
                self.tokenizer = AutoTokenizer.from_pretrained(model)
            else:
                self.tokenizer = None
        except Exception as e:
            logger.info(f"Could not load tokenizer for model: {model}")
            self.tokenizer = None
            # logger.error(f"Using default tokenizer: meta-llama/Llama-3.1-8B-Instruct")
            # # Default to Llama-3.1 tokenizer
            # self.tokenizer = AutoTokenizer.from_pretrained(
            #     "meta-llama/Llama-3.1-8B-Instruct"
            # )

    def reinitialize(self) -> None:
        self.prepare_llm(
            model_name=self._model_name,
            port=self._config.port,
            tokenizer=self._config.tokenizer,
        )

    def update_config(self, **kwargs) -> None:
        for key, value in kwargs.items():
            setattr(self._config, key, value)
            # for each key, value in kwargs
            logging.info(f"Updated config: {key} = {value}")

    # define a retry decorator
    def retry_with_exponential_backoff(
        initial_delay: float = 1,
        exponential_base: float = 2,
        jitter: bool = True,
        max_retries: int = 10,
        no_retry_on: Optional[Collection[Type[Exception]]] = None,
    ) -> Callable[[Q], Q]:
        """Retry a function with exponential backoff."""

        def decorator(func: Q) -> Q:
            def wrapper(*args, **kwargs):
                # Initialize variables
                num_retries = 0
                delay = initial_delay
                error = None

                # Loop until a successful response or max_retries is hit or an exception is raised
                while num_retries <= max_retries:
                    try:
                        return func(*args, **kwargs)
                    # Raise exceptions for any errors specified
                    except Exception as e:
                        if no_retry_on is not None and type(e) in no_retry_on:
                            raise e
                        # Sleep for the delay
                        sleep(delay)
                        # Increment the delay
                        delay *= exponential_base * (1 + jitter * random.random())
                        # Set the error to the last exception
                        error = e
                        # Increment retries
                        num_retries += 1
                        logger.warning(
                            f"Retrying {func.__name__} after error: {e} (retry {num_retries} of {max_retries})"
                        )
                if error is not None:
                    raise error

            return wrapper

        return decorator

    def llm_completion(self, prompt, **kwargs):
        if self.hosted_vllm:
            from vllm import SamplingParams

            if "extra_headers" in kwargs.keys():
                extra_headers = kwargs["extra_headers"]
                # cast min_p to an integer
                if "min_p" in extra_headers.keys():
                    extra_headers["min_p"] = float(extra_headers["min_p"])

                kwargs = {**kwargs, **extra_headers}
                del kwargs["extra_headers"]
                del kwargs["model"]
            sp = SamplingParams(**kwargs)

            output = self.client.generate([prompt], sampling_params=sp, use_tqdm=False)
            # will need to post process output
            output = FakeCompletions(output)

            return output
        else:
            return self.client.completions.create(prompt=prompt, **kwargs)

    def llm_chat(self, messages, **kwargs):
        if self.hosted_vllm:
            from vllm import SamplingParams

            if "extra_headers" in kwargs.keys():
                extra_headers = kwargs["extra_headers"]
                # cast min_p to an integer
                if "min_p" in extra_headers.keys():
                    extra_headers["min_p"] = float(extra_headers["min_p"])

                kwargs = {**kwargs, **extra_headers}
                del kwargs["extra_headers"]
                del kwargs["model"]
            sp = SamplingParams(**kwargs)

            output = self.client.chat(
                messages=messages,
                sampling_params=sp,
            )
            # will need to post process output
            output = FakeChatCompletions(output)

            return output
        else:
            return self.client.chat.completions.create(messages=messages, **kwargs)

    def generate(
        self,
        model_prompt,
        system_prompt: str = "",
        n=1,
        return_raw: bool = False,
    ) -> str | list[str] | None:
        output = None
        try:
            if self._is_reasoning:
                assert isinstance(model_prompt, str | list)
                if isinstance(model_prompt, str):
                    output = self.prompt_llm_reasoning(
                        model_prompt=model_prompt, system_prompt=system_prompt, n=n
                    )
                elif isinstance(model_prompt, list):
                    output = self.prompt_llm_reasoning_with_messages(
                        messages=model_prompt, n=n
                    )
            elif not self._is_instruct:
                assert isinstance(model_prompt, str)
                output = self.prompt_llm(prompt=model_prompt, n=n)
            else:
                if isinstance(model_prompt, str) and system_prompt is not None:
                    output = self.prompt_llm_chat(
                        system_prompt=system_prompt, user_prompt=model_prompt, n=n
                    )
                elif isinstance(model_prompt, list):
                    output = self.prompt_llm_chat_with_messages(
                        messages=model_prompt, n=n
                    )
                else:
                    messages = [
                        {"role": "user", "content": model_prompt},
                    ]
                    output = self.prompt_llm_chat_with_messages(messages=messages, n=n)
        except BadRequestError as e:
            logger.error(f"Error: {e}")
            return None

        if return_raw:
            return output

        return self._extract_text(output)

    @retry_with_exponential_backoff(
        max_retries=20,
        no_retry_on=(AuthenticationError, BadRequestError),
    )
    def prompt_llm(
        self,
        prompt: str,
        n: int = 1,
    ):
        assert n >= 1
        model_name = self._model_name
        max_tokens = self._config.max_tokens
        temperature = self._config.temperature
        stop = self._config.stop
        logprobs = self._config.logprobs
        top_p = self._config.top_p
        min_p = self._config.min_p
        echo = self._config.echo
        if self.hosted_vllm:
            return self.llm_completion(
                prompt=prompt,
                model=model_name,
                max_tokens=max_tokens,
                temperature=temperature,
                stop=stop,
                logprobs=logprobs,
                top_p=top_p,
                n=n,
                extra_headers={"min_p": f"{min_p}"},
            )

        if logprobs > 0:
            return self.client.completions.create(
                model=model_name,
                prompt=prompt,
                max_tokens=max_tokens,
                temperature=temperature,
                stop=stop,
                logprobs=logprobs,
                top_p=top_p,
                echo=echo,
                n=n,
                top_logprobs=logprobs,
                extra_headers={"min_p": f"{min_p}"},
            )
        else:
            return self.client.completions.create(
                model=model_name,
                prompt=prompt,
                max_tokens=max_tokens,
                temperature=temperature,
                stop=stop,
                top_p=top_p,
                echo=echo,
                n=n,
                extra_headers={"min_p": f"{min_p}"},
            )

    @retry_with_exponential_backoff(
        max_retries=20,
        no_retry_on=(AuthenticationError, BadRequestError),
    )
    def prompt_llm_chat(
        self,
        system_prompt: str,
        user_prompt: str,
        n=1,
    ):
        assert n >= 1
        model_name = self._model_name
        max_tokens = self._config.max_tokens
        temperature = self._config.temperature
        stop = self._config.stop
        top_p = self._config.top_p
        logprobs = self._config.logprobs
        min_p = self._config.min_p

        if logprobs > 0:
            return self.llm_chat(
                model=model_name,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_prompt},
                ],
                max_tokens=max_tokens,
                temperature=temperature,
                top_p=top_p,
                n=n,
                logprobs=logprobs,
                top_logprobs=logprobs,
                extra_headers={"min_p": f"{min_p}"},
            )
        else:
            return self.llm_chat(
                model=model_name,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_prompt},
                ],
                max_tokens=max_tokens,
                temperature=temperature,
                top_p=top_p,
                n=n,
                extra_headers={"min_p": f"{min_p}"},
            )

    @retry_with_exponential_backoff(
        max_retries=20,
        no_retry_on=(AuthenticationError, BadRequestError),
    )
    def prompt_llm_reasoning(
        self,
        model_prompt: str,
        system_prompt: str = "",
        n=1,
    ):
        assert n >= 1
        model_name = self._model_name

        return self.llm_chat(
            model=model_name,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": model_prompt},
            ],
            n=n,
            temperature=self._config.temperature,
            top_p=self._config.top_p,
        )

    @retry_with_exponential_backoff(
        max_retries=20,
        no_retry_on=(AuthenticationError, BadRequestError),
    )
    def prompt_llm_reasoning_with_messages(
        self,
        messages: list[dict],
        n=1,
    ):
        assert n >= 1
        model_name = self._model_name

        return self.llm_chat(
            model=model_name,
            messages=messages,
            n=n,
            temperature=self._config.temperature,
            top_p=self._config.top_p,
        )

    @retry_with_exponential_backoff(
        max_retries=20,
        no_retry_on=(AuthenticationError, BadRequestError),
    )
    def prompt_llm_chat_with_messages(
        self,
        messages: list,
        n=1,
    ) -> str | list[str] | None:
        assert n >= 1
        model_name = self._model_name
        max_tokens = self._config.max_tokens
        temperature = self._config.temperature
        stop = self._config.stop
        top_p = self._config.top_p
        logprobs = self._config.logprobs
        min_p = self._config.min_p
        if logprobs > 0:
            return self.llm_chat(
                model=model_name,
                messages=messages,
                max_tokens=max_tokens,
                temperature=temperature,
                top_p=top_p,
                n=n,
                logprobs=logprobs,
                top_logprobs=logprobs,
                extra_headers={"min_p": f"{min_p}"},
            )
        else:
            return self.llm_chat(
                model=model_name,
                messages=messages,
                max_tokens=max_tokens,
                temperature=temperature,
                top_p=top_p,
                n=n,
                extra_headers={"min_p": f"{min_p}"},
            )

    def _extract_text(self, output):
        if output is None:
            return None
        texts = []

        for choice in getattr(output, "choices", []):
            if hasattr(choice, "message"):  # chat completions
                texts.append(getattr(choice.message, "content", ""))
            else:  # completions
                texts.append(getattr(choice, "text", ""))
        if len(texts) == 1:
            return texts[0]
        return texts

    def parallel_generator(
        self,
        f,
        input_list: list[Any],
        output_dict: dict,
        n: int,
        parallel_case_ids: list[int],
        num_processes: int = 4,
    ):
        with pool.ThreadPool(num_processes) as p:
            list(
                tqdm(
                    p.imap(
                        lambda case_id: f(
                            case_id,
                            input_data=input_list[case_id],
                            output_dict=output_dict,
                            n=n,
                        ),
                        parallel_case_ids,
                    ),
                    total=len(parallel_case_ids),
                    desc=f"Running {f.__name__} with {self._model_name_str}",
                )
            )

    def __repr__(self) -> str:
        return (
            f"LLMEngine("
            f"model_name='{self._model_name_str}', "
            f"api_provider='{self._api_provider}', "
            f"is_instruct={self._is_instruct}, "
            f"is_reasoning={self._is_reasoning}, "
            f"max_tokens={self._config.max_tokens}, "
            f"temperature={self._config.temperature}, "
            f"top_p={self._config.top_p}, "
            f"min_p={self._config.min_p}, "
            f"stop={self._config.stop}, "
            f"logprobs={self._config.logprobs}, "
            f"echo={self._config.echo}, "
            f")"
        )

    def __getattr__(self, name):
        config_attrs = {
            "temperature",
            "top_p",
            "max_tokens",
            "min_p",
            "stop",
            "logprobs",
            "echo",
        }
        if name in config_attrs:
            return getattr(self._config, name)
        raise AttributeError(f"No attribute '{name}'")

    @property
    def model_name(self) -> str:
        return self._model_name_str

    @property
    def api_provider(self) -> str:
        return self._api_provider

    @property
    def is_instruct(self) -> bool:
        return self._is_instruct

    @is_instruct.setter
    def is_instruct(self, value: bool) -> None:
        self._is_instruct = value
        self._config.is_instruct = value

    @property
    def is_reasoning(self) -> bool:
        return self._is_reasoning

    @is_reasoning.setter
    def is_reasoning(self, value: bool) -> None:
        self._is_reasoning = value
        self._config.is_reasoning = value

    @property
    def config(self) -> LLMConfig:
        return self._config

import os
import json
import random
from typing import Optional, Tuple, List, Dict, Union
from concurrent.futures import ThreadPoolExecutor
from tqdm import tqdm
import torch
import numpy as np
from fastchat.model import get_conversation_template, load_model
from ftfy import fix_text
from transformers.generation import GenerationConfig
from vllm import LLM, SamplingParams, RequestOutput

from utils.rankllm import PromptMode, RankLLM
from utils.result import Result

ALPH_START_IDX = ord('A') - 1

class RankListwiseOSLLM(RankLLM):
    def __init__(
        self,
        model: str,
        context_size: int = 4096,
        prompt_mode: PromptMode = PromptMode.RANK_GPT,
        num_few_shot_examples: int = 0,
        device: str = "cuda",
        num_gpus: int = 1,
        variable_passages: bool = False,
        window_size: int = 20,
        system_message: str = None,
        batched: bool = False,
    ) -> None:
        super().__init__(model, context_size, prompt_mode, num_few_shot_examples)
        self._device = device
        if self._device == "cuda":
            assert torch.cuda.is_available(), "CUDA is not available on this device"
        if prompt_mode != PromptMode.RANK_GPT:
            raise ValueError(
                f"Unsupported prompt mode: {prompt_mode}. Only RANK_GPT is supported."
            )

        self._llm = LLM(model=model, max_logprobs=30, enforce_eager=False)
        self._tokenizer = self._llm.get_tokenizer()
        self.system_message_supported = "system" in self._tokenizer.chat_template
        self._batched = batched
        self._variable_passages = variable_passages
        self._window_size = window_size
        self._system_message = system_message
        self._output_token_estimate = None

        if num_few_shot_examples > 0:
            with open("data/output_v2_aug_filtered.jsonl", "r") as json_file:
                self._examples = list(json_file)[1:-1]

    def _evaluate_logits(self, logits: Dict[str, 'Logit'], use_alpha: bool, total: Tuple[int, int]) -> Tuple[str, Dict[int, float]]:
        if use_alpha:
            evaluations = {
                ord(logit.decoded_token): logit.logprob
                for logit in logits.values()
                if len(logit.decoded_token) == 1 and 
                   logit.decoded_token.isalpha() and 
                   ALPH_START_IDX + 1 <= ord(logit.decoded_token) <= ALPH_START_IDX + self._window_size
            }
            sorted_evaluations = sorted(evaluations.items(), key=lambda x: -x[1])
            result_string = ">".join([f"[{chr(x)}]" for x, y in sorted_evaluations])
        else:
            evaluations = {
                int(logit.decoded_token): logit.logprob
                for logit in logits.values()
                if logit.decoded_token.isnumeric() and
                   not unicodedata.name(logit.decoded_token).startswith(('SUPERSCRIPT', 'VULGAR FRACTION', 'SUBSCRIPT')) and
                   total[0] <= int(logit.decoded_token) <= total[1]
            }
            sorted_evaluations = sorted(evaluations.items(), key=lambda x: -x[1])
            result_string = ">".join([f"[{x}]" for x, y in sorted_evaluations])

        return result_string, evaluations

    def _get_logits_single_digit(self, output: RequestOutput, use_alpha: bool = False, effective_location: int = 1, total: Tuple[int, int] = (1, 9)):
        logits = output.outputs[0].logprobs[effective_location]
        return self._evaluate_logits(logits, use_alpha, total)

    def run_llm_batched(
        self,
        prompts: List[Union[str, List[Dict[str, str]]]],
        current_window_size: Optional[int] = None,
        use_logits: bool = False,
        use_alpha: bool = False,
    ) -> List[Tuple[str, int]]:
        if current_window_size is None:
            current_window_size = self._window_size

        temp = 0.0
        if use_logits:
            params = SamplingParams(
                min_tokens=2,
                max_tokens=2, 
                temperature=temp,
                logprobs=30,
            )
            outputs = self._llm.generate(prompts, sampling_params=params, use_tqdm=True)
            arr = [self._get_logits_single_digit(output, use_alpha=use_alpha) for output in outputs]
            return [(s, len(s)) for s, __ in arr]
        else:
            params = SamplingParams(
                temperature=temp,
                max_tokens=self.num_output_tokens(use_alpha, current_window_size),
                min_tokens=self.num_output_tokens(use_alpha, current_window_size),
            )
            outputs = self._llm.generate(prompts, sampling_params=params, use_tqdm=True)
            return [
                (output.outputs[0].text, len(output.outputs[0].token_ids))
                for output in outputs
            ]

    def run_llm(
        self, prompt: str, current_window_size: Optional[int] = None, use_logits: bool = False, use_alpha: bool = False
    ) -> Tuple[str, int]:
        if current_window_size is None:
            current_window_size = self._window_size

        temp = 0.0
        if use_logits:
            params = SamplingParams(min_tokens=1, max_tokens=1, temperature=temp, logprobs=30)
            output = self._llm.generate([prompt+"["], sampling_params=params, use_tqdm=False)[0]
            s, _ = self._get_logits_single_digit(output, effective_location=0, use_alpha=use_alpha)
            return s, len(s)
        else:
            max_new_tokens = self.num_output_tokens(use_alpha, current_window_size)
            params = SamplingParams(min_tokens=max_new_tokens, max_tokens=max_new_tokens, temperature=temp)
            output = self._llm.generate([prompt], sampling_params=params, use_tqdm=False)[0]
            return output.outputs[0].text, len(output.outputs[0].text)

    def num_output_tokens(self, use_alpha: bool, current_window_size: Optional[int] = None) -> int:
        if current_window_size is None:
            current_window_size = self._window_size

        if self._output_token_estimate and self._window_size == current_window_size:
            return self._output_token_estimate

        if use_alpha:
            token_str = " > ".join([f"[{i+1}]" for i in range(current_window_size)])
        else:
            token_str = " > ".join([f"[{chr(ALPH_START_IDX+i+1)}]" for i in range(current_window_size)])

        _output_token_estimate = len(self._tokenizer.encode(token_str)) - 1

        if self._window_size == current_window_size:
            self._output_token_estimate = _output_token_estimate

        return _output_token_estimate

    def _add_prefix_prompt(self, use_alpha, query: str, num: int) -> str:
        if use_alpha:
            return f"I will provide you with {num} passages, each indicated by a alphabetical identifier []. Rank the passages based on their relevance to the search query: {query}.\n"
        else:
            return f"I will provide you with {num} passages, each indicated by a numerical identifier []. Rank the passages based on their relevance to the search query: {query}.\n"

    def _add_post_prompt(self, use_alpha, query: str, num: int) -> str:
        if use_alpha:
            example_ordering = "[B] > [A]" if self._variable_passages else "[D] > [B]"
        else:
            example_ordering = "[2] > [1]" if self._variable_passages else "[4] > [2]"
        return f"Search Query: {query}.\nRank the {num} passages above based on their relevance to the search query. All the passages should be included and listed using identifiers, in descending order of relevance. The output format should be [] > [], e.g., {example_ordering}, Only respond with the ranking results, do not say any word or explain."

    def _add_few_shot_examples(self, conv):
        for _ in range(self._num_few_shot_examples):
            ex = random.choice(self._examples)
            obj = json.loads(ex)
            prompt = obj["conversations"][0]["value"]
            response = obj["conversations"][1]["value"]
            conv.append_message(conv.roles[0], prompt)
            conv.append_message(conv.roles[1], response)
        return conv

    def _add_few_shot_examples_messages(self, messages):
        for _ in range(self._num_few_shot_examples):
            ex = random.choice(self._examples)
            obj = json.loads(ex)
            prompt = obj["conversations"][0]["value"]
            response = obj["conversations"][1]["value"]
            messages.append({"role": "user", "content": prompt})
            messages.append({"role": "assistant", "content": response})
        return messages

    def create_prompt(self, result: Result, use_alpha: bool, rank_start: int, rank_end: int) -> Tuple[str, int]:
        query = result.query
        num = len(result.hits[rank_start:rank_end])
        max_length = 300
        while True:
            messages = list()
            if self._system_message and self.system_message_supported:
                messages.append({"role": "system", "content": self._system_message})
            messages = self._add_few_shot_examples_messages(messages)
            prefix = self._add_prefix_prompt(use_alpha, query, num)
            rank = 0
            input_context = f"{prefix}\n"
            for hit in result.hits[rank_start:rank_end]:
                rank += 1
                content = hit["content"].replace("Title: Content: ", "").strip()
                content = " ".join(content.split()[:max_length])
                identifier = chr(ALPH_START_IDX + rank) if use_alpha else str(rank)
                input_context += f"[{identifier}] {self._replace_number(content, use_alpha)}\n"
            input_context += self._add_post_prompt(use_alpha, query, num)
            messages.append({"role": "user", "content": input_context})
            if self._system_message and not self.system_message_supported:
                messages[0]["content"] = self._system_message + "\n " + messages[0]["content"]
            prompt = self._tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
            prompt = fix_text(prompt)
            num_tokens = self.get_num_tokens(prompt)
            if num_tokens <= self.max_tokens() - self.num_output_tokens(rank_end - rank_start):
                break
            else:
                max_length -= max(
                    1,
                    (
                        num_tokens - self.max_tokens() + self.num_output_tokens(rank_end - rank_start)
                    ) // ((rank_end - rank_start) * 4),
                )
        return prompt, num_tokens

    def create_prompt_batched(
        self,
        results: List[Result],
        use_alpha: bool,
        rank_start: int,
        rank_end: int,
        batch_size: int = 32,
    ) -> List[Tuple[str, int]]:
        def chunks(lst, n):
            """Yield successive n-sized chunks from lst."""
            for i in range(0, len(lst), n):
                yield lst[i : i + n]

        all_completed_prompts = []

        with ThreadPoolExecutor() as executor:
            for batch in tqdm(chunks(results, batch_size), desc="Processing batches"):
                completed_prompts = list(
                    executor.map(
                        lambda result: self.create_prompt(result, use_alpha, rank_start, rank_end),
                        batch,
                    )
                )
                all_completed_prompts.extend(completed_prompts)
        return all_completed_prompts

    def get_num_tokens(self, prompt: str) -> int:
        return len(self._tokenizer.encode(prompt))

    def cost_per_1k_token(self, input_token: bool) -> float:
        return 0

