class VLLMServerModel(ApiModel):
    """Model to use [vLLM](https://docs.vllm.ai/) server endpoint for fast LLM inference and serving.

    Parameters:
        model_id (`str`):
            The model identifier to use on the server (e.g. "gpt-3.5-turbo").
        api_base (`str`, *optional*):
            The base URL of the VLLM server endpoint.
        api_key (`str`, *optional*):
            The API key to use for authentication.
        custom_role_conversions (`dict[str, str]`, *optional*):
            Custom role conversion mapping to convert message roles in others.
            Useful for specific models that do not support specific message roles like "system".
        flatten_messages_as_text (`bool`, default `False`):
            Whether to flatten messages as text.
        **kwargs:
            Additional keyword arguments to pass to the VLLM server API.
    """

    def __init__(
        self,
        model_id: str,
        api_base: Optional[str] = "http://0.0.0.0:8000/v1",
        api_key: Optional[str] = "token-abc",
        custom_role_conversions: Optional[Dict[str, str]] = None,
        flatten_messages_as_text: bool = True,
        lora_name: str = None,
        **kwargs,
    ):
        if importlib.util.find_spec("openai") is None:
            raise ModuleNotFoundError(
                "Please install 'openai' extra to use VLLMServerModel: `pip install 'smolagents[openai]'`"
            )
        super().__init__(flatten_messages_as_text=flatten_messages_as_text, **kwargs)
        self.model_id = model_id
        self.custom_role_conversions = custom_role_conversions
        self.client_kwargs = {
            "api_key": api_key,
            "base_url": api_base,
        }
        self.client = self.create_client()
        self.lora_name = lora_name

    def create_client(self):
        import openai

        return openai.OpenAI(**self.client_kwargs)

    def reassign_api_base(self, new_api_base):
        self.client_kwargs["base_url"] = new_api_base
        self.client = self.create_client()

    def __call__(
        self,
        messages: List[Dict[str, str]],
        stop_sequences: Optional[List[str]] = None,
        grammar: Optional[str] = None,
        tools_to_call_from: Optional[List[Tool]] = None,
        **kwargs,
    ) -> ChatMessage:
        # Preprocess messages for VLLM server
        messages = remove_tool_call_from_messages(messages)
        kwargs["extra_body"] = {"chat_template_kwargs": {"enable_thinking": False}}

        completion_kwargs = self._prepare_completion_kwargs(
            messages=messages,
            stop_sequences=stop_sequences,
            grammar=grammar,
            tools_to_call_from=tools_to_call_from,
            model=self.model_id,
            custom_role_conversions=self.custom_role_conversions,
            convert_images_to_image_urls=True,
            **kwargs,
        )

        if prefix := completion_kwargs.pop("prefix", None):
            completion_kwargs["messages"].append(
                {
                    "role": MessageRole.ASSISTANT,
                    "content": prefix
                }
            )
            completion_kwargs["extra_body"]["add_generation_prompt"] = False
            completion_kwargs["extra_body"]["continue_final_message"] = True

        if self.lora_name:
            completion_kwargs["model"] = self.lora_name

        response = self.client.chat.completions.create(**completion_kwargs)
        self.last_input_token_count = response.usage.prompt_tokens
        self.last_output_token_count = response.usage.completion_tokens

        if prefix:
            for choice in response.choices:
                choice.message.content = prefix + choice.message.content # in-place replacement

        if len(response.choices) == 1:
            first_message = ChatMessage.from_dict(
                response.choices[0].message.model_dump(include={"role", "content", "tool_calls"}),
                raw=response,
            )
            return self.postprocess_message(first_message, tools_to_call_from)
        else:
            all_messages = []
            for choice in response.choices:
                _message = ChatMessage.from_dict(
                    choice.message.model_dump(include={"role", "content", "tool_calls"}),
                    raw=response,
                )
                all_messages.append(self.postprocess_message(_message, tools_to_call_from))
            return all_messages


