from __future__ import annotations

import os
import sys
import warnings
import math
import logging

import torch

from ..base import BaseModel
from .prompt import Qwen2VLPromptMixin
from ...smp import get_rank_and_world_size, get_gpu_memory, listinstr
from ...dataset import DATASET_MODALITY

VLLM_MAX_IMAGE_INPUT_NUM = 24


def ensure_image_url(image: str) -> str:
    prefixes = ['http://', 'https://', 'file://', 'data:image;']
    if any(image.startswith(prefix) for prefix in prefixes):
        return image
    if os.path.exists(image):
        return 'file://' + image
    raise ValueError(f'Invalid image: {image}')


def ensure_video_url(video: str) -> str:
    prefixes = ['http://', 'https://', 'file://', 'data:video;']
    if any(video.startswith(prefix) for prefix in prefixes):
        return video
    if os.path.exists(video):
        return 'file://' + video
    raise ValueError(f'Invalid video: {video}')


def create_image_content(image_path, min_pixels, max_pixels):
    base64_image, mime_type = encode_image(image_path)
    return {
        "type": "image",
        "image": f"data:{mime_type};base64,{base64_image}",
        'min_pixels': min_pixels,
        'max_pixels': max_pixels
    }


def encode_image(image_path, max_side=None):
    from mimetypes import guess_type
    mime_type, _ = guess_type(image_path)
    if mime_type is None:
        mime_type = "image/jpeg"
    image_format = mime_type.split("/")[-1].upper() if mime_type else "JPEG"

    from PIL import Image
    image = Image.open(image_path)
    # Handle the alpha channel
    if image.mode == "RGBA":
        image = _rgba_to_rgb(image)
    if max_side:
        image = _resize_image(image, max_side)
    encoded_image = _encode_image(image, image_format)

    return encoded_image, mime_type


def _encode_image(image, image_format):
    from io import BytesIO
    with BytesIO() as output:
        image.convert("RGB").save(output, format=image_format)
        import base64
        base64_encoded_data = base64.b64encode(output.getvalue()).decode("utf-8")
    return base64_encoded_data


def _rgba_to_rgb(image):
    from PIL import Image
    background = Image.new("RGBA", image.size, (255, 255, 255, 255))
    return Image.alpha_composite(background, image).convert("RGB")


def _resize_image(image, max_side):
    resize_scale = max_side / max(image.size)
    new_size = (
        int(image.size[0] * resize_scale),
        int(image.size[1] * resize_scale),
    )
    return image.resize(new_size)


def process_video(video_path, num_frames, min_pixels, max_pixels):
    import cv2
    # Open the video file
    cap = cv2.VideoCapture(video_path)
    frame_count = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
    fps = cap.get(cv2.CAP_PROP_FPS)  # Frames per second

    # the sampling rate using max number of frames
    sampling_gap_maxframe = (
        1 if not num_frames else math.ceil(frame_count / num_frames)
    )
    sampling_gap = max(math.ceil(fps / 5), sampling_gap_maxframe)

    frame_number = 0
    images = []

    while True:
        import tempfile
        success, frame = cap.read()
        if not success:
            break
        # Sample frames based on the dynamic sampling rate
        if frame_number % sampling_gap == 0:
            # Create a temporary file for the frame
            with tempfile.NamedTemporaryFile(
                suffix=".jpg", delete=False
            ) as temp_frame:
                cv2.imwrite(temp_frame.name, frame)
                images.append(create_image_content(temp_frame.name, min_pixels, max_pixels))
                os.remove(temp_frame.name)
        frame_number += 1
    if frame_number == 0:
        raise ValueError(f"Failed to read video from {video_path}, check data...")
    logging.info(
        f"Sampled {len(images)}/{frame_number} frames from video {video_path}"
    )
    cap.release()
    return images


def setup_visible_devices_per_rank():
    total_gpus = torch.cuda.device_count()
    rank, world_size = get_rank_and_world_size()
    assert world_size == 1, "Only support world_size == 1 for vLLM inference"
    num_gpus = total_gpus // world_size
    start_idx = rank * num_gpus
    assigned_devices = list(range(start_idx, start_idx + num_gpus))
    os.environ["CUDA_VISIBLE_DEVICES"] = ",".join(str(i) for i in assigned_devices)
    logging.info(f"[Rank {rank}] Visible GPUs: {assigned_devices}")
    return num_gpus


class Qwen2VLChat(Qwen2VLPromptMixin, BaseModel):
    INSTALL_REQ = False
    INTERLEAVE = True
    VIDEO_LLM = True

    def __init__(
        self,
        model_path: str,
        min_pixels: int | None = None,
        max_pixels: int | None = None,
        total_pixels: int | None = None,
        max_new_tokens=2048,
        top_p=0.001,
        top_k=1,
        temperature=0.01,
        repetition_penalty=1.0,
        use_custom_prompt: bool = True,
        system_prompt: str | None = None,
        post_process: bool = False,  # if True, will try to only extract stuff in the last \boxed{}.
        verbose: bool = False,
        use_audio_in_video: bool = False,
        **kwargs,
    ):
        super().__init__(use_custom_prompt=use_custom_prompt)
        self.min_pixels = min_pixels
        self.max_pixels = max_pixels
        self.total_pixels = total_pixels
        self.max_new_tokens = max_new_tokens
        if self.total_pixels and self.total_pixels > 24576 * 28 * 28:
            print('The total number of video tokens might become too large, resulting in an overly long input sequence. We recommend lowering **total_pixels** to below **24576 × 28 × 28**.')  # noqa: E501
        self.generate_kwargs = dict(
            max_new_tokens=self.max_new_tokens,
            top_p=top_p,
            top_k=top_k,
            temperature=temperature,
            repetition_penalty=repetition_penalty,
        )
        self.system_prompt = system_prompt
        self.verbose = verbose
        self.post_process = post_process
        self.fps = kwargs.pop('fps', 2)
        self.nframe = kwargs.pop('nframe', 128)
        if self.fps is None and self.nframe is None:
            print("Warning: fps and nframe are both None, \
                  using default nframe/fps setting in qwen-vl-utils/qwen-omni-utils, \
                  the fps/nframe setting in video dataset is omitted")
        self.use_audio_in_video = use_audio_in_video
        self.FRAME_FACTOR = 2
        rank, world_size = get_rank_and_world_size()
        assert model_path is not None
        self.model_path = model_path
        MODEL_CLS = None

        if listinstr(['omni'], model_path.lower()):
            try:
                from transformers import Qwen2_5OmniForConditionalGeneration, Qwen2_5OmniProcessor
            except Exception as err:
                logging.critical("pip install git+https://github.com/huggingface/transformers@3a1ead0aabed473eafe527915eea8c197d424356")  # noqa: E501
                raise err
            MODEL_CLS = Qwen2_5OmniForConditionalGeneration
            self.processor = Qwen2_5OmniProcessor.from_pretrained(model_path)
        elif listinstr(['2.5', '2_5', 'qwen25'], model_path.lower()):
            from transformers import Qwen2_5_VLForConditionalGeneration, AutoProcessor
            MODEL_CLS = Qwen2_5_VLForConditionalGeneration
            self.processor = AutoProcessor.from_pretrained(model_path)
        else:
            from transformers import Qwen2VLForConditionalGeneration, Qwen2VLProcessor
            MODEL_CLS = Qwen2VLForConditionalGeneration
            self.processor = Qwen2VLProcessor.from_pretrained(model_path)

        gpu_mems = get_gpu_memory()
        max_gpu_mem = max(gpu_mems) if gpu_mems != [] else -1
        assert max_gpu_mem > 0
        self.use_vllm = kwargs.get('use_vllm', False)
        self.use_lmdeploy = kwargs.get('use_lmdeploy', False)
        self.limit_mm_per_prompt = VLLM_MAX_IMAGE_INPUT_NUM
        assert self.use_vllm + self.use_lmdeploy <= 1, "You can only set one flag between `use_vllm` and `use_lmdeploy` to True"  # noqa: E501

        if self.use_vllm:
            from vllm import LLM
            gpu_count = setup_visible_devices_per_rank()
            if gpu_count >= 8:
                tp_size = 8
            elif gpu_count >= 4:
                tp_size = 4
            elif gpu_count >= 2:
                tp_size = 2
            else:
                tp_size = 1
            logging.info(
                f'Using vLLM for {self.model_path} inference with {tp_size} GPUs (available: {gpu_count})'
            )
            import os
            if os.environ.get('VLLM_WORKER_MULTIPROC_METHOD') != 'spawn':
                logging.warning(
                    'VLLM_WORKER_MULTIPROC_METHOD is not set to spawn.'
                    'Use \'export VLLM_WORKER_MULTIPROC_METHOD=spawn\' to avoid potential multi-process issues'
                )
            self.llm = LLM(
                model=self.model_path,
                max_num_seqs=5,
                max_model_len=32768,
                limit_mm_per_prompt={"image": self.limit_mm_per_prompt},
                tensor_parallel_size=tp_size,
                gpu_memory_utilization=kwargs.get("gpu_utils", 0.9),
            )

        elif self.use_lmdeploy:
            from lmdeploy import TurbomindEngineConfig, pipeline, ChatTemplateConfig
            num_gpus = torch.cuda.device_count()
            self.model = pipeline(
                model_path,
                backend_config=TurbomindEngineConfig(session_len=32768, cache_max_entry_count=0.1, tp=num_gpus)
            )
            torch.cuda.set_device(0)
            self.device = 'cuda'
        else:
            self.model = MODEL_CLS.from_pretrained(
                model_path, torch_dtype='auto', device_map="auto", attn_implementation='flash_attention_2'
            )
            self.model.eval()

        torch.cuda.empty_cache()

    def _prepare_content(self, inputs: list[dict[str, str]], dataset: str | None = None) -> list[dict[str, str]]:
        """
        inputs list[dict[str, str]], each dict has keys: ['type', 'value']
        """
        content = []
        for s in inputs:
            if s['type'] == 'image':
                item = {'type': 'image', 'image': ensure_image_url(s['value'])}
                if dataset == 'OCRBench':
                    item['min_pixels'] = 10 * 10 * 28 * 28
                    warnings.warn(f"OCRBench dataset uses custom min_pixels={item['min_pixels']}")
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                else:
                    if self.min_pixels is not None:
                        item['min_pixels'] = self.min_pixels
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                if self.total_pixels is not None:
                    item['total_pixels'] = self.total_pixels
            elif s['type'] == 'video':
                item = {
                    'type': 'video',
                    'video': ensure_video_url(s['value'])
                }
                if self.min_pixels is not None:
                    item['min_pixels'] = self.min_pixels
                if self.max_pixels is not None:
                    item['max_pixels'] = self.max_pixels
                if self.total_pixels is not None:
                    item['total_pixels'] = self.total_pixels
                if self.fps is not None:
                    item['fps'] = self.fps
                elif self.nframe is not None:
                    import cv2
                    video = cv2.VideoCapture(s['value'])
                    frame_count = int(video.get(cv2.CAP_PROP_FRAME_COUNT))
                    video.release()
                    if frame_count < self.nframe:
                        new_frame_count = frame_count // self.FRAME_FACTOR * self.FRAME_FACTOR
                        print(f"use {new_frame_count} for {s['value']}")
                        item['nframes'] = new_frame_count
                    else:
                        item['nframes'] = self.nframe
            elif s['type'] == 'text':
                item = {'type': 'text', 'text': s['value']}
            elif s['type'] == 'audio':
                item = {'type':'audio','audio':s['value']}
            else:
                raise ValueError(f"Invalid message type: {s['type']}, {s}")
            content.append(item)
        return content

    def _prepare_content_vllm(self, inputs: list[dict[str, str]], dataset: str | None = None) -> list[dict[str, str]]:
        """
        inputs list[dict[str, str]], each dict has keys: ['type', 'value']
        """
        content = []
        video_inputs = [s for s in inputs if s['type'] == 'video']
        video_count = len(video_inputs)
        cur_image_count = 0
        for s in inputs:
            if s['type'] == 'image':
                item = {'type': 'image', 'image': ensure_image_url(s['value'])}
                if dataset == 'OCRBench':
                    item['min_pixels'] = 10 * 10 * 28 * 28
                    warnings.warn(f"OCRBench dataset uses custom min_pixels={item['min_pixels']}")
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                else:
                    if self.min_pixels is not None:
                        item['min_pixels'] = self.min_pixels
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                if self.total_pixels is not None:
                    item['total_pixels'] = self.total_pixels
                if cur_image_count < self.limit_mm_per_prompt:
                    content.append(item)
                    cur_image_count += 1
                else:
                    logging.warning(
                        f"Number of images exceeds the limit of {self.limit_mm_per_prompt}. "
                        f"Only the first {self.limit_mm_per_prompt} images will be used."
                    )
            elif s['type'] == 'video':
                if video_count > 1:
                    logging.warning(
                        "Multiple videos detected. Using video frames for each video"
                    )
                    if dataset == 'OCRBench':
                        min_pixels = 10 * 10 * 28 * 28
                        warnings.warn(f"OCRBench dataset uses custom min_pixels={min_pixels}")
                        if self.max_pixels is not None:
                            max_pixels = self.max_pixels
                    else:
                        if self.min_pixels is not None:
                            min_pixels = self.min_pixels
                        if self.max_pixels is not None:
                            max_pixels = self.max_pixels
                    import cv2
                    video = cv2.VideoCapture(s['value'])
                    frame_count = int(video.get(cv2.CAP_PROP_FRAME_COUNT))
                    video.release()

                    frames_per_video = max(1, self.limit_mm_per_prompt // video_count)
                    content.append({"type": "text", "text": "<video frames start>"})
                    content.extend(process_video(s['value'], frames_per_video, min_pixels, max_pixels))
                    content.append({"type": "text", "text": "<video frames end>"})

                else:
                    item = {
                        'type': 'video',
                        'video': ensure_video_url(s['value'])
                    }
                    if self.min_pixels is not None:
                        item['min_pixels'] = self.min_pixels
                    if self.max_pixels is not None:
                        item['max_pixels'] = self.max_pixels
                    if self.total_pixels is not None:
                        item['total_pixels'] = self.total_pixels
                    if self.fps is not None:
                        item['fps'] = self.fps
                    elif self.nframe is not None:
                        import cv2
                        video = cv2.VideoCapture(s['value'])
                        frame_count = int(video.get(cv2.CAP_PROP_FRAME_COUNT))
                        video.release()
                        if frame_count < self.nframe:
                            new_frame_count = frame_count // self.FRAME_FACTOR * self.FRAME_FACTOR
                            print(f"use {new_frame_count} for {s['value']}")
                            item['nframes'] = new_frame_count
                        else:
                            item['nframes'] = self.nframe
                    content.append(item)
            elif s['type'] == 'text':
                item = {'type': 'text', 'text': s['value']}
                content.append(item)
            else:
                raise ValueError(f"Invalid message type: {s['type']}, {s}")
        return content

    def generate_inner_transformers(self, message, dataset=None):
        if listinstr(['omni'], self.model_path.lower()):
            try:
                from qwen_omni_utils import process_mm_info
            except Exception as err:
                logging.critical("qwen_omni_utils not found, please install it via 'pip install qwen-omni-utils[decord]'")  # noqa: E501
                raise err
        else:
            try:
                from qwen_vl_utils import process_vision_info
            except Exception as err:
                logging.critical("qwen_vl_utils not found, please install it via 'pip install qwen-vl-utils'")  # noqa: E501
                raise err

        messages = []
        if self.system_prompt is not None:
            messages.append({'role': 'system', 'content': self.system_prompt})
        messages.append({'role': 'user', 'content': self._prepare_content(message, dataset=dataset)})
        if self.verbose:
            print(f'\033[31m{messages}\033[0m')

        text = self.processor.apply_chat_template([messages], tokenize=False, add_generation_prompt=True)
        if listinstr(['omni'], self.model_path.lower()):
            audios, images, videos = process_mm_info([messages], use_audio_in_video=self.use_audio_in_video)
            inputs = self.processor(text=text, images=images,audio=audios, videos=videos, padding=True, return_tensors='pt',use_audio_in_video=self.use_audio_in_video)  # noqa: E501
        else:
            images, videos = process_vision_info([messages])
            inputs = self.processor(text=text, images=images, videos=videos, padding=True, return_tensors='pt')  # noqa: E501
        inputs = inputs.to('cuda')

        if listinstr(['omni'], self.model_path.lower()):
            self.generate_kwargs['use_audio_in_video'] = self.use_audio_in_video
            self.generate_kwargs['return_audio'] = False
        generated_ids = self.model.generate(
            **inputs,
            **self.generate_kwargs,
        )
        generated_ids = [
            output_ids[len(input_ids):] for input_ids, output_ids in zip(inputs.input_ids, generated_ids)
        ]
        out = self.processor.tokenizer.batch_decode(
            generated_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False
        )
        response = out[0]
        if self.post_process:
            resp = response.split('\\boxed{')[-1]
            lt = len(resp)
            counter, end = 1, None
            for i in range(lt):
                if resp[i] == '{':
                    counter += 1
                elif resp[i] == '}':
                    counter -= 1
                if counter == 0:
                    end = i
                    break
                elif i == lt - 1:
                    end = lt
                    break
            if end is not None:
                response = resp[:end]

        if self.verbose:
            print(f'\033[32m{response}\033[0m')
        return response

    def generate_inner_lmdeploy(self, message, dataset=None):
        from lmdeploy import GenerationConfig
        gen_config = GenerationConfig(
            max_new_tokens=self.max_new_tokens,
            top_p=self.generate_kwargs['top_p'],
            top_k=self.generate_kwargs['top_k'],
            temperature=self.generate_kwargs['temperature'],
            repetition_penalty=self.generate_kwargs['repetition_penalty'],
        )
        gen_config.random_seed = None
        messages_list = self.message_to_lmdeploy(message, system_prompt=self.system_prompt)
        assert len(messages_list) == 1
        response = self.model(messages_list, gen_config=gen_config)[0]
        response = response.text
        return response

    def generate_inner_vllm(self, message, dataset=None):
        from vllm import SamplingParams

        if listinstr(['omni'], self.model_path.lower()):
            try:
                from qwen_omni_utils import process_mm_info
            except Exception as err:
                logging.critical("qwen_omni_utils not found, please install it via 'pip install qwen-omni-utils[decord]'")  # noqa: E501
                raise err
        else:
            try:
                from qwen_vl_utils import process_vision_info
            except Exception as err:
                logging.critical("qwen_vl_utils not found, please install it via 'pip install qwen-vl-utils'")  # noqa: E501
                raise err

        messages = []
        if self.system_prompt is not None:
            messages.append({'role': 'system', 'content': self.system_prompt})
        messages.append({'role': 'user', 'content': self._prepare_content_vllm(message, dataset=dataset)})
        if self.verbose:
            print(f'\033[31m{messages}\033[0m')

        text = self.processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        if listinstr(['omni'], self.model_path.lower()):
            audios, images, videos = process_mm_info(messages, use_audio_in_video=self.use_audio_in_video)
        else:
            images, videos = process_vision_info(messages)
        print('finishing process vision info in vllm.')

        if DATASET_MODALITY(dataset) == 'VIDEO':
            assert len(videos) == 1
            videos_nd = [videos[0].detach().cpu().numpy().transpose(0, 2, 3, 1)]

            video_inputs = {
                "prompt": text[0],
                "multi_modal_data": {"video": videos_nd[0]},
                "mm_processor_kwargs":{}
            }
            if self.use_audio_in_video:
                import vllm
                assert not vllm.envs.VLLM_USE_V1, ("V1 does not support use_audio_in_video. Please launch this example with `VLLM_USE_V1=0`.")  # noqa: E501
                video_inputs["multi_modal_data"]["audio"] = audios[0]
                video_inputs['mm_processor_kwargs']['use_audio_in_video'] = True
            if videos_nd[0].shape[0] > VLLM_MAX_IMAGE_INPUT_NUM:
                print('video input sequence may be too long for vllm, Maybe cannot generate response for VLLM')
        sampling_params = SamplingParams(
            temperature=0.0, max_tokens=self.max_new_tokens, stop_token_ids=None
        )
        if images:
            outputs = self.llm.generate(
                {
                    "prompt": text,
                    "multi_modal_data": {"image": images},
                },
                sampling_params=sampling_params,
            )
        elif videos_nd:
            outputs = self.llm.generate(
                video_inputs,
                sampling_params=sampling_params,
            )
        else:
            outputs = self.llm.generate(
                {
                    "prompt": text,
                },
                sampling_params=sampling_params,
            )

        for o in outputs:
            generated_text = o.outputs[0].text

        if self.post_process:
            resp = generated_text.split('\\boxed{')[-1]
            lt = len(resp)
            counter, end = 1, None
            for i in range(lt):
                if resp[i] == '{':
                    counter += 1
                elif resp[i] == '}':
                    counter -= 1
                if counter == 0:
                    end = i
                    break
                elif i == lt - 1:
                    end = lt
                    break
            if end is not None:
                generated_text = resp[:end]

        if self.verbose:
            print(f'\033[32m{generated_text}\033[0m')
        return generated_text

    def generate_inner(self, message, dataset=None):
        if self.use_vllm:
            return self.generate_inner_vllm(message, dataset=dataset)
        elif self.use_lmdeploy:
            return self.generate_inner_lmdeploy(message, dataset=dataset)
        else:
            return self.generate_inner_transformers(message, dataset=dataset)

import json
import re
from abc import ABC, abstractmethod
from enum import Enum
from typing import TYPE_CHECKING, Any, Dict, Tuple

import numpy as np

from Ayo.dags.node_commons import NodeOps
from Ayo.logger import GLOBAL_INFO_LEVEL, get_logger
from Ayo.utils import (
    check_unfilled_placeholders_in_prompt_template,
    fill_prompt_template_with_placeholdersname_approximations,
)
from vllm import SamplingParams

logger = get_logger(__name__, level=GLOBAL_INFO_LEVEL)

if TYPE_CHECKING:
    from Ayo.dags.node import Node


class RequestType(str, Enum):
    """Types of vector database operations"""

    INGESTION = "ingestion"  # Insert vectors and texts
    SEARCHING = "searching"  # Search for similar vectors


def extract_json_values(s: str):
    match = re.search(r"(\{\{.*\}\})", s)
    if not match:
        return []
    json_str = match.group(1)
    if json_str.startswith("{{") and json_str.endswith("}}"):
        json_str = json_str[1:-1]
    try:
        data = json.loads(json_str)
        return list(data.values())
    except Exception as e:
        print("JSON parsing failed:", e)
        return []


class PayloadTransformer(ABC):
    """Base class for payload transformers"""

    @abstractmethod
    def transform(self, input_kwargs: Dict[str, Any]) -> Any:
        """Transform input data to engine required format

        Args:
            input_kwargs: Original input parameters

        Returns:
            Transformed data
        """
        pass


class VectorDBTransformer(PayloadTransformer):
    """Payload transformer for vector database"""

    def transform(self, node: "Node") -> Tuple[RequestType, Any]:
        """Transform vector database input

        Handle two types of requests:
        1. Ingestion request: requires embeddings and texts
        2. Search request: requires query_vector and top_k

        Args:
            input_kwargs: Dictionary containing request parameters

        Returns:
            Tuple[RequestType, Any]: Request type and transformed data
        """
        # Check if operation type is provided
        request_type = (
            RequestType.INGESTION
            if node.op_type == NodeOps.VECTORDB_INGESTION
            else RequestType.SEARCHING
        )

        if not request_type:
            raise ValueError("Missing operation type in input")

        if request_type == RequestType.INGESTION:
            # Handle ingestion request
            embeddings = None
            texts = None

            for key, value in node.input_kwargs.items():
                if "embed" in key.lower():
                    embeddings = value
                    break

            for key, value in node.input_kwargs.items():
                if "embed" not in key.lower() and (
                    "text" in key.lower() or "passage" in key.lower()
                ):
                    texts = value
                    break

            if embeddings is None or texts is None:
                raise ValueError("Missing embeddings or texts for ingestion")

            if len(embeddings) != len(texts):
                raise ValueError("Number of embeddings must match number of texts")

            if isinstance(texts, list):
                num_text_embeddings_pairs = len(texts)
            else:
                num_text_embeddings_pairs = 1

            if isinstance(embeddings, list):
                assert (
                    len(embeddings) == num_text_embeddings_pairs
                ), "Number of embeddings must match number of texts"
                assert isinstance(
                    embeddings[0], list
                ), "Embeddings must be a list of lists"

            elif isinstance(embeddings, np.ndarray):
                assert (
                    len(embeddings) == num_text_embeddings_pairs
                ), "Length of embeddings np array must match number of texts"
                embeddings = embeddings.tolist()
            else:
                raise ValueError("Invalid embeddings format")

            # Ensure texts is a list of strings
            if not isinstance(texts, list):
                texts = [str(texts)]
            texts = [str(text) for text in texts]

            # （embeddings, texts） pair
            data = [(embedding, text) for embedding, text in zip(embeddings, texts)]

            logger.debug(f"{self.__class__.__name__} len of data: {len(data)}")

            logger.debug(f"vector db transformer data: len of data: {len(data)}")

            return {"request_type": RequestType.INGESTION, "data": data}

        elif request_type == RequestType.SEARCHING:
            # Handle search request
            query_vectors = None

            for key, value in node.input_kwargs.items():
                if key.lower() in [
                    "query_vectors",
                    "query_vector",
                    "query_embedding",
                    "query_embeddings",
                    "queries_embeddings",
                    "expanded_query_embedding",
                    "expanded_queries_embeddings",
                    "expanding_queries_embedding",
                    "embeddings",
                    "embedding",
                    "query_vector_list",
                    "query_vector_lists",
                    "queries",
                    "query_list",
                    "query_lists",
                ]:
                    query_vectors = value
                    break

            top_k = node.config.get("top_k", None)

            print(f"query_vectors: {query_vectors} type: {type(query_vectors)}")

            # Ensure query_vector is a list of numpy arrays
            if isinstance(query_vectors, list):
                if len(query_vectors) == 0:
                    raise ValueError(
                        f"Empty query_vectors list for node {node.name} vector db searching"
                    )

                if isinstance(query_vectors[0], list):
                    # Convert list of lists to list of numpy arrays
                    try:
                        query_vectors = [
                            np.array(query_vector, dtype=float)
                            for query_vector in query_vectors
                        ]
                    except (ValueError, TypeError):
                        raise ValueError(
                            f"Failed to convert query vectors to numpy arrays for node {node.name} vector db searching"
                        )

                elif isinstance(query_vectors[0], np.ndarray):
                    # Already a list of numpy arrays, ensure they are 1D
                    for i, qv in enumerate(query_vectors):
                        if qv.ndim != 1:
                            raise ValueError(
                                f"Query vector at index {i} has {qv.ndim} dimensions, expected 1D for node {node.name} vector db searching"
                            )

                else:
                    raise ValueError(
                        f"Invalid query_vector format: expected list of lists or numpy arrays for node {node.name} vector db searching, got {type(query_vectors)}"
                    )

            elif isinstance(query_vectors, np.ndarray):
                # Handle single or multiple query vectors in a numpy array
                if query_vectors.ndim == 1:
                    # Single 1D vector
                    query_vectors = [query_vectors]
                elif query_vectors.ndim == 2:
                    # Multiple vectors in a 2D array, convert to list of 1D arrays
                    query_vectors = [
                        query_vectors[i] for i in range(query_vectors.shape[0])
                    ]
                else:
                    raise ValueError(
                        f"Query vector numpy array has {query_vectors.ndim} dimensions, expected 1D or 2D for node {node.name} vector db searching"
                    )

            else:
                raise ValueError(
                    f"Invalid query_vector format: expected list or numpy array for node {node.name} vector db searching"
                )

            # （query_vector, top_k） pair
            data = (query_vectors, top_k)

            assert (
                top_k is not None
            ), f"Missing top_k for node {node.name} vector db searching"
            assert (
                query_vectors is not None
            ), f"Missing query_vector for node {node.name} vector db searching"

            return {"request_type": RequestType.SEARCHING, "data": data}

        else:
            raise ValueError(f"Unknown operation type: {request_type}")


class EmbedderTransformer(PayloadTransformer):
    def transform(self, node: "Node") -> Dict:
        texts = []
        # a workaround for the case the input from a queryexpanding LLMdecoding
        # TODO: Take a more general approach to handle the case
        if (
            node.parents[0].op_type == NodeOps.LLM_DECODING
            and node.parents[0].config.get("expanded_query_num", 0) > 0
            and node.parents[0].config.get("parse_json", False) is True
        ):
            for key, value in node.input_kwargs.items():
                if isinstance(value, str):
                    logger.debug(
                        f"Transform the input for embedder from LLM query expanding decoding, try to parse a json str into list of strings: value before extract_json_values: {value}"
                    )
                    extracted_values = extract_json_values(value)
                    logger.debug(
                        f"Transform the input for embedder from LLM query expanding decoding, extracted_values: {extracted_values}"
                    )
                    texts.extend(extracted_values)

        else:
            for value in node.input_kwargs.values():
                if isinstance(value, (list, tuple)):
                    texts.extend(str(item) for item in value)
                else:
                    texts.append(str(value))

        logger.debug(f"Transform the input for embedder, texts: {texts}")

        return {"texts": texts}


class RerankerTransformer(PayloadTransformer):
    def transform(self, node: "Node") -> Dict:

        # TODO: fix the input_kwargs for any possible input names
        # Add the top_k config
        top_k = node.config.get("top_k", None)
        query = None
        passages = None

        for key, value in node.input_kwargs.items():
            if key.lower() in [
                "query",
                "queries",
                "query_text",
                "query_texts",
                "query_texts_list",
            ]:
                query = value
            elif key.lower() in [
                "text",
                "texts",
                "passages",
                "documents",
                "context",
                "document",
                "contexts",
                "docs",
                "search_results",
                "search_result_list",
                "search_result_lists",
                "searching_results",
                "searching_result_list",
                "searching_result_lists",
            ]:
                passages = value

        assert query is not None, f"Missing query for node {node.name} reranking"
        assert passages is not None, f"Missing passages for node {node.name} reranking"
        assert top_k is not None, f"Missing top_k for node {node.name} reranking"

        if isinstance(query, list):
            if len(query) == 1 and isinstance(query[0], str):
                query = query[0]
            else:
                raise ValueError(
                    f"Query is a list for node {node.name} reranking, only string is supported. please check the input_kwargs"
                )
        elif isinstance(query, str):
            pass
        else:
            raise ValueError(f"Invalid query format for node {node.name} reranking")

        if isinstance(passages, list):
            if len(passages) == 0:
                raise ValueError(f"Empty passages list for node {node.name} reranking")

            if isinstance(passages[0], list):
                # Process nested lists
                merged_passages = []
                for i, passage_list in enumerate(passages):
                    if not isinstance(passage_list, list):
                        raise ValueError(
                            f"Inconsistent passages format for node {node.name} reranking"
                        )

                    # Skip empty lists
                    if len(passage_list) == 0:
                        raise ValueError(
                            f"Empty passages list at index {i} for node {node.name} reranking"
                        )

                    # Check the first element type and process the whole list accordingly type and process the whole list accordingly
                    if passage_list and isinstance(passage_list[0], str):
                        # If it's a list of strings, add non-None elements (filter out  of )add non-None elements (filter out None)
                        merged_passages.extend(
                            [str(p) for p in passage_list if p is not None]
                        )
                    elif passage_list and isinstance(passage_list[0], dict):
                        # If it's a list of dicts, find the text key and extract
                        text_key = None
                        # Only check the first dict's keys, assuming all dicts have the same key structure
                        for key in passage_list[0].keys():
                            if key.lower() in [
                                "text",
                                "passage",
                                "doc",
                                "document",
                                "context",
                                "content",
                                "texts",
                                "passages",
                                "docs",
                                "documents",
                                "contexts",
                            ]:
                                text_key = key
                                break

                        if text_key is None:
                            raise ValueError(
                                f"Missing text key in nested dict list for node {node.name} reranking"
                            )

                        # Extract all texts at once
                        merged_passages.extend(
                            str(p_dict[text_key]) for p_dict in passage_list
                        )
                    else:
                        raise ValueError(
                            f"Passages contains unsupported element types for node {node.name} reranking"
                        )

                passages = merged_passages
            elif isinstance(passages[0], str):
                # process single layer string list
                passages = [str(p) for p in passages if p is not None]
            elif isinstance(passages[0], dict):
                # a possible format for the passages is a list of dicts, each dict contains a "text"-related key and a "score"-related key
                # process nested list
                text_key = None
                # TODO: handle the score key
                merged_passages = []
                for key in passages[0].keys():
                    if key.lower() in [
                        "text",
                        "passage",
                        "doc",
                        "document",
                        "context",
                        "content",
                        "texts",
                        "passages",
                        "docs",
                        "documents",
                        "contexts",
                    ]:
                        text_key = key
                    elif key.lower() in [
                        "score",
                        "similarity_score",
                        "cosine_score",
                        "cosine_similarity_score",
                    ]:
                        pass
                        # TODO: handle the score key, not used for now
                    else:
                        raise ValueError(
                            f"Invalid passage format for node {node.name} reranking"
                        )

                if text_key is None:
                    raise ValueError(f"Missing text key for node {node.name} reranking")
                else:
                    for passage in passages:
                        merged_passages.append(passage[text_key])
                    passages = merged_passages

            else:
                raise ValueError(
                    f"Invalid passages format {type(passages[0])} for node {node.name} reranking"
                )

            # ensure the processed list is not empty
            if len(passages) == 0:
                raise ValueError(
                    f"No valid passages after processing for node {node.name} reranking"
                )

        elif isinstance(passages, str):
            passages = [passages]
            logger.warning(
                f"Passages is a single string for node {node.name} reranking, convert to list"
            )
        else:
            raise ValueError(f"Invalid passages format for node {node.name} reranking")

        return {"query": query, "passages": passages, "top_k": top_k}


class DefaultTransformer(PayloadTransformer):
    def transform(self, node: "Node") -> Dict[str, Any]:
        return node.input_kwargs


class AggregatorTransformer(PayloadTransformer):
    def transform(self, node: "Node") -> Dict[str, Any]:
        """Transform the input for the aggregator engine"""
        agg_mode = node.config.get("agg_mode", "concat")
        data_sources = node.config.get("data_sources", [])

        return {"agg_mode": agg_mode, "data_sources": data_sources}


class LLMTransformer(PayloadTransformer):
    def transform(self, node: "Node") -> Dict[str, Any]:
        # llm_internal_id: str,
        # prompt: str,
        # llm_op_type: NodeOps,
        # llm_partial_decoding_idx: int = -1,
        # sampling_params: SamplingParams = None

        llm_internal_id = node.config.get("llm_internal_id", "")

        # TODO: make the prompt is complete without any unfilled placeholders

        potential_prompt_template = None
        potential_prompt = None
        prompt = None

        for key, value in node.config.items():
            if key.lower() in [
                "prompt_template",
                "prompt_templates",
                "template",
                "templates",
            ]:
                potential_prompt_template = value
            elif key.lower() in ["prompt", "prompts", "prompt_list", "prompt_lists"]:
                potential_prompt = value
            else:
                continue

        if node.op_type in [
            NodeOps.LLM_PREFILLING,
            NodeOps.LLM_PARTIAL_PREFILLING,
            NodeOps.LLM_FULL_PREFILLING,
        ]:
            if potential_prompt is None and potential_prompt_template is None:
                raise ValueError(
                    f"Missing prompt for node {node.name} llm prefilling-related operation {node.op_type}"
                )
            else:
                if potential_prompt_template is not None:
                    # we should fill the prompt template with the input_kwargs
                    input_kwargs = node.input_kwargs
                    input_kwargs.update(node.config)
                    prompt = fill_prompt_template_with_placeholdersname_approximations(
                        potential_prompt_template, input_kwargs
                    )

                    # first find the placeholders in the prompt template
                else:
                    prompt = potential_prompt
                    # check if the prompt is complete without any unfilled placeholders
                    if not check_unfilled_placeholders_in_prompt_template(prompt):
                        raise ValueError(
                            f"Prompt is not complete without any unfilled placeholders for node {node.name} llm prefilling-related operation {node.op_type}"
                        )

        # prepare the prompt for the LLM

        max_tokens = node.config.get("max_tokens", 150)
        llm_op_type = node.op_type

        support_partial_output = node.config.get("partial_output", False)
        support_partial_prefilling = node.config.get("partial_prefilling", False)

        llm_partial_decoding_idx = node.config.get("llm_partial_decoding_idx", -1)

        # FIXME: this sampling_params is not used for decoding-related operations
        sampling_params = SamplingParams(
            temperature=0.9,
            top_p=0.95,
            max_tokens=max_tokens,
            support_partial_output=support_partial_output,
            support_partial_prefilling=support_partial_prefilling,
        )

        assert (
            llm_internal_id != ""
        ), f"Missing llm_internal_id for node {node.name} llm"
        assert llm_op_type in [
            NodeOps.LLM_PREFILLING,
            NodeOps.LLM_PARTIAL_PREFILLING,
            NodeOps.LLM_FULL_PREFILLING,
            NodeOps.LLM_DECODING,
            NodeOps.LLM_PARTIAL_DECODING,
        ], f"Invalid llm_op_type for node {node.name} llm"

        if llm_op_type in [
            NodeOps.LLM_PREFILLING,
            NodeOps.LLM_PARTIAL_PREFILLING,
            NodeOps.LLM_FULL_PREFILLING,
        ]:
            assert prompt is not None, f"Missing prompt for node {node.name} llm"

        return {
            "llm_internal_id": llm_internal_id,
            "prompt": prompt,
            "llm_op_type": llm_op_type,
            "llm_partial_decoding_idx": llm_partial_decoding_idx,
            "sampling_params": sampling_params,
        }


