            # )
            return DeepSeekVLlmDecoder(
                batch_size=batch_size,
                name=HF_HOME + f"deepseek-ai/deepseek-coder-{nb}b-base",
                temperature=temperature,
            )
    elif name == "wizardcoder-34b":
        return WizardCoderDecoder(
            batch_size=batch_size,
