import os
import time
import asyncio
from typing import List
import torch
from loguru import logger
from magic_pdf.utils.load_image import load_image


class MonkeyChat_vLLM_async:
    def __init__(self, model_path, tp=1):
        try:
            from vllm import AsyncLLMEngine, SamplingParams
            from vllm.engine.arg_utils import AsyncEngineArgs
        except ImportError:
            raise ImportError("vLLM is not installed. Please install it: "
                              "https://github.com/Yuliang-Liu/MonkeyOCR/blob/main/docs/install_cuda.md")

        self.model_name = os.path.basename(model_path)

        engine_args = AsyncEngineArgs(
            model=model_path,
            max_seq_len_to_capture=10240,
            mm_processor_kwargs={'use_fast': True},
            gpu_memory_utilization=self._auto_gpu_mem_ratio(0.9),
            disable_log_stats=True,
            enable_prefix_caching=True,
            tensor_parallel_size=tp
        )

        self.engine = AsyncLLMEngine.from_engine_args(engine_args)
        logger.info(f"vLLM Async engine initialized: {self.model_name}")

        self.gen_config = SamplingParams(
            max_tokens=4096,
            temperature=0,
            repetition_penalty=1.05,
        )

        self.request_timeout = 600

    def _auto_gpu_mem_ratio(self, ratio):
        mem_free, mem_total = torch.cuda.mem_get_info()
        ratio = ratio * mem_free / mem_total
        return ratio

    async def async_batch_inference(self, images: List[str], questions: List[str]) -> List[str]:
        if len(images) != len(questions):
            raise ValueError("Images and questions must have the same length")

        semaphore = asyncio.Semaphore(min(64, max(1, len(images))))
        timeout_s = 300

        async def infer_one(img_path: str, q: str, req_id: str) -> str:
            placeholder = "<|image_pad|>"
            prompt = (
                "<|im_start|>system\nYou are a helpful assistant.<|im_end|>\n"
                f"<|im_start|>user\n<|vision_start|>{placeholder}<|vision_end|>"
                f"{q}<|im_end|>\n"
                "<|im_start|>assistant\n"
            )

            inputs = {
                "prompt": prompt,
                "multi_modal_data": {
                    "image": [load_image(img_path, max_size=1600)],
                }
            }

            start = time.time()
            final_output = None
            async for out in self.engine.generate(inputs, self.gen_config, req_id):
                if time.time() - start > timeout_s:
                    try:
                        abort_res = self.engine.abort(req_id)
                        if asyncio.iscoroutine(abort_res):
                            await abort_res
                        logger.info(f"{req_id} aborted due to timeout")
                    except Exception as abort_err:
                        logger.warning(f"Abort failed for {req_id}: {abort_err}")
                    return "Error: Request timed out"
                final_output = out
                if getattr(out, "finished", False):
                    break

            if final_output and getattr(final_output, "outputs", None):
                return final_output.outputs[0].text
            return "Error: No output generated"

        async def bounded(img: str, q: str, idx: int):
            async with semaphore:
                req_id = f"batch_req_{idx}_{int(time.time()*1000)}"
                try:
                    return await infer_one(img, q, req_id)
                except Exception as e:
                    logger.error(f"Task {idx} failed: {e}")
                    return f"Error: {str(e)}"

        tasks = [bounded(img, q, i) for i, (img, q) in enumerate(zip(images, questions))]
        results = await asyncio.gather(*tasks, return_exceptions=True)

        out = []
        for i, r in enumerate(results):
            if isinstance(r, Exception):
                logger.error(f"Task {i} exception: {r}")
                out.append(f"Error: {str(r)}")
            else:
                out.append(r)
        return out

    def batch_inference(self, images: List[str], questions: List[str]) -> List[str]:
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            return asyncio.run(self.async_batch_inference(images, questions))

        import concurrent.futures

        def run_in_thread():
            new_loop = asyncio.new_event_loop()
            asyncio.set_event_loop(new_loop)
            try:
                return new_loop.run_until_complete(self.async_batch_inference(images, questions))
            finally:
                new_loop.close()

        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
            fut = ex.submit(run_in_thread)
            try:
                return fut.result(timeout=self.request_timeout)
            except Exception as e:
                logger.error(f"Synchronous batch inference failed: {e}")
                return [f"Error: {str(e)}"] * len(images)

import pandas as pd
import os
import pandas as pd
from vllm import LLM, SamplingParams
from tqdm import tqdm
os.environ["CUDA_VISIBLE_DEVICES"] = "1"

import numpy as np
import os
import requests
import base64
import pickle
import os
from tqdm import tqdm

def badcase_extraction(path):
    data = pd.read_csv(path)
    methods = ['ours', 'mistral', 't5', 'chemtrans']
    total_badcase_idxes = set()
    for method in methods:
        badcase = data[data[f'EM_{method}'] < 40]
        badcase_idx = list(badcase.index)
        total_badcase_idxes = total_badcase_idxes.union(set(badcase_idx))
        print(f'{method}: {len(badcase)} bad cases')

    print(f'Total: {len(total_badcase_idxes)} bad cases')
    badcase = data.iloc[sorted(list(total_badcase_idxes))]
    save_path = path.replace('.csv', '_badcase.csv')
    badcase.to_csv(save_path)
    return save_path

def create_cand_ref_pair(data, method):
    cand_ref_pairs = []
    for i in range(len(data)):
        cand = data.iloc[i][f'action_pred_{method}']
        ref = data.iloc[i]['action_labels']
        cand_ref_pairs.append([cand, ref])
    return cand_ref_pairs

def prompt_func(template):
    return lambda args: template.format(*args)
def encode_image(image_path):
    with open(image_path, "rb") as image_file:
        return base64.b64encode(image_file.read()).decode('utf-8')

def call_llm(model_name, cand_ref_pairs):
    if 'llama3' in model_name:
        model_path = 'llama3_8b_instruct'
    elif 'mistral' in model_name:
        model_path = 'Mistral-7B-Instruct-v0.2'
    else:
        raise ValueError(f'not support loading model {model_name}')
    print(f'loading model from {model_path}')
    llm = LLM(model = model_path, trust_remote_code=True, tensor_parallel_size=1, 
            max_context_len_to_capture=1024, gpu_memory_utilization=0.8, max_num_seqs=1024)
    sampling_params = SamplingParams(temperature=0, top_p=1, max_tokens = 300, stop = ['!!!'])

    scoring_template = '''Please rate the following two experimental operations' similarity from the perspective of chemical experiments. Use a scoring range from 0 to 1, with intervals of 0.1. A higher score indicates smaller differences between them (1 meaning the experimental operations are identical). A lower score indicates larger differences (0 meaning there is no similarity between the experimental operations at all).\n\
    The first operation: {}\n\
    The second oepration: {}\n\
    Only output the score and the explanation with a tuple format of "('explanation',score)" without any other information and descriptions.
    '''

    scoring_func =  prompt_func(scoring_template)
    scoring_prompts = []
    for cand, ref in cand_ref_pairs:
        scoring_prompt = scoring_func([cand,ref])
        scoring_prompts.append(scoring_prompt)

    outputs = llm.generate(scoring_prompts, sampling_params)
    llm_responses = []
    for output in outputs:
        llm_responses.append(output.outputs[0].text.split('<|eot_id|>')[0].split('\n')[0])
    return llm_responses

def get_score(x):
    try:
        return float(eval(x.split("\n")[-1])[1])
    except:
        try:
            x = x.split('.')
            for i in range(len(x)-2, -1, -1):
                if x[i][-1] in ['0', '1'] and x[i+1][0] in [str(j) for j in range(10)]:
                    score = x[i][-1]+'.'+x[i+1][0]
                    assert float(score) <= 1.0 and float(score) >= 0.0
                    assert float(score) is not np.nan
                    return float(score)
                # 0
                if x[i][-1] in ['0', '1'] and x[i+1][0] not in [str(j) for j in range(10)]:
                    return float(x[i][-1])
                if '0)' in x[i+1]:
                    return 0.0
                if '1)' in x[i+1]:
                    return 1.0
            return 'Invalid'
        except:
            return 'Invalid'   

def response_process(x):
    x = x.split('```')[0]
    x = x.split('\"""')[0]
    x = x.split('<|eot_id|>')[0]
    x = x.split('\n\n')[0]
    x = x.split('#')[0]

    return x.strip("\n")

