import argparse
import os
import re
from copy import deepcopy

import pandas as pd
import torch
from natsort import index_natsorted
from tqdm import tqdm
from transformers import AutoTokenizer
from vllm import LLM, SamplingParams

from utils.logger import logger


def extract_output(s, prefix='"rewritten description": '):
    """Customize the function according to the prompt."""
    # Since some LLMs struggles to output strictly formatted JSON strings as specified by the prompt,
    # thus manually parse the output string `{"rewritten description": "your rewritten description here"}`.
    match = re.search(r"{(.+?)}", s, re.DOTALL)
    if not match:
        logger.warning(f"{s} is not in the json format. Return None.")
        return None
    output = match.group(1).strip()
    if output.startswith(prefix):
        output = output[len(prefix) :]
        if output[0] == '"' and output[-1] == '"':
            return output[1:-1]
        else:
            logger.warning(f"{output} does not start and end with the double quote. Return None.")
            return None
    else:
        logger.warning(f"{output} does not start with {prefix}. Return None.")
        return None

"""The file unifies the following two tasks:
1. Caption Rewrite: rewrite the video recaption results by LLMs.
2. Beautiful Prompt: rewrite and beautify the user-uploaded prompt via LLMs.

For the caption rewrite task, the input video_metadata_path should have the following format:
```jsonl
{"video_path_column": "1.mp4", "caption_column": "a man is running in the street."}
...
{"video_path_column": "100.mp4", "caption_column": "a dog is chasing a cat."}
```
The video_path_column in the argparse must be specified.

For the beautiful prompt task, the input video_metadata_path should have the following format:
```jsonl
{"caption_column": "a man is running in the street."}
...
{"caption_column": "a dog is chasing a cat."}
```
The beautiful_prompt_column in the argparse must be specified for the saving purpose.
"""

def parse_args():
    parser = argparse.ArgumentParser(description="Rewrite the video caption by LLMs.")
    parser.add_argument(
        "--video_metadata_path", type=str, required=True, help="The path to the video dataset metadata (csv/jsonl)."
    )
    parser.add_argument(
        "--video_path_column",
        type=str,
        default=None,
        help=(
            "The column contains the video path (an absolute path or a relative path w.r.t the video_folder)."
            "It is conflicted with the beautiful_prompt_column."
        ),
    )
    parser.add_argument(
        "--caption_column",
        type=str,
        default="caption",
        help="The column contains the video caption.",
    )
    parser.add_argument(
        "--beautiful_prompt_column",
        type=str,
        default=None,
        help="The column name for the beautiful prompt column. It is conflicted with the video_path_column.",
    )
    parser.add_argument(
        "--batch_size",
        type=int,
        default=128,
        required=False,
        help="The batch size for vllm inference. Adjust according to the number of GPUs to maximize inference throughput.",
    )
    parser.add_argument(
        "--model_name",
        type=str,
        default="NousResearch/Meta-Llama-3-8B-Instruct",
    )
    parser.add_argument(
        "--prompt",
        type=str,
        required=True,
        help="A string or a txt file contains the prompt.",
    )
    parser.add_argument(
        "--prefix",
        type=str,
        required=True,
        help="The prefix to extract the output from LLMs.",
    )
    parser.add_argument(
        "--answer_template",
        type=str,
        default="",
        help="The anwer template in the prompt. If specified, rewritten results same as the answer template will be removed.",
    )
    parser.add_argument(
        "--max_retry_count",
        type=int,
        default=1,
        help="The maximum retry count to ensure outputs with the valid format from LLMs.",
    )
    parser.add_argument("--saved_path", type=str, required=True, help="The save path to the output results (csv/jsonl).")
    parser.add_argument("--saved_freq", type=int, default=1, help="The frequency to save the output results.")

    args = parser.parse_args()
    return args


def main():
    args = parse_args()

    if args.video_metadata_path.endswith(".csv"):
        video_metadata_df = pd.read_csv(args.video_metadata_path)
    elif args.video_metadata_path.endswith(".jsonl"):
        video_metadata_df = pd.read_json(args.video_metadata_path, lines=True)
    elif args.video_metadata_path.endswith(".json"):
        video_metadata_df = pd.read_json(args.video_metadata_path)
    else:
        raise ValueError(f"The {args.video_metadata_path} must end with .csv, .jsonl or .json.")

    saved_suffix = os.path.splitext(args.saved_path)[1]
    if saved_suffix not in set([".csv", ".jsonl", ".json"]):
        raise ValueError(f"The saved_path must end with .csv, .jsonl or .json.")

    if args.video_path_column is None and args.beautiful_prompt_column is None:
        raise ValueError("Either video_path_column or beautiful_prompt_column should be specified in the arguments.")
    if args.video_path_column is not None and args.beautiful_prompt_column is not None:
        raise ValueError(
            "Both video_path_column and beautiful_prompt_column can not be specified in the arguments at the same time."
        )

    if os.path.exists(args.saved_path):
        if args.saved_path.endswith(".csv"):
            saved_metadata_df = pd.read_csv(args.saved_path)
        elif args.saved_path.endswith(".jsonl"):
            saved_metadata_df = pd.read_json(args.saved_path, lines=True)

        if args.video_path_column is not None:
            # Filter out the unprocessed video-caption pairs by setting the indicator=True.
            merged_df = video_metadata_df.merge(saved_metadata_df, on=args.video_path_column, how="outer", indicator=True)
            video_metadata_df = merged_df[merged_df["_merge"] == "left_only"]
            # Sorting to guarantee the same result for each process.
            video_metadata_df = video_metadata_df.iloc[index_natsorted(video_metadata_df[args.video_path_column])]
            video_metadata_df = video_metadata_df.reset_index(drop=True)
        if args.beautiful_prompt_column is not None:
            # Filter out the unprocessed caption-beautifil_prompt pairs by setting the indicator=True.
            merged_df = video_metadata_df.merge(saved_metadata_df, on=args.caption_column, how="outer", indicator=True)
            video_metadata_df = merged_df[merged_df["_merge"] == "left_only"]
            # Sorting to guarantee the same result for each process.
            video_metadata_df = video_metadata_df.iloc[index_natsorted(video_metadata_df[args.caption_column])]
            video_metadata_df = video_metadata_df.reset_index(drop=True)
        logger.info(
            f"Resume from {args.saved_path}: {len(saved_metadata_df)} processed and {len(video_metadata_df)} to be processed."
        )

    if args.prompt.endswith(".txt") and os.path.exists(args.prompt):
        with open(args.prompt, "r") as f:
            args.prompt = "".join(f.readlines())
    logger.info(f"Prompt: {args.prompt}")

    if args.max_retry_count < 1:
        raise ValueError(f"The max_retry_count {args.max_retry_count} must be greater than 0.")

    if args.video_path_column is not None:
        video_path_list = video_metadata_df[args.video_path_column].tolist()
    if args.caption_column in video_metadata_df.columns:
        sampled_frame_caption_list = video_metadata_df[args.caption_column].tolist()
    else:
        # When two columns with the same name, the dataframe merge operation on will distinguish them by adding 'x' and 'y'.
        sampled_frame_caption_list = video_metadata_df[args.caption_column + "_x"].tolist()

    CUDA_VISIBLE_DEVICES = os.getenv("CUDA_VISIBLE_DEVICES", None)
    tensor_parallel_size = torch.cuda.device_count() if CUDA_VISIBLE_DEVICES is None else len(CUDA_VISIBLE_DEVICES.split(","))
    logger.info(f"Automatically set tensor_parallel_size={tensor_parallel_size} based on the available devices.")

    llm = LLM(model=args.model_name, trust_remote_code=True, tensor_parallel_size=tensor_parallel_size)
    if "Meta-Llama-3" in args.model_name:
        if "Meta-Llama-3-70B" in args.model_name:
            # Llama-3-70B should use the tokenizer from Llama-3-8B
            # https://github.com/vllm-project/vllm/issues/4180#issuecomment-2068292942
            tokenizer = AutoTokenizer.from_pretrained("NousResearch/Meta-Llama-3-8B-Instruct")
        else:
            tokenizer = AutoTokenizer.from_pretrained(args.model_name)
        stop_token_ids = [tokenizer.eos_token_id, tokenizer.convert_tokens_to_ids("<|eot_id|>")]
        sampling_params = SamplingParams(temperature=0.7, top_p=1, max_tokens=1024, stop_token_ids=stop_token_ids)
    else:
        tokenizer = AutoTokenizer.from_pretrained(args.model_name)
        sampling_params = SamplingParams(temperature=0.7, top_p=1, max_tokens=1024)

    if args.video_path_column is not None:
        result_dict = {args.video_path_column: [], args.caption_column: []}
    if args.beautiful_prompt_column is not None:
        result_dict = {args.caption_column: [], args.beautiful_prompt_column: []}

    for i in tqdm(range(0, len(sampled_frame_caption_list), args.batch_size)):
        if args.video_path_column is not None:
            batch_video_path = video_path_list[i : i + args.batch_size]
        batch_caption = sampled_frame_caption_list[i : i + args.batch_size]
        batch_prompt = []
        for caption in batch_caption:
            # batch_prompt.append("user:" + args.prompt + str(caption) + "\n assistant:")
            messages = [
                {"role": "system", "content": "You are a helpful assistant."},
                {"role": "user", "content": args.prompt + "\n" + str(caption)},
            ]
            text = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
            batch_prompt.append(text)

        cur_retry_count = 0
        while cur_retry_count < args.max_retry_count:
            if len(batch_prompt) == 0:
                break

            batch_result = []
            batch_output = llm.generate(batch_prompt, sampling_params)
            batch_output = [output.outputs[0].text.rstrip() for output in batch_output]
            if args.prefix is not None:
                batch_output = [extract_output(output, args.prefix) for output in batch_output]

            if args.video_path_column is not None:
                retry_batch_video_path, retry_batch_prompt = [], []
                for (video_path, prompt, output) in zip(batch_video_path, batch_prompt, batch_output):
                    # Filter out data that does not meet the output format to retry.
                    if output is not None and output != args.answer_template:
                        batch_result.append((video_path, output))
                    else:
                        retry_batch_video_path.append(video_path)
                        retry_batch_prompt.append(prompt)
                if len(batch_result) != 0:
                    batch_video_path, batch_output = zip(*batch_result)
                    result_dict[args.video_path_column].extend(deepcopy(batch_video_path))
                    result_dict[args.caption_column].extend(deepcopy(batch_output))

                batch_video_path, batch_prompt = retry_batch_video_path, retry_batch_prompt
            if args.beautiful_prompt_column is not None:
                retry_batch_caption, retry_batch_prompt = [], []
                for (caption, prompt, output) in zip(batch_caption, batch_prompt, batch_output):
                    # Filter out data that does not meet the output format to retry.
                    if output is not None and output != args.answer_template:
                        batch_result.append((caption, output))
                    else:
                        retry_batch_caption.append(caption)
                        retry_batch_prompt.append(prompt)
                if len(batch_result) != 0:
                    batch_caption, batch_output = zip(*batch_result)
                    result_dict[args.caption_column].extend(deepcopy(batch_caption))
                    result_dict[args.beautiful_prompt_column].extend(deepcopy(batch_output))

                batch_caption, batch_prompt = retry_batch_caption, retry_batch_prompt

            cur_retry_count += 1
            logger.info(
                f"Current retry count/Maximum retry count: {cur_retry_count}/{args.max_retry_count}.: "
                f"Retrying {len(batch_prompt)} prompts with invalid output format."
            )

        # Save the metadata every args.saved_freq.
        if (i // args.batch_size) % args.saved_freq == 0 or (i + 1) * args.batch_size >= len(sampled_frame_caption_list):
            if len(result_dict[args.caption_column]) > 0:
                result_df = pd.DataFrame(result_dict)
                # Append is not supported (oss).
                if args.saved_path.endswith(".csv"):
                    if os.path.exists(args.saved_path):
                        saved_df = pd.read_csv(args.saved_path)
                        result_df = pd.concat([saved_df, result_df], ignore_index=True)
                    result_df.to_csv(args.saved_path, index=False)
                elif args.saved_path.endswith(".jsonl"):
                    if os.path.exists(args.saved_path):
                        saved_df = pd.read_json(args.saved_path, orient="records", lines=True)
                        result_df = pd.concat([saved_df, result_df], ignore_index=True)
                    result_df.to_json(args.saved_path, orient="records", lines=True, force_ascii=False)
                logger.info(f"Save result to {args.saved_path}.")

            result_dict = {args.caption_column: []}
            if args.video_path_column is not None:
                result_dict = {args.video_path_column: [], args.caption_column: []}
            if args.beautiful_prompt_column is not None:
                result_dict = {args.caption_column: [], args.beautiful_prompt_column: []}

if __name__ == "__main__":
    main()

import json
import torch
from PIL import Image
from transformers import AutoTokenizer, AutoConfig, AutoProcessor
from vllm import LLM, SamplingParams
from vllm.assets.image import ImageAsset
from vllm.assets.video import VideoAsset
from vllm.lora.request import LoRARequest
from vllm.multimodal.image import convert_image_mode
from typing import Tuple, List


class Predictor():

    def __init__(self,
                 tensor_parallel_size: int = 1,
                 model_from_pretrained: str = None,
                 resume_path: str = None,
                 **args
                 ):
        '''
        Predictor: LLM预测器 (LLM predictor)

        ### Args:

        `tensor_parallel_size`: 张量并行使用的 GPU 数量（模型被拆分到多个卡）

        `model_from_pretrained`: 预训练模型的路径或名称（如HuggingFace模型名）

        `resume_path`: 如果有预训练的LoRA模型，可以指定路径进行加载
        '''
        self.tp = tensor_parallel_size
        self.model_from_pretrained = model_from_pretrained
        self.lora_path = resume_path
        self.model_init(**args)

    def model_init(self, **args):
        self.config = AutoConfig.from_pretrained(
            self.model_from_pretrained, trust_remote_code=True)
        self.tokenizer = AutoTokenizer.from_pretrained(
            self.model_from_pretrained, padding_side="left", trust_remote_code=True)
        self.model_type = self.config.model_type if hasattr(self.config, 'model_type') else 'llama'
        self.llm = LLM(self.model_from_pretrained, tensor_parallel_size=self.tp, trust_remote_code=True, enable_lora=self.lora_path is not None, **args)
        self.processor = self.tokenizer
        if hasattr(self.config, 'eos_token_id'):
            self.eos_token_id = [self.config.eos_token_id]
        if hasattr(self.config, 'bos_token_id'):
            self.bos_token_id = [self.config.bos_token_id]
        if self.model_type == 'chatglm':
            self.eos_token_id = self.config.eos_token_id
        elif self.model_type == 'llama':
            self.tokenizer.pad_token = self.tokenizer.eos_token
            terminators = [
                self.tokenizer.eos_token_id,
                self.tokenizer.convert_tokens_to_ids("<|eot_id|>")
            ]
            if not hasattr(self, 'eos_token_id'):
                self.eos_token_id = []
            for t in terminators:
                if t is not None:
                    self.eos_token_id.append(t)
        elif self.model_type == "mimo":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
        elif self.model_type == "tinyr1":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
        elif self.model_type == "qwen2_5_vl":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
            self.processor = AutoProcessor.from_pretrained(self.model_from_pretrained, padding_side='left')
        elif self.model_type == "llava":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
            from transformers import LlavaForConditionalGeneration
            self.model =  LlavaForConditionalGeneration.from_pretrained(self.model_from_pretrained, torch_dtype=torch.float16, device_map="auto", trust_remote_code=True)
            self.processor = AutoProcessor.from_pretrained(self.model_from_pretrained, padding_side='left')
        elif self.model_type == "mllama":
            self.eos_token_id = self.config.eos_token_id
            self.bos_token_id = self.config.bos_token_id
            from transformers import MllamaForConditionalGeneration
            self.model =  MllamaForConditionalGeneration.from_pretrained(self.model_from_pretrained, torch_dtype=torch.float16, device_map="auto", trust_remote_code=True)
            self.processor = AutoProcessor.from_pretrained(self.model_from_pretrained, padding_side='left', trust_remote_code=True)

    def process_model_outputs(self, inputs, outputs, tokenizer):
        responses = []
        for input_ids, output_ids in zip(inputs['input_ids'], outputs):
            response = tokenizer.decode(output_ids[len(input_ids):], skip_special_tokens=True).strip()
            responses.append(response)
        return responses

    def build_chat_input(self, query:list, history=None):
        if history is None:
            history = []
        history.append(query)
        is_mm = self.is_mm(history)
        max_input_tokens = 0
        new_batch_input = self.tokenizer.apply_chat_template(history, add_generation_prompt=True, tokenize=False)
        max_input_tokens = max(max_input_tokens, len(new_batch_input))
        return {
            'text': new_batch_input,
            'max_input_tokens': max_input_tokens,
            'is_mm': is_mm
        }

    def is_mm(self, message: dict | list):
        if not isinstance(message, list):
            message = [message]
        for msg in message:
            if isinstance(msg, dict) and 'content' in msg and isinstance(msg['content'], list):
                for content in msg['content']:
                    if 'type' in content and content['type'] in ['image', 'video']:
                        return True
        return False

    def process_mm(self, query_list:list, history_list=None):
        if history_list is not None:
            assert len(query_list) == len(history_list), "Query and history must have the same length."
            for query, history in zip(query_list, history_list):
                if isinstance(query, str):
                    query = {'role': 'user', 'content': query}
                history.append(query)
        else:
            history_list = [[query] for query in query_list]

        images_list = []
        for history in history_list:
            images = []
            for msg in history:
                if isinstance(msg['content'], list):
                    for content in msg['content']:
                        if isinstance(content, dict) and 'type' in content and content['type'] == 'image':
                            images.append(convert_image_mode(Image.open(content['image']), "RGB"))
            images_list.append(images)
        return images_list

    def prepare_generate(self, query: str | list = '', history: List = None, max_length=512, max_new_tokens=512, num_beams:int=1, top_p: float = 1.0, temperature=0, do_sample: bool = False, build_message=True):
        if not isinstance(query, list):
            query = [query]
            history = [history] if history is not None else None
        is_mm = False
        if build_message:
            inputs = []
            batch_max_len = 0
            for i, t in enumerate(query):
                if isinstance(t, str):
                    t = {'role': 'user', 'content': t}
                if history is not None and len(history) > 0:
                    h_unit = history[i]
                else:
                    h_unit = []
                chat_input = self.build_chat_input(t, h_unit)
                if batch_max_len < chat_input['max_input_tokens']:
                    batch_max_len = chat_input['max_input_tokens']
                inputs.append(chat_input['text'])
                if chat_input['is_mm']:
                    is_mm = True
        else:
            inputs = query
            batch_max_len = 0
            for i in range(len(query)):
                if len(query[i]) > batch_max_len:
                    batch_max_len = len(query[i])

        if is_mm:
            images_list = self.process_mm(query, history)
        else:
            images_list = []

        if len(images_list) > 0:
            new_inputs = []
            for i, text in enumerate(inputs):
                new_inputs.append({
                    "prompt": text,
                    "multi_modal_data": {"image": images_list[i]},
                })
            inputs = new_inputs

        sampling_params = SamplingParams(temperature=temperature, top_p=top_p, max_tokens=max_new_tokens)

        return inputs, sampling_params

    def predict(self, query: str | list = '', history: List = None, max_length=512, max_new_tokens=512, num_beams:int=1, top_p: float = 0.8, temperature=1.0, do_sample: bool = False, build_message=True):
        '''
        Predict method for generating responses from the model.

        ### Args:
        - `query`: The input query or list of queries.
        - `history`: Conversation history, if any.
        - `max_length`: Maximum length of the generated response.
        - `max_new_tokens`: Maximum number of new tokens to generate.
        - `num_beams`: Number of beams for beam search (default is 1).
        - `top_p`: Top-p sampling parameter.
        - `temperature`: Temperature for sampling.
        - `do_sample`: Whether to use sampling or greedy decoding.
        - `build_message`: Whether to build the message format for the model.

        ### Returns:
        - List of generated responses.
        '''

        inputs, sampling_params = self.prepare_generate(query, history, max_length, max_new_tokens, num_beams, top_p, temperature, do_sample, build_message)
        if self.lora_path is not None:
            outputs = self.llm.generate(
                inputs,
                sampling_params,
                lora_request=LoRARequest("custom_lora", 1, self.lora_path)
            )
        else:
            outputs = self.llm.generate(inputs, sampling_params)
        results = []
        for output in outputs:
            prompt = output.prompt
            generated_text = output.outputs[0].text
            results.append(generated_text)
        return results

    def __call__(self, query: str | list = '', history: List = None, max_length=512, max_new_tokens=512, num_beams:int=1, top_p: float = 0.8, temperature=1.0, do_sample: bool = False, build_message=True):
        return self.predict(query, history, max_length, max_new_tokens, num_beams, top_p, temperature, do_sample, build_message)

import json
import math
import time
import base64
import random
import argparse
from tqdm import tqdm
from transformers import AutoProcessor
from vllm import LLM, SamplingParams
# from vision_process import process_vision_info
from qwen_vl_utils import process_vision_info
from torch.utils.data import Dataset, DataLoader
from dataclasses import dataclass, field
import os
os.environ["VLLM_WORKER_MULTIPROC_METHOD"] = "spawn"
# os.environ["CUDA_VISIBLE_DEVICES"] = "0,1,2,3"


def init_model(model_path, tensor_parallel_size):
    llm = LLM(
        model=model_path,
        limit_mm_per_prompt={"image": 1, "video": 1},
        tensor_parallel_size=tensor_parallel_size
    )
    sampling_params = SamplingParams(
        temperature=0,
        top_p=0.001,
        repetition_penalty=1.05,
        max_tokens=2048,
        stop_token_ids=[],
    )
    processor = AutoProcessor.from_pretrained(model_path)
    return llm, sampling_params, processor


class QwenDataset(Dataset):
    def __init__(self, data_list, data_root, processor, video_kwargs=None, complex_prompt=False):
        super(QwenDataset, self).__init__()
        if complex_prompt:
            self.image_prompt = "Please describe the image in detail. Your description should follow these rules:\n"\
                "a) You should describe each object in the image in detail, including its name, number, color, and spatial relationship between objects.\n"\
                "b) You should describe the scene of the image.\n"\
                "c) You should describe the camera angle when shooting this image, such as level angle, high angle, low angle, or dutch angle.\n"\
                "d) You should describe the style of the image, such as realistic, animated, special-effect, old-fashioned and so on.\n"\
                "e) If there are any texts in the image, you should describe the text content.\n"\
                "f) If you know the character in the image, you should tell his or her name.\n"\
                "Directly output your detailed description in a elaborate paragraph, instead of itemizing them in list form. Your description: "
            self.video_prompt = "Please describe the video in detail. Your description should follow these rules:\n"\
                "a) You should describe each events in the video in order, especially focusing on the behavior and action of characters, including people, animals.\n"\
                "b) You should describe each object in the video in detail, including its name, number, color, and spatial relationship between objects.\n"\
                "c) You should describe the scene of the video.\n"\
                "d) You should describe the camera movement when shooting this video, especially the direction, such as pan left, track right, tilt up, boom down, zoom in, dolly out, and so on.\n"\
                "e) You should describe the style of the video, such as realistic, animated, special-effect, old-fashioned and so on.\n"\
                "f) If there are any texts in the video, you should describe the text content.\n"\
                "g) If you know the character in the video, you should tell his or her name.\n"\
                "Directly output your detailed description in a elaborate paragraph, instead of itemizing them in list form. Your description: "
        else:
            self.image_prompt = "Please describe the image in detail."
            self.video_prompt = "Please describe the video in detail."
        self.data_list = data_list
        self.data_root = data_root
        self.processor = processor
        self.video_kwargs = video_kwargs

    def __len__(self):
        return len(self.data_list)

    def __getitem__(self, index):
        data = self.data_list[index]
        llm_input = self.get_llm_input_from_data(data, self.video_kwargs)
        return data, llm_input

    def get_llm_input_from_data(self, data, video_kwargs=None):
        if data['data_type'] == 'image':
            file_path = data['file_path']
            text_prompt = self.image_prompt
            content = [
                {
                    "type": "image",
                    "image": f"file://{os.path.join(self.data_root, file_path)}",
                },
                {
                    "type": "text",
                    "text": text_prompt
                },
            ]
        elif data['data_type'] == 'video':
            file_path = data['file_path']
            text_prompt = self.video_prompt
            content = [
                {
                    "type": "video",
                    "video": f"file://{os.path.join(self.data_root, file_path)}",
                    # "fps": 2.0,
                    # "max_frames": 768,
                },
                {"type": "text", "text": text_prompt},
            ]
            if video_kwargs is not None:
                content[0].update(video_kwargs)
        else:
            raise ValueError("No image or video path in data")

        messages = [
            {"role": "system", "content": "You are a helpful assistant."},
            {
                "role": "user",
                "content": content,
            },
        ]

        prompt = self.processor.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=True,
        )

        image_inputs, video_inputs = process_vision_info(messages)
        mm_data = {}
        if image_inputs is not None:
            mm_data["image"] = image_inputs
        if video_inputs is not None:
            mm_data["video"] = video_inputs

        llm_input = {
            "prompt": prompt,
            "multi_modal_data": mm_data,
        }

        return llm_input

@dataclass
class DataCollator(object):
    def __call__(self, batch):
        datas = []
        llm_inputs = []
        for e in batch:
            datas.append(e[0])
            llm_inputs.append(e[1])
        return datas, llm_inputs


def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("--model_path", type=str, required=True)
    parser.add_argument("--save_root", type=str, required=True)
    parser.add_argument("--benchmark", type=str, required=False, default=None)
    parser.add_argument("--error_save_root", type=str, required=False, default=None)
    parser.add_argument("--is_processing_large_videos", action="store_true")
    parser.add_argument("--num_gpus", type=int, default=4)
    parser.add_argument("--complex_prompt", action='store_true', default=False)
    return parser.parse_args()


def llm_infer(llm, llm_inputs, sampling_params):
    try:
        outputs = llm.generate(llm_inputs, sampling_params=sampling_params)
        generated_texts = [outputs[j].outputs[0].text for j in range(len(llm_inputs))]
    except Exception as e:
        print("Error:", e)
        return None

    return generated_texts

if __name__ == '__main__':
    args = parse_args()
    model_path = args.model_path
    model_name = os.path.basename(model_path)
    tensor_parallel_size = args.num_gpus
    llm, sampling_params, processor = init_model(model_path, tensor_parallel_size)

    anno_root = "../annotations"
    data_root = "../"
    anno_files = [os.path.join(anno_root, filename) for filename in os.listdir(anno_root)]
    if args.benchmark is not None:
        anno_files = [f for f in anno_files if args.benchmark in f]
        assert len(anno_files) == 1
    save_root = args.save_root
    os.makedirs(save_root, exist_ok=True)

    if args.error_save_root is not None:
        os.makedirs(args.error_save_root, exist_ok=True)

    for anno_file in tqdm(anno_files, desc="task"):
        if 'action' in anno_file:
            continue

        task_name = os.path.basename(anno_file).split('.')[0]
        save_file = os.path.join(save_root, f"{task_name}.jsonl")
        if args.error_save_root is not None:
            error_file = os.path.join(args.error_save_root, f"{task_name}.jsonl")
        with open(anno_file, 'r', encoding='utf-8') as f:
            data = [json.loads(l.strip('\n')) for l in f.readlines()]

        data_type = data[0]['data_type']
        if data_type == 'image':
            data_type = 'image'
            batch_size = 4 if '72B' in model_path else 24
        elif data_type == 'video':
            data_type = 'video'
            batch_size = 2 if '72B' in model_path else 4
        else:
            raise ValueError("No image or video path in data")



        print(f"[{task_name}] data length: {len(data)}")
        if os.path.exists(save_file):
            with open(save_file, 'r', encoding='utf-8') as f:
                processed_data = [json.loads(l.strip('\n')) for l in f.readlines()]
            processed_data = [d['file_id'] for d in processed_data]
            remain_data = [d for d in data if d['file_id'] not in processed_data]
            print(f"[{task_name}] Find {len(processed_data)} records, remaining {len(remain_data)} to be processed")
        else:
            remain_data = data
        if len(remain_data) == 0:
            continue

        if args.is_processing_large_videos and 'Qwen2.5' in args.model_path:
            video_kwargs = {
                "max_pixels": 360 * 512,
            }
            batch_size = 1
        elif args.is_processing_large_videos:
            video_kwargs = {
                "max_pixels": 360 * 360,
                "fps": 1.0,
                "max_frames": 384,
            }

        else:
            video_kwargs = None
        dataset = QwenDataset(remain_data, data_root, processor, video_kwargs, complex_prompt=args.complex_prompt)
        dataloader = DataLoader(
            dataset, batch_size=batch_size,
            shuffle=False, num_workers=8,
            collate_fn=DataCollator(), pin_memory=True
        )

        for i, (datas, llm_inputs) in enumerate(tqdm(dataloader, desc=task_name)):
            generated_texts = llm_infer(llm, llm_inputs, sampling_params)
            if generated_texts is None:
                assert data_type == "video"
                for d in datas:
                    llm_inputs = [dataset.get_llm_input_from_data(d)]
                    generated_texts = llm_infer(llm, llm_inputs, sampling_params)
                    if generated_texts is None:
                        if args.error_save_root is not None:
                            with open(error_file, 'a', encoding='utf-8') as f:
                                f.write(json.dumps(d, ensure_ascii=False) + '\n')
                            continue
                    else:
                        with open(save_file, 'a', encoding='utf-8') as f:
                            f.write(json.dumps({'file_id': d['file_id'], 'caption': generated_texts[0]}, ensure_ascii=False) + '\n')
            else:
                with open(save_file, 'a', encoding='utf-8') as f:
                    for k,v in zip(datas, generated_texts):
                        f.write(json.dumps({'file_id':k['file_id'], 'caption': v}, ensure_ascii=False) + '\n')


        if args.error_save_root is not None and os.path.exists(error_file):
            with open(error_file, 'r', encoding='utf-8') as f:
                error_data = [json.loads(l.strip('\n')) for l in f.readlines()]
            if len(error_data) == 0:
                os.remove(error_file)

import os
import logging
from dotenv import load_dotenv
import argparse
from tqdm import tqdm
from transformers import AutoTokenizer, AutoModelForCausalLM
from vllm import LLM, SamplingParams
import openai


os.makedirs(f'logs', exist_ok=True)
logging.basicConfig(filename=f"logs/translation.log", level=logging.INFO, format='%(asctime)s %(levelname)s %(module)s - %(funcName)s: %(message)s', datefmt='%Y-%m-%d %H:%M:%S')


def main(args):

    extensions = {'python': 'py', 'java': 'java'}

    experiment_type = 'no_test'
    if args.use_misleading_test:
        experiment_type = 'misleading_test'
    elif args.use_test:
        experiment_type = 'w_test'

    test_type = 'tests'
    if args.use_misleading_test:
        test_type = 'misleading_tests'

    in_folder = f'translation_dataset/{args.dataset}/{args.source_lang}/code'
    test_folder = f'translation_dataset/{args.dataset}/{args.source_lang}/tests'
    out_folder = f'translation_output/{experiment_type}/{args.model}/{args.dataset}/{args.source_lang}/{args.target_lang}'

    in_files = os.listdir(in_folder)
    print(f'found {len(in_files)} inputs')

    # check for files alraedy extracted
    already_extracted_files = []
    if os.path.exists(out_folder):
        already_extracted_files = os.listdir(out_folder)
        if len(already_extracted_files) > 0:
            already_extracted_files = [x.split('.')[0] for x in already_extracted_files if os.stat(f'{out_folder}/{x}').st_size != 0]

    if len(already_extracted_files) > 0:
        in_files = [x for x in in_files if x.split('.')[0] not in already_extracted_files]

    ext = extensions[args.target_lang]
    device = f'cuda:{args.gpu_id}'

    tokenizer, model = None, None
    if args.model == 'codellama':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("codellama/CodeLlama-13b-Instruct-hf", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("codellama/CodeLlama-13b-Instruct-hf", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'magicoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("ise-uiuc/Magicoder-S-DS-6.7B", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("ise-uiuc/Magicoder-S-DS-6.7B", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'wizardcoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("WizardLM/WizardCoder-15B-V1.0", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("WizardLM/WizardCoder-15B-V1.0", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'deepseekcoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("deepseek-ai/deepseek-coder-6.7b-instruct", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("deepseek-ai/deepseek-coder-6.7b-instruct", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'starcoder':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("bigcode/starcoder", token=os.environ['STARCODER_AUTH_TOKEN'], cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("bigcode/starcoder", token=os.environ['STARCODER_AUTH_TOKEN'], cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'mistral':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained("mistralai/Mistral-7B-Instruct-v0.1", cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained("mistralai/Mistral-7B-Instruct-v0.1", cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'llama2':
        kwargs = {}
        tokenizer = AutoTokenizer.from_pretrained('meta-llama/Llama-2-13b-hf', token=os.environ['LLAMA2_AUTH_TOKEN'], cache_dir=args.cache_dir)
        model = AutoModelForCausalLM.from_pretrained('meta-llama/Llama-2-13b-hf', token=os.environ['LLAMA2_AUTH_TOKEN'], cache_dir=args.cache_dir, device_map='auto', **kwargs)

    elif args.model == 'starcoder2':
        kwargs = {}
        model = LLM(model="bigcode/starcoder2-15b", tokenizer="bigcode/starcoder2-15b", **kwargs)

    elif args.model in ['gpt-4', 'gpt-3.5']:
        model = openai.OpenAI(
                    # This is the default and can be omitted
                    api_key=os.environ['OPENAI_API_KEY'],
                )

    # loop over input files
    os.makedirs(out_folder, exist_ok=True)
    for f in tqdm(in_files):

        base_name = f.split('.')[0]

        test_input = open(f'{test_folder}/{base_name}_in.txt', 'r').read()
        test_output = ''
        if args.use_test:
            test_output = open(f'{test_folder}/{base_name}_out.txt', 'r').read()
        elif args.use_misleading_test:
            test_output = open(f'{test_folder}/{base_name}_misleading_out.txt', 'r').read()

        if len(test_input) > 500 or len(test_output) > 500:
            continue

        prompt_file = f'{in_folder}/{f}'

        with open(prompt_file, "r", encoding="ISO-8859-1", errors='ignore') as fin:
            prompt = fin.readlines()

            if args.model == 'codellama':
                if args.use_test or args.use_misleading_test:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n"
                else:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n"
                prompt = f"[INST] <<SYS>>\nYou are an expert {args.target_lang} programmer and assistant\n<</SYS>>\n\n{prompt}[/INST]\n"

            elif args.model == 'magicoder':
                if args.use_test or args.use_misleading_test:
                    prompt = f"You are an exceptionally intelligent coding assistant that consistently delivers accurate and reliable responses to user instructions.\n\n@@ Instruction\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n\n@@ Response\n"
                else:
                    prompt = f"You are an exceptionally intelligent coding assistant that consistently delivers accurate and reliable responses to user instructions.\n\n@@ Instruction\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n\n@@ Response\n"

            elif args.model == 'wizardcoder':
                if args.use_test or args.use_misleading_test:
                    prompt = f"Below is an instruction that describes a task. Write a response that appropriately completes the request.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"
                else:
                    prompt = f"Below is an instruction that describes a task. Write a response that appropriately completes the request.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"

            elif args.model == 'deepseekcoder':
                if args.use_test or args.use_misleading_test:
                    prompt = f"You are an expert Python programmer.Your task is to write a Python function to solve a programming problem.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"
                else:
                    prompt = f"You are an expert Python programmer.Your task is to write a Python function to solve a programming problem.\n\n### Instruction:\nTranslate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n\n### Response:\n"

            elif args.model == 'mistral':
                if args.use_test or args.use_misleading_test:
                    prompt = f"[INST] Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n[/INST]\n"
                else:
                    prompt = f"[INST] Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + "\n```\n[/INST]\n"

            elif args.model in ['starcoder', 'starcoder2']:
                if args.use_test or args.use_misleading_test:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + f"\n```\n\n{args.target_lang} code:"
                else:
                    prompt = f"Translate the following {args.source_lang} code to {args.target_lang} and enclose your solution inside ```{args.target_lang.lower()}```:\n```\n" + "".join(prompt) + f"\n```\n\n{args.target_lang} code:"
                prefix_token = "<fim_prefix>"
                suffix_token = "<fim_suffix><fim_middle>"
                prompt = prefix_token + prompt + suffix_token

            elif args.model in ['gpt-4', 'gpt-3.5']:
                if args.use_test or args.use_misleading_test:
                    prompt = "Translate the following code from " + args.source_lang + " to " + args.target_lang + " and enclose your solution inside ```" + args.target_lang.lower() + "```.\nA sample test case is provided below:\n\nTest input:\n" + test_input + "\nExpected output:\n" + test_output + "\n\n```\n" + "".join(prompt) + "\n```\n"
                else:
                    prompt = "Translate the following code from " + args.source_lang + " to " + args.target_lang + " and enclose your solution inside ```" + args.target_lang.lower() + "```:\n```\n" + "".join(prompt) + "\n```\n"

            try:

                if args.model in ['starcoder2']:
                    total_input_tokens = len(model.get_tokenizer().encode(prompt))
                    model_max_length = 2048
                    if total_input_tokens >= model_max_length:
                        out_file = f'{out_folder}/{f.split(".")[0]}.{ext}'
                        with open(out_file, 'w') as fot:
                            print("# Token size exceeded.", file=fot)
                        continue
                    max_new_tokens = model_max_length - total_input_tokens
                    vllm_outputs = model.generate(
                        prompt,
                        SamplingParams(
                            temperature=0.0,
                            max_tokens=max_new_tokens,
                            stop=['<|endoftext|>'],
                            top_p=1.0,
                        ),
                        use_tqdm=False,
                    )

                    gen_strs = [x.outputs[0].text.replace("\t", "    ") for x in vllm_outputs]
                    generated_output = gen_strs[0]

                elif args.model in ['gpt-4', 'gpt-3.5']:
                    try:
                        response = model.chat.completions.create(
                            model="gpt-4-1106-preview" if args.model == 'gpt-4' else "gpt-3.5-turbo",
                            messages=[
                                {
                                    "role": "system",
                                    "content": "You are an expert " + args.target_lang + " programmer and assistant"
                                },
                                {
                                    "role": "user",
                                    "content": prompt
                                }
                            ]
                        )
                        generated_output = response.choices[0].message.content
                    except openai.BadRequestError as e:
                        generated_output = f'token size exceeded. {e}'

                else:

                    inputs = tokenizer.encode(prompt, return_tensors="pt").to(device)
                    total_input_tokens = inputs.shape[1]
                    model_max_length = 2048
                    if total_input_tokens >= model_max_length:
                        out_file = f'{out_folder}/{f.split(".")[0]}.{ext}'
                        with open(out_file, 'w') as fot:
                            print("# Token size exceeded.", file=fot)
                        continue
                    max_new_tokens = model_max_length - total_input_tokens

                    raw_outputs = ''
                    raw_outputs = model.generate(
                        inputs,
                        max_new_tokens=max_new_tokens,
                        do_sample=False,
                        pad_token_id=tokenizer.eos_token_id,
                    )

                    generated_output = tokenizer.decode(raw_outputs[0])

                out_file = f'{out_folder}/{f.split(".")[0]}.{ext}'
                with open(out_file, 'w') as fot:
                    print(generated_output, file=fot)

            except (ValueError, FileNotFoundError) as e:
                print(e)
                continue


if __name__ == "__main__":
    load_dotenv()
    parser = argparse.ArgumentParser(description='run translation with open-source models given dataset and languages')
    parser.add_argument('--model', help='model to use for code translation', required=True, type=str)
    parser.add_argument('--dataset', help='dataset to use for code translation', required=True, type=str)
    parser.add_argument('--source_lang', help='source language to use for code translation', required=True, type=str)
    parser.add_argument('--target_lang', help='target language to use for code translation', required=True, type=str)
    parser.add_argument('--gpu_id', help='gpu id to use', required=True, type=int)
    parser.add_argument('--cache_dir', help='cache directory for huggingface models', required=True, type=str)
    parser.add_argument('--use_test', help='use test dataset', action='store_true')
    parser.add_argument('--use_misleading_test', help='use test dataset', action='store_true')
    args = parser.parse_args()

    # Initialize configurations
    source = args.source_lang
    target = args.target_lang
    logging.info(f"translating examples from {source} to {target} using {args.model} and {args.dataset} dataset")
    main(args)
